// 士兵吶喊音效：多層次噪音+低頻衝擊+漸強群呼
function sndBattleCry(){
 try{
  if(typeof AC==='undefined'||_sfxMuted) return;
  const now=_safeAcTime();

  // === 人群吶喊主體：12 層不同頻段的帶通噪音，形成群眾齊聲 ===
  const roarFreqs=[180,220,260,310,370,440,520,610,720,850,1000,1200];
  roarFreqs.forEach((freq,i)=>{
    const buf=AC.createBuffer(1,AC.sampleRate*1.8,AC.sampleRate);
    const d=buf.getChannelData(0);
    // 填入帶有人聲共鳴感的噪音（用正弦調製）
    for(let j=0;j<d.length;j++){
      const t=j/AC.sampleRate;
      d[j]=(Math.random()*2-1)*(0.6+0.4*Math.sin(t*freq*0.08+i));
    }
    const src=AC.createBufferSource(); src.buffer=buf;
    const bp=AC.createBiquadFilter(); bp.type='bandpass';
    bp.frequency.value=freq; bp.Q.value=2.2+i*0.15;
    const g=AC.createGain();
    const onset=i*0.025;
    g.gain.setValueAtTime(0,now+onset);
    g.gain.linearRampToValueAtTime(0.16+Math.random()*0.06, now+onset+0.18);
    g.gain.setValueAtTime(0.14, now+onset+0.5);
    g.gain.exponentialRampToValueAtTime(0.001, now+onset+1.6);
    src.connect(bp); bp.connect(g); g.connect(AC.destination);
    src.start(now+onset); src.stop(now+onset+1.8);
  });

  // === 戰吼調 (pitched shout) — 複數音高齊喊感 ===
  [90,110,130,160].forEach((freq,i)=>{
    const o=AC.createOscillator(), g=AC.createGain();
    o.type='sawtooth';
    o.frequency.setValueAtTime(freq,now+i*0.03);
    o.frequency.linearRampToValueAtTime(freq*1.08,now+i*0.03+0.3);
    o.frequency.linearRampToValueAtTime(freq*0.92,now+i*0.03+0.9);
    const dist=AC.createWaveShaper();
    const curve=new Float32Array(256);
    for(let j=0;j<256;j++){ const x=j/128-1; curve[j]=x<0?-Math.pow(-x,0.6):Math.pow(x,0.6); }
    dist.curve=curve;
    g.gain.setValueAtTime(0,now+i*0.03);
    g.gain.linearRampToValueAtTime(0.12,now+i*0.03+0.15);
    g.gain.exponentialRampToValueAtTime(0.001,now+i*0.03+1.2);
    o.connect(dist); dist.connect(g); g.connect(AC.destination);
    o.start(now+i*0.03); o.stop(now+i*0.03+1.3);
  });

  // === 戰鼓 — 三連擊 ===
  [0, 0.22, 0.42].forEach((t,i)=>{
    const buf=AC.createBuffer(1,AC.sampleRate*0.5,AC.sampleRate);
    const d=buf.getChannelData(0);
    for(let j=0;j<d.length;j++) d[j]=(Math.random()*2-1)*Math.exp(-j/(AC.sampleRate*0.06));
    const src=AC.createBufferSource(); src.buffer=buf;
    const lp=AC.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=180;
    const g=AC.createGain();
    g.gain.setValueAtTime(0.55-i*0.08, now+t);
    g.gain.exponentialRampToValueAtTime(0.001, now+t+0.45);
    src.connect(lp); lp.connect(g); g.connect(AC.destination);
    src.start(now+t); src.stop(now+t+0.5);
  });

  // === 金屬兵器撞擊聲 ===
  [0.05, 0.14].forEach(t=>{
    const buf=AC.createBuffer(1,AC.sampleRate*0.18,AC.sampleRate);
    const d=buf.getChannelData(0);
    for(let j=0;j<d.length;j++) d[j]=(Math.random()*2-1)*Math.exp(-j/(AC.sampleRate*0.025));
    const src=AC.createBufferSource(); src.buffer=buf;
    const hp=AC.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=2200;
    const g=AC.createGain(); g.gain.setValueAtTime(0.22,now+t);
    g.gain.exponentialRampToValueAtTime(0.001,now+t+0.18);
    src.connect(hp); hp.connect(g); g.connect(AC.destination);
    src.start(now+t); src.stop(now+t+0.2);
  });
 }catch(_eBc){ try{ console.warn('[sndBattleCry] 例外(已吞):', _eBc && _eBc.message); }catch(_){} }
}

// ====== VFX ENGINE ======
var FX_LAYER=null;
function ensureFxLayer(){
  if(FX_LAYER)return;
  FX_LAYER=document.createElement('div');
  FX_LAYER.id='fx-layer';
  FX_LAYER.style.cssText='position:absolute;inset:0;pointer-events:none;overflow:hidden;z-index:700';
  document.getElementById('gc').appendChild(FX_LAYER);
}
function cardRect(h){
  if(!h||h.side===undefined||h.pos===undefined) return null;
  var el=document.getElementById('card-'+h.side+'-'+h.pos);
  if(!el)return null;
  var gcEl=document.getElementById('gc');
  var gcR=gcEl.getBoundingClientRect();
  var r=el.getBoundingClientRect();
  var sc=gcR.width>0?gcR.width/1920:1;
  return{x:(r.left-gcR.left)/sc+(r.width/sc)/2,y:(r.top-gcR.top)/sc+(r.height/sc)/2,w:r.width/sc,h:r.height/sc};
}
function spawnParticles(cx,cy,opts){
  ensureFxLayer();
  var count=opts.count||12,color=opts.color||'#fff',size=opts.size||6,spread=opts.spread||60;
  var duration=opts.duration||700,gravity=opts.gravity!==undefined?opts.gravity:0.3,rise=opts.rise||false;
  for(var i=0;i<count;i++){
    (function(){
      var p=document.createElement('div');
      var ang=rise?(Math.random()*Math.PI*2):(Math.random()*Math.PI);
      var spd=spread*(0.4+Math.random()*0.6);
      var vx=Math.cos(ang)*spd,vy=rise?-Math.abs(Math.sin(ang)*spd):(Math.sin(ang)*spd*0.6-spread*0.3);
      var sz=size*(0.5+Math.random()*0.8);
      p.style.cssText='position:absolute;width:'+sz+'px;height:'+sz+'px;border-radius:50%;background:'+color+';left:'+cx+'px;top:'+cy+'px;transform:translate(-50%,-50%);pointer-events:none;';
      FX_LAYER.appendChild(p);
      var t2=0;
      var step=function(){
        t2+=16;vx*=0.94;vy+=gravity;
        p.style.left=(cx+vx*(t2/16))+'px';
        p.style.top=(cy+vy*(t2/16)+(gravity*t2*t2/512))+'px';
        p.style.opacity=Math.max(0,1-t2/duration);
        p.style.transform='translate(-50%,-50%) scale('+Math.max(0.1,1-t2/duration*0.7)+')';
        if(t2<duration)requestAnimationFrame(step);else p.remove();
      };
      requestAnimationFrame(step);
    })();
  }
}
function showActionLabel(h, text){
  // ★ v3.4.9 — FX 同步:技能名顯示
  try{
    if(h && typeof _wbFxCapture === 'function' && typeof _wbFxShouldCapture === 'function' && _wbFxShouldCapture()){
      _wbFxCapture({ type:'showActionLabel', side:h.side, pos:h.pos, text:text });
    }
  }catch(_){}
  ensureFxLayer();
  var rc=cardRect(h);
  if(!rc) return;
  // 移除同一張卡的舊標籤
  FX_LAYER.querySelectorAll('.card-action-label[data-card="'+h.side+'-'+h.pos+'"]').forEach(function(el){el.remove();});
  var _lbl=document.createElement('div');
  _lbl.className='card-action-label';
  _lbl.dataset.card=h.side+'-'+h.pos;
  _lbl.textContent=text;
  // ★ v3.13.75 — 天賦標籤配色:與「技能/普攻」(白字+金邊)做區隔。
  //   偵測文字含「天賦」或「✦」前綴 → 視為天賦標籤,改紫字+紫光暈+紫邊,
  //   讓玩家一眼分辨「這是天賦效果觸發」。其餘標籤(技能/普攻/休息/未命中…)維持原樣不變。
  //   (天賦標籤一律用此兩種記號:✦ 由 _traitLabel 產生;「天賦」後綴由各職業天賦呼叫帶入。)
  try{
    if(((''+text).indexOf('天賦')>=0) || ((''+text).indexOf('✦')>=0)){
      _lbl.style.color='#c77dff';
      _lbl.style.textShadow='0 0 12px rgba(199,125,255,0.9),0 0 24px rgba(199,125,255,0.55),2px 2px 0 rgba(0,0,0,0.9),-2px -2px 0 rgba(0,0,0,0.9),2px -2px 0 rgba(0,0,0,0.9),-2px 2px 0 rgba(0,0,0,0.9)';
      _lbl.style.borderColor='rgba(199,125,255,0.85)';
    }
  }catch(_alE){}
  // 定位在卡片中央偏上
  _lbl.style.left=rc.x+'px';
  _lbl.style.top=(rc.y - rc.h*0.15)+'px';
  _lbl.style.position='absolute';
  _lbl.style.zIndex='9999';
  _lbl.style.pointerEvents='none';
  FX_LAYER.appendChild(_lbl);
  setTimeout(function(){if(_lbl.parentNode)_lbl.remove();},1000);
}
