function _healGifOnCard(h){
  if(!h) return;
  const el = document.getElementById('card-'+h.side+'-'+h.pos);
  if(!el) return;
  // 避免堆疊：先清舊的(順便釋放 GIF 解碼緩衝)
  const old = el.querySelector('._heal-gif-fx');
  if(old){
    try{ old.src = ''; }catch(_){}
    old.remove();
  }
  const img = document.createElement('img');
  img.className = '_heal-gif-fx';
  // ★ v6100 — 不加 cache-buster,讓瀏覽器吃快取以節省 iPad 記憶體
  img.src = 'https://github.com/clarebox123jp-art/LXPSGAME/raw/main/%E6%B2%BB%E7%99%82%E7%89%B9%E6%95%88.gif';
  img.style.cssText = 'position:absolute;left:0;top:0;width:100%;height:100%;object-fit:cover;pointer-events:none;z-index:200;opacity:0.9;';
  // 確保 el 為相對定位容器
  const cs = getComputedStyle(el);
  if(cs.position === 'static') el.style.position = 'relative';
  el.appendChild(img);
  setTimeout(()=>{
    // ★ v6100 — 移除前清 src,協助 iOS Safari 立即釋放 GIF 解碼緩衝區
    try{ img.src = ''; }catch(_){}
    if(img.parentNode) img.remove();
  }, 1200);
}

