var STAGE_ONLY_SUBJECTS = ['日本關','埃及','中國關','關島交流','木柵動物園','五下自然期中評量','照顧與陪伴幼兒','領養與照顧狗狗','世界機關王大賽'];
// 判斷一題是否屬「關卡/活動專屬題庫」(含五下自然系列前綴規則,與 _kingGetSubjects 完全同口徑)
function _isStageOnlySubject(sub){
  if(!sub) return false;
  try{
    if(STAGE_ONLY_SUBJECTS.indexOf(sub) >= 0) return true;
    if(typeof sub.indexOf === 'function' && sub.indexOf('五下自然') === 0) return true;
  }catch(_){}
  return false;
}
try {
  window.STAGE_ONLY_SUBJECTS = STAGE_ONLY_SUBJECTS;
  window._isStageOnlySubject = _isStageOnlySubject;
} catch(_eSubWin){ console.warn('[v5.66.0] 掛 window 關卡題庫常數例外', _eSubWin); }

// ════════════════════════════════════════════════════════════════════════════
// ★★ v5.118.0(老師需求:「所有科目包含『年級第幾單元』的都歸類到課堂複習」)★★
//   「年級單元題庫」的判定條件全檔原本散在三處各寫一份同樣的 regex
//   (_dailyBonusInfo / _kingGetReviewSubjects ×1 / _advGroupSubjects 配色),
//   而 _kingGetSubjects() 卻是寫死 startsWith('五下自然') ⇒ 口徑不一致,
//   造成「四下自然第三/四單元」(v3.14.18 被 push 進 ADV_QUIZ_DB)同時出現在
//   知識王「一般科目池」與「課堂複習池」兩邊 —— 這正是老師本次看到的分類錯誤。
//   ⇒ 收攏成本謂詞,四處共用;日後新增任何年級單元題庫自動歸課堂複習,不必再改程式。
// ════════════════════════════════════════════════════════════════════════════
window._GRADE_UNIT_RE = /^(低|中|高|國[一二三]|[一二三四五六七八九十]+)[上下]/;
window._isGradeUnitSubject = function(sub){
  try{ return !!sub && window._GRADE_UNIT_RE.test(sub); }catch(_e){ return false; }
};

// ════════════════════════════════════════════════════════════════════════════
// ★★ v5.116.0(老師需求)— 題庫可見性單一真相 window._lxpsQuizVisible(subject, scene) ★★
//   老師原話:「讓 GM 可以勾選是否顯示各單元題庫，或出現在知識王、競技場、龍王戰。
//              六上還沒教的課程我可以先隱藏。」
//   scene 四種:'adv'(冒險科目選單) / 'king'(知識王) / 'arena'(鬥技場) / 'wb'(世界龍王戰)
//   資料來源:gameConfig/quizVisibility → window._quizVisCfg.hidden[scene] = 被關掉的科目陣列。
//   ⚠⚠ 設計要點(不可更動的三條)⚠⚠
//   ① **黑名單制**:只記「被關掉的」。未設定的科目一律可見 ⇒ 日後新增題庫預設會出現,
//      老師不必每次上線都回後台補勾;也保證「沒設定過 = 完全維持舊行為」零回歸。
//   ② **任何例外一律回 true**。寧可多顯示一個科目,也絕不能因為讀取失敗害學生無題可答、
//      或讓知識王/鬥技場拿到空題庫而卡死。
//   ③ **本謂詞是「再加一層」,既有排除邏輯全部原封保留**(STAGE_ONLY_SUBJECTS 排除、
//      五下自然前綴排除等一行未動)。GM 開關只能「再關掉」,不能「打開本來就該擋的」。
// ════════════════════════════════════════════════════════════════════════════
window._lxpsQuizVisible = function(subject, scene){
  try{
    if(!subject || !scene) return true;
    var _d = window._quizVisCfg;
    if(!_d || !_d.hidden) return true;
    var _list = _d.hidden[scene];
    if(!Array.isArray(_list) || _list.length === 0) return true;
    return _list.indexOf(subject) < 0;
  }catch(_e){ return true; }
};
// 方便各處直接過濾一整包題目(題目物件 → 讀 q.subject)
window._lxpsQuizItemVisible = function(q, scene){
  try{ return window._lxpsQuizVisible(q && q.subject, scene); }catch(_e){ return true; }
};
