// 啟動時:同步按鈕視覺到當前 _artStyle、套用畫風
function _initArtStyleUI(){
  try{
    const _cute = document.getElementById('art-style-cute-btn');
    const _prem = document.getElementById('art-style-premium-btn');
    if(_cute) _cute.classList.toggle('selected', _artStyle === 'cute');
    if(_prem) _prem.classList.toggle('selected', _artStyle === 'premium');
  }catch(_){}
  try{ if(typeof _loadHeroPortraitChoiceLocal === 'function') _loadHeroPortraitChoiceLocal(); }catch(_){}
  // ★ v1.0.20260501.4720 — 載入每日免費召喚記錄
  try{ if(typeof _loadDailyFreeSummonDate === 'function') _loadDailyFreeSummonDate(); }catch(_){}
  // 延遲套用,確保 HERO_IMGS / PET_DB / HERO_PORTRAIT_LIBRARY 都已載入
  if(_artStyle === 'premium'){
    setTimeout(()=>{ try{ _applyArtStyle(); }catch(_){} }, 100);
  } else {
    document.body.classList.add('art-cute');
  }
  // ★ v1.0.20260424.0400 — 啟動後預載精美版圖,讓首次切換體驗更順暢
  setTimeout(_preloadPremiumArt, 2000);
}

let _premiumArtPreloaded = false;
function _preloadPremiumArt(){
  if(_premiumArtPreloaded) return;
  _premiumArtPreloaded = true;
  const _urls = [];
  try{
    // BOSS 精美版
    if(typeof _PREMIUM_ART_OVERRIDE !== 'undefined'){
      ['hero','mob','pet','portrait','shop'].forEach(cat => {
        const map = _PREMIUM_ART_OVERRIDE[cat];
        if(!map) return;
        Object.values(map).forEach(url => { if(url) _urls.push(url); });
      });
    }
    // 場景背景圖(7 個 + 4 個選角頁)
    const _premiumScenes = [
      './%E9%81%8A%E6%88%B2%E9%A6%96%E9%A0%81(%E7%B2%BE%E7%BE%8E%E7%89%88).png',
      './%E5%8A%9B%E8%A1%8C%E6%A0%A1%E9%96%80%E5%8F%A3(%E7%B2%BE%E7%BE%8E%E7%89%88).png',
      './%E8%87%AA%E7%84%B6%E6%95%99%E5%AE%A4(%E7%B2%BE%E7%BE%8E%E7%89%88).png',
      './%E6%99%AF%E7%BE%8E%E6%BA%AA%E6%B2%B3%E5%A0%A4(%E7%B2%BE%E7%BE%8E%E7%89%88).png',
      './%E6%A8%9F%E6%B9%96%E6%AD%A5%E9%81%93(%E7%B2%BE%E7%BE%8E%E7%89%88).png',
      './%E8%B2%93%E7%A9%BA%E8%8C%B6%E5%9C%92(%E7%B2%BE%E7%BE%8E%E7%89%88).png',
      './%E6%93%8D%E5%A0%B4(%E7%B2%BE%E7%BE%8E%E7%89%88).png',
    ];
    _urls.push(..._premiumScenes);
    // LV10/LV20/3 號圖 portrait(從 HERO_PORTRAIT_LIBRARY)
    if(typeof HERO_PORTRAIT_LIBRARY !== 'undefined'){
      Object.keys(HERO_PORTRAIT_LIBRARY).forEach(name => {
        (HERO_PORTRAIT_LIBRARY[name]||[]).forEach(p => {
          if(p && p.url && /(_lv10$|_lv20$|_shop3$|3\.png|2\.png)/.test(p.id||'') ){
            _urls.push(p.url);
          }
          if(p && p.url && /3\.png/.test(p.url)) _urls.push(p.url);
        });
      });
    }
    // 去重
    const _unique = Array.from(new Set(_urls.filter(Boolean)));
    console.log('[精美版預載] 開始下載 ' + _unique.length + ' 張圖...');
    let _loaded = 0;
    _unique.forEach(url => {
      const img = new Image();
      img.onload = () => {
        _loaded++;
        if(_loaded === _unique.length){
          console.log('[精美版預載] 完成 ' + _loaded + ' / ' + _unique.length);
        }
      };
      img.onerror = () => { _loaded++; };
      img.src = url;
    });
  }catch(_e){ console.warn('[精美版預載] 失敗:', _e); }
}
// 在 DOM 載入後初始化(_artStyle 已從 localStorage 讀取)
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', _initArtStyleUI);
} else {
  setTimeout(_initArtStyleUI, 0);
}

// 玩家已解鎖的替代肖像：{heroName: [portraitId, ...]}（不含 'default'，default 永遠解鎖）
let _heroPortraitUnlocked = {};
// 玩家目前使用的肖像：{heroName: portraitId}；未記錄者 = 'default'
let _heroPortraitChoice = {};

// 套用目前選擇的肖像到 HERO_IMGS（遊戲啟動 / 存檔載入時呼叫）
function _applyHeroPortraitChoices(){
  if(typeof HERO_IMGS === 'undefined') return;
  const _isPrem = (typeof _artStyle !== 'undefined' && _artStyle === 'premium');
  Object.keys(HERO_PORTRAIT_LIBRARY).forEach(name => {
    // ★ v5520 — 先判斷「玩家是否明確選擇過此英雄的肖像」
    const _hasExplicitChoice = Object.prototype.hasOwnProperty.call(_heroPortraitChoice, name)
                            && typeof _heroPortraitChoice[name] === 'string'
                            && _heroPortraitChoice[name].length > 0;
    // 精美畫風 + 玩家未選擇 + 在 mob 精美覆蓋表中 → 跳過,讓 _applyArtStyle 設好的精美 BOSS 留著
    if(_isPrem && !_hasExplicitChoice && typeof _PREMIUM_ART_OVERRIDE !== 'undefined'
       && _PREMIUM_ART_OVERRIDE.mob && _PREMIUM_ART_OVERRIDE.mob[name]){
      return;
    }
    // 同樣條件:精美畫風 + 未選擇 + hero 精美覆蓋表中 → 跳過
    if(_isPrem && !_hasExplicitChoice && typeof _PREMIUM_ART_OVERRIDE !== 'undefined'
       && _PREMIUM_ART_OVERRIDE.hero && _PREMIUM_ART_OVERRIDE.hero[name]){
      return;
    }
    const lib = HERO_PORTRAIT_LIBRARY[name];
    let choice;
    if(_hasExplicitChoice){
      // 玩家明確選了某個肖像(包括選 'default' 想看原始 Q 版) → 絕對尊重
      choice = _heroPortraitChoice[name];
    } else {
      // 玩家從未選擇 → 走 default
      choice = 'default';
      // 精美畫風 + 玩家從未選擇 → 自動套用「已解鎖的最高等級精美版」(LV20 > LV10 > 商店3)
      if(_isPrem){
        try{
          const _unlocked = (typeof _heroPortraitUnlocked !== 'undefined' && _heroPortraitUnlocked[name]) || [];
          const _findByPattern = (pattern) => {
            const entry = lib.find(p => p.id && pattern.test(p.id) && _unlocked.includes(p.id));
            return entry ? entry.id : null;
          };
          const _bestId = _findByPattern(/_lv20$/) || _findByPattern(/_lv10$/) || _findByPattern(/_shop3$/);
          if(_bestId) choice = _bestId;
        }catch(_){}
      }
    }
    const entry = lib.find(e => e.id === choice) || lib.find(e => e.id === 'default');
    if(entry) HERO_IMGS[name] = entry.url;
  });
}
// 切換肖像（使用者從英雄圖鑑點擊時呼叫）
function _switchHeroPortrait(heroName, portraitId){
  const lib = HERO_PORTRAIT_LIBRARY[heroName];
  if(!lib) return false;
  const entry = lib.find(e => e.id === portraitId);
  if(!entry) return false;
  // 檢查解鎖狀態
  if(entry.requiresUnlock && !((_heroPortraitUnlocked[heroName]||[]).includes(portraitId))){
    return false;
  }
  _heroPortraitChoice[heroName] = portraitId;
  HERO_IMGS[heroName] = entry.url;
  // ★ v1.0.20260501.4680 — 立即寫入 localStorage(雲端 save 是 async,本地寫入是同步)
  //   這樣即使雲端 save 失敗或時序問題,重開遊戲時本地依然有最新選擇
  try{ if(typeof _saveHeroPortraitChoiceLocal === 'function') _saveHeroPortraitChoiceLocal(); }catch(_){}
  try{ if(typeof gameCloudSave==='function') gameCloudSave(); }catch(_){}
  return true;
}
// ★ v1.0.20260501.4680 — 本地持久化(雲端 save/load 失敗時的後備)
function _saveHeroPortraitChoiceLocal(){
  try{
    localStorage.setItem('lxps_hero_portrait_choice', JSON.stringify(_heroPortraitChoice||{}));
    localStorage.setItem('lxps_hero_portrait_unlocked', JSON.stringify(_heroPortraitUnlocked||{}));
  }catch(_){}
}
function _loadHeroPortraitChoiceLocal(){
  try{
    const _rawC = localStorage.getItem('lxps_hero_portrait_choice');
    if(_rawC){
      const _c = JSON.parse(_rawC);
      if(_c && typeof _c === 'object') _heroPortraitChoice = _c;
    }
    const _rawU = localStorage.getItem('lxps_hero_portrait_unlocked');
    if(_rawU){
      const _u = JSON.parse(_rawU);
      if(_u && typeof _u === 'object') _heroPortraitUnlocked = _u;
    }
  }catch(_){}
}
// ★ v3.13.47 — 皮膚解鎖紀錄(對應 _heroUnlockHistory 模式)
//   每次新解鎖一個肖像就寫一筆到 localStorage 'lxps_skin_unlock_history',
//   並透過 _buildSafeData → gameCloudSave 同步到雲端 players/{uid}._skinUnlockHistory。
//   用途:① 老師查證學生「我買的皮膚不見了」真假 ② 跨槽/復原時的稽核依據。
//   結構:{ hero, id, source, at, uid }  source: 'shop'|'level'|'admin_grant'|'gift'|...
//   去重:同英雄同肖像只記一筆(保留最早來源),重複呼叫不灌水。
function _logSkinUnlock(hero, id, source){
  try{
    if(!hero || !id) return;
    let _hist = [];
    try{
      const _raw = localStorage.getItem('lxps_skin_unlock_history');
      _hist = _raw ? JSON.parse(_raw) : [];
      if(!Array.isArray(_hist)) _hist = [];
    }catch(_){ _hist = []; }
    if(_hist.some(e => e && e.hero === hero && e.id === id)) return;  // 已記過 → 跳過
    _hist.push({
      hero: hero, id: id, source: source || 'unknown',
      at: Date.now(),
      uid: (window._gUserId || '').slice(0, 12)
    });
    if(_hist.length > 300) _hist = _hist.slice(-300);
    localStorage.setItem('lxps_skin_unlock_history', JSON.stringify(_hist));
  }catch(_){}
}
window._logSkinUnlock = _logSkinUnlock;
// ★ v3.13.48 — 知識幣消費/收入帳本(寫入 _coinTransactions,後台「💰 知識幣帳目」分頁顯示)
//   entry: { at, amount(+收入/-消費), balance(變動後餘額), reason, id, uid }
//   寫入點:① 各大金流點呼叫 _logCoinTx(amount, reason)(變動「之後」呼叫,balance 才正確)
//          ② _buildSafeData 的 _reconcileCoinTx() 對帳補抓「沒被明確記錄」的變動(reason=未分類)
//   保留上限 400 筆;載入完成前(_progressLoaded!==true)不記,避免時序雜訊。
function _logCoinTx(amount, reason){
  try{
    amount = Math.round(Number(amount)||0);
    if(!amount) return;
    if(window._progressLoaded !== true) return;
    let h=[]; try{ const r=localStorage.getItem('lxps_coin_tx'); h=r?JSON.parse(r):[]; if(!Array.isArray(h))h=[]; }catch(_){ h=[]; }
    h.push({ at:Date.now(), amount:amount, balance:(_knowledgeCoins||0), reason:String(reason||'').slice(0,48),
             id:(Date.now().toString(36)+Math.random().toString(36).slice(2,6)), uid:(window._gUserId||'').slice(0,12) });
    if(h.length>400) h=h.slice(-400);
    localStorage.setItem('lxps_coin_tx', JSON.stringify(h));
  }catch(_){}
}
window._logCoinTx = _logCoinTx;
function _reconcileCoinTx(){
  try{
    if(window._progressLoaded !== true) return;
    let h=[]; try{ const r=localStorage.getItem('lxps_coin_tx'); h=r?JSON.parse(r):[]; if(!Array.isArray(h))h=[]; }catch(_){ h=[]; }
    const cur=_knowledgeCoins||0;
    if(!h.length){
      h.push({ at:Date.now(), amount:0, balance:cur, reason:'基準(開始記錄餘額)', id:(Date.now().toString(36)+'base'), uid:(window._gUserId||'').slice(0,12) });
      localStorage.setItem('lxps_coin_tx', JSON.stringify(h)); return;
    }
    const last=h[h.length-1].balance;
    if(typeof last==='number' && cur!==last){
      h.push({ at:Date.now(), amount:cur-last, balance:cur, reason:'(未分類變動)', id:(Date.now().toString(36)+Math.random().toString(36).slice(2,6)), uid:(window._gUserId||'').slice(0,12) });
      if(h.length>400) h=h.slice(-400);
      localStorage.setItem('lxps_coin_tx', JSON.stringify(h));
    }
  }catch(_){}
}
window._reconcileCoinTx = _reconcileCoinTx;

// ★ v3.13.58(2026-06-05)— 召喚水晶帳本(完全鏡像知識幣帳本 _coinTransactions):
//   老師需求:學生常反應「召喚水晶突然消失」,但水晶過去完全沒有交易紀錄 → 無從查證。
//   entry: { at, amount(+獲得/-消費), balance(變動後餘額), reason, id, uid }
//   寫入點:① 各水晶金流點呼叫 _logCrystalTx(amount, reason)(在變動「之後」呼叫,balance 才正確)
//          ② _buildSafeData 的 _reconcileCrystalTx() 用「餘額差」補抓任何沒被明確記錄的變動(reason=未分類變動)
//             → 即使漏掉某些「直接改 _playerBackpack.summon_crystal」的點,餘額對帳也一定抓得到 = 不會有隱形消失。
