    _t.style.cssText = 'position:absolute;left:50%;bottom:64px;transform:translateX(-50%);z-index:31;max-width:88%;'
      + 'background:rgba(12,16,34,0.96);border:2px solid rgba(212,168,67,0.7);border-radius:14px;'
      + 'padding:12px 18px;color:#ffe9b0;font-size:17px;font-weight:800;text-align:center;line-height:1.5;'
