// ★ v5690 — 戰鬥卡片專屬圖片位置表
//   邀請預覽 vs 戰鬥卡片的容器寬高比不同,同樣的 center 42% 在邀請預覽好看,
//   但戰鬥卡片容器更窄會顯得太低,所以分開設定。
//   未列入此表者 fallback 到 getHeroObjPos 取通用位置。
// ★ 已搬至 hero_db.js — HERO_BATTLE_CARD_POS (原 L16484~L16486, 3 行)

function getHeroBattleCardObjPos(name){
  // 戰鬥卡片優先用 HERO_BATTLE_CARD_POS,沒覆寫時 fallback 到 getHeroObjPos
  if(HERO_BATTLE_CARD_POS[name]) return HERO_BATTLE_CARD_POS[name];
  return (typeof getHeroObjPos === 'function') ? getHeroObjPos(name) : 'center 20%';
}

function _getCurPortraitObjPos(name){
  try{
    const choice = (typeof _heroPortraitChoice !== 'undefined' && _heroPortraitChoice[name]) || 'default';
    if(choice !== 'default' && typeof HERO_PORTRAIT_LIBRARY !== 'undefined'){
      const lib = HERO_PORTRAIT_LIBRARY[name];
      if(lib){
        const entry = lib.find(e => e.id === choice);
        if(entry && entry.objPos) return entry.objPos;
      }
    }
  }catch(_){}
  return null;
}
function getHeroObjPos(name){
  const _override = _getCurPortraitObjPos(name);
  if(_override){
    const parts = _override.split(' ');
    return 'center ' + (parts[1] || parts[0] || '20%');
  }
  // 精美畫風自動偵測
  if(typeof _artStyle !== 'undefined' && _artStyle === 'premium'){
    try{
      // ★ v1.0.20260424.0440 — 若 HERO_IMGS 已換成精美版,優先讀對應 portrait 的個別 objPos
      //   讓特定角色(木靈使 Lv10 上移、時空法師 Lv20 下移等)能客製化裁切位置
      const _lib = (typeof HERO_PORTRAIT_LIBRARY !== 'undefined') ? HERO_PORTRAIT_LIBRARY[name] : null;
      const _curUrl = (typeof HERO_IMGS !== 'undefined') ? HERO_IMGS[name] : '';
      if(_lib && _curUrl){
        const _curEntry = _lib.find(p => p.url === _curUrl);
        if(_curEntry && _curEntry.objPos){
          const parts = _curEntry.objPos.split(' ');
          return 'center ' + (parts[1] || parts[0] || '20%');
        }
      }
      // fallback:default 'center 20%'
      const _hasPremiumOverride =
        (typeof _PREMIUM_ART_OVERRIDE !== 'undefined' && _PREMIUM_ART_OVERRIDE.mob && _PREMIUM_ART_OVERRIDE.mob[name]) ||
        (typeof _PREMIUM_ART_OVERRIDE !== 'undefined' && _PREMIUM_ART_OVERRIDE.hero && _PREMIUM_ART_OVERRIDE.hero[name]);
      const _arenaCovered = (typeof _arenaPremiumApplied !== 'undefined' && _arenaPremiumApplied);
      if(_hasPremiumOverride || _arenaCovered) return 'center 20%';
      if(_lib && _curUrl){
        const _matchPremium = _lib.find(p => (p.id||'').match(/_lv10$|_lv20$|_shop3$/) && p.url === _curUrl);
        if(_matchPremium) return 'center 20%';
      }
    }catch(_){}
  }
  const pos = HERO_IMG_POS[name] || ['160% auto','center 12%'];
  const parts = pos[1].split(' ');
  const vert = parts[1] || '12%';
  return 'center ' + vert;
}

// ★ v3.15.68 — 英雄編組頁(左側列表 + 右側預覽)專屬圖片 Y 微調
//   只影響編組頁,不動戰鬥卡/圖鑑/其他頁面(getHeroObjPos / getHeroThumbObjPos / HERO_IMG_POS 本體不變)。
//   ★ v3.15.71 — 加 where 參數分離 grid(編組選單左列縮圖)/ preview(右半部預覽詳情):
//     拘留者 / 科學發明家:grid -20、preview -20;電腦老師:grid -20、preview -10;機關王雙人組:grid 0、preview -10。
//     負值=往上(露出更多頭部);grid base 多為 'center center'(無%)→ 函式內視為 50% 再加偏移。
function _teamFormAdjustObjPos(name, baseObjPos, where){
  // ★ v3.15.71 — where 區分:'grid'(編組選單左列縮圖,base 多為 center center)|'preview'(右半部預覽詳情/戰鬥預覽)。未指定→'preview'(沿用舊行為)。
  //   負值=往上(露出更多頭部);grid 與 preview 可給不同 Y 偏移。
  const _ADJ = {
    '拘留者':       { grid:-20, preview:-20 },
    '科學發明家':   { grid:-20, preview:-20 },
    '機關王雙人組': { grid:0,   preview:-10 },
    '電腦老師':     { grid:-20, preview:-10 },
    '偵探':         { grid:-20, preview:-20 },
    // ★ v4.17.0 — 老師指定:左列(grid)高度Y減少20%(負值=往上露出更多頭部)
    '大天狗':       { grid:-20, preview:0 },
    '酒吞童子':     { grid:-20, preview:0 },
    '玉藻前':       { grid:-20, preview:0 },
    '暗魔將·血':    { grid:-20, preview:0 },
    '地府酋長':     { grid:-20, preview:0 },
    '鐵匠':         { grid:-20, preview:0 },
    '大刀勇士':     { grid:-40, preview:0 },   // ★ v5.85.0 舊值 grid:-20(v4.17.0)保留備查
    // ★ v4.17.0 — 左列-20% 且 右側預覽(preview)高度Y減少20%
    '魔術師':       { grid:-20, preview:-20 },
    // ★ v5.85.0(2026-08-19·老師截圖裁定)— 左列縮圖再往上 20%(累計 -40%)。
    //   兩位在 v4.17.0 已有 grid:-20,老師本輪是「看著現況截圖」再要求減 20% → 相對再減,故合計 -40。
    //   縮圖基準 = getHeroThumbObjPos → HERO_THUMB_POS 查無 → 'center center'(50%);50-40=10% 仍在有效範圍。
    '聖冥法師':     { grid:-40, preview:-20 },   // 舊值 grid:-20(v4.17.0)保留備查
    // ★ v5.85.0(2026-08-19·老師截圖裁定)— 編組左半頁縮圖「圖片過高、頭部被切」統一 Y -20%。
    //   老師點名清單 = 該頁 SSR 縮圖中「除了 麻吉喵‧Nico 與 主角 以外」全部;
    //   ★ 諸葛亮特別指定 -30%(比其他人再多 10%),且右側預覽(preview)另外 -20%。
    //   以下 11 位縮圖基準皆為 'center center'(50%)→ 50-20=30% / 諸葛亮 50-30=20%,均在有效範圍不留空白。
    '炎火超少女':   { grid:-20, preview:0 },
    '貓人族長':     { grid:-20, preview:0 },
    '幽魂暗狐':     { grid:-20, preview:0 },
    '哪吒':         { grid:-20, preview:0 },
    '楊戩':         { grid:-20, preview:0 },   // ★ v5.293.0 新 SSR(比照中國一梯四位)
    '劉備':         { grid:-20, preview:0 },   // ★ v5.293.0 三國/西遊新 SSR 六位
    '張飛':         { grid:-20, preview:0 },
    '趙雲':         { grid:-20, preview:0 },
    '唐三藏':       { grid:-20, preview:0 },
    '豬八戒':       { grid:-20, preview:0 },
    '沙悟淨':       { grid:-20, preview:0 },
    '孫悟空':       { grid:-20, preview:0 },
    '關羽':         { grid:-20, preview:0 },
    '姜子牙':       { grid:-20, preview:0 },
    '牛魔王':       { grid:-20, preview:0 },
    '呂布':         { grid:-20, preview:0 },
    '蚩尤':         { grid:-20, preview:0 },
    // ★ v5.85.0 — 諸葛亮:老師指定縮圖 -30%,右側預覽另外 -20%
    //   preview 基準 = getHeroObjPos → HERO_IMG_POS['諸葛亮'][1] = 'center 20%' → 20-20 = 0%(切齊頂端·不留空白)
    '諸葛亮':       { grid:-30, preview:-20 },
    // ★ v4.17.0 — 右側預覽高度Y增加10%(正值=往下)
    '御雲使‧沐雲雪': { grid:0, preview:10 },
    '喚龍使‧蜜鶴林': { grid:0, preview:10 },
    // ★ v5.200.0(老師需求)— 十二星神(除了天蠍星神、射手星神以外)左列縮圖與右側預覽高度Y各減少25%
    //   (負值=往上,露出更多頭部;天蠍星神老師確認不調整,維持無 _ADJ 覆寫的原始位置)。
    '牡羊星神': { grid:-25, preview:-25 },
    '金牛星神': { grid:-25, preview:-25 },
    '雙子星神': { grid:-25, preview:-25 },
    '巨蟹星神': { grid:-25, preview:-25 },
    '獅子星神': { grid:-25, preview:-25 },
    '處女星神': { grid:-25, preview:-25 },
    '天秤星神': { grid:-25, preview:-25 },
    '摩羯星神': { grid:-25, preview:-25 },
    '水瓶星神': { grid:-25, preview:-25 },
    '雙魚星神': { grid:-25, preview:-25 },
    // ★ v5.222.0(老師需求)— 射手星神比照其餘十位星神一併調整(左列縮圖與右側預覽高度Y各減少25%);
    //   天蠍星神依老師本輪明確指示維持排除,仍不列入本表(無 _ADJ 覆寫,原始位置)。
    '射手星神': { grid:-25, preview:-25 },
  }[name];
  if(!_ADJ) return baseObjPos;
  const _adj = (where === 'grid') ? _ADJ.grid : _ADJ.preview;
  if(typeof _adj !== 'number' || _adj === 0) return baseObjPos;
  // 解析 base 垂直 %;若 base 無數字%(如 'center center' / 'center')→ 視為 50%
  const _m = String(baseObjPos).match(/(-?\d+(?:\.\d+)?)\s*%/);
  const _baseY = _m ? parseFloat(_m[1]) : 50;
  const _y = _baseY + _adj;
  return 'center ' + _y + '%';
}

