// ★ v3.13.87 — 我的豚豚 S1「軟萌削弱」(_cuteWeaken)疊層:每層攻擊/特技各 -5%(以附加當下的 base 為準,上限 10 層 = -50%)
//   用「加法還原」避免與其他減益快照衝突:status 物件記 _baseAtk/_baseSp/_atkCut/_spCut/_stacks,
//   每次疊層重算 want=floor(base*stacks*5%),只施加增量 delta(小數值靠整數門檻累積),還原時 h.atk+=_atkCut
//   第一層走 addStatus(讓目標自身免疫/反制有機會攔截),後續層直接增量(單次技能內不重複檢查)
function _applyCuteWeakenStack(target){
  if(!target || target.curHp <= 0) return false;
  try{
    let s = (target.status || []).find(x => x.type === '_cuteWeaken');
    if(s){
      if((s._stacks||0) >= 10){ s.dur = Math.max(s.dur||0, 2); try{ renderCard(target); }catch(_){} return false; }
      s._stacks = (s._stacks||0) + 1;
    } else {
      addStatus(target, '_cuteWeaken', 2);
      s = (target.status || []).find(x => x.type === '_cuteWeaken');
      if(!s) return false; // 被目標自身免疫/反制擋下
      s._stacks  = 1;
      s._baseAtk = target.atk;
      s._baseSp  = target.sp;
      s._atkCut  = 0;
      s._spCut   = 0;
    }
    s.dur = Math.max(s.dur||0, 2);
    const wantAtk = Math.floor((s._baseAtk||0) * s._stacks * 0.05);
    const wantSp  = Math.floor((s._baseSp ||0) * s._stacks * 0.05);
    const dAtk = wantAtk - (s._atkCut||0);
    const dSp  = wantSp  - (s._spCut ||0);
    if(dAtk > 0){ const real = Math.min(dAtk, target.atk - 1); if(real > 0){ target.atk -= real; s._atkCut = (s._atkCut||0) + real; } }
    if(dSp  > 0){ const real = Math.min(dSp,  target.sp  - 1); if(real > 0){ target.sp  -= real; s._spCut  = (s._spCut ||0) + real; } }
    try{ renderCard(target); }catch(_){}
    return true;
  }catch(_){ return false; }
}
// ✨ 命星 我的豚豚 s1「軟萌催眠星」:可愛攻攻攻攻攻擊結束時,目標疊滿 10 層 → 睡眠 1 回合(BOSS 改緩速 1 回合)並清空層數(加法還原);同一目標每 3 回合限 1 次
window._cstPigS1Proc = function(a, t){
  try{
    if(!a || !t || t.curHp <= 0) return;
    if(!window._cstHasN(a,'s1','我的豚豚')) return;
    const s = (t.status || []).find(function(x){ return x && x.type === '_cuteWeaken'; });
    if(!s || (s._stacks || 0) < 10) return;
    const r = (typeof G !== 'undefined' && G && G.round) || 0;
    if(typeof t._cstPigSlpR === 'number' && r - t._cstPigSlpR < 3) return;
    const _boss = ((typeof _zeusIsTrueBoss==='function' && _zeusIsTrueBoss(t)) || (typeof _isWorldBossTarget==='function' && _isWorldBossTarget(t)));
    /* 審查:睡眠被免疫擋下時不清層、不進冷卻(下次再試) */
    if(!_boss){ if(window._cstCap.ctrlBlocked(t, true)) return; addStatus(t, 'sleep', 1); if(!hasStatus(t, 'sleep')) return; window._cstCap.markCtrl(t, 'sleep'); }   // ★ v5.262.0 命座 G6:控制抗性中比照「被免疫」:不清層、不進冷卻(審查 L4:quiet,每次受擊不再洗一行紀錄)
    t._cstPigSlpR = r;
    if(s._atkCut){ t.atk += s._atkCut; s._atkCut = 0; }
    if(s._spCut){  t.sp  += s._spCut;  s._spCut  = 0; }
    t.status = (t.status || []).filter(function(x){ return x !== s; });
    if(_boss){
      if(typeof _cstApplySlow === 'function') _cstApplySlow(t, 1);
      log('✨ [' + a.name + '] 命星:軟萌催眠![' + t.name + '] 疊滿 10 層軟萌削弱,BOSS 被萌到變慢(緩速 1 回合),層數歸零');
    } else {
      log('✨ [' + a.name + '] 命星:軟萌催眠![' + t.name + '] 疊滿 10 層軟萌削弱,被萌到睡著 1 回合,層數歸零');
    }
    try{ renderCard(t); }catch(_){}
  }catch(_eCstPigS1){}
};
