    if(h._weakenOrigSp!==undefined){  h.sp=h._weakenOrigSp;   delete h._weakenOrigSp; }
    if(h._weakenOrigSpd!==undefined){ h.spd=h._weakenOrigSpd; delete h._weakenOrigSpd; }
