  try{ _restoreStatDebuffOnRemove(h, (h.status||[]).filter(s=>s && BAD_STATUS.includes(s.type) && s.type!=='strongTaunt' && s.type!=='_youyouNightmare' && !s._strong)); }catch(_){}
