  h.status=h.status.filter(s=>!BAD_STATUS.includes(s.type) || s.type==='strongTaunt' || s.type==='_youyouNightmare' || (s._strong && !s._dajiCharm));
  if(_cstBdP2) _cstBdB2Post(h, _cstBdP2);
