        console.error('[鬥技場 票進場] 例外', e);
        alert('❌ 例外:' + (e && e.message || '未知錯誤'));
        btnUse.disabled = false;
        btnUse.style.opacity = '1';
        btnUse.textContent = '🎫 使用 1 張入場券';
