// ════════════════════════════════════════════════════════════════════
// ★ v5.91.0（老師 2026-08-20 回報）— 鬥技場 UR 禁用「單一真相」謂詞
//   老師回報：「我看到有人用 UR 角色打鬥技場，我說過鬥技場無法使用 UR 角色。」
//   稽核結果＝規則本身自 v3.13.71 就寫在英雄池過濾裡（allNames 那行的
//   `_getHeroRarity(n) !== 'UR'`），**但只守住「選英雄」這一條路**，另有兩條路完全沒守：
//     ❶ _applyPresetTeam（一鍵套用預設陣容）的合法性檢查整段包在 if(isAdvMode) 裡
//        → 鬥技場模式一行都不檢查；而鬥技場預設陣容 _arenaPresetTeams 是獨立一份、
//        且 v3.13.71 立規之前存下的舊陣容仍留在雲端 → 一鍵套用即可帶 UR 上場。
//     ❷ arena.js 的 _arenaIsTeamValid（上雲前 + 抽對手池 的共同守門）只有三層黑名單
//        （BOSS_NAMES／JAPAN_ARENA_EXCLUDE／EVENT_ONLY_HEROES），**沒有 UR 這層**
//        → 髒陣容照樣上雲、也照樣被抽出來當對手 ＝ 老師看到「別人用 UR」的最可能來源。
//   ⚠ 判定一律走既有 _getHeroRarity（UR 名單 _RARITY_UR_HEROES 是唯一權威，
//     日後新增 UR 只要加進那個 Set，本謂詞與所有守門自動生效，不必再改任何一處）。
//   ⚠ 讀不到 _getHeroRarity 時退回 window._LXPS_RARITY_UR 陣列（同一份資料的既有投影）；
//     兩者都取不到才回 false —— 刻意「取不到就放行」是為了不讓載入順序問題把玩家鎖在門外，
//     真正的最終保險在 confirmHeroPick／_applyPresetTeam 兩個建隊點（那時一定載入完成）。
// ════════════════════════════════════════════════════════════════════
window._arenaHeroBannedUR = function(name){
  /* ★ v5.227.0 — 改為委派給全檔共用的 `_lxpsIsUR()`(內部仍是同一套 _getHeroRarity → _LXPS_RARITY_UR 退路)。
     本輪冒險模式也開始需要「這隻是不是 UR」(隊伍最多 2 名 UR),兩邊若各寫一份判定遲早會分岔
     —— v5.92.0 的 _pageLabel / _pageLabel2 就是這樣各自演化、學生看到生英文字串的。 */
  try{
    if(typeof window._lxpsIsUR === 'function') return window._lxpsIsUR(name);
    if(!name) return false;
    if(typeof window._getHeroRarity === 'function'){
      return window._getHeroRarity(name) === 'UR';
    }
    if(Array.isArray(window._LXPS_RARITY_UR)){
      return window._LXPS_RARITY_UR.indexOf(name) >= 0;
    }
  }catch(_e){ try{ console.warn('[鬥技場 UR 守門]', _e); }catch(_){} }
  return false;
};
// 便利版：回傳陣容中所有違規的 UR 名字（空陣列＝合法）。三個守門點共用。
window._arenaListBannedUR = function(names){
  var _bad = [];
  try{
    (names || []).forEach(function(n){
      if(window._arenaHeroBannedUR(n)) _bad.push(n);
    });
  }catch(_e){}
  return _bad;
};

// ════════════════════════════════════════════════════════════════════
// ★ v5.91.0（老師 2026-08-20 裁定甲）— 鬥技場「開始整裝」音效單一真相
//   sfx-adv-start（開始整裝.mp3）原為冒險關卡「開始整隊，踏上冒險之旅」的出發音，
//   老師裁定改為鬥技場專用：只在按下「單人挑戰／開始對戰」開戰那一刻播放。
//   參數與冒險端原碼一字不差（音量 0.7 → 2 秒後每 100ms 減 0.1 淡出、淡完 pause）。
//   ⚠ 刻意不走 playSfx()：playSfx 會再乘 0.49 基準與 _sfxUserVol，響度會比原本低一半以上；
//     此處沿用原本「直接操作 <audio> 元素」的寫法以維持老師熟悉的音量。
//   ⚠ 尊重靜音：_sfxMuted 為 true 時直接不播（原冒險端未檢查，本輪順手補上）。
//   ⚠ 任何例外一律靜默吞掉，絕不阻擋開戰流程。
// ════════════════════════════════════════════════════════════════════
window._arenaPlayGearUpSfx = function(){
  try{
    if(typeof _sfxMuted !== 'undefined' && _sfxMuted) return;
    const _el = document.getElementById('sfx-adv-start');
    if(!_el) return;
    if(_el._lxpsFadeIv){ clearInterval(_el._lxpsFadeIv); _el._lxpsFadeIv = null; }
    if(_el._lxpsFadeTo){ clearTimeout(_el._lxpsFadeTo); _el._lxpsFadeTo = null; }
    _el.currentTime = 0;
    _el.volume = 0.7;
    _el.play().catch(function(){});
    _el._lxpsFadeTo = setTimeout(function(){
      let _vol = _el.volume;
      _el._lxpsFadeIv = setInterval(function(){
        _vol = Math.max(0, _vol - 0.1);
        try{ _el.volume = _vol; }catch(_){}
        if(_vol <= 0){
          clearInterval(_el._lxpsFadeIv); _el._lxpsFadeIv = null;
          try{ _el.pause(); }catch(_){}
        }
      }, 100);
    }, 2000);
  }catch(_e){ try{ console.warn('[鬥技場 開始整裝音效]', _e); }catch(_){} }
};

function _arenaStartSoloBattle(){
  // ★ v3.14.6 — PvP 殘留清理:玩家直接點「單人挑戰」時,若殘留未開打的 _pvpCtx
  //   (例如先前在雙人決鬥編組中途退出),一律清除,避免單機戰被 PvP 握手閘門誤攔。
  //   PvP 自身走本管線時用 _pvpExpectPipeline 一次性旗標放行。
  try{
    if(window._pvpExpectPipeline){ window._pvpExpectPipeline = false; }
    else if(window._pvpCtx && !window._pvpCtx.battleLive){
      console.warn('[鬥技場開戰] 清除殘留 PvP context');
      window._pvpCtx = null;
    }
  }catch(_ePvpClean){}
  try{
    // ★ v3.13.41(2026-06-04) — 同 _arenaStartFromMenu:改用 _arenaCanBattle 判斷已載入
    //   (window._arenaLoaded 從未被賦值,舊檢查永遠 fallback 到 initGame)
    if(typeof window._arenaCanBattle !== 'function'){
      console.warn('[鬥技場開戰] arena.js 未載入(_arenaCanBattle 不存在),直接進原流程');
      initGame();
      return;
    }
    // ★ v3.13.20 — 重置玩家總傷害累計(供 GM 戰鬥記錄審核用)
    try{ window._arenaP1DmgDealt = 0; }catch(_){}
    // ★ v3.15.54 — 同步重置「逐回合×逐英雄×技能」明細收集(防上一場殘留;若 G 由 initGame 重建亦無妨)
    try{ if(typeof G !== 'undefined' && G) G._arenaDmgSources = []; }catch(_){}
    // ★ v3.15.61 — 重置鬥技場高階獎章追蹤(無須療傷 / 閃電雙殺)
    try{ window._arenaUsedHeal = false; window._arenaKillLog = []; }catch(_){}
    // 1. 檢查今日場次上限
    const _stats = window._arenaGetStatsForUI();
    // ★ v3.13.32(2026-06-03) — 老師需求 A:若是入場券進場(_arenaBypassDailyLimit=true),跳過上限檢查
    //   旗標在 _arenaShowUseTicketPrompt 使用入場券成功後立起,進來後立即清(避免下次誤用)
    const _bypassLimit = (window._arenaBypassDailyLimit === true);
    if(_bypassLimit){
      try{ window._arenaBypassDailyLimit = false; }catch(_){}
      console.log('[鬥技場開戰] 入場券進場,跳過每日上限檢查');
    }
    if(!_bypassLimit && !window._arenaCanBattle()){
      // ★ v3.13.32(2026-06-03) — 老師需求 A:今日場次用完時,若持有入場券就提供使用選項
      //   (admin 不會走進這分支,_arenaCanBattle 對 admin 永遠 true)
      const _tkN = (typeof window._arenaGetMyTicketCount === 'function')
        ? window._arenaGetMyTicketCount() : 0;
      if(_tkN > 0){
        // 有券:跳「使用入場券」彈窗
        _arenaShowUseTicketPrompt(_tkN, _stats);
        return;
      }
      // 沒券:照舊提示
      try{
        if(typeof _showInGameToast === 'function'){
          _showInGameToast(
            '⚔ 今日鬥技場場次已用完(' + _stats.todayBattleLimit + '/' + _stats.todayBattleLimit + ')\n\n明天再來挑戰吧!\n📊 今日戰績:勝 ' + _stats.todayWins
            + ' 平 ' + _stats.todayDraws + ' 敗 ' + _stats.todayLosses
            + '\n🎖 鬥技之證累積:' + _stats.zhengTotal,
            '#ffaa66', 5000);
        } else {
          alert('今日鬥技場場次已用完!明天再來挑戰吧!');
        }
      }catch(_eToast){ console.warn(_eToast); }
      return;
    }
    // 2. 顯示今日剩餘場次提示(非阻擋,僅資訊)
    try{
      const _btnInfo = document.getElementById('adv-arena-daily-info');
      if(_btnInfo){
        _btnInfo.textContent = '今日剩 ' + (_stats.todayBattleLimit - _stats.todayBattles)
          + '/' + _stats.todayBattleLimit + ' 場 · 累積鬥技之證 ' + _stats.zhengTotal;
      }
    }catch(_eInfo){}
    // ★ v5.91.0（老師 2026-08-20 裁定甲）— 「開始整裝」音效搬家到鬥技場。
    //   原本這支 sfx-adv-start（開始整裝.mp3）掛在冒險關卡的 startAdventureGame，
    //   老師裁定：所有冒險關卡不再使用，改成只在鬥技場開戰時出現。
    //   ★ 刻意掛在「函式內、通過場次檢查之後」而非按鈕的 onclick：
    //     ①單點涵蓋三條開戰入口（主頁「單人挑戰」鈕／入場券進場／PvP 雙人決鬥管線），
    //       日後任何新入口只要走本函式就自動有聲，不必逐顆按鈕接線。
    //     ②今日場次用完被擋下、或 arena.js 未載入時不會誤放（那兩條在上面已 return）。
    //   ⚠ 進入戰鬥畫面那一聲是另一支 playBattleStartSfx（sfx-battle-start・開始進攻.mp3），
    //     由既有 startBattle／預設陣容路徑負責，本輪一行未動 → 兩個時機各一首、不重疊。
    //   音量與淡出完全沿用冒險端原參數（0.7 起、2 秒後每 100ms 減 0.1 淡出）。
    try{ if(typeof window._arenaPlayGearUpSfx === 'function') window._arenaPlayGearUpSfx(); }catch(_eGearUp){}
    // 3. 進入鬥技場(走既有 initGame)
    //    場次計數在「真正開戰」時才 +1,避免進選角又離開就被扣場次
    //    所以這裡只清旗標,場次 +1 在 startTurn / confirmHeroPick 鬥技場分支處理
    window._arenaBattleStartPending = true;  // 標記:下次 startTurn 觸發 +1
    try{ if(G){ delete G._arenaResultShown; delete G._arenaRewardGranted; } }catch(_){}
    window._arenaLastResultDraw = false;
    // ★ v3.13.21 — 關閉主頁 overlay(進選英雄頁前)
    try{ _closeArenaLobby(true); }catch(_){}  // true = 保留 BGM(主頁→選英雄共用 BGM)
    // ★ v3.13.41(2026-06-04) — BGM 保險:確保進「英雄編組」前一定是鬥技場 BGM(老師需求:
    //   編組 BGM 要和冒險模式區分、採用鬥技場原本 BGM)。正常 lobby→solo 流程 lobby 已設好,
    //   但萬一是其他路徑(如入場券)進來,這裡再保險設一次(idempotent)。
    try{
      window._arenaBgmContext = true;
      if(typeof bgmPlayArenaLobby === 'function') bgmPlayArenaLobby();
      else if(typeof bgmPlay === 'function') bgmPlay('bgm-arena-lobby');
    }catch(_eArenaSoloBgm){ console.warn('[鬥技場開戰] BGM 保險失敗', _eArenaSoloBgm); }
    // ★ v3.13.15(2026-06-02) — 鬥技場每回合答題:預先準備題庫(混合所有科目)
    try{
      if(typeof ADV_QUIZ_DB !== 'undefined' && Array.isArray(ADV_QUIZ_DB) && ADV_QUIZ_DB.length){
        // ★★ v5.66.0(老師 2026-08-18 裁定)— 鬥技場題庫排除「關卡/活動專屬題庫」★★
        //   老師原話:「鬥技題庫一起修不要外洩測試期內容。」
        //   舊碼 _arenaQuizPool = ADV_QUIZ_DB.slice() 完全沒過濾 → 中國關 200 題(當時測試期未公開)
        //   與日本關 150 題/埃及 30 題都會在鬥技場答題出現,等同繞過鐵律 1.234 的知識王防線。
        //   改走 _isStageOnlySubject 單一真相點(與 _kingGetSubjects 完全同口徑)→ 日後新關卡
        //   只要在 STAGE_ONLY_SUBJECTS 加一項,知識王與鬥技場雙處同時生效。
        //   ⚠ 「台灣環島」500 題**保留在池內**(v5740 老師裁定納入科目池,非關卡專屬排除對象)。
        //   (原 v3.13.15 版本保留備查:const _arenaQuizPool = ADV_QUIZ_DB.slice(); )
        const _arenaQuizPool = ADV_QUIZ_DB.filter(function(_q){
          if(!_q) return false;
          if(typeof _isStageOnlySubject === 'function' && _isStageOnlySubject(_q.subject)) return false;
          // ★ v5.116.0 — 再加一層 GM 可見性開關(既有 STAGE_ONLY 排除原封保留)
          if(typeof window._lxpsQuizItemVisible === 'function' && !window._lxpsQuizItemVisible(_q, 'arena')) return false;
          return true;
        });
        // Fisher-Yates 洗牌
        for(let _qi = _arenaQuizPool.length - 1; _qi > 0; _qi--){
          const _qj = Math.floor(Math.random() * (_qi + 1));
          [_arenaQuizPool[_qi], _arenaQuizPool[_qj]] = [_arenaQuizPool[_qj], _arenaQuizPool[_qi]];
        }
        if(typeof _advSessionQuestions !== 'undefined'){
          _advSessionQuestions = _arenaQuizPool;
        }
        if(typeof _advQuestionPool !== 'undefined'){
          _advQuestionPool = _arenaQuizPool;
        }
        if(typeof _advUsedQuestionIds !== 'undefined'){
          _advUsedQuestionIds = new Set();
        }
        // 鬥技場用「綜合」難度設定:沒科目限定(advPickQuestion default 分支會走全 pool 隨機)
        try{ _advPlayerSubject = ''; }catch(_){}
        try{ _advPlayerDifficulty = '普通'; }catch(_){}  // 3 選項中等難度
        console.log('[鬥技場] 題庫初始化完成,共 ' + _arenaQuizPool.length + ' 題(已排除關卡/活動專屬題庫,原始 ' + ADV_QUIZ_DB.length + ' 題)');
      }
    }catch(_eArenaQ){ console.warn('[鬥技場 題庫初始化] 例外', _eArenaQ); }
    // 雲端陣容池預抓取(背景非同步,選角頁開啟前就先暖快取)
    try{ if(typeof window._arenaFetchTeamPool === 'function') window._arenaFetchTeamPool().catch(()=>{}); }catch(_){}
    initGame();
  }catch(e){
    console.error('[鬥技場開戰] 例外,fallback initGame()', e);
    try{ initGame(); }catch(_){}
  }
}
window._arenaStartSoloBattle = _arenaStartSoloBattle;

function initGame(){
  // ★ v1.1.0 — 標記遊戲已開始,啟動方向監聽(手機直立時自動顯示提示)
  window._gameInitialized = true;
  try{ window._burstCastActive = false; window._burstWatch = null; }catch(_){}   // ★ v5.305.0 新戰鬥不繼承上一場卡住的「爆發施放中」
  try{
    if(typeof window._setupOrientationWatcher === 'function'){
      window._setupOrientationWatcher();
      // 立刻檢查一次方向
      if(typeof window._isMobileDevice === 'function' && window._isMobileDevice()){
        if(typeof window._isPortrait === 'function' && window._isPortrait()){
          window._showPortraitReminder();
        }
      }
    }
  }catch(_){}
  // ★ 防護：清除任何殘留的冒險模式狀態
  try{
    const _gcI = document.getElementById('gc');
    if(_gcI) _gcI.classList.remove('adv-battle');
    // 清除殘留 overlay
    ['adv-cutscene-overlay','adv-boss-detail-pop','adv-mini-result'].forEach(id=>{
      const el=document.getElementById(id);
      if(el){ el.classList && el.classList.remove('show'); if(el.id==='adv-boss-detail-pop') el.remove(); }
    });
  }catch(_){}
  // ★ 返回正常戰鬥練習模式時，重置冒險模式旗標
  if(typeof _adventureMode !== 'undefined'){ _adventureMode = false; _adventureStage = null; }
  if(typeof exitAdventureMode === 'function'){ exitAdventureMode(); }
  // ★ 清除所有可能殘留的戰鬥/冒險狀態
  if(typeof _advMiniBattleActive !== 'undefined') _advMiniBattleActive = false;
  if(typeof _isAdventurePickMode !== 'undefined') window._isAdventurePickMode = false;
  try{
    // 關閉所有overlay，確保乾淨狀態
    ['elem-pick-overlay','skill-replace-overlay','adv-cutscene-overlay',
     'hero-pick-overlay','adv-result-overlay','adv-hero-meet-overlay',
     'battle-start-overlay','hero-page-overlay','hero-detail-overlay',
     'login-gate-modal'].forEach(id=>{
      const el=document.getElementById(id);
      if(el){ el.style.display='none'; el.classList && el.classList.remove('show'); }
    });
    // 移除戰鬥class
    const gc=document.getElementById('gc');
    if(gc){ gc.classList.remove('adv-battle'); }
    // 停止所有BGM
    bgmStop();
    ['bgm-adv-scene','bgm-battle-01','bgm-battle-02','bgm-battle-03',
     'bgm-battle-04','bgm-battle-05','bgm-boss-02'].forEach(id=>{
      const el=document.getElementById(id);
      if(el){ try{el.pause();el.currentTime=0;}catch(_){} }
    });
  }catch(_){}
  // 切換回首頁音樂（無論從結果畫面或首頁按鈕進入）
  if(typeof bgmFadeTo==='function') bgmFadeTo('bgm-menu-01',500);
  document.getElementById('overlay').style.display='none';
  document.getElementById('result-overlay').style.display='none';
  fieldCards=[];
  updateFieldFX();
  G={
    p1:[],p2:[],
    energy:{p1:2,p2:2},
    inv:[null,null,null],
    inv2:[null,null,null],
    deck:[],
    activeChar:null,
    selMove:null,selItem:null,
    pendingTarget:null,
    taunted:null,
    lastSkill:null,
    lastSkillByHero:{},   // {heroKey: skName} 記錄每位英雄上一次用的技能
    comboFatigueByHero:{},// {heroKey: 疲勞層數}       // 連招疲勞層數
    dmgUp:[],
    guardFor:null,
    gunnerTarget:null,
    alchemist_s2_used:false,
    waitFor:null,
    passiveInterruptUsed:false,
    interruptTarget:null,
    sellUsed:new Set(),
    battleStats:{},
    lastSkillName:null,   // 上一次使用的技能名
    comboFatigue:0,       // 累積的連招疲勞層數 // key: hero name → {dmg, heal, statusCount, hitsReceived, side, av}
  };
  buildDeck();
  fadeTransition(()=>{ showHeroPickOverlay(); }, 350);
}

