function getElemData(elemKey){ return elemKey ? ELEMENT_DB[elemKey] : null; }

function elemIcon(elemKey){
  if(!elemKey) return '';
  const e=ELEMENT_DB[elemKey];
  return e ? `<span class="elem-badge ${e.cls}" title="${e.name}">${e.icon}</span>` : '';
}

function applyElemBonus(h){
  const e=getElemData(h.element);
  if(!e) return;
  if(e.bonus_hp){ h.hp+=e.bonus_hp; h.curHp+=e.bonus_hp; }
  if(e.bonus_atk){ h.atk+=e.bonus_atk; }
  if(e.bonus_sp){ h.sp+=e.bonus_sp; }
  if(e.bonus_spd){ h.spd+=e.bonus_spd; }
  // bonus_dmgreduce 在 doDmg 中動態讀取，不需在此修改數值
}

function getElemDmgMod(attacker, target){
  if(fieldHas('balance')) return 0;
  // ★ v1.0.20260421.3017 — 相剋 +10%、劣勢 -10%；元素增幅把 ±10% 提升為 ±20%（取代，不疊加）
  const ae=attacker&&attacker.element, te=target&&target.element;
  if(!ae||!te||ae===te) return 0;
  const aData=ELEMENT_DB[ae];
  if(!aData) return 0;
  const _atkBoost = attacker && (attacker.elemBoost || hasBuff(attacker,'elemBoost'));
  const _defBoost = target   && (target.elemBoost   || hasBuff(target,'elemBoost'));
  if(aData.vs_adv && aData.vs_adv.includes(te)){
    // 相剋增傷：攻擊方元素增幅 → 10% 提升為 20%
    return _atkBoost ? 0.20 : (aData.adv_dmg_pct||0.10);
  }
  if(aData.vs_dis && aData.vs_dis.includes(te)){
    // 劣勢減傷：被攻擊方元素增幅 → -10% 提升為 -20%（對受害者更有利）
    return _defBoost ? -0.20 : (aData.dis_dmg_pct||-0.10);
  }
  return 0;
}

