function getSkillForceElemMod(attacker, target, skillName){
  const result = { elemPct: 0, skillPct: 0, total: 0, forceElem: null };
  // 角色屬性相剋(原本邏輯)
  result.elemPct = getElemDmgMod(attacker, target);
  if(fieldHas('balance')) {
    result.total = result.elemPct;
    return result;
  }
  // ★ v1.0.20260424.1080 — 優先檢查 SKILL_RANDOM_ELEMENTS:每次呼叫都隨機選一個
  let fe = null;
  if(skillName && SKILL_RANDOM_ELEMENTS[skillName]){
    const _pool = SKILL_RANDOM_ELEMENTS[skillName];
    if(Array.isArray(_pool) && _pool.length > 0){
      fe = _pool[Math.floor(Math.random() * _pool.length)];
    }
  }
  // 沒有 RANDOM 才看 FORCE
  if(!fe && skillName && SKILL_FORCE_ELEMENT[skillName]){
    fe = SKILL_FORCE_ELEMENT[skillName];
  }
  // 兩者都沒有 → 只有角色屬性
  if(!fe) {
    result.total = result.elemPct;
    return result;
  }
  result.forceElem = fe;
  const te = target && target.element;
  if(!te || fe === te) {
    result.total = result.elemPct;
    return result;
  }
  const fData = ELEMENT_DB[fe];
  if(!fData) {
    result.total = result.elemPct;
    return result;
  }
  // 計算技能屬性相剋(技能版額外 +20%)
  if(fData.vs_adv && fData.vs_adv.includes(te)){
    result.skillPct = 0.20;  // 技能屬性相剋:額外 +20%
  } else if(fData.vs_dis && fData.vs_dis.includes(te)){
    result.skillPct = -0.20;  // 技能屬性劣勢:額外 -20%
  }
  result.total = result.elemPct + result.skillPct;
  return result;
}

// ★ v1.0.20260424.1060 — 取得屬性對應顏色(供子彈/光束使用)
//   注意:ELEMENT_DB 只有 7 種主屬性(water/fire/wind/grass/earth/light/dark),
//   ice/thunder 不是獨立屬性,但歷史既有 elemColors 字典有定義(供文學描述用),
//   保留是為了與遊戲其他地方既有 elemColors 字典一致(line ~16627)
const ELEM_COLORS = {
  fire:    '#ff6600',
  water:   '#4488ff',
  grass:   '#44ee44',
  ice:     '#a8eeff',  // 同 elemColors 字典的歷史既定值
  thunder: '#aaff00',  // 同 elemColors 字典的歷史既定值
  light:   '#ffffaa',
  dark:    '#9944cc',
  wind:    '#aaffcc',
  earth:   '#cc8844',
};
function getSkillBeamColor(actor, skillName){
  // ★ v1.0.20260424.1080 — 隨機屬性技能:每次呼叫都隨機選一個顏色
  if(skillName && SKILL_RANDOM_ELEMENTS && SKILL_RANDOM_ELEMENTS[skillName]){
    const _pool = SKILL_RANDOM_ELEMENTS[skillName];
    if(Array.isArray(_pool) && _pool.length > 0){
      const _fe = _pool[Math.floor(Math.random() * _pool.length)];
      return ELEM_COLORS[_fe] || null;
    }
  }
  // 技能強制屬性優先,否則用角色屬性
  if(skillName && SKILL_FORCE_ELEMENT[skillName]){
    const fe = SKILL_FORCE_ELEMENT[skillName];
    return ELEM_COLORS[fe] || null;
  }
  if(actor && actor.element){
    return ELEM_COLORS[actor.element] || null;
  }
  return null;
}

function checkElemImmune(h, statusType){
  if(fieldHas('balance')) return true;
  const e=getElemData(h.element);
  if(!e||!e.immune50) return false;
  if(!e.immune50.includes(statusType)) return false;
  // ★ v1.0.20260421.3017 — 元素增幅：對應元素的不利狀態抵抗 50% → 100%
  const _hasBoost = h && (h.elemBoost || (typeof hasBuff==='function' && hasBuff(h,'elemBoost')));
  const _rate = _hasBoost ? 1.0 : 0.5;
  if(Math.random() < _rate){
    log(`[${h.name}] 元素免疫觸發（${ELEMENT_DB[h.element].name}${_hasBoost?'・增幅':''}）！免疫 ${statusName(statusType)}！`);
    playSfx('sfx-resist',0.75);
    showPopup(h,'抵抗','miss');
    return true;
  }
  return false;
}

