function epSelectElem(key){
  window._epPickKey=key;
  const e=ELEMENT_DB[key];
  playSfx('sfx-charsel',0.75);
  document.querySelectorAll('.ep-node').forEach(n=>n.classList.remove('ep-selected'));
  const nd=document.getElementById('epn-'+key);
  if(nd) nd.classList.add('ep-selected');
  const ECOLOR={water:'#55bbff',fire:'#ff7733',wind:'#44cc66',grass:'#88bb22',earth:'#aa7733',light:'#ffdd22',dark:'#9944cc'};
  const bc=ECOLOR[key]||'#fff';

  // 中央提示文字改為「英雄名 獲得X屬性加護」
  const _chint=document.getElementById('ep-center-hint');
  if(_chint){
    const heroName = _epHeroes[_epActivePos] ? _epHeroes[_epActivePos].name : '';
    _chint.innerHTML=`<span style="text-shadow:2px 2px 4px rgba(0,0,0,0.75),0px 0px 12px rgba(0,0,0,0.75),-2px -2px 4px rgba(0,0,0,0.75),2px -2px 4px rgba(0,0,0,0.75),-2px 2px 4px rgba(0,0,0,0.75)">${heroName}</span><br><span style="font-size:36px;color:${bc};text-shadow:0 0 20px ${bc}99,2px 2px 4px rgba(0,0,0,0.75),0px 0px 12px rgba(0,0,0,0.75),-2px -2px 4px rgba(0,0,0,0.75),2px -2px 4px rgba(0,0,0,0.75),-2px 2px 4px rgba(0,0,0,0.75)">${e.icon} 獲得${e.name}屬性加護</span>`;
    _chint.style.display='block';
  }

  // 中央「確定」按鈕已刪除，保持隱藏
  const btn=document.getElementById('ep-confirm-btn');
  btn.style.display='none';

  // 右側欄位發光
  document.querySelectorAll('.ep-attr-row').forEach(row=>{
    const isActive = row.id==='epar-'+key;
    row.style.borderColor = isActive ? bc : Object.entries(ECOLOR).find(([k])=>row.id==='epar-'+k)?.[1]+'44'||'rgba(255,255,255,0.1)';
    row.style.boxShadow = isActive ? `0 0 18px ${bc}88,0 0 36px ${bc}33` : '';
    row.style.background = isActive ? `${bc}18` : 'rgba(0,0,0,0.4)';
  });
  document.querySelectorAll('.ep-bless-btn').forEach(btn2=>{
    btn2.style.display = btn2.dataset.key===key ? 'inline-block' : 'none';
  });
}

function epBlessFromPanel(key){
  // 右側「獲得加護」按鈕：等同 confirmElemPick
  window._epPickKey=key;
  confirmElemPick();
  // 重置右側欄位發光
  document.querySelectorAll('.ep-attr-row').forEach(row=>{
    row.style.boxShadow=''; row.style.background='rgba(0,0,0,0.4)';
  });
  document.querySelectorAll('.ep-bless-btn').forEach(btn=>btn.style.display='none');
}

function confirmElemPick(){
  const key=window._epPickKey; if(!key) return;
  playSfx('sfx-coin',0.85);
  const pos=_epActivePos;
  const h=_epHeroes[pos];
  if(!h) return;
  // Remove old element bonus if switching
  if(_epApplied[pos] && _epApplied[pos]!==key){
    // revert old bonus (simple: just record the change; bonus stacking handled by applyElemBonus)
    // For simplicity, re-apply the new one on top (applyElemBonus is additive, so reset stats first)
    const oldKey=_epApplied[pos];
    const oldE=ELEMENT_DB[oldKey];
    if(oldE){
      if(oldE.bonus_hp){ h.hp-=oldE.bonus_hp; h.curHp=Math.min(h.curHp,h.hp); }
      if(oldE.bonus_atk) h.atk-=oldE.bonus_atk;
      if(oldE.bonus_sp) h.sp-=oldE.bonus_sp;
      if(oldE.bonus_spd) h.spd-=oldE.bonus_spd;
    }
  }
  _epAssigned[pos]=key;
  _epApplied[pos]=key;
  h.element=key;
  applyElemBonus(h);
  // 記錄已正式加護的屬性
  if(!window._epConfirmedKeys) window._epConfirmedKeys={};
  window._epConfirmedKeys[key]=true;
  playSfx('sfx-ok',0.7);
  document.getElementById('ep-confirm-btn').style.display='none';
  window._epPickKey=null;
  _epRenderHeroes();
  // Auto-advance to next unassigned hero
  let next=-1;
  for(let i=0;i<_epHeroes.length;i++){
    if(!_epAssigned[i]){ next=i; break; }
  }
  if(next>=0) _epActivateHero(next);
  else {
    // 全部選完：隱藏中間提示訊息
    const _doneHint=document.getElementById('ep-center-hint');
    if(_doneHint) _doneHint.style.display='none';
    _epActivePos=-1;
    document.querySelectorAll('.ep-hero-card').forEach(el=>el.classList.remove('ep-hc-active'));
  }
}

function autoRecommendElem(){
  // ★ 優化後的推薦規則
  // 治療技能（含爆發）
  const HEAL_NAMES = new Set([
    '救贖神光','治癒之風','神聖鎚擊','天堂樂章','賢者之石','持續恢復','神之賜福','慈悲之雨',
    '黃昏詩歌','迷心醫術','治療之光','全體治療','復活術',
    '天籟之音','流浪者之歌','一壺鐵觀音','一壺包種茶','雙小提琴協奏曲','BUG修復'
  ]);
  // BOSS 屬性剋制（貓空主boss是fire）
  const bossBossElem = (G && G.p2 && G.p2.find(h=>h.name==='九尾空貓怪')) ? 'fire' : null;
  // 剋制fire的是water
  // ★ v5.81.0 雷→風正名:earth 的剋制對象原寫 'thunder'(不存在於 ELEMENT_DB)→ 推薦會選到無效元素。
  //   依 ELEMENT_DB 實際相剋(土剋風 vs_adv:['wind'])更正為 wind;thunder 鍵保留為無害 fallback。
  //   舊行備查:const COUNTER_MAP = {fire:'water',water:'wind',wind:'earth',earth:'thunder',thunder:'fire',
  const COUNTER_MAP = {fire:'water',water:'wind',wind:'earth',earth:'wind',thunder:'fire',
                       light:'dark',dark:'light',grass:'fire',ice:'grass'};
  const bossCounter = bossBossElem ? (COUNTER_MAP[bossBossElem]||'water') : 'water';

  const usedElems = new Set();

  function countHealSkills(h){
    let cnt = 0;
    if(HEAL_NAMES.has(h.s1.n)) cnt++;
    if(HEAL_NAMES.has(h.s2.n)) cnt++;
    if(typeof BURST_DB!=='undefined' && BURST_DB[h.name] && HEAL_NAMES.has(BURST_DB[h.name].n)) cnt++;
    return cnt;
  }

  function pickBestElem(h, preferred){
    for(const key of preferred) if(!usedElems.has(key)) return key;
    for(const key of Object.keys(ELEMENT_DB)) if(!usedElems.has(key)) return key;
    return preferred[0];
  }

  // 計算全隊特性
  const maxAtk = Math.max(..._epHeroes.map(h=>h.atk));
  const maxHp  = Math.max(..._epHeroes.map(h=>h.hp));
  const maxEnergyCost = Math.max(..._epHeroes.map(h=>(h.s1.c||0)+(h.s2.c||0)));
  const minSp  = Math.min(..._epHeroes.map(h=>h.sp));

  _epHeroes.forEach((h, i)=>{
    const healCnt = countHealSkills(h);
    const energyCost = (h.s1.c||0)+(h.s2.c||0);
    let preferred;

    if(healCnt >= 2){
      preferred = ['grass','water','light']; // 草優先：治療角色
    } else if(h.atk === maxAtk){
      preferred = ['fire','wind','dark'];   // 火優先：攻擊最高(★ v5.81.0 雷→風正名:'thunder' 非有效元素,改 dark 遞補)
    } else if(h.hp === maxHp){
      preferred = ['earth','dark','water'];  // 地優先：HP最高
    } else if(energyCost === maxEnergyCost){
      preferred = ['dark','wind','earth'];   // 暗次推薦：能量消耗最高
    } else if(h.sp === minSp){
      preferred = ['earth','fire','wind'];   // 特技最低：不推薦光屬性
    } else {
      preferred = [bossCounter,'water','wind']; // 其他：剋制BOSS屬性
    }

    const key = pickBestElem(h, preferred);
    usedElems.add(key);

    // 清除舊屬性加成
    if(_epApplied[i] && _epApplied[i]!==key){
      const oldE=ELEMENT_DB[_epApplied[i]];
      if(oldE){
        if(oldE.bonus_hp){ h.hp-=oldE.bonus_hp; h.curHp=Math.min(h.curHp,h.hp); }
        if(oldE.bonus_atk) h.atk-=oldE.bonus_atk;
        if(oldE.bonus_sp)  h.sp -=oldE.bonus_sp;
        if(oldE.bonus_spd) h.spd-=oldE.bonus_spd;
      }
    }
    _epAssigned[i]=key; _epApplied[i]=key;
    h.element=key; applyElemBonus(h);
  });

  playSfx('sfx-coin',0.85);
  _epRenderHeroes();
  // 高亮右側欄位並顯示已推薦
  document.querySelectorAll('.ep-attr-row').forEach(row=>{ row.style.boxShadow=''; row.style.background='rgba(0,0,0,0.4)'; });
  document.querySelectorAll('.ep-bless-btn').forEach(btn=>btn.style.display='none');
  log('✦ 自動推薦屬性完成！');
  // 啟用底部「進入技能配置」按鈕
  const finishBtn2=document.getElementById('ep-finish-btn-bar');
  if(finishBtn2){ finishBtn2.disabled=false; finishBtn2.style.opacity='1'; finishBtn2.style.cursor='pointer'; }
}

// 元素選擇頁：點?開啟戰鬥預覽視窗（非focusHero）
// ── 屬性節點和說明卡的光粒效果 ──
const _EP_COLOR={water:'#55bbff',fire:'#ff7733',wind:'#44cc66',grass:'#88bb22',earth:'#aa7733',light:'#ffdd22',dark:'#9944cc'};
let _epGlowTimers={};

function _epNodeGlow(key){
  const bc=_EP_COLOR[key]||'#fff';
  // 節點發光 + 呼吸class
  const nd=document.getElementById('epn-'+key);
  if(nd){
    nd.style.borderColor=bc;
    nd.style.boxShadow=`0 0 28px ${bc}cc,0 0 50px ${bc}66`;
    nd.classList.add('ep-node-breathe');
    nd.style.setProperty('--ep-glow-color', bc);
  }
  // 說明卡發光 + 呼吸class
  const card=document.getElementById('epar-'+key);
  if(card){
    card.style.borderColor=bc;
    card.style.boxShadow=`0 0 18px ${bc}aa,0 0 36px ${bc}44`;
    card.style.background='rgba(6,7,18,0.98)';
    card.classList.add('ep-card-breathe');
    card.style.setProperty('--ep-glow-color', bc);
  }
  // 清除舊定時器
  if(_epGlowTimers[key]) clearInterval(_epGlowTimers[key]);
  // 持續噴粒子（每 400ms 一批）
  _epSpawnParticles(key, bc);
  _epGlowTimers[key] = setInterval(()=>_epSpawnParticles(key, bc), 400);
}

function _epNodeGlowClear(key){
  // _epConfirmedKeys：記錄已正式「獲得加護」的屬性（不清除）
  const confirmed = window._epConfirmedKeys && window._epConfirmedKeys[key];
  const nd=document.getElementById('epn-'+key);
  if(nd && !confirmed){
    nd.style.borderColor='';
    nd.style.boxShadow='';
    nd.classList.remove('ep-node-breathe');
  }
  const card=document.getElementById('epar-'+key);
  if(card && !confirmed){
    card.style.boxShadow='';
    card.style.background='rgba(6,7,18,0.94)';
    card.classList.remove('ep-card-breathe');
  }
  if(_epGlowTimers[key]){ clearInterval(_epGlowTimers[key]); delete _epGlowTimers[key]; }
}

function _epSpawnParticles(key, color){
  const wrap=document.getElementById('ep-ring-wrap');
  if(!wrap) return;
  // 從節點位置生成 8 個粒子
  const nd=document.getElementById('epn-'+key);
  const card=document.getElementById('epar-'+key);
  const origins=[];
  if(nd){
    const x=parseFloat(nd.style.left)||0, y=parseFloat(nd.style.top)||0;
    origins.push({x,y});
  }
  if(card){
    const x=parseFloat(card.style.left)||0, y=parseFloat(card.style.top)||0;
    origins.push({x,y});
  }
  origins.forEach(o=>{
    for(let i=0;i<6;i++){
      const p=document.createElement('div');
      p.className='ep-particle';
      const angle=Math.random()*Math.PI*2;
      const dist=40+Math.random()*60;
      const tx=Math.cos(angle)*dist, ty=Math.sin(angle)*dist;
      const size=3+Math.random()*4;
      p.style.cssText=`left:${o.x}px;top:${o.y}px;width:${size}px;height:${size}px;background:${color};box-shadow:0 0 6px ${color};--tx:${tx}px;--ty:${ty}px;`;
      wrap.appendChild(p);
      setTimeout(()=>p.remove(), 700);
    }
  });
}

function finishElemPick(){
  if(Object.keys(_epAssigned).length<_epHeroes.length){ log('請為所有英雄選擇元素屬性！'); return; }
  playSfx('sfx-confirm2',0.9);
  document.getElementById('elem-pick-overlay').style.display='none';
  try{
    if(typeof _epGlowTimers === 'object' && _epGlowTimers){
      Object.keys(_epGlowTimers).forEach(function(k){
        try{ clearInterval(_epGlowTimers[k]); }catch(_){}
        delete _epGlowTimers[k];
      });
    }
    // 清乾淨殘留的粒子節點(避免戰鬥畫面看到飄粒子)
    const _ring = document.getElementById('ep-ring-wrap');
    if(_ring){
      _ring.querySelectorAll('.ep-particle, [class*="ep-part"]').forEach(function(n){
        try{ n.remove(); }catch(_){}
      });
    }
  }catch(_){}
  if(_epCb){ const cb=_epCb; _epCb=null; cb(); }
}

function pickElem(key){
  // Legacy fallback - now handled by confirmElemPick
  confirmElemPick();
}

