    if(typeof window._advSelectedVariantIdx === 'undefined') window._advSelectedVariantIdx = 0;
    if(typeof window._advApricotPreviewTeam === 'undefined') window._advApricotPreviewTeam = null;
    _renderAdvBossPreview();

    _buildHeroPickNodes();
    _applyAdvLocks(); // ← 取代原本的手動 forEach 鎖定邏輯

    // ★ v3.7.5 — 若玩家先前已選了排序/篩選,進冒險編隊頁時自動套用(老師需求:同步)
