  3: { lv:1,  sk:0, burst:0, tre:0, gear:0, pet:false },
  4: { lv:20, sk:2, burst:1, tre:1, gear:3, pet:true },
  5: { lv:30, sk:3, burst:2, tre:1, gear:4, pet:true },
  6: { lv:45, sk:4, burst:3, tre:1, gear:6, pet:true }
