window._lxpsPrepReqOf = function(stage){
  try{
    if(!stage) return null;                                   // 非冒險關（鬥技場/預設陣容編輯器）→ 不標
    if(stage === 'worldboss') return null;                    // 世界龍王走 world-boss-ui.html 自己的替補列表，本輪不涉
    if(window._LXPS_PREP_REQ[stage]) return window._LXPS_PREP_REQ[stage];
    var _st = 5;
    try{ if(typeof ADV_STAGES !== 'undefined' && ADV_STAGES[stage] && ADV_STAGES[stage].stars) _st = ADV_STAGES[stage].stars; }catch(_eS){}
    _st = Math.max(3, Math.min(6, _st));
    return window._LXPS_PREP_REQ_BY_STAR[_st] || null;
  }catch(_eR){ return null; }
};
// ══ 單一真相：六項整備資料一次取齊（_lxpsPrepCheck 顯示層、_lxpsPrepScore 推薦計分層 共用）══
//   ⚠ 任一欄位讀不到 → 回 null（上游一律視同「已達標/不加分」，寧可漏標不誤標）。
window._lxpsPrepStats = function(name){
  try{
    if(!name) return null;
    var _g = (typeof window._lxpsPrepGrowth === 'function') ? window._lxpsPrepGrowth(name) : null;
    if(!_g || !_g.ok) return null;
    var _o = { lv:_g.lv, free:_g.free, s1:_g.s1, s2:_g.s2, burst:_g.burst, stage:_g.stage,
               tre:0, gear:0, pet:false, gearOn:true, petOn:true };
    // 至寶件數
    try{
      var _td = (typeof _taiwanTreasureData === 'object' && _taiwanTreasureData)
        ? _taiwanTreasureData : (window.taiwanTreasureData || null);
      if(_td && typeof _td === 'object'){
        Object.keys(_td).forEach(function(_id){ if(_td[_id] && _td[_id].equippedTo === name) _o.tre++; });
      }
    }catch(_eT){}
    // 裝備件數（未對這位玩家開放時 gearOn=false）
    try{ if(typeof window._gearVisibleForMe === 'function') _o.gearOn = !!window._gearVisibleForMe(); }catch(_eGV){}
    if(_o.gearOn){
      try{ if(typeof _gearGetHeroEquipped === 'function') _o.gear = (_gearGetHeroEquipped(name) || []).length; }catch(_eG){}
    }
    // 跟隨寵物
    try{ if(typeof window._petSysOpenForMe === 'function') _o.petOn = !!window._petSysOpenForMe(); }catch(_eP){}
    if(_o.petOn){
      try{ _o.pet = !!(typeof window._petFollowOf === 'function' && window._petFollowOf(name)); }catch(_eP2){ _o.pet = true; }
    }
    return _o;
  }catch(_eS){ return null; }
};
// 主判定：回 { need:是否要標紅字, miss:[缺項文字], stage, req }
window._lxpsPrepCheck = function(name){
  var _res = { need:false, miss:[], stage:null, req:null };
  try{
    if(!name) return _res;
    if(window._isAdventurePickMode === false) return _res;    // 鬥技場（鐵律 1.153）
    var _p = window._lxpsPrepStats(name);
    if(!_p) return _res;
    var _req = window._lxpsPrepReqOf(_p.stage);
    if(!_req) return _res;
    _res.stage = _p.stage; _res.req = _req;

    if(_req.lv > 1 && _p.lv < _req.lv) _res.miss.push('等級未满 Lv' + _req.lv + '（目前 Lv' + _p.lv + '）');
    if(_p.free > 0) _res.miss.push('還有 ' + _p.free + ' 點素質沒投資');
    if(_req.sk > 0 && Math.min(_p.s1, _p.s2) < _req.sk) _res.miss.push('技能等級未满 +' + _req.sk);
    if(_req.burst > 0 && _p.burst < _req.burst) _res.miss.push('極限爆發未满 +' + _req.burst);
    if(_req.tre > 0 && _p.tre < _req.tre) _res.miss.push('沒有裝備至寶');
    if(_req.gear > 0 && _p.gearOn && _p.gear < _req.gear) _res.miss.push('裝備只有 ' + _p.gear + '/6 件');
    if(_req.pet && _p.petOn && !_p.pet) _res.miss.push('沒有攜帶寵物');
    _res.need = _res.miss.length > 0;
  }catch(_ePC){ console.warn('[v5.86.0 整備度檢查]', _ePC); }
  return _res;
};
// ★ v5.86.0（老師需求 3）— 推薦陣容計分用的「整備度分數」（上限 22）。
//   設計口徑：核心效果（剋制關係）仍是推薦的主軸——故同輪把核心效果權重 ×2（老師指示），
//   整備度只做「同等剋制能力時，優先推薦練得好的那一位」的次要區別。
//   ⚠ 鬥技場一律回 0（鐵律 1.153：那邊 Lv1 公平戰、無至寶無裝備，計入就不公平）。
window._lxpsPrepScore = function(name){
  try{
    if(window._isAdventurePickMode === false) return 0;
    var _p = window._lxpsPrepStats(name);
    if(!_p) return 0;
    var _s = 0;
    _s += Math.min(8, Math.floor((_p.lv || 1) / 6));      // 等級：Lv50 滿 8
    if(_p.free === 0) _s += 2;                            // 素質點已投完
    _s += Math.min(4, Math.min(_p.s1, _p.s2));            // 技能等級（取較低者）
    _s += Math.min(2, _p.burst);                          // 極限爆發等級
    _s += Math.min(2, _p.tre * 2);                        // 至寶（1 件就滿）
    if(_p.gearOn) _s += Math.min(3, Math.floor(_p.gear / 2));  // 裝備件數
    if(_p.petOn && _p.pet) _s += 1;                       // 有帶寵物
    return _s;
  }catch(_ePS){ return 0; }
};
