  //     換人改由下方的「輪替配額」負責，比隨機更準確也更公平。
  //   舊行備查：return { n:n, s:window._lxpsHeroCounterScore(n, _threat.counterWeight) + (Math.random() * 0.98 - 0.49) };
  var _scored = _pool.map(function(n){
    return { n:n, s:window._lxpsHeroCounterScore(n, _threat.counterWeight) };
  });
  _scored.sort(function(a, b){
    var _d = b.s - a.s;
    if(_d) return _d;
    return a.n < b.n ? -1 : (a.n > b.n ? 1 : 0);        // 同分時姓名字典序 → 順序穩定可預期
  });

