/* ══════════════════════════════════════════════════════════════════════════════
 * ★★ v5.227.0(老師「冒險模式 UR 角色編組限制:隊伍最多只能配置 2 名 UR。
 *     預設陣容中 UR 角色達 3 名以上的都由系統刪除」)★★
 *   `_LXPS_ADV_UR_MAX` 是唯一的上限常數,兩個守門點(confirmHeroPick 建隊、_applyPresetTeam 套用)
 *   與預設陣容清理(_lxpsPurgeOverURPresets)全部讀它;老師日後要改成 1 或 3 只改這一個數字。
 *   ⚠ 只約束冒險模式。鬥技場自 v5.91.0 起 UR **一律不得上場**(更嚴格,四道守門各自獨立),
 *     世界龍王戰不走這條建隊路徑,兩者都不受本上限影響。
 * ══════════════════════════════════════════════════════════════════════════════ */
window._LXPS_ADV_UR_MAX = 2;
window._lxpsAdvURCheck = function(names){
  var _r = { n: 0, max: (window._LXPS_ADV_UR_MAX | 0) || 2, names: [], over: false };
  try{
    (names || []).forEach(function(n){ if(n && window._lxpsIsUR(n)) _r.names.push(n); });
    _r.n = _r.names.length;
    _r.over = _r.n > _r.max;
  }catch(_e){ try{ console.warn('[冒險 UR 上限]', _e); }catch(_){} }
  return _r;
};
/* 清除「UR 數量超過上限」的冒險預設陣容(老師:達 3 名以上的都由系統刪除)。
   ⚠ 呼叫點只有一個:_applySafeData 把雲端 advPresetTeams 還原完的那一刻(見該處說明)。
   ⚠ 清掉的欄位設成 null,與 _deletePresetSlot 的「空欄位」表示法一致 —— 不可以把陣列砍短,
     否則五個欄位的編號會整組往前位移,學生會以為別的陣容也被動過。
   ⚠ 只在真的有清到東西時才存檔 + 告知,沒清到就完全安靜(每次開機都跳訊息會讓學生以為壞掉)。
   ⚠ 這支跑在 _applySafeData 裡面,而 _advPresetTeams 是 classic script 的頂層 let
     (全域詞彙環境,跨 <script> 區塊共用) ⇒ 這裡改得到、後面所有消費點也一定看得到新值。 */
window._lxpsPurgeOverURPresets = function(){
  try{
    if(!Array.isArray(_advPresetTeams)) return 0;
    var _max = (window._LXPS_ADV_UR_MAX | 0) || 2, _removed = [], i, pt, chk;
    for(i = 0; i < _advPresetTeams.length; i++){
      pt = _advPresetTeams[i];
      if(!pt || !Array.isArray(pt.heroes)) continue;
      chk = window._lxpsAdvURCheck(pt.heroes);
      if(chk && chk.over){
        _removed.push({ slot: i + 1, name: (pt.name || ('欄位' + (i + 1))), urs: chk.names.slice() });
        _advPresetTeams[i] = null;
      }
    }
    if(!_removed.length) return 0;
    try{ console.warn('[冒險 UR 上限 v5.227.0] 已刪除 UR 超過 ' + _max + ' 名的預設陣容:', _removed); }catch(_){}
    try{ if(typeof gameCloudSave === 'function') Promise.resolve(gameCloudSave()).catch(function(){}); }catch(_){}
    /* 延遲告知:此刻還在載入流程中,畫面多半還是登入/讀取中,馬上彈 toast 看不到 */
    setTimeout(function(){
      try{
        var _t = _removed.map(function(r){ return '欄位' + r.slot + '「' + r.name + '」'; }).join('、');
        _showInGameToast('📋 冒險隊伍現在最多只能帶 ' + _max + ' 名 UR 英雄\n\n' + _t
          + ' 因為 UR 超過上限,已經自動移除,請重新編一隊。\n(英雄本身一隻都沒有少,只是陣容紀錄被清掉)', '#ffaa44', 9000);
      }catch(_){}
    }, 4000);
    return _removed.length;
  }catch(e){ try{ console.warn('[冒險 UR 上限] 清理例外', e); }catch(_){} return 0; }
};
