      const _isLight = (hero._dualStarForm || 'light') === 'light';
      const _activeStyle = _isLight
        ? 'background:#ffffff;color:#000000;padding:2px 6px;border-radius:4px;font-weight:bold;border:1px solid #ffcc44;'
        : 'background:#000000;color:#ffffff;padding:2px 6px;border-radius:4px;font-weight:bold;border:1px solid #9966ff;';
