    if(s1IsPassive) s1b.innerHTML=`<b style="font-size:20px;white-space:normal;line-height:1.3;display:block">⚙ ${a.s1.n} 🔷${c1} <span class="csk-detail-btn-lg" data-skname="${a.s1.n}" data-skmeta="${'🔷'+c1+' [被動]'}" data-skdesc="${(a.s1.fd||a.s1.d||'').replace(/"/g,'&quot;')}" onclick="event.stopPropagation();showSkillDetailPopup(this)" style="border-radius:50%;width:30px;height:30px;line-height:30px;font-size:20px;display:inline-flex;align-items:center;justify-content:center;vertical-align:middle;margin-left:4px">?</span></b><span style="color:#ff9900;font-size:22px;display:block;margin-top:3px;line-height:1.4;white-space:normal">${a.s1.d||''}</span>`;
    if(s2IsPassive) s2b.innerHTML=`<b style="font-size:20px;white-space:normal;line-height:1.3;display:block">⚙ ${a.s2.n} 🔷${c2} <span class="csk-detail-btn-lg" data-skname="${a.s2.n}" data-skmeta="${'🔷'+c2+' [被動]'}" data-skdesc="${(a.s2.fd||a.s2.d||'').replace(/"/g,'&quot;')}" onclick="event.stopPropagation();showSkillDetailPopup(this)" style="border-radius:50%;width:30px;height:30px;line-height:30px;font-size:20px;display:inline-flex;align-items:center;justify-content:center;vertical-align:middle;margin-left:4px">?</span></b><span style="color:#ff9900;font-size:22px;display:block;margin-top:3px;line-height:1.4;white-space:normal">${a.s2.d||''}</span>`;
