window._CST_EFFECTS = window._CST_EFFECTS || {};   /* 命星戰鬥效果登錄表:{ 英雄名: { t1:{prep:fn(h,cst)}, ... } } —— 第一階段為空,下一輪起分批接線 */
window._cstHas = function(h, slot){ try{ return !!(h && h._cst && h._cst.lit && h._cst.lit[slot]); }catch(_){ return false; } };
/* ★ v5.255.0 各命星效果一律走 _cstHasN(英雄物件, 槽, 星的主人名):多驗「這個物件就是星的主人」。
   理由:凡人「模仿／臨摹」別人的技能或爆發時,施放者物件是凡人,若只問 _cstHas 會把凡人自己的同槽命星誤套到別人的招式上。 */
window._cstHasN = function(h, slot, owner){ try{ return !!(h && h.name === owner && h._cst && h._cst.lit && h._cst.lit[slot]); }catch(_){ return false; } };
/* ★ 主角命星專用:主角在戰鬥中的名字可能是「主角」或「主角‧覺醒」⇒ 一律用 _isProtagHero(定義在 game_adv.js)判斷本人。
   凡人臨摹/模仿主角時施放者物件是凡人 ⇒ 不成立。 */
window._cstHasP = function(h, slot){ try{ return !!(h && ((typeof window._isProtagHero === 'function' && window._isProtagHero(h.name)) || h._cstPF === true) && h._cst && h._cst.lit && h._cst.lit[slot]); }catch(_){ return false; } };
/* ★ v5.275.0 h._cstPF:借來的「好友主角」(本機唯一別名)由 _cstApplyFriend 依好友命星快照設定;只掛在該英雄物件本人身上(臨摹的凡人不帶)。 */
/* ✨ 命星 主角‧覺醒 s1「手感來了星」:施放技能一欄位(a.s1)的技能時武裝,綁定本次行動序號 G._actSeq(下一次行動自動失效)。
   cast=true 由 AI 路徑呼叫(AI 不會取消選目標 ⇒ 當場計次);玩家路徑在 endAction 才確認計次(取消選目標不算)。
   同一 _actSeq 內 re-dispatch(七十二變/模仿等)不重複武裝、不重複計次。次數記在英雄物件、以 G 物件換場歸零。 */
window._cstPgS1Arm = function(a, sk, cast){
  try{
    if(!a || !sk || sk.p || !a.s1 || !(sk === a.s1 || sk.n === a.s1.n)) return;
    if(!window._cstHasP(a,'s1')) return;
    if(typeof G === 'undefined' || !G) return;
    var _sq = G._actSeq || 0;
    if(a._cstPgS1G !== _cstBidD()){ a._cstPgS1G = _cstBidD(); a._cstPgS1N = 0; a._cstPgS1CntSeq = null; a._cstPgS1Seq = null; }   // ★ v5.262.0 命座(審查 L6):存戰鬥序號而非 G 物件(避免快照 JSON 循環參照)
    if(a._cstPgS1Seq === _sq) return;
    a._cstPgS1CntSeq = null;   // 🔧 v5.259.0 審查 M2:同一 _actSeq 的再行動(女神權能/連斬等)上一發已計次、已由 _cstPgS1NewAct 解除 ⇒ 這次是新的一次施放,要重新計次
    a._cstPgS1Seq = _sq;
    a._cstPgS1Crit = ((a._cstPgS1N || 0) + 1 === 3);
    if(cast){ window._cstPgS1Log(a); a._cstPgS1N = (a._cstPgS1N || 0) + 1; a._cstPgS1CntSeq = _sq; }   // 🔧 v5.259.0 審查 M1:「手感來了」紀錄改在確認計次時才印(AI 當場計次 ⇒ 當場印;玩家在 endAction 印,取消選目標不留紀錄)
  }catch(_eCstPgArm){}
};
// 🔧 v5.259.0 審查 M1:「手感來了」紀錄(在計次「之前」呼叫,顯示的是這一次的序數)
window._cstPgS1Log = function(a){
  try{ log('✨ [' + a.name + '] 命星:手感來了!技能一傷害與治療 +20%' + (a._cstPgS1Crit ? ',第 3 次施放必定暴擊!' : '(本場第 ' + ((a._cstPgS1N || 0) + 1) + ' 次)')); }catch(_){}
};
