        fieldCards.length = 0;
        try{ if(window._cstHasN(h,'b2','雅典娜')) _gaCard._cstAthB2 = 1; }catch(_eCstAthB2){}   // ✨ v5.266.0 命星 雅典娜 b2「勝利女神星」:擊倒延長(每張 1 次)
        fieldCards.push(_gaCard);
