        if(_rcGm) spawnParticles(_rcGm.x, _rcGm.y, {count:12, color:'#ffbb55', size:7, spread:50, duration:500});
        try{ playSfx(_gmHitIdx >= 3 ? 'sfx-bomb-explode' : 'sfx-explode', 0.8); }catch(_){}
        renderCard(_tgt);
