        try{ if(window._cstHasN(h,'b1','雙魚星神') && Math.random() < 0.50){ addStatus(t, 'confused', 1); if(hasStatus(t,'confused')) log('✨ [' + h.name + '] 命星:鏡海迷霧![' + t.name + '] 陷入混亂 1 回合!'); } }catch(_eCstPsB1){}   // ✨ 命星 雙魚星神 b1
