  try{ if(typeof G !== 'undefined' && G && G._cstMyHalf) window._cstMyB2Done(h); }catch(_eCstMyB2d){}   // ✨ v5.272.0 命星 沐雲雪 b2:雙虹爆發結束(只認命星寫入的 G._cstMyHalf)
