  try{ if(h && h._cstMyB2 && window._cstMyB2Next(h, _interrupted)) return; }catch(_eCstMyB2n){}   // ✨ v5.272.0 命星 ⚙ 沐雲雪 b2:雲中雙虹接著喚發第 2 名友方的爆發(只認命星寫入的欄位)
  G.passiveInterruptUsed=false;
