/* ═════════════════════════════════════════════════════════════════════════════
 * ✨ v5.264.0 命座 ✦ 新機制 SSR 第一批(巫女～地府酋長 14 位、37 顆)共用零件
 *   ★ 12甲:每支函式都先過 _cstHasN,或只認「點亮的命星才會寫入」的欄位/標記;未點亮時不寫入任何東西、不多擲骰。
 *   ★ 跨回合記號一律存 {b:戰鬥序號 _cstBidD(), ...},英雄參照存 side:name 字串(不掛 G/英雄物件,避免快照循環參照)。
 *   ★ 可見標記走 _cstS1Mark(buff,帶 _fromBurst ⇒ 不可被消除/奪取/吞噬;_side ⇒ 被偷到敵方也不生效)。
 *   ★ 命星觸發的反擊/濺射/追擊一律帶 _cstReact:1(G8);額外回能走 _cstCap.gainEnergy(G3);硬控走 ctrlOk/markCtrl(G6);
 *      免死走 trySurvive(G7);再行動走 tryExtraAction(G2);增傷走 capHit(G9)。
 * ═════════════════════════════════════════════════════════════════════════════ */
function _cstS1R(){ try{ return (typeof G !== 'undefined' && G && G.round) || 1; }catch(_){ return 1; } }
function _cstS1Boss(t){ try{ return !!window._cstCap.isBoss(t); }catch(_){ return false; } }
function _cstS1Lv(h){ try{ return (typeof _heroLevels !== 'undefined' && h && _heroLevels[h.name]) ? _heroLevels[h.name] : 1; }catch(_){ return 1; } }
function _cstS1Opp(side){ return (side === 'p1') ? 'p2' : 'p1'; }
function _cstS1Alive(side){ try{ return (G[side] || []).filter(function(x){ return x && x.curHp > 0; }); }catch(_){ return []; } }
function _cstS1Mark(h, type, dur, extra){
  try{
    if(!h) return null;
    if(!Array.isArray(h.buffs)) h.buffs = [];
    h.buffs = h.buffs.filter(function(b){ return !(b && b.type === type); });
    var o = { type:type, dur:dur, _fromBurst:true, _cstMk:1, _b:_cstBidD(), _side:h.side };
    if(extra) Object.keys(extra).forEach(function(k){ o[k] = extra[k]; });
    h.buffs.push(o);
    return o;
  }catch(_){ return null; }
}
function _cstS1MarkGet(h, type){
  try{ return (h && Array.isArray(h.buffs)) ? (h.buffs.find(function(b){ return b && b.type === type && b._cstMk && _cstBidOk(b._b) && b._side === h.side; }) || null) : null; }catch(_){ return null; }
}
function _cstS1Pick(arr){ return (arr && arr.length) ? arr[Math.floor(Math.random() * arr.length)] : null; }

/* ── 致命傷保命(主路徑/固定傷害路徑都在祭司 b2 之後呼叫):巫女 t2 御守、死靈法師 t2 亡靈守護 ── */
window._cstS1Save = function(t){
  try{
    if(!t || typeof G === 'undefined' || !G || !Array.isArray(t.buffs)) return false;
    var om = _cstS1MarkGet(t, '_cstOmamori');
    if(om){
      var U = G._cstMiT2U || (G._cstMiT2U = {});
      if((U[t.side] || 0) < 2 && window._cstCap.trySurvive(t)){
        U[t.side] = (U[t.side] || 0) + 1;
        t.buffs = t.buffs.filter(function(b){ return b !== om; });
        log('✨ [巫女] 命星:御守護身![' + t.name + '] 的御守替他擋下致命一擊,保留 1 HP!(全隊本場 ' + U[t.side] + '/2)');
        try{ bannerFX(t, '🧧 御守!', '#ff8899', 1000); }catch(_){}
        return true;
      }
    }
    var ng = _cstS1MarkGet(t, '_cstNcGuard');
    if(ng){
      var V = G._cstNcT2U || (G._cstNcT2U = {});
      if((V[t.side] || 0) < 2 && window._cstCap.trySurvive(t)){
        V[t.side] = (V[t.side] || 0) + 1;
        t.buffs = t.buffs.filter(function(b){ return b !== ng; });
        log('✨ [死靈法師] 命星:亡靈守護![' + t.name + '] 被亡靈托住,保留 1 HP!(全隊本場 ' + V[t.side] + '/2)');
        try{ bannerFX(t, '👻 亡靈守護!', '#aaccff', 1000); }catch(_){}
        return true;
      }
    }
  }catch(_eCstS1Sv){}
  try{ if(window._cstS3Save && window._cstS3Save(t)) return true; }catch(_eCstS3Sv){}   // ✨ v5.266.0 死神 t2 冥府契約/法老王 t2(兩條致命路徑共用)
  return false;
};

