    var r = _cstS1R();
    if(_cstBidOk(a._cstTmT2G) && a._cstTmT2R === r) return;
    if(_cstBidOk(t._cstTmT2G) && r < (t._cstTmT2N || 0)) return;
    a._cstTmT2G = _cstBidD(); a._cstTmT2R = r;
    t._cstTmT2G = _cstBidD(); t._cstTmT2N = r + 3;
