      pony._cstPnT2R = { b:_cstBidD(), r:_cstS1R() };   // ★ 審查:帶戰鬥序號
      _cstS1Mark(pony, '_cstPnSpd', 2, { _v:5 });
      log('✨ [' + pony.name + '] 命星:疾蹄馳援!救醫馬速度 +5(2 回合)');
