/* ── 護盾被打破(一般 shield/bigshield 各破碎分支呼叫):青炎龍王 t2 青炎回燃、神槍手 t2 護盾回禮 ── */
window._cstShBreak2 = function(t, a, opts, list){
  try{
    if(!t || !list || !list.length || typeof G === 'undefined' || !G) return;
    opts = opts || {};
    var at = opts.actor || a;
    var foe = !!(at && at !== t && at.side !== t.side && at.curHp > 0);
    list.forEach(function(sh){
      if(!sh || !sh._cstAzBy || sh._cstAzDone || !_cstBidOk(sh._cstAzB)) return;
      sh._cstAzDone = 1;
      var az = _cstRefGet(sh._cstAzBy);
      if(!az || !foe || !window._cstHasN(az,'t2','青炎龍王') || !window._cstCap.reactOk(opts)) return;
      window._cstCap.noteReact(opts);
      var d = _cstS2Sp(az, 0.80);
      log('✨ [' + az.name + '] 命星:青炎回燃![' + t.name + '] 的青炎護盾碎裂爆炸,反燒 [' + at.name + '](特技 80% 火屬性)並燃燒 2 回合!');
      setTimeout(function(){ try{ if(at.curHp > 0){ doDmg(at, d, { actor:az, isSkill:true, elem:'fire', element:'fire', isRebound:true, noGuard:true, ignoreEvasion:true, _cstReact:1 }); if(at.curHp > 0){ addStatus(at, 'hellfire', 2); var hs = (at.status || []).find(function(s){ return s && s.type === 'hellfire'; }); if(hs){ hs._actor = az; hs._dotSrc = az; } } try{ renderCard(at); }catch(_){} } }catch(_){} }, 250);
    });
    try{ window._cstS3ShBreak(t, at, opts, list); }catch(_eCstS3Sb){}   // ✨ v5.266.0 地獄將軍 s2 戰旗反擊
    try{ window._cstS5ShBreak(t, at, opts, list); }catch(_eCstS5Sb){}   // ✨ v5.268.0 摩羯星神 b2 岩壁反震
    if(!foe) return;
    var gun = (G[t.side] || []).find(function(x){ return x && x.name === '神槍手' && x.curHp > 0 && window._cstHasN(x,'t2','神槍手'); });
    if(!gun) return;
    var r = _cstS1R();
    if(!_cstSameRec(gun._cstGsT2) || gun._cstGsT2.r !== r) gun._cstGsT2 = { b:_cstBidD(), r:r, n:0 };
    if(gun._cstGsT2.n >= 2 || !window._cstCap.reactOk(opts)) return;
    gun._cstGsT2.n++; window._cstCap.noteReact(opts);
    var d2 = Math.max(1, Math.floor((gun.atk || 1) * 0.60));
    log('✨ [' + gun.name + '] 命星:護盾回禮![' + t.name + '] 的護盾被打破,神槍手對 [' + at.name + '] 開 1 槍(攻擊 60%,穿透護盾;本回合 ' + gun._cstGsT2.n + '/2)!');
    setTimeout(function(){ try{ if(gun.curHp > 0 && at.curHp > 0){ doDmg(at, d2, { actor:gun, isRebound:true, pierceShield:true, noGuard:true, ignoreEvasion:true, _cstReact:1 }); try{ renderCard(at); }catch(_){} } }catch(_){} }, 300);
  }catch(_){}
};
/* ── 神槍手 ── */
window._cstGsS2Rec = function(a, opts, amt){   // s2「拆盾回收星」:子彈穿透扣下的護盾 50% ⇒ 最低 HP% 友方的護盾(取大值覆蓋)
  try{
    var g = (opts && opts.actor) || a;
    if(!g || g.name !== '神槍手' || !(amt > 0) || !opts || !opts.pierceShield || !window._cstHasN(g,'s2','神槍手')) return;
    var low = _cstS2Low(g.side, null); if(!low) return;
    var got = _cstS2Shield(low, Math.max(1, Math.floor(amt * 0.5)), '_cstGsRec', 99);
    if(got > 0){ log('✨ [' + g.name + '] 命星:拆盾回收!穿透扣下 ' + amt + ' 護盾,一半(' + got + ')轉給 [' + low.name + ']!'); try{ renderCard(low); }catch(_){} }
  }catch(_){}
};
window._cstGsB2Arm = function(h){ try{ if(!h || !window._cstHasN(h,'b2','神槍手')) return; _cstS1Mark(h, '_cstGsCover', 1); G._cstGsCv = 1; log('✨ [' + h.name + '] 命星:烈焰掩護!進入「掩護射擊」1 回合:友方被攻擊時代承一半傷害並開火反擊!'); try{ renderCard(h); }catch(_){} }catch(_){} };
window._cstGsB2Cover = function(target, rawDmg, opts){   // b2「烈焰掩護星」:回傳 undefined = 不代承;否則回傳代承後本體受到的傷害
  try{
    if(!target || !(rawDmg > 0) || !(target.curHp > 0) || opts.fixedDmg || opts._fromBurn || opts._isDot || opts._isDotTick || opts._fromBleedProc || opts.isRebound || opts.isHeal || opts._cstGsCov) return undefined;
    var at = opts.actor; if(!at || at.side === target.side) return undefined;
    var gun = (G[target.side] || []).find(function(x){ return x && x !== target && x.name === '神槍手' && x.curHp > 0 && _cstS1MarkGet(x, '_cstGsCover') && window._cstHasN(x,'b2','神槍手'); });
    if(!gun) return undefined;
    var half = Math.max(1, Math.floor(rawDmg * 0.5));
    log('✨ [' + gun.name + '] 命星:掩護射擊!替 [' + target.name + '] 擋下一半傷害(' + half + ')!');
    try{ showShieldVFX(gun, 'block'); }catch(_){}
    doDmg(gun, half, Object.assign({}, opts, { _mochiGuardChecked:true, noGuard:true, _cstGsCov:1 }));
    var r = _cstS1R(), sq = (G && G._actSeq) || 0;
    if(!_cstSameRec(gun._cstGsB2) || gun._cstGsB2.r !== r) gun._cstGsB2 = { b:_cstBidD(), r:r, n:0, sq:-1 };
    var R = gun._cstGsB2;
    if(R.n < 3 && R.sq !== sq && at.curHp > 0 && gun.curHp > 0 && window._cstCap.reactOk(opts)){
      R.n++; R.sq = sq; window._cstCap.noteReact(opts);
      var d = Math.max(1, Math.floor((gun.atk || 1) * 1.0));
      log('✨ [' + gun.name + '] 命星:掩護射擊!對 [' + at.name + '] 開火反擊(攻擊 100% 火屬性;本回合 ' + R.n + '/3)!');
      setTimeout(function(){ try{ if(gun.curHp > 0 && at.curHp > 0){ doDmg(at, d, { actor:gun, isRebound:true, noGuard:true, ignoreEvasion:true, element:'fire', elem:'fire', _cstReact:1 }); try{ renderCard(at); }catch(_){} } }catch(_){} }, 300);
    }
    return doDmg(target, Math.max(0, rawDmg - half), Object.assign({}, opts, { _mochiGuardChecked:true, noGuard:true, _cstGsCov:1 }));
  }catch(_){ return undefined; }
};

