/* ── 傷害加成(由 _cstS2Mod 末尾呼叫;固定傷害不進來):幽幽怨念/死亡印記/豚豚得意/王權加持/醉龍香/熔岩 t2 減傷 ── */
window._cstS3Mod = function(target, dmg, opts, a){
  try{
    var at = opts.actor || a;
    var plain = !opts.isRebound && !opts._isDot && !opts._isDotTick && !opts._fromBurn && !opts.isTraitShare && !opts.isChaos;
    if(at && at !== target && at.side !== target.side && plain){
      if(at.name === '幽幽' && at._cstYyGr && _cstSameRec(at._cstYyGr) && at._cstYyGr.n > 0 && window._cstHasN(at,'t2','幽幽')){
        var k1 = window._cstCap.capHit(opts, 'stat', 0.05 * at._cstYyGr.n); if(k1 > 0) dmg = Math.max(1, Math.floor(dmg * (1 + k1)));
      }
      if(at.name === '我的豚豚' && at._cstPigPr && _cstSameRec(at._cstPigPr) && at._cstPigPr.n > 0 && window._cstHasN(at,'t2','我的豚豚')){
        var k2 = window._cstCap.capHit(opts, 'stat', 0.08 * at._cstPigPr.n); if(k2 > 0) dmg = Math.max(1, Math.floor(dmg * (1 + k2)));
      }
      if(at.name === '死神' && target._cstGrMark && _cstBidOk(target._cstGrMark.b) && _cstS1R() <= target._cstGrMark.until && target._cstGrMark.by === _cstRefOf(at) && window._cstHasN(at,'t2','死神')){
        var k3 = window._cstCap.capHit(opts, 'vuln', 0.40); if(k3 > 0) dmg = Math.max(1, Math.floor(dmg * (1 + k3)));
      }
      if(Array.isArray(at.buffs) && at.buffs.length){
        var ry = _cstS1MarkGet(at, '_cstPhRoyal');
        if(ry && ry._pct > 0){ var k4 = window._cstCap.capHit(opts, 'dmg', ry._pct); if(k4 > 0) dmg = Math.max(1, Math.floor(dmg * (1 + k4))); }
      }
      if(opts._dragonHit && target._cstHlScent && at.name === '喚龍使‧蜜鶴林'){
        var sc = target._cstHlScent;
        if(_cstBidOk(sc.b) && _cstS1R() <= sc.until && sc.by === _cstRefOf(at) && window._cstHasN(at,'s2','喚龍使‧蜜鶴林')){ opts.critBoost = ((typeof opts.critBoost === 'number') ? opts.critBoost : 0) + 1.0; }
      }
      if(target.name === '熔岩巨人' && hasStatus(at, 'hellfire') && window._cstHasN(target,'t2','熔岩巨人')) dmg = Math.max(1, Math.floor(dmg * 0.90));
    }
    dmg = window._cstS4Mod(target, dmg, opts, a);   // ✨ v5.267.0 SSR 第四批
  }catch(_){}
  return dmg;
};

/* ── 致命傷保命(由 _cstS1Save 末尾呼叫):死神 t2 冥府契約、法老王 t2(隊伍沒有豔后)── */
window._cstS3Save = function(t){
  try{
    if(!t || typeof G === 'undefined' || !G) return false;
    if(t.name === '死神' && window._cstHasN(t,'t2','死神') && !_cstSameRec(t._cstGrT2U) && window._cstCap.trySurvive(t)){
      t._cstGrT2U = { b:_cstBidD() };
      var at = G.activeChar;
      if(at && at.side !== t.side && at.curHp > 0){ at._cstGrMark = { b:_cstBidD(), until:_cstS1R() + 1, by:_cstRefOf(t) }; }
      log('✨ [' + t.name + '] 命星:冥府契約!死神與冥府立約,保留 1 HP' + (at && at._cstGrMark ? ',並在 [' + at.name + '] 身上刻下「死亡印記」2 回合(受到死神傷害 +40%)' : '') + '!(每場 1 次)');
      try{ bannerFX(t, '📜 冥府契約!', '#cc0033', 1000); }catch(_){}
      return true;
    }
    if(t.name === '法老王' && window._cstHasN(t,'t2','法老王') && !(G[t.side] || []).some(function(x){ return x && x.name === '埃及豔后'; }) && !_cstSameRec(t._cstPhT2U) && window._cstCap.trySurvive(t)){
      t._cstPhT2U = { b:_cstBidD() };
      log('✨ [' + t.name + '] 命星:雙王共治!沒有王后在旁,法老王以王者意志撐住致命一擊,保留 1 HP!(每場 1 次)');
      try{ bannerFX(t, '👑 王者不倒!', '#ffd86b', 1000); }catch(_){}
      return true;
    }
    if(window._cstS4Save(t)) return true;   // ✨ v5.267.0 大刀勇士 t2 戰魂不滅
    if(window._cstS5Save(t)) return true;   // ✨ v5.268.0 牡羊星神 t2 金羊毛/處女星神 b2 免死
    if(window._cstS6Save(t)) return true;   // ✨ v5.269.0 奧汀 b2 黃昏餘燼
  }catch(_){}
  return false;
};

/* ── 行動前(startTurn,燃燒行動前結算之前呼叫):風術士 t2 順風、熔岩巨人 t2 地心熔脈、熔岩巨人 b2 火山灰;回傳是否有做事 ── */
window._cstS3Turn = function(next){
  var did = false;
  try{
    if(!next || !(next.curHp > 0) || typeof G === 'undefined' || !G) return false;
    if(Array.isArray(next.buffs) && next.buffs.length){
      var w = _cstS1MarkGet(next, '_cstWsWind');
      if(w){
        next.buffs = next.buffs.filter(function(b){ return b !== w; });
        var ws = _cstRefGet(w._by);
        if(ws && window._cstHasN(ws,'t2','風術士')){ var g = window._cstCap.gainEnergy(next.side, 1); log('✨ [' + ws.name + '] 命星:順風而行![' + next.name + '] 乘著順風出發' + (g > 0 ? ',我方能量 +1' : '') + '!'); }
        did = true;
      }
    }
    if(next.name === '熔岩巨人' && window._cstHasN(next,'t2','熔岩巨人')){
      var nb = _cstS1Alive(_cstS1Opp(next.side)).filter(function(f){ return hasStatus(f, 'hellfire'); }).length;
      if(nb > 0 && next.curHp < next.hp){
        var hv = Math.max(1, Math.floor((next.hp || 0) * Math.min(0.06, 0.02 * nb)));
        doHeal(next, hv, { actor:next, isHeal:true, noDice:true, noWarhorn:true });
        log('✨ [' + next.name + '] 命星:地心熔脈!' + nb + ' 名對手正在燃燒,熔岩巨人回復 ' + hv + ' HP');
        did = true;
      }
    }
    if(Array.isArray(G._cstFcD) && G._cstFcD.length){
      var e = window._cstFcD.on('ash', _cstS1Opp(next.side));
      if(e){
        var own = window._cstFcD.owner(e);
        if(!own || window._cstHasN(own,'b2','熔岩巨人')){
          var d = Math.max(1, Math.floor((e.sp || 0) * 0.30));
          log('✨ [' + e.own + '] 命星:火山灰雲![' + next.name + '] 在火山灰中行動,受到 ' + d + ' 火屬性傷害');
          _cstS3As(own, function(){ doDmg(next, d, { actor:(own || undefined), isSkill:true, element:'fire', elem:'fire', _cstReact:1 }); });
          if(next.curHp > 0 && Math.random() < 0.30){ addStatus(next, 'forecast', 1); if(hasStatus(next, 'forecast')) log('✨ [' + e.own + '] 命星:火山灰雲![' + next.name + '] 被火山灰遮住視線,失明 1 回合!'); }
          try{ renderCard(next); }catch(_){}
          did = true;
        }
      }
    }
  }catch(_eCstS3T){ console.warn('[命星 SSR 第三批 行動前]', _eCstS3T); }
  return did;
};

/* ── 護盾被打破(由 _cstShBreak2 呼叫):地獄將軍 s2 戰旗反擊 ── */
window._cstS3ShBreak = function(t, at, opts, list){
  try{
    if(!_cstS3Foe(t, at)) return;
    list.forEach(function(sh){
      if(!sh || !sh._cstHgBy || !_cstBidOk(sh._cstHgB)) return;
      var g = _cstRefGet(sh._cstHgBy);
      if(!g || !(g.curHp > 0) || g.side !== t.side || !window._cstHasN(g,'s2','地獄將軍')) return;
      var r = _cstS1R();
      if(_cstSameRec(t._cstHgS2R) && t._cstHgS2R.r === r) return;
      if(!window._cstCap.reactOk(opts)) return;
      t._cstHgS2R = { b:_cstBidD(), r:r }; window._cstCap.noteReact(opts);
      var d = Math.max(1, Math.floor((g.atk || 1) * 0.80));
      log('✨ [' + g.name + '] 命星:戰旗反擊![' + t.name + '] 的守護護盾被打破,戰旗燃起,反擊 [' + at.name + '](將軍攻擊 80% 火屬性)!');
      _cstS3Later(function(){ if(g.curHp > 0 && at.curHp > 0){ doDmg(at, d, { actor:g, isRebound:true, noGuard:true, ignoreEvasion:true, element:'fire', elem:'fire', _cstReact:1 }); try{ renderCard(at); }catch(_){} } }, 300);
    });
  }catch(_){}
};

/* ── 倒下事件(由 _cstS2Ko 末尾呼叫):朱玥 s2 藤蔓轉生、雅典娜 b2 勝利女神 ── */
window._cstS3Ko = function(target, opts){
  try{
    if(!target || typeof G === 'undefined' || !G) return;
    var ps = (target.status || []).find(function(s){ return s && s.type === '_zhuyueParasite' && !s._cstZyJ; });
    if(ps){
      var z = (G[ps._zyOwnerSide] || []).find(function(x){ return x && x.name === ps._zyOwnerName; });
      if(z && z.curHp > 0 && z.side !== target.side && window._cstHasN(z,'s2','魔界花使‧朱玥')){
        var L = _cstS1Alive(target.side).filter(function(x){ return x !== target; });
        if(L.length){
          var nx = L.slice().sort(function(x, y){ return y.curHp - x.curHp; })[0];
          nx.status = (nx.status || []).filter(function(s){ return !(s && s.type === '_zhuyueParasite'); });
          nx.status.push(Object.assign({}, ps, { dur:3, _cstZyJ:1 }));
          log('✨ [' + z.name + '] 命星:藤蔓轉生![' + target.name + '] 倒下,花藤跳到 HP 最高的 [' + nx.name + '] 身上重新寄生 2 回合!');
          try{ bannerFX(nx, '🌿 寄生轉移!', '#88dd66', 800); renderCard(nx); }catch(_){}
        }
      }
    }
    var k = opts.actor || G.activeChar;
    if(k && k.side !== target.side && typeof fieldCards !== 'undefined' && Array.isArray(fieldCards)){
      var gc = fieldCards.find(function(f){ return f && f.effect === 'goddess' && f._cstAthB2 && !f._cstAthExt && f.side === k.side; });
      if(gc){ gc._cstAthExt = 1; gc.dur = (gc.dur || 0) + 1; log('✨ [雅典娜] 命星:勝利女神![' + k.name + '] 擊倒 [' + target.name + '],「女神權能」延長 1 回合!'); try{ renderBfield(); }catch(_){} }
    }
    try{ window._cstS4Ko(target, opts); }catch(_eCstS4KoC){}   // ✨ v5.267.0 SSR 第四批
    try{ window._cstS5Ko(target, opts); }catch(_eCstS5KoC){}   // ✨ v5.268.0 SSR 第五批
    try{ window._cstS6Ko(target, opts); }catch(_eCstS6KoC){}   // ✨ v5.269.0 UR
  }catch(_eCstS3Ko){ console.warn('[命星 SSR 第三批 倒下事件]', _eCstS3Ko); }
};

/* ── 每回合開始(由 _cstS2RoundStart 末尾呼叫):地獄將軍 t2 戰魂記帳、b2 不滅戰魂 ── */
window._cstS3RoundStart = function(){
  try{
    if(typeof G === 'undefined' || !G) return;
    var r = G.round || 1;
    (G.p1 || []).concat(G.p2 || []).forEach(function(x){
      if(!x) return;
      if(x._cstHgPay){
        var P = x._cstHgPay;
        if(!_cstBidOk(P.b) || P.r < r - 1) delete x._cstHgPay;
        else if(P.r === r - 1){
          delete x._cstHgPay;
          if(x.curHp > 0 && window._cstHasN(x,'t2','地獄將軍')){
            var hv = Math.min(Math.max(1, Math.floor(P.n * 0.30)), Math.max(1, Math.floor((x.hp || 0) * 0.05)));
            doHeal(x, hv, { actor:x, isHeal:true, noDice:true, noWarhorn:true });
            log('✨ [' + x.name + '] 命星:戰魂記帳!上回合為戰而付出的 ' + P.n + ' HP,將軍意志追加回復 ' + hv + ' HP');
            try{ renderCard(x); }catch(_){}
          }
        }
      }
      if(x._cstHgB2){
        var B = x._cstHgB2;
        if(!_cstBidOk(B.b) || r > B.r0 + 2) delete x._cstHgB2;
        else if(r > B.r0){
          if(x.curHp > 0 && window._cstHasN(x,'b2','地獄將軍')){
            var hv2 = Math.max(1, Math.floor(B.amt * 0.25));
            doHeal(x, hv2, { actor:x, isHeal:true, noDice:true, noWarhorn:true });
            log('✨ [' + x.name + '] 命星:不滅戰魂!戰魂回流,回復 ' + hv2 + ' HP');
            try{ renderCard(x); }catch(_){}
          }
          if(r >= B.r0 + 2) delete x._cstHgB2;
        }
      }
    });
    try{ window._cstS4RoundStart(); }catch(_eCstS4RsC){}   // ✨ v5.267.0 SSR 第四批
    try{ window._cstS5RoundStart(); }catch(_eCstS5RsC){}   // ✨ v5.268.0 SSR 第五批
    try{ window._cstS6RoundStart(); }catch(_eCstS6RsC){}   // ✨ v5.269.0 UR
    try{ window._cstS7RoundStart(); }catch(_eCstS7RsC){}   // ✨ v5.270.0 ⚙ 第一批
  }catch(_eCstS3Rs){ console.warn('[命星 SSR 第三批 回合開始]', _eCstS3Rs); }
};

/* ═════════════════════════════════════════════════════════════════════════════
 * ✨ v5.267.0 命座 ✦ 新機制 SSR 第四批(拘留者～姜子牙 15 位、40 顆)共用零件
 *   規則同前三批:先過 _cstHasN 或只認命星寫入的欄位;未點亮不寫入、不多擲骰。
 *   ⚙ 型本批不做:科學發明家 t2、御雲使‧沐雲雪 b2、麻吉喵‧Nico b2、孫悟空 s2、關羽 b2。
 * ═════════════════════════════════════════════════════════════════════════════ */
function _cstS4Atk(h, pct){ try{ return Math.max(1, Math.floor(window._lxpsAtkv(h) * pct)); }catch(_){ return 1; } }
function _cstS4Seq(){ try{ return (typeof G !== 'undefined' && G && G._actSeq) || 0; }catch(_){ return 0; } }
function _cstS4Haste(h){ try{ addBuff(h, 'haste', 1); var hb = h.buffs && h.buffs.find(function(b){ return b && b.type === 'haste'; }); if(hb) hb._cstSpd = 1.25; return !!hb; }catch(_){ return false; } }

/* ── 拘留者 ── */
window._cstDtT2Mark = function(h){   // t2「時痕刻印星」:時序回響成功 ⇒ 時痕 +1(最多 3)
  try{
    if(!h || h.name !== '拘留者' || !window._cstHasN(h,'t2','拘留者')) return;
    if(!_cstSameRec(h._cstDtMk)) h._cstDtMk = { b:_cstBidD(), n:0 };
    if(h._cstDtMk.n >= 3) return;
    h._cstDtMk.n++;
    log('✨ [' + h.name + '] 命星:時痕刻印!時序回響留下「時痕」' + h._cstDtMk.n + '/3 層');
  }catch(_){}
};
window._cstDtT2Ratio = function(t, ratio){   // t2:空間果實發動 ⇒ 消耗全部時痕,每層反噬比例 +8%(最高 74%);沒有時痕 ⇒ 原值
  try{
    if(!t || !t._cstDtMk || !_cstSameRec(t._cstDtMk) || !(t._cstDtMk.n > 0) || !window._cstHasN(t,'t2','拘留者')) return ratio;
    var n = t._cstDtMk.n; t._cstDtMk.n = 0;
    var r2 = Math.max(ratio, Math.min(0.74, ratio + 0.08 * n));
    log('✨ [' + t.name + '] 命星:時痕刻印!消耗 ' + n + ' 層時痕,時空反噬比例 ' + Math.round(ratio * 100) + '% → ' + Math.round(r2 * 100) + '%');
    return r2;
  }catch(_){ return ratio; }
};
