/* ── 科學發明家 ── */
window._cstSciS2Full = function(h){   // s2「靈感不浪費星」:靈感觸發但背包已滿 ⇒ 我方 +1 能量(每回合 1、每場 3)
  try{
    if(!h || !(h.curHp > 0) || !window._cstHasN(h,'s2','科學發明家')) return;
    var inv = (typeof _invSideInv === 'function') ? _invSideInv(h.side) : null;
    if(!Array.isArray(inv) || inv.some(function(x){ return !x; })) return;   // 🔧 審查 L18:確認背包真的滿了
    var r = _cstS1R();
    if(!_cstSameRec(h._cstSciS2)) h._cstSciS2 = { b:_cstBidD(), r:0, n:0 };
    var S = h._cstSciS2; if(S.r === r || S.n >= 3) return;
    var g = window._cstCap.gainEnergy(h.side, 1);
    if(g > 0){ S.r = r; S.n++; log('✨ [' + h.name + '] 命星:靈感不浪費!背包滿了,靈感化為能量 +1(本場 ' + S.n + '/3)'); try{ updateUI(); }catch(_){} }
  }catch(_){}
};
window._cstSciB2Try = function(h, card){   // b2「最後一試星」:變賣前先以該卡 50% 的效果試用一次
  try{
    if(!h || !card || !window._cstHasN(h,'b2','科學發明家') || typeof G === 'undefined' || !G) return;
    var side = h.side, opp = _cstS1Opp(side);
    var al = function(){ return _cstS1Alive(side); }, fo = function(){ return _cstS1Alive(opp); };
    var low = function(){ var L = al(); return L.length ? L.slice().sort(function(x, y){ return x.curHp - y.curHp; })[0] : null; };
    var rnd = function(){ return _cstS1Pick(fo()); };
    log('✨ [' + h.name + '] 命星:最後一試!變賣前先以【' + card.n + '】50% 的效果試用一次!');
    try{ bannerFX(h, '🧪 最後一試!', '#88ffaa', 900); }catch(_){}
    if(card.type === 'invent'){
      var sp = card.inventorSpv || ((typeof _inventSpvOf === 'function') ? _inventSpvOf(h) : 0) || 20;
      if(card.inv === 'heal_shield'){
        (G[side] || []).forEach(function(t){ if(!t) return; if(t.curHp <= 0) doRevive(t, 0.15); else doHeal(t, Math.max(1, Math.floor(t.hp * 0.15)), { actor:h, isHeal:true, isPctHeal:true }); if(t.curHp > 0) t.shield = (t.shield || 0) + 25; try{ renderCard(t); }catch(_){} });
      } else if(card.inv === 'cleanse_heal'){
        al().forEach(function(t){ doHeal(t, Math.max(1, Math.floor(t.hp * 0.25)), { actor:h, isHeal:true, isPctHeal:true }); try{ _inventRemoveNDebuffs(t, 1); }catch(_){} try{ renderCard(t); }catch(_){} });
      } else if(card.inv === 'atk_boost'){
        al().forEach(function(t){ addBuff(t, 'dmgup', 1); t.buffs = (t.buffs || []).filter(function(b){ return b && b.type !== '_inventEnergyAtk'; }); t.buffs.push({ type:'_inventEnergyAtk', dur:1 }); try{ renderCard(t); }catch(_){} });
      } else if(card.inv === 'poison_dispel'){
        fo().forEach(function(t){ if(!hasStatus(t, 'poison')){ t.status.push({ type:'poison', dur:1, _strong:true }); t._poisonAmt = Math.max(1, Math.floor(t.hp * 0.075)); } try{ _inventRemoveNBuffs(t, 1); }catch(_){} try{ renderCard(t); }catch(_){} });
      } else if(card.inv === 'nuke_para'){
        var L = fo(); var t1 = L.length ? L.slice().sort(function(x, y){ return y.curHp - x.curHp; })[0] : null;
        if(t1){
          doDmg(t1, Math.max(1, Math.floor(sp * 1.5)), { actor:h, isSkill:true, mustHit:true, ignoreBuffs:true, ignoreEvasion:true, noGuard:true, noHidden:true, _cstReact:1 });
          if(t1.curHp > 0 && Math.random() < 0.5 && _cstS2Ctrl(t1, 'para', 1)){ var ps = (t1.status || []).find(function(s){ return s && s.type === 'para'; }); if(ps) ps._strong = true; }
          try{ renderCard(t1); }catch(_){}
        }
      } else if(card.inv === 'immune_counter'){
        var shv = Math.max(1, Math.floor(sp * 0.5));
        al().forEach(function(t){ _cstS2Shield(t, shv, '_cstSciSh', 1); try{ renderCard(t); }catch(_){} });
        log('✨ [' + h.name + '] 命星:最後一試!反應力場半效化為全體護盾 ' + shv + '(特技 50%)1 回合(無敵本來就由奇蹟提供)');
      }
      return;
    }
    var it = card;
    if(it.type === 'atk'){
      var d = Math.max(1, Math.ceil((it.dmg || 0) * 0.5));
      var ts = (it.target === 'e3') ? fo() : [rnd()].filter(Boolean);
      ts.forEach(function(t){ doDmg(t, d, { actor:h, _pierceBossReduce:true, isAoe:(it.target === 'e3'), _cstReact:1 }); try{ renderCard(t); }catch(_){} });
    } else if(it.type === 'heal'){
      var hv = Math.max(1, Math.ceil((it.hp || 0) * 0.5));
      var hs = (it.target === 'a3') ? al() : [low()].filter(Boolean);
      hs.forEach(function(t){ if(it.hp) doHeal(t, hv, { actor:h, isHeal:true }); if(it.effect === 'cleanse') _clearOneBadStatus(t); if(it.effect === 'shield') addBuff(t, 'shield', 1); try{ renderCard(t); }catch(_){} });
    } else if(it.type === 'revive'){
      var dd = (G[side] || []).filter(function(x){ return x && x.curHp <= 0; });
      var rv = _cstS1Pick(dd); if(rv){ doRevive(rv, it.full ? 0.5 : 0.25); try{ renderCard(rv); }catch(_){} }
    } else if(it.type === 'buff' && it.effect === 'shield'){
      var b1 = low(); if(b1){ addBuff(b1, 'shield', 1); try{ renderCard(b1); }catch(_){} }
    } else if(it.type === 'energy'){
      var ge = window._cstCap.gainEnergy(side, Math.floor((it.e || 0) / 2)); if(ge > 0) log('✨ [' + h.name + '] 命星:最後一試!能量 +' + ge);
    } else if(it.type === 'debuff'){
      var dt = rnd();
      if(dt){
        if(it.effect === 'dispel'){ try{ _inventRemoveNBuffs(dt, Math.ceil((dt.buffs || []).length / 2)); }catch(_){} }
        else if(it.effect === 'seal' || it.effect === 'noatk'){ if(Math.random() < 0.5) addStatus(dt, it.effect, 1); }
        else if(it.effect === 'drain5' || it.effect === 'drain9'){ var dr = window._cstCap.drainEnergy(h, dt.side, it.effect === 'drain5' ? 2 : 4); if(dr > 0) log('✨ [' + h.name + '] 命星:最後一試![' + dt.name + '] 陣營能量 -' + dr); }
        else if(it.effect === 'redcard'){ if(Math.random() < 0.5) _cstS2Ctrl(dt, 'stun', 1); }
        try{ renderCard(dt); }catch(_){}
      }
    } else {
      log('✨ [' + h.name + '] 命星:最後一試!【' + it.n + '】這種卡沒辦法只用一半,直接變賣');
    }
  }catch(_eCstSciB2){ console.warn('[命星 科學發明家 b2]', _eCstSciB2); }
};

