    log('✨ [' + mg.name + '] 命星:大變活人![' + t.name + '] 走出牢籠的瞬間,牢籠把記下的傷害變回來(累積 ' + C.acc + ' 的 30% = ' + d + ')!');
    try{ bannerFX(t, '🎩 大變活人!', '#9b4ddb', 1000); }catch(_){}
    _cstS3As(mg, function(){ doDmg(t, d, { actor:mg, isSkill:true, fixedDmg:true, mustHit:true, ignoreEvasion:true, noCrit:true, noCounter:true, _cstReact:1 }); });
