/* ── 水瓶星神 b2「時代革新星」:星海覆滅的禁療期間,對手原本會恢復的 HP 改流向我方 HP 最低的友方 ── */
window._cstAqB2Tag = function(h, t){ try{ if(h && t && window._cstHasN(h,'b2','水瓶星神')){ var s = (t.status || []).find(function(x){ return x && x.type === 'noheal_curse'; }); if(s){ s._cstAqBy = _cstRefOf(h); s._cstAqB = _cstBidD(); s._cstAqU = _cstS1R() + Math.max(1, s.dur || 2); } } }catch(_){} };
