    var s = (t.status || []).find(function(x){ return x && x.type === 'noheal_curse' && x._cstAqBy && _cstBidOk(x._cstAqB) && _cstS1R() <= (x._cstAqU || 0); }); if(!s) return;   // 只認這次爆發給的禁療期間(之後被別的禁療刷新也不延長)
    var aq = _cstRefGet(s._cstAqBy); if(!aq || aq.side === t.side || !(aq.curHp > 0) || !window._cstHasN(aq,'b2','水瓶星神')) return;
