/* ── 藝天使．克雷爾 s2「聖潔鏡繪星」:聖潔彩繪的「預防不利狀態」改為鏡繪:擋下的不利狀態以 1 回合反施給施放它的對手
 *    (每名友方每回合 1 次;BOSS 不會被反施;強力挑釁本來就擋不下) ── */
var _CST_CLR_NOMIR = ['deathmark','taunt','_youyouNightmare','phoenixFeather','lightshadow','_aquariusMark','reverseDomainCurse','_confess'];
window._cstClrS2Tag = function(a, t){ try{ if(a && t && window._cstHasN(a,'s2','藝天使．克雷爾')){ var b = (t.buffs || []).find(function(x){ return x && x.type === 'statusImmune'; }); if(b){ b._cstClMir = _cstRefOf(a); b._cstClMirB = _cstBidD(); } } }catch(_){} };
window._cstClrS2Mirror = function(h, ty){   // addStatus 被 statusImmune 擋下時呼叫
  try{
    if(!h || !ty || ty === 'strongTaunt' || typeof BAD_STATUS === 'undefined' || BAD_STATUS.indexOf(ty) < 0) return;
    if(_CST_CLR_NOMIR.indexOf(ty) >= 0) return;   // 需要施放者資料的狀態(死亡宣告/嘲諷/惡夢/熾羽/光影/刻印/反域/認罪)不反照:沒有來源資料會變成即死或卡死
    var b = (h.buffs || []).find(function(x){ return x && x.type === 'statusImmune' && x._cstClMir && _cstBidOk(x._cstClMirB); }); if(!b) return;
    var cl = _cstRefGet(b._cstClMir); if(!cl || !window._cstHasN(cl,'s2','藝天使．克雷爾')) return;
    var src = G.activeChar; if(!src || src.side === h.side || !(src.curHp > 0) || _cstS1Boss(src)) return;
    var r = _cstS1R(); if(_cstSameRec(h._cstClMirR) && h._cstClMirR.r === r) return;
    if(window._cstCap.HARD_CTRL.indexOf(ty) >= 0 && !window._cstCap.ctrlOk(src)) return;   // G6
    if(hasStatus(src, ty)) return;   // 已經有同一種 ⇒ 不覆蓋
    var pre = window._cstCap.ctrlPre(src, ty);
    addStatus(src, ty, 1);
    var ns = (src.status || []).find(function(s){ return s && s.type === ty; }); if(!ns) return;   // 對方免疫 ⇒ 不算用掉這回合的 1 次
    h._cstClMirR = { b:_cstBidD(), r:r };
    ns.dur = 1; delete ns._strong;
    if(window._cstCap.HARD_CTRL.indexOf(ty) >= 0) window._cstCap.markCtrl(src, ty, pre);
    log('✨ [' + cl.name + '] 命星:聖潔鏡繪![' + h.name + '] 身上的鏡繪擋下「' + _cstS2Name(ty) + '」,反照回 [' + src.name + '] 身上 1 回合!');
    try{ bannerFX(src, '🪞 鏡繪反照!', '#bfe9ff', 800); renderCard(src); }catch(_){}
  }catch(_){}
};

