    var t = _cstS9Foe(h).sort(function(x, y){ return y.curHp - x.curHp; })[0]; if(!t) return;
    var cap = Math.floor(R.atk0 * 3.0); if(_cstS1Boss(t)) cap = Math.floor(cap / 2);
