          try{ if(typeof _zeusIsTrueBoss === 'function' && _zeusIsTrueBoss(f)) amt = Math.min(amt, 5000); }catch(_){}
          doDmg(f, amt, { actor:h, isAoe:true, fixedDmg:true, mustHit:true, ignoreEvasion:true, noCounter:true, _moonBlast:true, elem:'dark', _cstReact:1 });
          try{ renderCard(f); }catch(_){}
