      try{ if(typeof _ur4TraitOn === 'function' && !_ur4TraitOn(h)){ log('✨ [' + h.name + '] 命星:月蝕輪迴 — 天賦被封住,衛月無法重新升起'); return; } }catch(_){}   // 比照原本所有召喚衛月的路徑:天賦被封不召喚
