/* ── 爆·貳「臨摹之眼星」:異界之力發動 ⇒ 臨摹友方(非 BOSS、不含自己)最高的一項素質(攻擊/特技/速度擇一),2 回合內取代自己的同項素質 ──
 *    以「差額」加上去、到期扣回(期間其他效果改到的素質不會被蓋掉);只在比自己高時才臨摹 */
window._cstPgB2Copy = function(h, side){
  try{
    if(!h || !(h.curHp > 0) || !window._cstHasP(h,'b2')) return;
    if(_cstSameRec(h._cstPgCopy)) window._cstPgB2Undo(h, true);   // 先還原上一段再重新臨摹
    var best = null;
    _cstS1Alive(side || h.side).forEach(function(x){
      if(x === h || _cstS1Boss(x)) return;
      ['atk','sp','spd'].forEach(function(st){ var v = x[st] || 0; if(!best || v - (h[st] || 0) > best.gain) best = { x:x, st:st, v:v, gain:v - (h[st] || 0) }; });
    });
    if(!best || !(best.gain > 0)){ log('✨ [' + h.name + '] 命星:臨摹之眼 — 夥伴沒有比主角更高的素質,這次不臨摹'); return; }
    h[best.st] = (h[best.st] || 0) + best.gain;
    h._cstPgCopy = { b:_cstBidD(), st:best.st, d:best.gain, until:_cstS1R() + 1 };
    var nm = { atk:'攻擊', sp:'特技', spd:'速度' }[best.st];
    log('✨ [' + h.name + '] 命星:臨摹之眼!臨摹 [' + best.x.name + '] 的' + nm + '(' + best.v + '),2 回合內主角的' + nm + '也是 ' + h[best.st] + '!');
    try{ bannerFX(h, '👁 臨摹' + nm + '!', '#ffd97a', 1000); renderCard(h); }catch(_){}
  }catch(_){}
};
window._cstPgB2Undo = function(h, quiet){
  try{
    var R = h && h._cstPgCopy; if(!R) return;
    delete h._cstPgCopy;
    if(!_cstSameRec(R)) return;
    h[R.st] = Math.max(1, (h[R.st] || 0) - R.d);
    if(!quiet) log('✨ [' + h.name + '] 命星:臨摹之眼的效果結束,' + ({ atk:'攻擊', sp:'特技', spd:'速度' })[R.st] + '恢復原狀');
    try{ renderCard(h); }catch(_){}
  }catch(_){}
};
