    if(!(a.status || []).some(function(s){ return s && s.type === 'burstVamp' && s._cstVpB2; })) return;
    if(!window._cstHasN(a,'b2','吸血鬼')) return;
    const _over = Math.floor(Math.max(0, (hp0 || 0) + amt - (a.hp || 0)) - (minus || 0));   // ★ v5.262.0 審查:(review8_1 M8)只算超過最大 HP 的部分(減療/增療改掉的量不再被當成溢出)
