      const _pk = _al.filter(function(x){ return !(x._cstAstGuide && _cstBidOk(x._cstAstGuide.b)); }).sort(function(x, y){ return _cmax(y) - _cmax(x); })[0];   // ★ v5.262.0 審查:(M9)
