          try{ if(_odTl2 >= 3 && window._cstHasN(_odinH,'t1','主神奧汀')){ rawDmg = Math.max(1, Math.floor(rawDmg * 0.8)); log('✨ [' + _odinH.name + '] 命星:雙鴉注視!注視已滿額,這一擊額外減傷 20%'); } }catch(_eCstOdnT1dr){}
