          const _dlabel = target._dragonSupreme ? '🐉👑 至尊天青龍' : '🐉 天青龍';
          log(`${_dlabel} 代承 [${target.name}] ${_dAbsorb} 傷害!(剩 ${Math.max(0,target._dragonHp)}/${target._dragonHpMax})`);
          bannerFX(target, `${_dlabel}守護!`, '#7df9ff', 900); // ★ v3.16.60 召喚物笑果標籤(天青龍守護!/至尊天青龍守護!·扣血數字見上方 log)
          flashCard(target, 'rgba(125,249,255,0.40)', 400);
          renderCard(target);
