// 執行:丟棄玩家某格物品 + 將偷到的物品放入該格
function _doStealReplaceItem(thief, victim, victimItemIdx, mySlotIdx, stolenItem){
  const _ov = document.getElementById('steal-discard-ov');
  if(_ov) _ov.remove();
  const _vInv = (victim.side === 'p2') ? G.inv2 : G.inv;
  const _myInv = (thief.side === 'p1') ? G.inv : G.inv2;
  const _discarded = _myInv[mySlotIdx];
  // 對方那格仍存在嗎?
  if(_vInv[victimItemIdx] !== stolenItem){
    log('該物品已不存在,偷取失敗!');
    // 回到 picker
    const st = window._stealState;
    if(st && st.remaining > 0) _showStealPicker(thief, victim, st.remaining, st.cost);
    return;
  }
  // 執行丟棄+置換
  _myInv[mySlotIdx] = stolenItem;
  _vInv[victimItemIdx] = null;
  log(`🗑️ [${thief.name}] 丟棄 [${_discarded ? _discarded.n : '空格'}],偷得 [${stolenItem.n}]!`);
  bannerFX(thief, '🗡偷得 '+stolenItem.n, '#ffcc00', 800);
  if(thief.side === 'p1') renderItems();

  // 更新 stealState
  const st = window._stealState;
  if(st){
    st.remaining--;
    const _cntEl = document.getElementById('steal-remaining-cnt');
    if(_cntEl) _cntEl.textContent = st.remaining;
    if(st.remaining > 0){
      _showStealPicker(thief, victim, st.remaining, st.cost);
    } else {
      _finishSteal();
    }
  }
}

