// ★ v3.10.19 — 此函式已棄用(舞者「魅惑之舞」改為單純強力魅惑 2 回合)
//   保留 dead code 以防未來有其他「操控對方使用技能」類設計可借鏡
function _showCharmPicker(dancer, victim, cost){
  var ov=document.getElementById('charm-ov');
  if(ov) ov.remove();
  ov=document.createElement('div');
  ov.id='charm-ov';
  ov.style.cssText='position:absolute;inset:0;background:rgba(0,0,0,0.86);z-index:310;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;font-family:Share Tech Mono,monospace;';
  var sk1Disabled=victim.s1.p;
  var sk2Disabled=victim.s2.p;
  var ek1=G.energy[victim.side]<skillCost(victim.s1,victim,true);
  var ek2=G.energy[victim.side]<skillCost(victim.s2,victim,true);
  // Classify skills: heal/buff type → applied to dancer's allies; attack → to dancer's enemies
  var healSkillSet=new Set(['救贖神光','治癒之風','神聖鎚擊','聖殿領域','天堂樂章','熱情之舞',
    '挺身守護','道具複製','賢者之石','金鐘罩','急速閃躲','隱身療傷',
    '不動如山','以牙還牙','轉禍為福','增強術','能力轉換','元素增幅',
    '兵貴神速之計','極限閃光']);
  function isHealSkill(sk){ return healSkillSet.has(sk.n); }
  ov.innerHTML='<div style="font-size:20px;color:#ff77dd;letter-spacing:4px">💃 魅惑之舞</div>'
   +'<div style="font-size:16px;color:#fff">操控 '+victim.av+' '+victim.name+' 使用：</div>'
   +'<div style="display:flex;gap:12px;flex-wrap:wrap;justify-content:center;max-width:860px">'
   +'<button id="cm0" style="background:rgba(20,20,40,0.9);border:2px solid #ff55cc;border-radius:10px;padding:14px 18px;cursor:pointer;color:#fff;font-family:Share Tech Mono,monospace;min-width:200px;text-align:left"><div style="font-size:18px;font-weight:500;color:#ff88ee;margin-bottom:4px">普通攻擊</div><div style="font-size:12px;color:#aaa">ATK '+victim.atk+' → 攻擊施展者的敵人</div></button>'
   +'<button id="cm1" style="background:rgba(20,20,40,0.9);border:2px solid #ff55cc;border-radius:10px;padding:14px 18px;cursor:pointer;color:#fff;font-family:Share Tech Mono,monospace;min-width:200px;text-align:left;'+(sk1Disabled||ek1?'opacity:0.4;pointer-events:none':'')+'">'
   +'<div style="font-size:18px;font-weight:500;color:#ff88ee;margin-bottom:4px">'+victim.s1.n+' '+(isHealSkill(victim.s1)?'💚':'⚔')+'</div>'
   +'<div style="font-size:12px;color:#aaa">🔷'+victim.s1.c+' — '+(isHealSkill(victim.s1)?'作用於我方':'作用於敵方')+'</div></button>'
   +'<button id="cm2" style="background:rgba(20,20,40,0.9);border:2px solid #ff55cc;border-radius:10px;padding:14px 18px;cursor:pointer;color:#fff;font-family:Share Tech Mono,monospace;min-width:200px;text-align:left;'+(sk2Disabled||ek2?'opacity:0.4;pointer-events:none':'')+'">'
   +'<div style="font-size:18px;font-weight:500;color:#ff88ee;margin-bottom:4px">'+victim.s2.n+' '+(isHealSkill(victim.s2)?'💚':'⚔')+'</div>'
   +'<div style="font-size:12px;color:#aaa">🔷'+victim.s2.c+' — '+(isHealSkill(victim.s2)?'作用於我方':'作用於敵方')+'</div></button>'
   +'</div><div style="font-size:12px;color:#888">⚔ = 攻擊/控制技能作用於施展者的敵方 | 💚 = 治療/支援技能作用於我方</div>';
  document.getElementById('gc').appendChild(ov);
  function doClose(){ var o=document.getElementById('charm-ov'); if(o)o.remove(); }
  var myEnemies=G[dancer.side==='p1'?'p2':'p1'].filter(function(h){return h.curHp>0;});
  var myAllies=G[dancer.side].filter(function(h){return h.curHp>0;});
  function execCharm(sk, isSelf){
    // isSelf=true: heal/buff skill → apply to dancer's allies
    // isSelf=false: attack skill → apply to dancer's enemies
    if(isSelf){
      var t=myAllies.length?myAllies[Math.floor(Math.random()*myAllies.length)]:null;
      if(!t){ log('['+victim.name+'] 魅惑失敗：無我方目標'); endAction(dancer,cost); return; }
      log('['+victim.name+'] 受魅惑，對 ['+t.name+'] 使用支援技能 ['+sk.n+']！');
      G.energy[victim.side]=Math.max(0,G.energy[victim.side]-skillCost(sk,victim,true));
      doHeal(t, victim.sp, {actor:victim, isHeal:true});
      endAction(dancer,cost);
    } else {
      var foe=myEnemies.length?myEnemies[Math.floor(Math.random()*myEnemies.length)]:null;
      if(!foe){ log('['+victim.name+'] 魅惑失敗：無敵方目標'); endAction(dancer,cost); return; }
      log('['+victim.name+'] 受魅惑，對 ['+foe.name+'] 使用攻擊技能 ['+sk.n+']！');
      G.energy[victim.side]=Math.max(0,G.energy[victim.side]-skillCost(sk,victim,true));
      doDmg(foe, victim.sp, {actor:victim});
      endAction(dancer,cost);
    }
  }
  document.getElementById('cm0').onclick=function(){
    doClose();
    var foe=myEnemies.length?myEnemies[Math.floor(Math.random()*myEnemies.length)]:null;
    if(foe){ log('['+victim.name+'] 受魅惑普攻 ['+foe.name+']！'); var _charmDmg = (victim.name==='幽幽') ? Math.max(1, Math.floor((victim.sp||0)*(1+(victim.sp||0)*0.01))) : victim.atk; doDmg(foe, _charmDmg, {actor:victim}); }
    endAction(dancer,cost);
  };
  document.getElementById('cm1').onclick=function(){
    if(sk1Disabled||ek1) return;
    doClose();
    execCharm(victim.s1, isHealSkill(victim.s1));
  };
  document.getElementById('cm2').onclick=function(){
    if(sk2Disabled||ek2) return;
    doClose();
    execCharm(victim.s2, isHealSkill(victim.s2));
  };
}

// ★ v3.13.28(2026-06-03) — 大天狗 S2「風捲殘雲」速度降低 25% 共用 helper(execSkill + aiUseSkill 共用)
//   做法比照天神宙斯 S1 _zeusSpDown:真的把 spd 乘 0.75,並把原值存進 status._origSpd,到期由 tickStatus 還原。
//   專屬狀態 _tenguSpdDown(不與冰法師的 traitSlow 共用,避免兩者 _origSpd 互相覆寫)。
//   重複施放保護:若目標已帶 _tenguSpdDown,先把 spd 還原成原值再重新套用,避免「在已降速的基礎上再降 25%」疊乘 + _origSpd 失真。
function _applyTenguSpdDown25(t, dur){
  try{
    if(!t || t.curHp <= 0) return;
    // ★ v3.34.0 — 大刀勇士「愈戰愈勇」:不會被降低能力(直寫點守門,單一咽喉點涵蓋所有呼叫者)
    if(typeof _bvStatDownImmune === 'function' && _bvStatDownImmune(t, '速度降低')) return;
    if(!Array.isArray(t.status)) t.status = [];
    // 先還原既有的本招減速(取真正的原始速度當基底)
    const _existing = t.status.find(s => s && s.type === '_tenguSpdDown');
    if(_existing && _existing._origSpd !== undefined){ t.spd = _existing._origSpd; }
    t.status = t.status.filter(s => s && s.type !== '_tenguSpdDown');
    const _orig = t.spd;
    t.spd = Math.max(1, Math.floor(t.spd * 0.75));   // 速度 -25%
    t.status.push({ type:'_tenguSpdDown', dur:(dur||2), _origSpd:_orig });
    try{ bannerFX(t, '🌪️ 速度-25%', '#88ccff', 800); }catch(_){}
  }catch(e){ console.warn('[_applyTenguSpdDown25]', e); }
}

// ════════════════════════════════════════════════════════════════
// ★★ v5.76.0(老師 2026-08-19 裁定)— 破防 / 破盾 施加共用 helper
//   背景:v5.75.0 重新設計三個「破綻類」狀態後,破防只有炸彈客天賦一個來源、
//   破盾完全沒有來源。老師裁定把兩者分別配給日本關兩隻弱化版英雄:
//     ・大天狗 S2「風捲殘雲」→ 敵全體【破防】2 回合(受暴擊率 +25%)
//     ・酒吞童子 S1「鬼力橫掃」→ 敵全體【破盾】2 回合(格擋率 -25%)
//   兩支 helper 供 execSkill(玩家)與 aiUseSkill(AI)兩條路徑共用(鐵律 1.128),
//   實作不得各寫一份以免日後單邊改動失同步。
//   ★ 一律走 addStatus → 既有免疫/抗性/地龍王之麟等守門全數自動尊重,不另開後門。
//   ★ 皆為「普通版」(不帶 _strong);強力版依老師 v5.75.0 裁定保留給爆發或 UR。
// ════════════════════════════════════════════════════════════════
function _applyBreakDefTo(t, dur){
  try{
    if(!t || t.curHp <= 0) return;
    if(typeof addStatus !== 'function') return;
    addStatus(t, 'breakDef', (dur || 2));
    try{ bannerFX(t, '💣 破防!', '#ff4422', 800); }catch(_){}
  }catch(e){ console.warn('[_applyBreakDefTo]', e); }
}
function _applyBreakBlockTo(t, dur){
  try{
    if(!t || t.curHp <= 0) return;
    if(typeof addStatus !== 'function') return;
    addStatus(t, 'breakBlock', (dur || 2));
    try{ bannerFX(t, '💥 破盾!', '#ffaa33', 800); }catch(_){}
  }catch(e){ console.warn('[_applyBreakBlockTo]', e); }
}
/* ✨ 命星 酒吞童子 s1(老師 2026-10-15 裁定甲):「鬼力橫掃」暴擊命中的目標,已掛上的「破盾」升級為「強力破盾」(格擋率 -50%)。
   只在 _cstHasN 為真且該目標本次暴擊時被呼叫;破盾被免疫/擋下(身上沒有 breakBlock)⇒ 不另開後門、什麼都不做。
   execSkill / aiUseSkill 兩條路徑共用(鐵律 1.128)。 */
window._cstShutenStrongBlock = function(a, t){
  try{
    if(!a || !t || !(t.curHp > 0)) return false;
    if(!window._cstHasN(a,'s1','酒吞童子')) return false;
    var _arr = t.status || [], _bb = null;
    for(var _i = 0; _i < _arr.length; _i++){ if(_arr[_i] && _arr[_i].type === 'breakBlock'){ _bb = _arr[_i]; break; } }
    if(!_bb || _bb._strong) return false;
    _bb._strong = true;
    try{ log('✨ [' + a.name + '] 命星:鐵棒碎甲!暴擊砸穿 [' + t.name + '] 的防具,「破盾」升級為「強力破盾」(格擋率 -50%)!'); }catch(_){}
    try{ bannerFX(t, '💥 強力破盾!', '#ff7711', 900); }catch(_){}
    return true;
  }catch(_eCstShS1){ return false; }
};
/* ✨ v5.256 命星 SSR(h5 批)共用零件:只在 _cstHasN 為真時被呼叫,未點亮時完全不會執行 */
window._cstHitSnap = function(t){
  try{
    if(!t) return null;
    var _s = (t.shield || 0);
    (t.buffs || []).forEach(function(b){ if(b && typeof _ur4IsShieldBuff === 'function' && _ur4IsShieldBuff(b)) _s += (_lxpsShAmt(b) || 0); });   // 🔧 v5.258.0 舊 bug:原本只算 _amt,amt / val 欄位的護盾被打掉也不算「被打中」
    if(t._dragonActive) _s += (t._dragonHp || 0);
    return { hp:(t.curHp || 0), sh:_s };
  }catch(_){ return null; }
};
window._cstHitWas = function(t, snap){
  try{ var n = window._cstHitSnap(t); return !!(snap && n && (n.hp < snap.hp || n.sh < snap.sh)); }catch(_){ return false; }
};
/* 維京海盜船長 s1:同一目標吃 ≥2 發 → 破盾(拆數值護盾/護盾類 buff/天青龍盾;不拆 _protected/_noStripe 與世界龍王元素盾)+ 擊退行動條 20%(BOSS 只破盾) */
window._cstVkShot = function(a, t, snap){
  try{
    var st = a && a._cstVkCast; if(!st || st.done || !t) return;
    if(!window._cstHitWas(t, snap)) return;
    var c = (st.cnt.get(t) || 0) + 1; st.cnt.set(t, c);
    if(c < 2 || t.curHp <= 0) return;
    st.done = true;
    var _br = 0;
    if((t.shield || 0) > 0){ t.shield = 0; _br++; }
    if(Array.isArray(t.buffs)){
      var _n0 = t.buffs.length;
      t.buffs = t.buffs.filter(function(b){ return !(b && typeof _ur4IsShieldBuff === 'function' && _ur4IsShieldBuff(b) && !b._protected && !b._noStripe); });
      _br += (_n0 - t.buffs.length);
    }
    if(t._dragonActive && (t._dragonHp || 0) > 0){ t._dragonHp = 0; t._dragonActive = false; t._dragonSupreme = false; _br++; }
    var _boss = (typeof _zeusIsTrueBoss === 'function' && _zeusIsTrueBoss(t)) || (typeof _isWorldBossTarget === 'function' && _isWorldBossTarget(t));
    if(!_boss) t._cstPush = Math.min(0.9, (t._cstPush || 0) + 0.2);
    log('✨ [' + a.name + '] 命星:集火齊鳴![' + t.name + '] 被 2 發砲彈集中轟擊' + (_br ? ',護盾碎裂' : '(沒有可破的護盾)') + (_boss ? '(BOSS 不被擊退)' : ',行動條被擊退 20%') + '!');
    try{ bannerFX(t, '💥 破盾!', '#ffaa33', 800); renderCard(t); }catch(_){}
  }catch(_e){ console.warn('[命星 維京 s1]', _e); }
};
/* 火柴人 s1:追加機率 +20%(上限 100%);目標燃燒中必定追加 */
window._cstMmExtra = function(a, t, rate, r){
  try{
    if(!window._cstHasN(a, 's1', '火柴人')) return false;
    var _burn = (t.status || []).some(function(s){ return s && (s.type === 'hellfire' || s.type === 'burn'); });
    var _ok = _burn || (r < Math.min(1, rate + 0.20));   /* 沿用同一次骰值(審查:另擲一次會讓機率變成 r+(1−r)(r+0.2)) */
    if(_ok) log('✨ [' + a.name + '] 命星:連環點火' + (_burn ? '(目標正在燃燒,必定追加)' : '') + '!');
    return _ok;
  }catch(_){ return false; }
};
/* 青炎龍王 s1:扣能量前判斷是否「上回合剛被熄火」→ 本回合不再扣;扣完後若歸零 → 龍王 +1 能量(每回合 1 次) */
window._cstAzSkip = function(a, opp){
  try{
    if(!window._cstHasN(a, 's1', '青炎龍王')) return false;
    var r = (G.round || 1);
    var sk = !!(G._cstAzZero && G._cstAzZero[opp] === r - 1);
    if(sk) log('✨ [' + a.name + '] 命星:熄火吞能——對手上回合已被熄火,本回合青炎爆破不再扣能量。');
    return sk;
  }catch(_){ return false; }
};
window._cstAzPost = function(a, opp, e0, skipped){
  try{
    if(skipped || !window._cstHasN(a, 's1', '青炎龍王')) return;
    if(!(e0 > 0) || (G.energy[opp] || 0) !== 0) return;
    var r = (G.round || 1);
    G._cstAzZero = G._cstAzZero || {}; G._cstAzZero[opp] = r;
    if(a._cstAzS1R === r) return;
    a._cstAzS1R = r;
    var g = window._cstCap.gainEnergy(a.side, 1);
    if(g > 0) log('✨ [' + a.name + '] 命星:熄火吞能!對手能量歸零,龍王陣營能量 +' + g + '!');
  }catch(_e){ console.warn('[命星 青炎龍王 s1]', _e); }
};

