// ★ v5.42.0 — 孫悟空 S2「七十二變」候選池(老師 2026-08-15 追加裁定:隨機技)
//   規則:現有 SSR 英雄的「同消耗能量(c=5)攻擊技能」隨機一招,以孫悟空自身素質結算。
//   過濾:①稀有度=SSR(_getHeroRarity;自動排除 R/SR/UR 與查無稀有度的 BOSS/小怪)
//         ②非 BOSS_NAMES(雙保險排除妖王/魔物技能) ③非被動(p) ④c===5
//         ⑤說明含「造成」+「傷害」(排除只提到受傷/減傷的防禦技) ⑥黑名單(防禦/增益/需特殊資源技)
//         ⑦排除孫悟空自己與主角。exec/AI 兩路徑共用同一顆(鐵律 1.128 同口徑)。
//   施展=re-dispatch 回 execSkill/aiUseSkill(stype 不變 → _activeSkLvMult 讀七十二變自己的等級,
//   升級自然放大被模仿招的傷害;_curSkillName 隨之改為被模仿技能名 → 屬性/特效全吃該招原設定)。
// ════════════════════════════════════════════════════════════════
const _WK72_BLACKLIST = new Set(['暗行','冥佑','血劍·防','進攻號令','武器精煉強化','防具精煉強化','杳杳香魂','烈焰力場']);
function _wk72PickCandidates(cost){
  const _out = [];
  try{
    for(const _hn in HERO_DB){
      if(_hn === '孫悟空') continue;
      try{ if(window._isProtagHero && window._isProtagHero(_hn)) continue; }catch(_){}
      const _rr = (typeof _getHeroRarity === 'function') ? _getHeroRarity(_hn) : null;
      if(_rr !== 'SSR') continue;
      if(typeof BOSS_NAMES !== 'undefined' && BOSS_NAMES.includes && BOSS_NAMES.includes(_hn)) continue;
      ['s1','s2'].forEach(function(_slot){
        const _s = HERO_DB[_hn][_slot];
        if(!_s || _s.p || _s.c !== cost) return;
        const _d = (_s.d || '') + (_s.fd || '');
        if(_d.indexOf('造成') < 0 || _d.indexOf('傷害') < 0) return;
        if(_WK72_BLACKLIST.has(_s.n)) return;
        _out.push({ hero:_hn, sk:_s });
      });
    }
  }catch(_eWkPool){ console.warn('[七十二變 候選池] 失敗', _eWkPool); }
  return _out;
}
try{ window._wk72PickCandidates = _wk72PickCandidates; }catch(_){}
