        try{ if(_th !== _cstCaTh0 && (t.curHp / (t.hp || 1)) >= _cstCaTh0) log('✨ [' + _cra.name + '] 命星:柳宿增三鉗!門檻放寬為 ' + Math.round(_th*100) + '%,[' + t.name + '] 也被照顧到了!'); }catch(_){}
