      try{ _cstTmS1Burn = !!(_cstTmS1 && (hasStatus(t,'hellfire') || hasStatus(t,'burn'))); }catch(_eCstTmS1B){ _cstTmS1Burn = false; }
      if(_cstTmS1Burn){ try{ log('✨ ['+a.name+'] 命星:狐火命中燃燒中的 ['+t.name+'],傷害 +30%!'); }catch(_eCstTmS1L){} }
      doDmg(t, (_cstTmS1Burn ? Math.floor(spv(a) * _multTam1 * 1.3) : Math.floor(spv(a) * _multTam1)), {actor:a, isSkill:true, element:'fire'});
