      // ★ 附加 30 護盾（取較大值覆蓋）
      const _exSh = _tgt.buffs.find(b=>b.type==='bigshield');
      if(_exSh){ _exSh._hp = Math.max(_exSh._hp||0, 30); _exSh.dur = 99; }
      else { _tgt.buffs.push({type:'bigshield', dur:99, _hp:30}); }
