    const _enemySideB = (a.side === 'p1') ? 'p2' : 'p1';
    const _foesB = G[_enemySideB].filter(h => h && h.curHp > 0 && h.side === _enemySideB && h.side !== a.side);
    if(_foesB.length === 0){ endAction(a, cost); return; }
    log(`🌑 [${a.name}] 黑暗光束!三道漆黑光柱劈下!`);
