      log(`[${a.name}] 增強術 [${t.name}]！攻擊、特技、速度提升50%，2回合！`);
      // 先清除舊的增強狀態（刷新）
      t.buffs=t.buffs.filter(b=>b.type!=='strengthened');
      const origAtk=t._strengthOrigAtk!==undefined?t._strengthOrigAtk:t.atk;
      const origSp=t._strengthOrigSp!==undefined?t._strengthOrigSp:t.sp;
      const origSpd=t._strengthOrigSpd!==undefined?t._strengthOrigSpd:t.spd;
      t._strengthOrigAtk=origAtk; t._strengthOrigSp=origSp; t._strengthOrigSpd=origSpd;
