    const _hisLv = (a._skLv && typeof a._skLv.s1 === 'number' && a.s1 && a.s1.n==='歷史的教訓') ? a._skLv.s1
                : (a._skLv && typeof a._skLv.s2 === 'number' && a.s2 && a.s2.n==='歷史的教訓') ? a._skLv.s2 : 0;
