      if(!t || t.curHp <= 0){ endAction(a, cost); return; }
      const _mmS1Lv = (a._skLv && typeof a._skLv.s1 === 'number') ? a._skLv.s1 : 0;
      const _mmMult = 2.00 + _mmS1Lv * 0.05;
