    log(`🐲 [${a.name}] 青炎爆破!自損 ${_selfLoss} HP,對全敵 ${_finalDmg} 火傷害(上限 Lv×20=${_azDmgCap})!扣對手 ${_azEnergyDrain} 能量!`);
    try{ bannerFX(a, '🐲 青炎爆破!', '#3399ff', 1200); }catch(_){}
