          try{ if(_cstJkS1 && (typeof _cstJkR !== 'number' || _cstJkR > 0) && t.curHp > 0){ t.status = t.status || []; let _cstSm = t.status.find(function(s){ return s && s.type === 'joker_sad_mask' && s._isJokerMask; }); let _cstSmMax = 5; try{ if(window._cstHasN(a,'t1','小丑')) _cstSmMax = 7; }catch(_){} if(!_cstSm){ _cstSm = {type:'joker_sad_mask', dur:99, _stacks:1, _isJokerMask:true, _strong:true}; t.status.push(_cstSm); } else if((_cstSm._stacks || 0) < Math.max(_cstSmMax, _cstSm._cstMax || 5)){ _cstSm._stacks = (_cstSm._stacks || 0) + 1; } if(_cstSmMax === 7) _cstSm._cstMax = 7; log('✨ [' + a.name + '] 命星:驚嚇禮炮![' + t.name + '] 悲傷面具 +1(現 ' + _cstSm._stacks + ' 層)'); } }catch(_eCstJkSad){}
          try{ renderCard(t); }catch(_){}
