    a.buffs = (a.buffs || []).filter(b => b.type !== '_youyouDarkwalk');
    if(!window._cstRevealBlk(a, '_youyouDarkwalk')) a.buffs.push(window._cstYyS2Tag(a, { type:'_youyouDarkwalk', dur:_dwDur + 1, _dmgBoost:_dwBoost, _mustHit:true, _unremovable:false }));   /* ✨ v5.266.0 命星 幽幽 s2:未點亮原物件不變 */   // ★ v5.262.0 命星 偵探 s2:被揭露者不能再進入暗行
    try{ renderCard(a); }catch(_){}
