      const _goodBuffs = _t.buffs.filter(b => !b._protected && !b._noStolen && !b._noSteal && !b._unremovable && !b._undispellable);  // 排除受保護  // 🔧 v5.258.0 舊 bug:原只認 _noStolen,補上 _noSteal/_unremovable/_undispellable(不可奪取/不可消除)
      // 隨機選最多 3 個移除
