      try{ if(_cstHkS1 && _cstHkRm >= 3 && _t.curHp > 0){ addStatus(_t,'seal',1); log('✨ [' + a.name + '] 命星:防火牆粉碎![' + _t.name + '] 一次被拆 3 個有利狀態,封印技能 1 回合!'); } }catch(_eCstHkS1s){}
      try{ renderCard(_t); }catch(_){}
