  var typeLabels = {'atk':'⚔ 攻擊','debuff':'☠ 不利狀態','heal':'💚 治療','revive':'✨ 復活','buff':'⭐ 強化','energy':'⚡ 能量','field':'🃏 戰場卡','equip':'🐾 寵物'};
  var done = false;
