    return '<div style="background:linear-gradient(160deg,#1a1d2e,#0e1018);border:3px solid ' + tc + ';border-radius:16px;padding:22px 26px;width:560px;max-width:100%;box-sizing:border-box;text-align:center;box-shadow:0 0 36px ' + tc + '55;display:flex;flex-direction:column;align-items:center;gap:12px;">'
