function _hasAlchemistPassive(actor){
  // 判斷是否為煉金術師且擁有道具複製技能，且有足夠能量
  if(!actor || actor.side!=='p1') return null;
  const sk = (actor.s1.n==='道具複製')?actor.s1:(actor.s2.n==='道具複製'?actor.s2:null);
  if(!sk) return null;
  const cost = skillCost(sk, actor, true);
  if(G.energy[actor.side] < cost) return null;
  if(hasStatus(actor,'seal') || fieldHas('sealall', actor.side)) return null;
  return {sk, cost};
}

