// 主動被動：高亮已由 updateUI disabled 邏輯處理，此函數保留空殼供 startTurn 呼叫
function highlightActivePassives(hero){ /* handled in updateUI */ }



// 檢查主動被動的觸發條件（輪到自己行動時）
function checkActivePassiveTrigger(hero){
  const enemies = G[hero.side==='p1'?'p2':'p1'].filter(h=>h.curHp>0);
  const allies  = G[hero.side].filter(h=>h.curHp>0);

  for(const sk of [hero.s1, hero.s2]){
    if(!sk.p || !ACTIVE_PASSIVES.includes(sk.n)) continue;
    const cost = skillCost(sk, hero);
    if(G.energy[hero.side] < cost) continue;

    let conditionMet = false;
    let triggerDesc = '';

    if(sk.n==='金鐘罩'){
      // 金鐘罩為純自動被動，不顯示主動觸發提示
      conditionMet=false;
    }
    else if(sk.n==='轉禍為福'){
      // 條件：有存活友方可加護
      if(!hasBuff(hero,'misfortune2') && G[hero.side].filter(h=>h.curHp>0).length>0){ conditionMet=true; triggerDesc='使友方全體1回合內受到傷害時獲得2能量（每人限1次）'; }
    }
    else if(sk.n==='不動如山'){
      // 條件：有存活的敵方（有被施加不利狀態的風險），且尚未啟動
      if(enemies.length && !hasBuff(hero,'immovable') && !hero._immovableUsedThisTurn){ conditionMet=true; triggerDesc=`有 ${enemies.length} 名敵方存活，可預先免疫不利狀態`; }
    }
    else if(sk.n==='以牙還牙'){
      // 條件：有存活的敵方（有受傷風險）
      if(enemies.length && !hasBuff(hero,'rebirth')){ conditionMet=true; triggerDesc=`有 ${enemies.length} 名敵方存活，受傷時可反彈傷害`; }
    }

    if(conditionMet) return { sk, cost, triggerDesc };
  }
  return null;
}

