    const _cp = (typeof _lxpsStatFxSanitizeCopies === 'function') ? _lxpsStatFxSanitizeCopies([cand.buff])[0] : Object.assign({}, cand.buff);
    const _ex = rec.buffs.find(function(b){ return b && b.type === _cp.type; });
