  const _astStarRoll0 = !!(next.name==='占星師' && next.curHp>0 && !hasStatus(next,'confused') && !(next._astStarG === G && next._astStarR === G.round));   // 🔧 v5.262.0 舊 bug:星語在 startTurn 有兩個觸發點,原本兩處各自擲骰 ⇒ 同一回合可能 +6 能量;改為每回合只擲 1 次(兩個觸發點共用旗標)
