      try{ bannerFX(next, `🎵 療癒之聲 +${_healAmt}`, '#66ccff', 700); }catch(_){}
      G[next.side].filter(h => h.curHp > 0).forEach(_a => { try{ renderCard(_a); }catch(_){} });
