  // ★ v1.0.20260518.6920 — 學霸(轉學生)天賦「考神附體」:回合結束時觸發
  //   觸發條件:
  //     - 場上有存活的學霸(p1 + p2 都掃)、未被疑惑
  //     - 機率擲骰:基礎 40% + 每升 1 級 +5%(Lv5 達 60%)
  //   實作:
  //     - 對對手陣營存活對手隨機挑 1 名,造成 100 固定傷害
  //     - 用 fixedDmg:true + ignoreBuffs:true,不暴擊、不受元素、無視有利
  //   ⚠ 此天賦在「回合切換」瞬間觸發(即上一回合結束),所以放在 G.round++ 之前
  //   ⚠ 同隊兩隻學霸都會各自獨立擲骰
  try{
    const _sides = ['p1','p2'];
    _sides.forEach(_s => {
      if(!G[_s]) return;
      G[_s].forEach(_sc => {
        if(!_sc || _sc.name !== '學霸(轉學生)' || _sc.curHp <= 0) return;
        if(typeof hasStatus === 'function' && hasStatus(_sc, 'confused')) return;
        const _scTl = (typeof _getTraitLv === 'function') ? _getTraitLv('學霸(轉學生)') : 0;
        const _scProc = Math.min(1.0, 0.40 + _scTl * 0.05 + ((function(){ try{ return window._cstHasN(_sc,'t1','學霸(轉學生)') ? 0.15 : 0; }catch(_eCstScT1){ return 0; } })()));   // ✨ 命星 學霸 t1:+15%
        if(Math.random() < _scProc){
          const _opp = _s === 'p1' ? 'p2' : 'p1';
          const _foes = (G[_opp] || []).filter(_f => _f.curHp > 0);
          if(!_foes.length) return;
          const _t = _foes[Math.floor(Math.random() * _foes.length)];
          try{ log(`🤓 [${_sc.name}] 考神附體!對 [${_t.name}] 降下 100 固定傷害!(機率 ${Math.round(_scProc*100)}%)`); }catch(_){}
          try{ bannerFX(_t, '🤓 考神附體!', '#aaccff', 900); }catch(_){}
          try{ playSfx('sfx-passive', 0.7); }catch(_){}
          try{
            doDmg(_t, ((function(){ try{ return (window._cstHasN(_sc,'t1','學霸(轉學生)') && _t.hp > 0 && _t.curHp < _t.hp * 0.5) ? 115 : 100; }catch(_eCstScT1b){ return 100; } })()), {   // ✨ 命星 學霸 t1:目標 HP<50% 時 115
              fixedDmg:true,
              actor:_sc,
              isSkill:true,
              ignoreBuffs:true,
              isRebound:true,             // 不引發還手類天賦
              _pressureAbsorbed:true       // 不會被另一個學霸的壓力吸收(防雙學霸自己餵自己)
            });
            try{ window._cstScT2Mark(_sc, _t); }catch(_eCstScT2m){}   // ✨ v5.265.0 命星 學霸 t2「紅筆訂正星」
            renderCard(_t);
          }catch(_){}
        }
      });
    });
  }catch(_se){ console.warn('[學霸] 考神附體觸發失敗', _se); }

  // ★ 時間倒轉用：滑動快照鏈 — 把目前快照變「上一回合」
