  try{ ['p1','p2'].forEach(function(_cstS){ const _cstBd = (G[_cstS]||[]).find(function(x){ return x && x.curHp>0 && window._cstHasN(x,'t2','吟遊詩人'); }); if(!_cstBd) return; const _cstO = _cstS==='p1'?'p2':'p1'; if(!(G[_cstO]||[]).some(function(x){ return x && x.curHp>0 && hasStatus(x,'sleep'); })) return; const _cstG = window._cstCap.gainEnergy(_cstS, 1); if(_cstG>0) log('✨ [' + _cstBd.name + '] 命星:夢囈!敵人還在沉睡,回復 1 能量'); }); }catch(_eCstBdT2){}
