        const _newMax = h._hpRampBase + Math.floor(h._hpRampBase * _pctHp / 100);
        if(_newMax > h.hp){
          const _gainHp = _newMax - h.hp;
          h.hp = _newMax;
          h.curHp = Math.min(h.hp, h.curHp + _healCurseGate(h, _gainHp));
          try{ log(`🌊 [${h.name}] 海龍王之爪!最大 HP +${_pctHp}%(+${_gainHp},上限 ${h.hp})`); }catch(_){}
          try{ if(typeof bannerFX === 'function') bannerFX(h, '🌊 HP上限+' + _pctHp + '%', '#3399ff', 600); }catch(_){}
        }
