  try{ window._cstS1RoundStart(); }catch(_eCstS1Rs){}   // ✨ v5.264.0 命星 SSR 第一批:奈米修復/血契結算(只讀命星寫入的欄位)
  try{ window._cstS2RoundStart(); }catch(_eCstS2Rs){}   // ✨ v5.265.0 命星 SSR 第二批:水精靈/迴力鏢/操偶重縫/安眠菇湯(只讀命星寫入的欄位)
  // ✨ 命星 諸葛亮 b1「七星東風星」:命星東風在場時,每回合開始觸發 1 次臥龍追擊(每張卡最多 2 次;諸葛亮須存活且點亮)
  try{ (fieldCards || []).forEach(function(f){ if(f && f.effect==='eastwind' && f._cstZgB1 && (f._cstZgN||0) < 2 && (f.side==='p1' || f.side==='p2')){ const _cstZgO = (G[f.side] || []).find(function(x){ return x && x.curHp > 0 && window._cstHasN(x,'b1','諸葛亮'); }); if(_cstZgO && typeof window._wolongFieldProc === 'function' && !(_cstZgO.status || []).some(function(s){ return s && (s.type==='_traitSeal' || s.type==='imprison' || s.type==='confused'); }) && (G[f.side==='p1'?'p2':'p1'] || []).some(function(x){ return x && x.curHp > 0; })){ f._cstZgN = (f._cstZgN||0) + 1; log('✨ [' + _cstZgO.name + '] 命星:七星東風!東風助陣,回合開始觸發臥龍追擊(' + f._cstZgN + '/2)!'); window._wolongFieldProc(f.side, {_cstReact:1}); } } }); }catch(_eCstZgB1r){}   // ★ v5.262.0 命座 G8:命星觸發的追擊,傷害不能再觸發命星反應   // 🔧 v5.258.0 舊 bug:(命星審查)天賦被封/禁錮/混亂或沒有存活對手時(臥龍不會發動)不扣次數、不印 log
  renderBfield(); updateFieldFX();

