  // ★ v3.13.69 — 救醫馬天賦「救馬本能」(5 年 4 班吳同學設計):新回合開始,
  //   若隊伍有存活救醫馬,自動用其特技 50% 治療「所有 HP 低於門檻」的友方(可復活)。
  //   門檻 = 50% + 5%/天賦級(Lv0 50% → Lv5 75%);100% 觸發(存活即生效,非機率)。
  //   特技值沿用救醫馬爆發公式 floor(sp×(1+sp×0.01));倒下友方用 doRevive 復活到「特技50%」血量。
  //   位置:在春/秋全友效果與下方劇毒/死亡標記扣血之間 — 屬「新回合開始」治療類。
  // ════════════════════════════════════════════════════════════════
  try{
    ['p1','p2'].forEach(_pside => {
      const _pteam = G[_pside] || [];
      const _pony = _pteam.find(x => x && x.name === '救醫馬' && x.curHp > 0);
      if(!_pony) return;
      const _ptl = (typeof _getTraitLv === 'function') ? (_getTraitLv('救醫馬') || 0) : 0;
      const _pThreshold = Math.min(1.0, 0.5 + _ptl * 0.05);          // 50% + 5%/級
      const _ponySpv = Math.floor((_pony.sp || 0) * (1 + (_pony.sp || 0) * 0.01));
      const _pHealAmt = Math.max(1, Math.floor(_ponySpv * 0.5));     // 特技 50%
      const _pHealedNames = [];
      _pteam.forEach(ally => {
        if(!ally) return;
        const _amax = ally.hp || 1;
        if(ally.curHp < _amax * _pThreshold){     // HP 低於門檻(含倒下 curHp<=0)
          if(ally.curHp <= 0){
            const _rpct = Math.min(1.0, Math.max(0.01, _pHealAmt / _amax));  // 可復活:回到「特技50%」血量
            try{ doRevive(ally, _rpct); }catch(_){}
            try{ if(ally.curHp > 0) window._cstPnT2Heal(_pony, ally); }catch(_eCstPnT2r){}   // ✨ v5.265.0 命星 救醫馬 t2:救馬本能復活的夥伴也算「被治療」
          } else {
            try{ doHeal(ally, _pHealAmt, { actor:_pony, isHeal:true, noDice:true, noWarhorn:true }); }catch(_){}
            try{ window._cstPnT2Heal(_pony, ally); }catch(_eCstPnT2){}   // ✨ v5.265.0 命星 救醫馬 t2「疾蹄馳援星」
          }
          // ✨ 命星 救醫馬 t1(老師 10/15 改寫):救馬本能治療時,同時為被治療的友方解除 1 個不利狀態(走 _clearOneBadStatus:尊重頑強詛咒/強力狀態不可解等通則)
          try{
            if(ally.curHp > 0 && window._cstHasN(_pony,'t1','救醫馬') && typeof _clearOneBadStatus === 'function'){
              const _cstPonyCl = _clearOneBadStatus(ally);
              if(_cstPonyCl){ log('✨ [' + _pony.name + '] 命星:救馬本能順手解除 [' + ally.name + '] 的 [' + statusName(_cstPonyCl) + ']!'); }
            }
          }catch(_eCstPonyT1){}
          _pHealedNames.push(ally.name);
          try{ renderCard(ally); }catch(_){}
        }
      });
      if(_pHealedNames.length){
        try{ log(`🐎 [${_pony.name}] 救馬本能!新回合衝向傷患,用特技 50% 救治 HP 低於 ${Math.round(_pThreshold*100)}% 的夥伴(可復活):${_pHealedNames.join('、')}`); }catch(_){}
        try{ bannerFX(_pony, '🐎 救馬本能!', '#88ddaa', 1100); }catch(_){}
      }
    });
  }catch(_ePony){ console.warn('[救醫馬天賦] 例外', _ePony); }
