      // 找「存活且未滿血」HP 比例最低的 1 名友方(不可復活 → curHp>0 才列入;含朱玥自己)
      const _zyRCand = _zyRTeam.filter(x => x && x.curHp > 0 && x.curHp < (x.hp || 1));
      if(!_zyRCand.length) return;                       // 全員滿血/全倒 → 不觸發
      _zyRCand.sort((x, y) => (x.curHp / Math.max(1, x.hp)) - (y.curHp / Math.max(1, y.hp)));
      const _zyRTgt = _zyRCand[0];
      const _zyRSpv = Math.floor((_zyRHer.sp || 0) * (1 + (_zyRHer.sp || 0) * 0.01));
