  try{ if(typeof window._cn2RoundProc === 'function') window._cn2RoundProc(); }catch(_eCn2Nr){ console.warn('[v5.293.0 CN2 回合天賦]', _eCn2Nr); }
  try{ if(typeof window._cn2RoundBond === 'function') window._cn2RoundBond(); }catch(_eCn2Rb){ console.warn('[v5.295.0 回合羈絆]', _eCn2Rb); }
  // ════════════════════════════════════════════════════════════════
  // ★ v3.13.0(2026-05-31)— 冬 winter 速度 -50%:用「進入時記錄、戰場卡 dur<=0 時還原」模式
  //   實作:每回合開始檢查若冬戰場卡剛消失,把所有 _winterOrigSpd 還原
  //         若冬戰場卡新建,把對方所有英雄 spd 減半並記錄原值
  //   (詳細實作見 addField 內,這裡是「卡剛消失」的還原 hook)
  // ════════════════════════════════════════════════════════════════
  if(!fieldHas('winter')){
    // 冬卡不在場(可能剛消失 dur=0),掃描所有英雄還原速度
    G.p1.concat(G.p2).forEach(h => {
      if(h._winterOrigSpd !== undefined){
        h.spd = h._winterOrigSpd;
        delete h._winterOrigSpd;
      }
    });
  }
  // ✨ 命星 魔界花使‧朱玥 s1「季節餘香星」:冬之餘香 = 敵方全體速度 -25% 1 回合(記差值 _cstZyWinCut,下回合同處加回)
  try{
    G.p1.concat(G.p2).forEach(function(h){
      if(h && typeof h._cstZyWinCut === 'number'){
        const _cstCut = h._cstZyWinCut;
        delete h._cstZyWinCut;
        if(h._winterOrigSpd !== undefined){ h._winterOrigSpd += _cstCut; h.spd += Math.floor(_cstCut * 0.5); }
        else { h.spd += _cstCut; }
      }
    });
    const _cstZyW = G._cstZyRem;
    if(_cstZyW && _cstZyW.eff === 'winter' && _cstZyW.r === G.round && !_cstZyW.wDone){
      _cstZyW.wDone = true;
      const _cstZyWFoe = (_cstZyW.side === 'p1') ? 'p2' : 'p1';
      (G[_cstZyWFoe] || []).forEach(function(h){
        if(h && h.curHp > 0){
          const _cstNs = Math.max(1, Math.floor(h.spd * 0.75));
          h._cstZyWinCut = h.spd - _cstNs;
          h.spd = _cstNs;
        }
      });
      log('✨ 命星:冬之餘香!敵方全體速度 -25%(1 回合)');
    }
  }catch(_eCstZyS1w){}
  // Death mark: fire at round start（含定時炸彈）
  G.p1.concat(G.p2).forEach(h=>{
    if(hasStatus(h,'deathmark') && h.curHp>0){
      const bombSt=h.status.find(s=>s.type==='deathmark'&&s._bomb);
      // ★ v5.298.0 邪骨暗龍王「死亡宣告」(_wbDoom):自己倒數,_wbDoomAt 回合開始時才觸發 ⇒ 該英雄 HP 變 1。
      //   倒數中每個新回合把 dur 校正成「剩餘回合 +1」(本回合 tickStatus 扣 1 後剛好等於剩餘),避免狀態提早被計時移除。
      //   不走下方「冒險 BOSS/菁英」分支(那個分支在世界 BOSS 戰會把玩家英雄也當成 BOSS,只扣 20% 當前 HP)。
      const _wbDoomSt = (bombSt || h.side !== 'p1') ? null : h.status.find(s=>s.type==='deathmark'&&s._wbDoom);   // 只認玩家方(被轉移到龍王/敵人身上的宣告走原本 BOSS 分支,不會把龍王打成 1 HP)
      if(_wbDoomSt){
        const _wbR = (G && G.round) || 1;
        const _wbLeft = (_wbDoomSt._wbDoomAt || _wbR) - _wbR;
        if(_wbLeft > 0){ _wbDoomSt.dur = _wbLeft + 1; return; }
        clearStatus(h,['deathmark']);
        h.curHp = 1;
        try{ log(`💀 黃泉之門開啟!死亡宣告倒數結束,【${h.name}】的 HP 只剩 1!`); }catch(_){}
        try{ bannerFX(h, '💀 死亡宣告!', '#cc44ff', 1100); }catch(_){}
        try{ renderCard(h); }catch(_){}
        return;
      }
      if(bombSt){
        // 定時炸彈爆炸
        // ★ v1.0.20260424.0510 — 若 _bombFixed 標記 → 用 doDmg(fixedDmg:true) 路徑
        const dmgAmt=bombSt._bombDmg||30;
        log(`💣 定時炸彈爆炸!【${h.name}】-${dmgAmt}HP!(固定傷害)`);
        bannerFX(h,'💥爆炸!','#ffaa00',900);
        playSfx('sfx-bomb-explode', 1.0);
        if(bombSt._bombFixed){
          doDmg(h, dmgAmt, {fixedDmg:true});
        } else {
          doDmg(h,dmgAmt,{ignoreBuffs:false,noGuard:false});
        }
        // 波及身旁角色(同陣營相鄰)
        const side=h.side;
        // 🔧 老師裁定(fd「波及鄰近角色」):原本只波及目標左右相鄰(依 pos;邊角只有 1 個)50%;
        //    _bombAll(只由 ✨ 機械師 s1 命星寫入)才波及目標以外全體存活者 50%。判定失敗時退回舊行為(全體)不中斷爆炸。
        let siblings;
        try{
          if(bombSt._bombAll){
            siblings=G[side].filter(x=>x!==h&&x.curHp>0);
          } else {
            const _bmIdx=G[side].indexOf(h);
            siblings=G[side].filter(x=>{
              if(!x||x===h||!(x.curHp>0)) return false;
              if(typeof h.pos==='number' && typeof x.pos==='number') return Math.abs(x.pos-h.pos)===1;
              const _bmXi=G[side].indexOf(x);
              return _bmIdx!==-1 && Math.abs(_bmXi-_bmIdx)===1;
            });
          }
        }catch(_eBmAdj){ siblings=G[side].filter(x=>x!==h&&x.curHp>0); }
        const splash=Math.ceil(dmgAmt*(bombSt._bombSplash||0.5));
        siblings.forEach(x=>{
          if(bombSt._bombFixed){
            doDmg(x, splash, {fixedDmg:true});
          } else { doDmg(x,splash,{}); }
          log(`💥 波及 [${x.name}] -${splash}HP!`);
        });
        clearStatus(h,['deathmark']);
      } else {
        // ★ v3.5.13 — 老師回報(2026/5/22):學生用「暗法師 + 吸血鬼」把世界 BOSS HP 90% 一招秒
        //   根因:此處 deathmark 觸發時直接 h.curHp=1,完全沒檢查是不是 BOSS,
        //         不論誰被附加 deathmark(無論是死亡宣告誤走 _isArena=true 分支,還是
        //         其他英雄技能 / 隨機機制透過 addStatus(t,'deathmark',N) 偷塞進來),
        //         只要進到這個 tick 就直接被秒殺。
        //   修法:對「世界 BOSS / BOSS / 菁英」改為「當前 HP 20% 必中傷害(上限英雄等級×10)」,
        //         非 BOSS 維持原本剩 1HP 行為。判定邏輯複製 line 24566 的標準 BOSS 判定。
        //   注意:即使原本死亡宣告 line 24570 已對 BOSS 走 doDmg 分支不該附加 deathmark,
        //         但這裡是「最後防線」— 任何路徑只要 deathmark 進到 BOSS 身上都必須擋住。
        // ★ v3.16.55 — 小怪名單擴充台/日/埃三關(與玩家路徑同口徑)
        const _miniMobs = [].concat(
          (typeof MINI_MONSTERS !== 'undefined' ? MINI_MONSTERS : []),
          (typeof MINI_MONSTERS_JP !== 'undefined' ? MINI_MONSTERS_JP : []),
          (typeof MINI_MONSTERS_EG !== 'undefined' ? MINI_MONSTERS_EG : [])
        );
        const _eliteNames = ['九尾空貓怪','綠竹筍小妖','茶葉精靈'];
        const _isPathMobDM = _miniMobs.includes(h.name);
        const _isBossOrEliteDM = _eliteNames.includes(h.name) || window._isEliteEnemy(h)   /* ★ v5.80.0 菁英守衛不是小怪(貓空/日本/中國四關菁英全納入·單一真相 _ELITE_ENEMY_NAMES) */
          || (!_isPathMobDM && typeof BOSS_NAMES !== 'undefined' && BOSS_NAMES.includes && BOSS_NAMES.includes(h.name))
          || (typeof _adventureMode !== 'undefined' && _adventureMode
              && typeof _advMiniBattleActive !== 'undefined' && !_advMiniBattleActive
              && !_isPathMobDM);
        if(_isBossOrEliteDM){
          // BOSS / 菁英:當前 HP 20% 必中傷害,上限英雄等級×10
          //   取附加者的等級當作上限基準;沒有附加者(_actor 沒記)就用受害者等級×10 兜底
          const _dmActor = h.status.find(s => s.type==='deathmark' && s._source) || null;
          const _dmActorName = (_dmActor && _dmActor._source && _dmActor._source.name) || null;
          let _dmLv = 1;
          if(_dmActorName && typeof _heroLevels !== 'undefined' && _heroLevels[_dmActorName]){
            _dmLv = _heroLevels[_dmActorName];
          } else if(typeof _heroLevels !== 'undefined' && _heroLevels[h.name]){
            _dmLv = _heroLevels[h.name];
          }
          const _dmMaxDmg = _dmLv * 20;   // 🔧 v5.262.0 舊 bug:到期保底上限原為英雄等級×10,技能本體(v3.15.62)與 fd 為 ×20 ⇒ 統一 ×20
          const _dmRaw = Math.max(1, Math.floor(h.curHp * 0.20));
          const _dmFinal = Math.min(_dmRaw, _dmMaxDmg);
          const _dmCapped = _dmRaw > _dmMaxDmg;
          log(`💀 死亡宣告觸發!【${h.name}】(BOSS/菁英) 受當前 HP 20% 必中傷害 = ${_dmFinal}${_dmCapped?'(上限 '+_dmMaxDmg+')':''}!`);
          bannerFX(h, '💀 死亡宣告!', '#cc44ff', 1100);
          doDmg(h, _dmFinal, { fixedDmg:true, isSkill:true, ignoreBuffs:true, noHidden:true, actor: (_dmActor && _dmActor._source) || null });
          clearStatus(h,['deathmark']);
        } else {
          // 小怪 / 鬥技場:維持原本「剩 1 HP」行為
          h.curHp=1; clearStatus(h,['deathmark']); log(`💀 死亡宣告觸發！[${h.name}] 只剩1HP！`); renderCard(h);
        }
      }
    }
  });

  // 狀態凍結（時間暫停）：跳過本輪狀態計時
  // 🔧 修 bug:原本這裡只把 _statusFrozen 減 1、沒有任何效果(且搶在本回合 tickStatus 之前歸零)。
  //   改由 tickStatus 第一次結算時消耗旗標(狀態停止計時 1 回合);此處只清掉已倒下者的殘留旗標,避免復活後誤凍結。
  G.p1.concat(G.p2).forEach(h=>{
    try{ if(h && h._statusFrozen>0 && h.curHp<=0){ h._statusFrozen = 0; } }catch(_eTsFrzClr){}
  });

  // 魔音：每回合-2能量（直笛團員技能）
  G.p1.concat(G.p2).forEach(h=>{
    if(h.curHp>0 && hasStatus(h,'_mayin')){
      const _ms=h.side==='p1'?'p1':'p2';
      G.energy[_ms]=Math.max(0,G.energy[_ms]-2);
      showPopup(h,'-2E','dmg');
      log(`🎵 魔音！[${h.name}] 能量-2！`);
    }
  });
  // 午睡時間：每回合恢復25%HP
  G.p1.concat(G.p2).forEach(h=>{
    if(h.curHp>0 && h._napMode && hasStatus(h,'sleep')){
      const _heal=Math.max(1,Math.floor(h.hp*0.25));
      doHeal(h,_heal,{actor:null,_healSrc:h,isHeal:true,noDice:true}); // ★ v3.16.46 午睡自療歸屬自身
      log(`💤 [${h.name}] 午睡恢復！+${_heal}HP！`);
      if(h.curHp>=h.hp){
        // HP回滿：醒來
        clearStatus(h,['sleep']); h._napMode=false;
        h.buffs=h.buffs.filter(b=>b.type!=='_napShield');
        log(`💤 [${h.name}] HP回滿，從午睡中醒來！`);
        bannerFX(h,'醒來！','#aaddff',800);
        // 清除夢境弱化
        G.p1.concat(G.p2).forEach(e=>{
          const _ds=e.status.find(s=>s.type==='_dreamDebuff'&&s._owner===h);
          if(_ds){ e.atk=_ds._origAtk; e.sp=_ds._origSp; e.status=e.status.filter(s=>s!==_ds); renderCard(e); }
        });
      }
    }
  });
  // ★ v3.13.73 — 中毒/猛毒：每回合 -最大HP 4%/8%(猛毒=_strong),無視護盾與減傷,鬥技場不調降,BOSS走5000上限
  G.p1.concat(G.p2).forEach(h=>{
    if(h.curHp>0 && hasStatus(h,'poison')){
      const _ps = (h.status||[]).find(s=>s.type==='poison');
      const _strong = !!(_ps && _ps._strong);
      // ★ v3.15.17 — 山岳地龍王弱點·畏毒:中毒改固定值(普通-1500/猛毒-3000),且繞過 5000 上限/強力減傷/護盾
      const _earthDragonPoison = (h.name === '山岳地龍王');
      // ★ v3.15.72 修復 — 中毒 tick 優先採用 per-hero 自訂傷害值 _poisonAmt。
      //   劇毒煙霧彈(15%)/窮奇巨爪出血(10%)/神樂強力中毒(15%)/各流血技(10%/5%)/固定12HP 等
      //   十餘個技能皆會設 h._poisonAmt;但 v3.13.73 將中毒改成百分比 4%/8% 時漏掉「優先讀 _poisonAmt」,
      //   導致這些技能傷害全部退回普通 4%/8%(=老師回報「猛毒沒扣足血/看似無效」的根因)。
      //   未設 _poisonAmt 者(純百分比中毒)仍照舊走 4%(普通)/8%(猛毒)。山岳地龍王畏毒固定值最優先不變。
      // ★ v3.15.72(老師補充裁示)— 百分比版中毒對 BOSS 傷害降至 1/4(中毒 4%→1%、猛毒 8%→2%);
      //   _poisonAmt 固定值不打折、山岳地龍王畏毒固定值不變(皆在三元前段先處理)。
      //   BOSS 認定:世界 BOSS 全龍王(_isWorldBossTarget)+ 關卡真 BOSS/埃及雙王(_zeusIsTrueBoss);菁英/小怪不算。
      // ★★ v5.80.0(老師裁定)— 中毒上限改制 + `_poisonAmt` 繞過漏洞收口
      //   ① 受保護目標(高血菁英/BOSS/龍王)百分比由 1%/2% 放寬為 **2%/4%**(window._dotPct);
      //      一般目標(小怪/玩家/鬥技場)維持 4%/8% 零改動。
      //   ② ★ 根治「_poisonAmt 固定值不打折」漏洞:刺客淬毒之刃(最大HP10%)/劇毒煙霧彈(15%)/
      //      強化BUG(15%)/千年發酵核爆(15%)/貓兔齊抓咬(15%)/等死不救(5%) 等十餘個技能寫進
      //      h._poisonAmt 的其實是「取得當下算出的最大HP百分比」,舊碼當成固定值直接放行 →
      //      這是全遊戲唯一繞過 BOSS DoT 減免的路徑(對蚩尤 35,000 = 3,500~5,250/回合)。
      //      改走 window._dotAmtCap 一律夾進同一個上限;對小怪完全不動。
      //   ③ 山岳地龍王「畏毒」固定值 1500/3000 維持最優先、不受本次改動影響(既有弱點設計)。
      //   舊行備查(勿刪):
      //     const _poisonOnBoss = _isWorldBossTarget(h) || _zeusIsTrueBoss(h);
      //     const _amt = _earthDragonPoison ? (_strong?3000:1500)
      //       : ((h._poisonAmt>0) ? h._poisonAmt
      //          : Math.floor(h.hp * (_poisonOnBoss ? (_strong?0.02:0.01) : (_strong?0.08:0.04))));
      const _amt = _earthDragonPoison
        ? (_strong ? 3000 : 1500)
        : ((h._poisonAmt && h._poisonAmt > 0)
            ? window._dotAmtCap(h, h._poisonAmt, 'poison', _strong)
            : Math.max(1, Math.floor((h.hp||1) * window._dotPct(h, 'poison', _strong))));
      let _cstAsAmt = _amt; try{ const _cstAsK = window._cstAsT2K(h, 'poison'); if(_cstAsK > 1){ _cstAsAmt = Math.max(1, Math.floor(_amt * _cstAsK)); log('✨ [刺客] 命星:毒血交織![' + h.name + '] 同時中毒與出血,中毒傷害提升為 1.5 倍!'); } }catch(_eCstAsT2p){ _cstAsAmt = _amt; }   // ✨ 命星 刺客 t2   // ★ v5.262.0 裁定乙
      const _cstHcHp0 = h.curHp;   // ✨ v5.264.0 命星 地府酋長 s2:記下結算前 HP(只讀)
      doDmg(h, _cstAsAmt, {ignoreBuffs:true, noGuard:true, _dotIgnoreShield:true, _arenaScalingExempt:true, _isDotTick:true, _dotBypassBossCap:_earthDragonPoison, actor:(_ps&&_ps._dotSrc)||undefined, skillName:(_strong?'猛毒':'中毒')});  // ★ v3.16.45 — 中毒 tick 歸給施術者
      log(`☠️ ${_strong?'猛毒':'中毒'}侵蝕 [${h.name}] -${_cstAsAmt}HP!${_earthDragonPoison?' (畏毒弱點!)':''}`);
      try{ if(_ps && _ps._cstHcStorm) window._cstHcS2Drain(h, _ps, Math.max(0, _cstHcHp0 - Math.max(0, h.curHp))); }catch(_eCstHcS2d){}   // ✨ v5.264.0 命星 地府酋長 s2「血霧吸魂星」(只認命星寫入的 _cstHcStorm)
    }
  });
  // ════════════════════════════════════════════════════════════════
  // ★★ v5.80.0(老師裁定⑤)— 出血機制改版:由「每回合白吃一次」改為「觸發式」
  //   新規則:帶著出血狀態的角色,①受到攻擊 ②自己使用普通攻擊/技能/爆發技 → 各觸發 1 次出血傷害;
  //           每回合最多 2 次;同一次行動的多段傷害只計 1 次;
  //           休息 / 使用物品與丹藥 / 麻痺等無法行動狀態 → 不觸發。
  //   實作點:①受傷觸發掛 doDmg(見 `_bleedTryProc` 呼叫點)②行動觸發掛 execAtk/execSkill/execBurst 共用入口。
  //   本處只保留「每回合把觸發次數歸零」,原本的固定 tick 整段停用(舊碼保留於下方註解備查·勿刪)。
  //   ⚠ 行為變化:我方替敵人上出血後,若該回合完全沒有攻擊他、他也沒行動,出血將不造成任何傷害。
  // ── 舊碼備查(v3.13.73 + v3.15.72,每回合固定 tick 版)────────────────────────
  //   G.p1.concat(G.p2).forEach(h=>{
  //     if(h.curHp>0 && hasStatus(h,'bleed')){
  //       const _bs = (h.status||[]).find(s=>s.type==='bleed');
  //       const _strong = !!(_bs && _bs._strong);
  //       const _bleedOnBoss = _isWorldBossTarget(h) || _zeusIsTrueBoss(h);
  //       const _amt = Math.floor(h.hp * (_bleedOnBoss ? (_strong?0.0225:0.015) : (_strong?0.09:0.06)));
  //       doDmg(h, _amt, {...});
  //     }
  //   });
  // ════════════════════════════════════════════════════════════════
  G.p1.concat(G.p2).forEach(h=>{ if(h) h._bleedProcTurn = 0; });   // ★ v5.80.0 每回合出血觸發次數歸零(上限 2)
  // ★★ v5.80.0(老師裁定⑥)— 睡眠:未受傷害時,每回合開始有 30% 機率自動醒來
  //   (配套:基礎回合數 3→5、受傷立即解除、被攻擊必中;三者合起來讓睡眠「久但好解」)
  //   ⚠ 排除爆發專屬的長眠(_burstSleep,dur:99 由招式自行收尾)與麻吉喵自睡休息(_napMode)。
  G.p1.concat(G.p2).forEach(h=>{
    try{
      if(!h || h.curHp <= 0) return;
      if(typeof hasStatus !== 'function' || !hasStatus(h,'sleep')) return;
      const _sl = (h.status||[]).find(s=>s && s.type==='sleep');
      if(!_sl || _sl._burstSleep || h._napMode) return;
      if(Math.random() < 0.30){
        clearStatus(h,['sleep']);
        try{ log(`💤 [${h.name}] 睡飽了,自己醒了過來!`); }catch(_){}
        try{ bannerFX(h,'💤 醒來!','#bb99ff',700); renderCard(h); }catch(_){}
      }
    }catch(_eSlpWake){}
  });
  // 持續恢復：每回合+HP（使用 hpRegen buff）
  G.p1.concat(G.p2).forEach(h=>{
    if(h.curHp>0 && hasBuff(h,'hpRegen')){
      const _amt=h._hpRegenAmt||12;
      doHeal(h,_amt,{noDice:true,noWarhorn:true,isHeal:true});
      log(`💚 持續恢復 [${h.name}] +${_amt}HP`);
    }
  });
  // ★ v5.30.0 — 裝備淨化(cleanse,騎士頭盔等):每回合開始機率消除自身 1 個不利狀態(鐵匠 S2 放大)
  try{ if(typeof _gearTurnCleanse === 'function') _gearTurnCleanse(); }catch(_eGearCl){ console.warn('[裝備淨化 tick] 失敗', _eGearCl); }
  // ★ v5.44.0 — 裝備恢復(regenPct,七星燈):每回合開始恢復最大 HP 3%(鐵匠 S2 放大·_jpBossHealCap 夾制)
  try{ if(typeof _gearTurnRegen === 'function') _gearTurnRegen(); }catch(_eGearRg){ console.warn('[裝備回合恢復 tick] 失敗', _eGearRg); }
  // ── 爆發：無盡長眠→每個睡眠回合為我方全體恢復20%HP ──
  ['p1','p2'].forEach(side=>{
    const sleepFoes=G[side==='p1'?'p2':'p1'].filter(h=>h.curHp>0&&hasStatus(h,'sleep'));
    sleepFoes.forEach(sf=>{
      const bsSt=sf.status.find(s=>s.type==='sleep'&&s._burstSleep);
      if(bsSt && bsSt._burstSleepOwner && bsSt._burstSleepOwner.curHp>0){
        const owner=bsSt._burstSleepOwner;
        G[owner.side].filter(h=>h.curHp>0).forEach(ally=>{
          const _sleepHp=bsSt._sleepHealPct||0.10;
          doHeal(ally,Math.max(1,Math.floor(ally.hp*_sleepHp)),{actor:owner,noDice:true,isHeal:true,isPctHeal:true});
          log(`🎵 [${owner.name}] 無盡長眠！[${ally.name}] 友方恢復${Math.round(_sleepHp*100)}%HP！`);
        });
      }
    });
  });
  // ── 爆發：木靈使 神樹恩澤→再生恢復 ──
  // ★ v1.0.20260423.2100 — 恢復量套用 _healMult（每升一級+10%）
  G.p1.concat(G.p2).forEach(h=>{
    if(h.curHp>0){
      const uSt=h.status.find(s=>s.type==='burstUndying');
      if(uSt&&uSt._owner&&uSt._owner.curHp>=0){
        const ownerSpv=Math.floor((uSt._owner.sp||0)*(1+(uSt._owner.sp||0)*0.01));
        const _healAmt=Math.max(1, Math.floor(ownerSpv * (uSt._healMult || 1)));
        doHeal(h,_healAmt,{noDice:true,isHeal:true});
        h.curHp=Math.max(1,h.curHp); // HP最低為1
        log(`🌿 [${h.name}] 神樹再生！恢復 ${_healAmt}HP！`);
      }
    }
  });
  // ── 爆發：負荷超載→計時，結束時爆炸 ──
  G.p1.concat(G.p2).forEach(h=>{
    if(h._burstOverloadActive>0){
      h._burstOverloadActive--;
      if(h._burstOverloadActive<=0){
        const _rawOverload=h._burstOverload||0;
        const _overMult=h._burstOverloadMult||1.0;
        const totalDmg=Math.floor(_rawOverload*_overMult);
        if(totalDmg>0){
          const opp2=h.side==='p1'?'p2':'p1';
          const foes=G[opp2].filter(x=>x.curHp>0);
          if(foes.length){
            const share=Math.ceil(totalDmg/foes.length);
            foes.forEach(f=>{ doDmg(f,share,{actor:h,isSkill:true,ignoreBuffs:true}); });
            log(`⚙️ [${h.name}] 負荷超載爆炸！累積${_rawOverload}×${_overMult.toFixed(1)}=${totalDmg}，敵方各受到${share}！`);
            flashScreen('rgba(200,200,255,1)',400);
          }
        }
        h._burstOverload=0;
        h._burstOverloadActive=0;
      }
    }
  });
  // ── 占星師升級：zeroCost期間每回合恢復額外能量 ──
  ['p1','p2'].forEach(side=>{
    if(G[side]){
      const _hasZC = G[side].some(t=>t.curHp>0&&hasBuff(t,'zeroCost'));
      if(_hasZC){
        G[side].forEach(t=>{
          if(t.curHp>0 && t._starBurstEnergyPerTurn && t._starBurstEnergyPerTurn>0){
            G.energy[side]=Math.min(10,(G.energy[side]||0)+t._starBurstEnergyPerTurn);
            showPopup(t,'+'+t._starBurstEnergyPerTurn+'E','energy');
          }
        });
      }
    }
  });
  // ── 命星 凡人 爆·壹:平均數值還原(只有點亮者才會帶 _cstMimicDelta)──
  try{
    G.p1.concat(G.p2).forEach(h=>{
      if(h && h._cstMimicDelta && !h._mimicInProgress){
        h.atk = Math.max(1, h.atk - (h._cstMimicDelta.atk||0)); h.sp = Math.max(0, h.sp - (h._cstMimicDelta.sp||0));
        delete h._cstMimicDelta;
      }
    });
  }catch(_eCstMr){}
  // ── 凡人：模仿加持結束後還原能力值 ──
