  // ── HELPER: find best attack target (弱點屬性優先，其次最低HP) ──
  function bestAtkTarget(){
    // ★ v3.13.87 — 我的豚豚 天賦「可愛」:成為敵人單體攻擊目標的機率 -70%(僅影響 AI 目標選擇;對全體攻擊無效)
    //   若選中的目標是我的豚豚、且還有其他存活敵人,則 70% 機率改挑其他目標
    function _cuteAvoid(picked){
      try{
        if(picked && picked.name === '我的豚豚'){
          const _others = enemies.filter(e => e && e.curHp > 0 && e.name !== '我的豚豚');
          if(_others.length > 0 && Math.random() < 0.70){
            return _others[Math.floor(Math.random() * _others.length)];
          }
        }
      }catch(_){}
      return picked;
    }
    // ★ v3.16.58 — 自動戰鬥「優先攻擊HP最高/最低的目標」設定(只在「恰好勾選其中一項」時生效;
    //   兩者皆勾或皆不勾 → 沿用預設「殘血/弱點優先」評分。僅對有設定的 p1 英雄生效,敵方不受影響)。
    if(_abTgtHigh !== _abTgtLow){
      try{
        var _abAlive = enemies.filter(function(e){ return e && e.curHp > 0; });
        if(_abAlive.length){
          _abAlive.sort(function(x,y){ return _abTgtHigh ? (y.curHp - x.curHp) : (x.curHp - y.curHp); });
          return _cuteAvoid(_abAlive[0]);
        }
      }catch(_eAbTgt){}
    }
    // ★ 冒險模式：BOSS隨機選目標（不鎖最低HP）
    if(typeof _adventureMode !== 'undefined' && _adventureMode && a.side === 'p2'){
      return _cuteAvoid(enemies[Math.floor(Math.random()*enemies.length)]);
    }
    // 計算屬性剋制加成（如 getElemData 有 adv 代表攻擊者剋制目標）
    let best = null, bestScore = -Infinity;
    for(const e of enemies){
      let score = (e.hp - e.curHp) / Math.max(e.hp,1) * 100; // 越殘血越優先
      // 屬性弱點加分
      if(a.element && e.element){
        const ae = getElemData(a.element);
        if(ae && ae.adv && ae.adv.includes(e.element)) score += 50;
      }
      // 死亡宣告目標優先
      if(hasStatus(e,'deathmark')) score += 80;
      // 治療職優先擊殺
      if(HEAL_SKILLS.includes(e.s1.n)||HEAL_SKILLS.includes(e.s2.n)) score += 30;
      // ★ 小劇團員天賦：成為目標機率(v3.12.4: 基礎 60% + 每級 +5%)
      if(e.name==='小劇團員'){
        const _traitLvAI = _getTraitLv(e.name);
        score += 60 + _traitLvAI * 5;
      }
      if(score>bestScore){ bestScore=score; best=e; }
    }
    return _cuteAvoid(best || enemies[0]);
  }

  // ── HELPER: 最需要治療的友方 ──
  function needsHeal(){
    const allAllies = G[a.side].filter(h=>h.curHp>=0);
    const dead = G[a.side].find(h=>h.curHp===0);
    if(dead) return dead;
    // ★ v3.16.89 — 老師裁示:統一治療門檻 75%(原 healer 85%／非 healer 60%)。
    //   只有友方 HP<75% 才使用治療技能/物品,不再對接近滿血(如 84%)的友方空放治療(「重複治療滿血隊友」根治)。
    const threshold = 0.75;
    const wounded = allAllies.filter(h=>h.curHp>0&&h.curHp<h.hp*threshold);
    if(!wounded.length) return null;
    return wounded.sort((x,y)=>_heroHealNeed(x)-_heroHealNeed(y))[0];
  }

