      const _cstBvKoA = a._cstBvKoName || '對手';
      const _cstBvFoeA = (typeof G !== 'undefined' && G) ? (G[a.side === 'p1' ? 'p2' : 'p1'] || []).some(function(x){ return x && x.curHp > 0; }) : false;
      const _cstBvGoA = (a.curHp > 0 && !a._traitReAct && typeof G !== 'undefined' && G && a._cstBvReActR === G.round && _cstBvFoeA && window._cstCap.tryExtraAction(a));
