function updateFieldFX(){
  // Update field card display in right energy panel (middle between energy bars)
  const panel = document.getElementById('field-card-panel');
  const center = document.getElementById('field-center');
  if(!panel) return;
  if(!fieldCards.length){
    panel.innerHTML='';
    if(center) center.innerHTML='';
    const fbLayer=document.getElementById('fb-layer');
    if(fbLayer) fbLayer.style.cssText='';
    return;
  }
  // Render field cards in right panel — full description, CSS handles wrapping
  panel.innerHTML = fieldCards.map(f=>{
    const fx = FIELD_FX[f.effect]||{icon:'🃏',color:'#888',label:f.n};
    const _safeD=(f.d||'').replace(/'/g,'&#39;').replace(/"/g,'&quot;');
    return `<div class="fc-card fc-${f.effect}" style="border-color:${fx.color}aa;color:${fx.color}" onclick="showFieldCardDetail('${f.effect}','${f.n}','${_safeD}','${fx.icon}','${fx.color}')">
      <span class="fc-icon">${fx.icon}</span>
      <div class="fc-body">
        <div class="fc-name" style="color:${fx.color}">${f.n}<span class="fc-timer"> ⏳${f.dur}</span></div>
        <div class="fc-desc">${f.d}</div>
      </div>
      <div class="fc-hint">點擊查看詳情</div>
    </div>`;
  }).join('');

  // Build border animation - use the most "dramatic" active card for border
  const priority = ['chaos','noheal','sealall','warhorn','noshop','sanctuary','purify','reverse','exhaust','discount','dice','minDmg','balance'];
  let dominant = null;
  for(const p of priority){ if(fieldCards.find(f=>f.effect===p)){ dominant=p; break; } }
  if(!dominant && fieldCards.length) dominant=fieldCards[0].effect;

  const fbLayer = document.getElementById('fb-layer');
  if(dominant && FIELD_FX[dominant]){
    const fx = FIELD_FX[dominant];
    fbLayer.style.cssText = `
      position:absolute;inset:0;opacity:1;
      box-shadow:inset 0 0 60px ${fx.border}, inset 0 0 120px ${fx.border};
      border:2px solid ${fx.glow}44;
      animation:fieldPulse_${dominant} 2s ease-in-out infinite alternate;
    `;
    // Inject keyframe if not present
    const kfId = 'kf-field-'+dominant;
    if(!document.getElementById(kfId)){
      const style=document.createElement('style');
      style.id=kfId;
      style.textContent=`@keyframes fieldPulse_${dominant}{from{box-shadow:inset 0 0 40px ${fx.border},inset 0 0 80px ${fx.border}33}to{box-shadow:inset 0 0 80px ${fx.border},inset 0 0 160px ${fx.border}66}}`;
      document.head.appendChild(style);
    }
  } else {
    fbLayer.style.cssText='';
  }
}

function showFieldCardDetail(effect, name, desc, icon, color){
let pop=document.getElementById('fc-detail-pop');
if(pop){ pop.remove(); return; }
const gc=document.getElementById('gc'); if(!gc) return;
pop=document.createElement('div');
pop.id='fc-detail-pop';
pop.style.cssText='position:absolute;right:168px;top:50%;transform:translateY(-50%);z-index:200;'
  +'background:rgba(6,7,18,0.98);border:2px solid '+color+';border-radius:14px;padding:18px 22px;'
  +'max-width:400px;min-width:260px;font-family:\'M PLUS Rounded 1c\',Nunito,sans-serif;'
  +'box-shadow:0 0 30px '+color+'44;animation:sdpIn 0.15s ease-out;';
pop.innerHTML=`<div style="font-size:36px;text-align:center;margin-bottom:8px">${icon}</div>`
  +`<div style="font-size:26px;font-weight:700;color:${color};text-align:center;margin-bottom:10px">${name}</div>`
  +`<div style="font-size:22px;color:#e8e4d8;line-height:1.7;font-weight:500">${desc}</div>`
  +`<div style="text-align:center;margin-top:12px"><button onclick="document.getElementById('fc-detail-pop')&&document.getElementById('fc-detail-pop').remove()" style="padding:6px 20px;background:${color}22;border:1px solid ${color};color:${color};border-radius:6px;cursor:pointer;font-size:18px;font-family:inherit">關閉</button></div>`;
gc.appendChild(pop);
setTimeout(()=>document.addEventListener('click',function _fcClose(e){
  const p=document.getElementById('fc-detail-pop');
  if(p&&!p.contains(e.target)){p.remove();document.removeEventListener('click',_fcClose);}
},{capture:true}),100);
}


