// ====== 技能說明彈出視窗 ======
var _skillPopupEl = null;
function toggleSkillPopup(btn, skName, skCost, skDesc){
  if(_skillPopupEl){ _skillPopupEl.remove(); _skillPopupEl=null; return; }
  const pop = document.createElement('div');
  pop.className = 'skill-popup';
  pop.innerHTML = `<div style="font-size:22px;font-weight:500;color:var(--teal);margin-bottom:6px">${skName} <span style="color:var(--gold);font-size:18px">${skCost}</span></div><div style="font-size:22px;font-weight:500;color:#fff;line-height:1.7">${skDesc}</div>`;
  // position near the button
  const gc = document.getElementById('gc');
  const gcR = gc.getBoundingClientRect();
  const bR = btn.getBoundingClientRect();
  const sc = gcR.width / 1920;
  const x = (bR.left - gcR.left) / sc;
  const y = (bR.top - gcR.top) / sc + 30;
  pop.style.left = Math.min(x, 1920-480) + 'px';
  pop.style.top = y + 'px';
  pop.style.position = 'absolute';
  pop.onclick = (e) => { e.stopPropagation(); pop.remove(); _skillPopupEl=null; };
  gc.appendChild(pop);
  _skillPopupEl = pop;
  playSfx('sfx-sel',0.4);
}

// ====== 能力說明彈出視窗 ======
// ★ v1.0.20260519.7200 (v3.4.0) — hp/atk 加上新加成說明
const STAT_DESCS = {
  hp:   { label:'生命值', color:'#ff6666', desc:'可承受的最大傷害，歸零即倒下，越高越耐打。每1點HP提升0.2%減輕受傷（最多減50%）和0.2%受治療量。', simple:'你能承受的血量，變 0 就倒下。血越多越耐打，受傷也會少一點（最多少一半）。' },
  atk:  { label:'攻擊值', color:'#ff9966', desc:'普通攻擊和部分技能的傷害基礎。每1點攻擊提升0.5%暴擊率和0.5%暴擊額外傷害（暴擊率最高疊到100%）。', simple:'打人的力氣！攻擊越高普攻越痛，也比較容易「暴擊」打出大傷害（暴擊率最多疊到100%）。' },
  sp:   { label:'特技值', color:'#cc88ff', desc:'使用大多數技能的強度，每1點提升1%技能傷害與治療量（沒有上限，投越多越強）。', simple:'技能的威力！特技越高，技能的傷害和治療都越強（沒有上限喔）。' },
  spd:  { label:'速度值', color:'#44aaff', desc:'數值越大行動越早，也影響命中率與迴避率（依速度差每1點+1%迴避，最多躲60%）。', simple:'誰先出手看它！越快越先動，也比較會打中、比較會閃開（最多躲6成攻擊）。' },
  heal: { label:'治療力', color:'#44ffaa', desc:'治療與支援能力，越高越適合擔任治療角色。', simple:'幫夥伴補血的能力！越高越適合當治療角色。' },
  ctrl: { label:'控場力', color:'#ffdd44', desc:'施加負面狀態的能力，越高越適合擾亂敵陣。', simple:'讓敵人暈眩、中毒的能力！越高越會搗亂敵人。' },
};
var _statPopupEl = null;
// ════════════════════════════════════════════════════════════════
// ★ v5.69.2(老師需求②)— 英雄圖鑑「素質加成明細」長按浮窗
// ────────────────────────────────────────────────────────────────
// 問題:一旦英雄裝備多(投資點/Lv/至寶💎/膠囊🧪/寵物🐾/裝備🛡️ 六種加成同時存在),
//   六個徽章全串在總值後面 → 四素質欄被撐高換行,壓到右側雷達圖與「使用膠囊」按鈕。
// 修法:六個徽章收合成單一「⬆ +N」按鈕,按住才展開明細小窗、放開自動收合(老師規格)。
//   明細 HTML 於渲染當下存入 window._LXPS_STAT_BONUS[stat](同時間只會有一位英雄的詳情頁),
//   按鈕只傳 stat 字串 → 完全避開中文/引號逃脫問題。
// 純顯示層:總值計算、投資按鈕、至寶/裝備/寵物加成邏輯完全零改動。
// ════════════════════════════════════════════════════════════════
window._LXPS_STAT_BONUS = window._LXPS_STAT_BONUS || {};
window._statBonusHide = function(){
  try{ var o = document.getElementById('_stat-bonus-pop'); if(o) o.remove(); }catch(_){}
};
window._statBonusShow = function(el, statKey){
  try{
    window._statBonusHide();
    var html = (window._LXPS_STAT_BONUS || {})[statKey];
    if(!html) return;
    var pop = document.createElement('div');
    pop.id = '_stat-bonus-pop';
    var r = el.getBoundingClientRect();
    // z 高於圖鑑詳情 detach 態(10600)與編輯器(9990);fixed 定位不受 overlay 捲動影響
    pop.style.cssText = 'position:fixed;z-index:12200;min-width:190px;max-width:300px;' +
      'background:rgba(18,16,26,0.98);border:2px solid #7dd3ff;border-radius:12px;' +
      'padding:10px 13px;box-shadow:0 6px 22px rgba(0,0,0,0.75);pointer-events:none;' +
      'font-family:inherit;line-height:1.65;';
    pop.innerHTML = html;
    document.body.appendChild(pop);
    // 先掛上才量得到尺寸 → 夾在視窗內不出界(靠左優先,空間不足才往上翻)
    var pr = pop.getBoundingClientRect();
    var x = Math.min(Math.max(6, r.left), window.innerWidth  - pr.width  - 6);
    var y = r.bottom + 8;
    if(y + pr.height > window.innerHeight - 6) y = Math.max(6, r.top - pr.height - 8);
    pop.style.left = x + 'px';
    pop.style.top  = y + 'px';
    try{ playSfx('sfx-sel', 0.3); }catch(_){}
  }catch(_e){ console.warn('[素質加成浮窗]', _e); }
};
// 保險:任何放開/離開/捲動/切頁都收合,絕不殘留
try{
  ['mouseup','touchend','touchcancel','scroll','blur'].forEach(function(ev){
    window.addEventListener(ev, function(){ window._statBonusHide(); }, true);
  });
}catch(_){}
function toggleStatPopup(el, statKey, numFontSize){
  if(_statPopupEl){ _statPopupEl.remove(); _statPopupEl=null; return; }
  const info = STAT_DESCS[statKey]; if(!info) return;
  const fs = numFontSize || 26;
  const pop = document.createElement('div');
  pop.className = 'stat-popup';
  const _scDesc = (typeof _artStyle !== 'undefined' && _artStyle === 'cute' && info.simple) ? info.simple : info.desc;
  pop.innerHTML = `<div style="font-size:${fs}px;font-weight:500;color:${info.color};margin-bottom:5px">${info.label}</div><div style="font-size:${fs}px;font-weight:500;color:#ddd;line-height:1.6">${_scDesc}</div>`;
  const gc = document.getElementById('gc');
  const gcR = gc.getBoundingClientRect();
  const eR = el.getBoundingClientRect();
  const sc = gcR.width / 1920;
  const x = (eR.left - gcR.left) / sc;
  const y = (eR.bottom - gcR.top) / sc + 8;
  pop.style.left = Math.min(x, 1920-400) + 'px';
  pop.style.top = y + 'px';
  pop.style.position = 'absolute';
  pop.onclick = (e) => { e.stopPropagation(); pop.remove(); _statPopupEl=null; };
  gc.appendChild(pop);
  _statPopupEl = pop;
  playSfx('sfx-sel',0.35);
}
// 點擊任何地方關閉彈出視窗
document.addEventListener('click', function(){
  if(_skillPopupEl){ _skillPopupEl.remove(); _skillPopupEl=null; }
  if(_statPopupEl){ _statPopupEl.remove(); _statPopupEl=null; }
});

