// ====== GOLDEN SPARKLE ON HERO PICK ILLUSTRATION ======
function startIllusSparkles(name){
  var wrap=document.querySelector('.hf-illus-wrap');
  if(!wrap) return;
  var existingCanvas=wrap.querySelector('canvas.sparkle-c');
  if(existingCanvas) return; // already running
  var cv=document.createElement('canvas');
  cv.className='sparkle-c';
  cv.style.cssText='position:absolute;inset:0;pointer-events:none;z-index:3;border-radius:12px;';
  cv.width=wrap.offsetWidth||300; cv.height=wrap.offsetHeight||280;
  wrap.appendChild(cv);
  var ctx=cv.getContext('2d');
  var particles=[];
  for(var i=0;i<22;i++) particles.push(_mkSp(cv.width,cv.height));
  function _mkSp(w,h){ return {x:Math.random()*w,y:Math.random()*h,r:Math.random()*2.5+0.8,alpha:0,life:0,maxLife:60+Math.random()*60,vx:(Math.random()-0.5)*0.5,vy:-Math.random()*0.7-0.2,hue:40+Math.random()*20}; }
  var raf2;
  function loop2(){
    ctx.clearRect(0,0,cv.width,cv.height);
    particles.forEach(function(sp){
      sp.x+=sp.vx; sp.y+=sp.vy; sp.life++;
      var lt=sp.life/sp.maxLife;
      sp.alpha=lt<0.3?lt/0.3:lt<0.7?1:(1-lt)/0.3;
      if(sp.life>=sp.maxLife){ var nw=wrap?wrap.offsetWidth:300,nh=wrap?wrap.offsetHeight:280; Object.assign(sp,_mkSp(nw,nh)); }
      ctx.beginPath(); ctx.arc(sp.x,sp.y,sp.r,0,Math.PI*2);
      ctx.fillStyle='hsla('+sp.hue+',100%,80%,'+sp.alpha+')';
      ctx.shadowBlur=8; ctx.shadowColor='hsla('+sp.hue+',100%,70%,0.8)';
      ctx.fill(); ctx.shadowBlur=0;
    });
    raf2=requestAnimationFrame(loop2);
  }
  loop2();
  cv._stopSparkle=function(){ cancelAnimationFrame(raf2); cv.remove(); };
}
function stopIllusSparkles(){
  var cv=document.querySelector('.hf-illus-wrap canvas.sparkle-c');
  if(cv&&cv._stopSparkle) cv._stopSparkle();
}

// ====== ELEMENT WHEEL CLICK INFO ======
(function(){
  window._epOpen=false; window._epKey='';
  window.closeElemPopup=function(){ var e=document.getElementById('elem-info-popup');if(e)e.style.display='none';window._epOpen=false;window._epKey=''; }
  window._openElemPopup=function(key,cx,cy){
    if(window._epOpen&&window._epKey===key){closeElemPopup();return;}
    window._epKey=key;window._epOpen=true;
    var ed=typeof ELEMENT_DB!=='undefined'?ELEMENT_DB[key]:null;
    var el=document.getElementById('elem-info-popup');
    if(!ed||!el)return;
    var SN={stun:'暈眩',freeze:'冰凍',sleep:'睡眠',para:'麻痺',trap:'禁動',seal:'封印技能',
      noatk:'封印攻擊',nosell:'封印物品',deathmark:'死亡宣告',noheal_curse:'禁止恢復',
      berserk:'狂亂',spddown:'遲緩',hellfire:'燃燒',exhaust:'技能費+1',forecast:'失明',
      stubbornDebuff:'怨念強化',poison:'劇毒',
      weakened:'能力降低',_cryDebuff:'能力降低',_dreamDebuff:'能力降低'};
    var imm=(ed.immune50||[]).map(function(s){return SN[s]||s;}).join('、')||'—';
    var adv=(ed.vs_adv||[]).map(function(k){return ELEMENT_DB[k]?ELEMENT_DB[k].name:k;}).join('、')||'—';
    var dis=(ed.vs_dis||[]).map(function(k){return ELEMENT_DB[k]?ELEMENT_DB[k].name:k;}).join('、')||'—';
    var bon=[];
    if(ed.bonus_hp)bon.push('HP+'+ed.bonus_hp);
    if(ed.bonus_atk)bon.push('攻擊+'+ed.bonus_atk);
    if(ed.bonus_sp)bon.push('特技+'+ed.bonus_sp);
    if(ed.bonus_spd)bon.push('速度+'+ed.bonus_spd);
    if(ed.bonus_healflat)bon.push('恢復+'+ed.bonus_healflat);
    if(ed.bonus_dmgreduce)bon.push('受傷-'+ed.bonus_dmgreduce);
    if(ed.bonus_energy)bon.push('能量+'+ed.bonus_energy+'/回');
    var bc={water:'#55bbff',fire:'#ff7733',wind:'#44cc66',grass:'#88bb22',earth:'#aa7733',light:'#ffdd22',dark:'#9944cc'}[key]||'var(--gold)';
    el.style.borderColor=bc;
    el.style.boxShadow='0 0 30px '+bc+'66,0 0 60px rgba(0,0,0,0.8)';
    el.innerHTML='<div class="ep-title"><span>'+ed.icon+'</span><span style="color:'+bc+'">'+ed.name+'屬性</span></div>'
      +'<div class="ep-section"><div class="ep-label">▸ 50%機率免疫異常</div><div class="ep-row ep-immune">'+imm+'</div></div>'
      +'<div class="ep-section"><div class="ep-label">▸ 能力提升</div><div class="ep-row ep-bonus">'+(bon.length?bon.join('　'):'—')+'</div></div>'
      +'<div class="ep-section"><div class="ep-label">▸ 造成傷害+'+Math.round((ed.adv_dmg_pct||0.10)*100)+'%的相剋目標</div><div class="ep-row ep-adv">→ '+adv+'</div></div>'
      +'<div class="ep-section"><div class="ep-label">▸ 受到傷害變動'+Math.round((ed.dis_dmg_pct||-0.10)*100)+'%的劣勢來源</div><div class="ep-row ep-dis">← '+dis+'</div></div>'
      +'<div style="font-size:11px;color:#555;margin-top:8px;text-align:center">再次點擊或點擊其他處關閉</div>';
    // Fixed center position - no px/py calculation needed
    // Position is fixed center via CSS (left:50%;top:50%;transform:translate(-50%,-50%))
    el.style.display='block';
  };
  window.addEventListener('load',function(){
    var wheel=document.getElementById('elem-wheel');
    if(!wheel)return;
    var EK={水:'water',火:'fire',風:'wind',草:'grass',土:'earth',光:'light',暗:'dark'};
    wheel.addEventListener('click',function(e){
      e.stopPropagation();
      _openAllElemPopup(e.clientX,e.clientY);
    });
    document.addEventListener('click',function(e){
      if(window._epOpen&&!e.target.closest('#elem-info-popup')&&!e.target.closest('#elem-wheel')){
        closeElemPopup();
      }
    });
  });
})();
function _openAllElemPopup(cx,cy){
  var el=document.getElementById('elem-info-popup');
  if(!el)return;
  // Toggle
  if(el.style.display==='block'){el.style.display='none';window._epOpen=false;window._epKey=null;return;}
  var SN={freeze:'冰凍',reflect:'反射',noatk:'封印攻擊',sleep:'睡眠',para:'麻痺',
    spddown:'遲緩',noheal_curse:'禁止恢復',berserk:'狂亂',exhaust:'技能費+1',
    trap:'禁動',seal:'封印技能',nosell:'封印物品',deathmark:'死亡宣告',stun:'暈眩',
    poison:'中毒',forecast:'失明',stubbornDebuff:'怨念強化',booklock:'禁書封鎖',confused:'疑惑'};
  var EKEYS=['water','fire','grass','earth','wind','light','dark'];
  var rows=EKEYS.map(function(key){
    var ed=ELEMENT_DB[key];
    var bc={water:'#55bbff',fire:'#ff7733',wind:'#44cc66',grass:'#88bb22',earth:'#aa7733',light:'#ffdd22',dark:'#9944cc'}[key]||'#fff';
    var imm=(ed.immune50||[]).map(function(s){return SN[s]||s;}).join('、')||'—';
    var adv=(ed.vs_adv||[]).map(function(k){return ELEMENT_DB[k]?ELEMENT_DB[k].name:k;}).join('、')||'—';
    var bon=[];
    if(ed.bonus_hp)bon.push('HP+'+ed.bonus_hp);
    if(ed.bonus_atk)bon.push('攻擊+'+ed.bonus_atk);
    if(ed.bonus_sp)bon.push('特技+'+ed.bonus_sp);
    if(ed.bonus_spd)bon.push('速度+'+ed.bonus_spd);
    if(ed.bonus_healflat)bon.push('恢復+'+ed.bonus_healflat);
    if(ed.bonus_dmgreduce)bon.push('受傷-'+ed.bonus_dmgreduce);
    if(ed.bonus_energy)bon.push('能量+'+ed.bonus_energy+'/回');
    return '<tr style="border-bottom:1px solid rgba(255,255,255,0.06)">'+
      '<td style="color:'+bc+';font-size:30px;font-weight:500;padding:9px 15px;white-space:nowrap">'+ed.icon+' '+ed.name+'</td>'+
      '<td style="font-size:24px;color:#ccc;padding:7px 12px">'+ed.desc+'</td>'+
      '<td style="font-size:24px;color:#ff9944;padding:7px 12px;white-space:nowrap">'+(bon.length?bon.join(' '):' — ')+'</td>'+
      '<td style="font-size:24px;color:#88ffcc;padding:7px 12px;white-space:nowrap">'+imm+'</td>'+
      '<td style="font-size:24px;color:#ffcc44;padding:7px 12px;white-space:nowrap">→ '+adv+'</td>'+
      '</tr>';
  }).join('');
 el.innerHTML='<div style="font-size:24px;font-weight:500;color:var(--gold);margin-bottom:14px;letter-spacing:3px">⚡ 全屬性效果一覽 <button onclick=\"closeElemPopup()\" style=\"background:transparent;border:1px solid #555;color:#aaa;font-size:20px;cursor:pointer;padding:4px 14px;border-radius:4px\">&#x2715;</button></div>'+
    '<table style="border-collapse:collapse;width:100%"><tr style="border-bottom:1px solid rgba(255,255,255,0.15)">'+
    '<th style="font-size:21px;color:var(--muted);text-align:left;padding:6px 15px">屬性</th>'+
    '<th style="font-size:18px;color:var(--muted);text-align:left;padding:5px 12px">說明</th>'+
    '<th style="font-size:18px;color:var(--muted);text-align:left;padding:5px 12px">能力</th>'+
    '<th style="font-size:18px;color:var(--muted);text-align:left;padding:5px 12px">50%免疫異常</th>'+
    '<th style="font-size:18px;color:var(--muted);text-align:left;padding:5px 12px">克制</th>'+
    '</tr>'+rows+'</table>'+
    '<div style="font-size:15px;color:#444;margin-top:8px;text-align:right">再次點擊相剋圖或此處 ✕ 關閉</div>';
  el.style.display='block';
  window._epOpen=true; window._epKey='__all__';
}
// ====== LOG ======
/* ★ v5.305.0(2026-10-28・老師「深度檢查…戰鬥中閃退」甲)— 戰鬥 LOG 上限 300 行＋不再整段重排。
   舊版每加一行就把整段 innerHTML 轉字串再整段重新解析;冒險/世界 BOSS/主線結束時又清錯元素(找 'battle-log',不存在),
   同一堂課連打幾場 LOG 無限長大 ⇒ 每行越來越慢、記憶體越吃越多 ⇒ 2019 iPad 越打越卡最後閃退。
   現在:insertAdjacentHTML 只解析新的那一行;超過 300 行從最舊的開始刪(展開 LOG 仍可往上看最近 300 行)。 */
function log(m){
  const l=document.getElementById('log');
  if(!l) return;
  l.insertAdjacentHTML('afterbegin', `<div>> ${m}</div>`);
  try{ while(l.childElementCount > 300 && l.lastElementChild) l.removeChild(l.lastElementChild); }catch(_){}
}
// ★ v3.16.56 — 戰鬥 LOG 展開/收合(展開時 #log 絕對定位覆蓋整個 #sb·可向上捲讀完整戰鬥過程)
//   設計:用 window.* 指派(跨 <script> 區塊安全);展開只改 #log 行內樣式·收合清回 ''
//   覆蓋層 z-index:55 < 切換鈕 60(鈕永遠可點) < 戰鬥結算遮罩(更高·不會外漏到結算畫面)
//   進入新戰鬥時 startTurn() round 1 會呼叫 _collapseBattleLog 自動收回·避免殘留展開態
window._logExpanded = false;
window._collapseBattleLog = function(){
  try{
    const l = document.getElementById('log');
    const btn = document.getElementById('log-toggle-btn');
    if(l){
      // 清回原本 CSS 控制(#log 預設樣式在 main.css)
      l.style.position=''; l.style.top=''; l.style.left=''; l.style.right=''; l.style.bottom='';
      l.style.maxHeight=''; l.style.zIndex=''; l.style.padding=''; l.style.background='';
      l.style.borderRadius=''; l.style.boxShadow='';
    }
    if(btn){ btn.textContent='戰報'; }   // ★ v4.25.0 — 圓鈕同 SOS 直徑·標籤「戰報」(舊「📜 LOG」)
    window._logExpanded = false;
  }catch(_){}
};
window.toggleBattleLog = function(){
  try{
    const l = document.getElementById('log');
    const btn = document.getElementById('log-toggle-btn');
    if(!l) return;
    try{ if(typeof playSfx==='function') playSfx('sfx-sel',0.45); }catch(_){}
    if(window._logExpanded){
      window._collapseBattleLog();
    }else{
      // 展開:絕對覆蓋整個 #sb·保留 column-reverse + 內部捲動
      l.style.position='absolute';
      l.style.top='0'; l.style.left='0'; l.style.right='0'; l.style.bottom='0';
      l.style.maxHeight='none';
      l.style.zIndex='55';
      l.style.padding='14px';   // ★ v4.18.0 — 鈕已移左下角固定位,頂部不再需要 44px 讓位
      l.style.background='rgba(14,10,26,0.97)';
      l.style.borderRadius='12px';
      l.style.boxShadow='0 6px 28px rgba(0,0,0,0.6)';
      if(btn){ btn.textContent='收合'; }   // ★ v4.25.0 — 圓鈕改 2 字「收合」(舊「✖ 收合」)
      window._logExpanded = true;
    }
  }catch(_){}
};

// ====== BGM ENGINE ======
// ★ v5.37.0(2026-08-14·老師需求2)— BGM 音量由固定 const 改「基準 × 使用者音量」單一權威:
//   BGM_VOLUME 改 let(值=_BGM_BASE_VOLUME × window._bgmUserVol),全檔十餘處既有消費點
//   (bgmPlay/暫停50%/淡入淡出/iPad 重試…)讀取時機皆在執行期 → 零改動自動吃到使用者音量。
//   使用者音量以 window 屬性存放(非裸 let):playSfx 等定義於更早 script 區塊,以 window 屬性
//   讀取可完全避開 let TDZ 風險(極早期呼叫也安全回退 1)。0 = 靜音(與 _bgmMuted 旗標連動)。
const _BGM_BASE_VOLUME = 0.4095;
window._bgmUserVol = 1;   // 0~1(音樂使用者音量·雲端 settings.bgmVol 持久化)
window._sfxUserVol = 1;   // 0~1(音效使用者音量·雲端 settings.sfxVol 持久化)
let BGM_VOLUME = _BGM_BASE_VOLUME;
let _curBgm = null;
let _bgmMuted = false;
let _advBestScore = 0; // ★ 玩家個人最高分（SABCD評分基準）
let _sfxMuted = false;
let _gamePaused = false;

let _gpPauseStartedAt = 0;
let _gpHeartbeatInterval = null;
// ★ v3.4.19 — interval 從 10 秒 → 3 秒,讓快速通道(5 秒卡死訊號)能真正在 5-8 秒內觸發
//   原本 10 秒 interval × 20 秒 timeout = 最差 30 秒才救,玩家體感「整場卡死」。
//   3 秒 interval + 5 秒快速通道 = 最差 8 秒救援,接近 AI watchdog 等級。
const _GP_HB_INTERVAL = 3000;    // 3 秒檢查一次
const _GP_TIMEOUT = 20000;       // 持續 20 秒視為卡死(原邏輯保留)

function _gpStartHeartbeat(){
  if(_gpHeartbeatInterval) return;
  _gpHeartbeatInterval = setInterval(_gpHeartbeatCheck, _GP_HB_INTERVAL);
}
function _gpHeartbeatCheck(){
  // ★ v5.21.0(2026-08-09)— 乙:冒險戰鬥全滅巡邏(玩家 BUG 回報 2026-08-08 根因鏈第三環:敵方全滅
  //   但 checkWin 未觸發·戰鬥閒置 23 秒才被 heartbeat 觸發的 startTurn 踩到 v3.14.0 保險強制收場,
  //   玩家體感「卡死後突然跳出遊戲」)。借用本 heartbeat 既有 3 秒節拍:任一方全滅且未結算 → 立即走
  //   與 startTurn v3.14.0/v3.14.4 保險完全相同的正規收場,把最長 20+ 秒凍結縮到 ≤3 秒。
  //   安全閘:①G 每場 initGame 全新物件 → _annihilationPatrolFired latch 天然歸零·每場最多發動一次
  //   ②cutscene / 小怪結算視窗顯示中不介入 ③答題進行中(asking/answered)跳過本拍 3 秒後再看
  //   ④世界 BOSS(worldboss)與鬥技場(非冒險)不適用,條件與 startTurn 保險完全對齊。
  try{
    if(typeof _adventureMode !== 'undefined' && _adventureMode
       && typeof _adventureStage !== 'undefined' && _adventureStage !== 'worldboss'
       && typeof G !== 'undefined' && G
       && Array.isArray(G.p1) && G.p1.length > 0
       && Array.isArray(G.p2) && G.p2.length > 0
       && !G._resultShown
       && !G._annihilationPatrolFired
       && !window._advMiniResultShowing){
      var _apQuizBusy = (typeof _advQuizPhase !== 'undefined'
                         && (_advQuizPhase === 'asking' || _advQuizPhase === 'answered'));
      var _apCsOv = document.getElementById('adv-cutscene-overlay');
      var _apCsShown = _apCsOv && (_apCsOv.style.display === 'flex' || _apCsOv.classList.contains('show'));
      if(!_apQuizBusy && !_apCsShown){
        var _apAllP1Dead = G.p1.every(function(h){ return !h || h.curHp <= 0; });
        var _apAllP2Dead = G.p2.every(function(h){ return !h || h.curHp <= 0; });
        if(_apAllP1Dead){
          G._annihilationPatrolFired = true;
          console.warn('🛡 [v5.21.0 全滅巡邏] 我方全滅但尚未結算(3 秒巡邏)→ 強制 checkWin(接關流程)');
          var _apHandled1 = false;
          try{ if(typeof checkWin === 'function' && checkWin()) _apHandled1 = true; }catch(_eApCw1){}
          if(!_apHandled1){
            try{ if(typeof _showResultWithDrama === 'function') _showResultWithDrama(false); }
            catch(_eApF1){ console.error('[v5.21.0 全滅巡邏] 我方全滅強制結算例外', _eApF1); }
          }
        } else if(_apAllP2Dead){
          G._annihilationPatrolFired = true;
          console.warn('🛡 [v5.21.0 全滅巡邏] 敵方全滅但尚未結算(3 秒巡邏)→ 強制收場');
          var _apHandled2 = false;
          try{ if(typeof checkWin === 'function' && checkWin()) _apHandled2 = true; }catch(_eApCw2){}
          if(!_apHandled2){
            try{
              if(typeof _advMiniBattleActive !== 'undefined' && _advMiniBattleActive
                 && typeof advFinishMiniBattle === 'function'){ advFinishMiniBattle(true); }
              else if(typeof _showResultWithDrama === 'function'){ _showResultWithDrama(true); }
            }catch(_eApF2){ console.error('[v5.21.0 全滅巡邏] 敵方全滅強制結算例外', _eApF2); }
          }
        }
      }
    }
  }catch(_eAnnPatrol){}
  try{
    if(!_gamePaused){
      _gpPauseStartedAt = 0;
      return;
    }
    // 第一次發現 paused → 記錄開始時間
    if(_gpPauseStartedAt === 0){
      _gpPauseStartedAt = Date.now();
      return;
    }
    const _elapsed = Date.now() - _gpPauseStartedAt;
    // ★ v3.4.19 — 快速通道:若 paused 超過 5 秒,且偵測到「孤兒 quiz overlay」或
    //   「mini quiz 殭屍 (phase=asking 但 overlay.show=false)」這兩種明確卡死訊號,
    //   就立刻救,不必等 20 秒。
    //   原本要 20 秒等小怪戰救援體感太久,玩家以為「卡死了」。
    if(_elapsed >= 5000 && _elapsed < _GP_TIMEOUT){
      try{
        const _qOv = document.getElementById('adv-quiz-overlay');
        const _qShown = _qOv && _qOv.classList && _qOv.classList.contains('show');
        const _phaseIdle = (typeof _advQuizPhase === 'undefined' || _advQuizPhase === 'idle' || !_advQuizPhase);
        const _miniPhaseAsking = (typeof window._miniQuizPhase !== 'undefined' && window._miniQuizPhase === 'asking');
        const _miniPhaseIdle = !window._miniQuizPhase || window._miniQuizPhase === 'idle';
        const _noBossCb = !(typeof _advQuizResolveCb !== 'undefined' && _advQuizResolveCb);
        const _noMiniCb = !(typeof window._miniQuizOnDone === 'function');
        // 訊號 A:孤兒 overlay (顯示但 phase=idle 且兩種 cb 都空)
        const _signalA = _qShown && _phaseIdle && _miniPhaseIdle && _noBossCb && _noMiniCb;
        // 訊號 B:mini quiz 殭屍 (phase=asking 但 overlay 沒顯示 — 題目從未渲染)
        const _signalB = _miniPhaseAsking && !_qShown;
        if(_signalA || _signalB){
          console.warn('🚨 [_gp heartbeat 快速通道] 偵測明確卡死訊號 ('
            + (_signalA ? '孤兒overlay' : 'mini quiz殭屍')
            + '),已等 ' + _elapsed + 'ms,立刻救援');
          // 強制清孤兒狀態
          try{
            if(_qShown && _signalA){
              _qOv.classList.remove('show');
              _qOv.style.display = 'none';
            }
            if(typeof _advQuizPhase !== 'undefined') _advQuizPhase = 'idle';
            window._miniQuizPhase = 'idle';
            window._miniQuizOnDone = null;
            window._miniQuizCurrentQ = null;
            window._miniQuizOnDoneSetAt = 0;
            window._bossQuizInFlight = false;
          }catch(_){}
          _gamePaused = false;
          _gpPauseStartedAt = 0;
          try{ _resumeTimers(); }catch(_){}
          // 立刻救卡住的 actor
          try{
            setTimeout(function(){
              try{
                if(typeof window._advForceRescueActor === 'function'){
                  window._advForceRescueActor('_gp heartbeat 快速通道');
                }
              }catch(_e){ console.warn('[_gp heartbeat 快速通道後續救援] 例外', _e); }
            }, 800);
          }catch(_){}
          return;
        }
      }catch(_eFast){ console.warn('[_gp heartbeat 快速通道] 例外', _eFast); }
    }
    if(_elapsed < _GP_TIMEOUT) return;  // 還沒超時
    // 檢查是否有合法 modal 顯示中(玩家正在操作 modal 是正常的長時間 paused)
    if(_gpIsAnyLegitModalOpen()){
      // 有合法 modal → 重新從現在開始計時(因為玩家還在操作)
      _gpPauseStartedAt = Date.now();
      return;
    }
    // 真的卡死了:強制釋放 + resume
    console.warn('🚨 [_gp heartbeat] _gamePaused 持續 '+_elapsed+'ms 且無合法 modal,強制釋放並 _resumeTimers');
    _gamePaused = false;
    _gpPauseStartedAt = 0;
    try{ _resumeTimers(); }catch(_){}
    // ★ v3.3.7+ — 連帶救援卡住的 actor(舊版只解除 paused,actor 仍 acted=false 卡在那)
    //   1.5 秒後呼叫共用救援函式
    try{
      setTimeout(function(){
        try{
          if(typeof window._advForceRescueActor === 'function'){
            window._advForceRescueActor('_gp heartbeat');
          }
        }catch(_e){ console.warn('[_gp heartbeat 後續救援] 例外', _e); }
      }, 1500);
    }catch(_){}
  }catch(_){}
}

window._advForceRescueActor = function(source){
  source = source || 'unknown';
  try{
    if(typeof _adventureMode === 'undefined' || !_adventureMode) return false;
    if(typeof G === 'undefined' || !G || !G.activeChar) return false;
    const _ac = G.activeChar;
    if(!_ac || _ac.acted || _ac.curHp <= 0) return false;  // 已正常推進
    // 戰鬥已結束(一邊全滅)→ 不救
    if(!G.p1 || !G.p2) return false;
    const _aliveP1 = G.p1.filter(x => x && x.curHp > 0).length;
    const _aliveP2 = G.p2.filter(x => x && x.curHp > 0).length;
    if(_aliveP1 === 0 || _aliveP2 === 0) return false;
    // 排除世界 BOSS 戰 client 端
    const _isWbClient = !!(typeof _adventureStage !== 'undefined'
      && _adventureStage === 'worldboss'
      && window._wbInWorldBossMode
      && !window._wbConnectedHostMode);
    if(_isWbClient){
      console.warn('🚨 [' + source + '] 連線 client 端不主動救援,等 host 處理');
      return false;
    }
    // burst-cinematic 演出中 → 不救
    if(document.getElementById('burst-cinematic')) return false;
    // 排除玩家正在操作 action-panel
    const _ap = document.getElementById('action-panel');
    const _apVisible = _ap && _ap.style.display !== 'none';
    if(_ac.side === 'p1' && _apVisible) return false;
    // ── 真卡 → 強制普攻過回合 ──
    console.warn('🚨 [' + source + ' 救援] actor=' + _ac.name
      + '(' + _ac.side + '-' + _ac.pos + ') curHp=' + _ac.curHp
      + ', acted=' + _ac.acted + ' → 強制普攻過回合');
    try{ if(typeof log === 'function') log('⚠️ 偵測到行動卡住,自動以普攻過回合'); }catch(_){}
    // ★ v3.3.7+ — 救援前先清掉所有 quiz 殘留 flag,避免救完後下一回合又卡
    try{
      if(window._bossQuizInFlight){
        console.warn('[' + source + ' 救援] 順手清掉殘留 _bossQuizInFlight');
        window._bossQuizInFlight = false;
      }
      if(typeof _advQuizResolveCb !== 'undefined' && _advQuizResolveCb){
        console.warn('[' + source + ' 救援] 順手清掉殘留 _advQuizResolveCb');
        _advQuizResolveCb = null;
      }
      if(typeof _advQuizPhase !== 'undefined' && _advQuizPhase !== 'idle'){
        console.warn('[' + source + ' 救援] 重置 _advQuizPhase=idle(原 ' + _advQuizPhase + ')');
        _advQuizPhase = 'idle';
      }
      // 順手關掉孤兒 quiz overlay
      const _qOv = document.getElementById('adv-quiz-overlay');
      if(_qOv && _qOv.classList.contains('show')){
        _qOv.classList.remove('show');
        _qOv.style.display = 'none';
        console.warn('[' + source + ' 救援] 順手關掉孤兒 quiz overlay');
      }
    }catch(_){}
    const _foeSide = _ac.side === 'p1' ? 'p2' : 'p1';
    const _foes = (G[_foeSide] || []).filter(x => x && x.curHp > 0);
    if(_foes.length === 0){
      try{ if(typeof endAction === 'function') endAction(_ac, 0); }catch(_){}
      console.log('✅ [' + source + ' 救援] 沒對手,直接 endAction');
      return true;
    }
    const _foe = _foes[Math.floor(Math.random() * _foes.length)];
    try{
      if(typeof execAtk === 'function' && typeof endAction === 'function'){
        const _atk = (typeof _ac.atk === 'number') ? _ac.atk : 1;
        execAtk(_ac, _foe, _atk);
        endAction(_ac, 0);
        console.log('✅ [' + source + ' 救援] 已強制 ' + _ac.name + ' 普攻 → ' + _foe.name);
        return true;
      }else{
        if(typeof doRest === 'function'){ doRest(); return true; }
      }
    }catch(_eSave){
      console.error('🚨 [' + source + ' 救援] execAtk 失敗,退回 endAction', _eSave);
      try{ endAction(_ac, 0); }catch(_){}
      return true;
    }
  }catch(_eOuter){
    console.warn('[' + source + ' 救援] 內部例外', _eOuter);
  }
  return false;
};

