// ★ v1.0.20260421.3020 — BGM fade token：防止多條 fade 競態搶奪同一個 audio 元素
let _bgmFadeToken = 0;
let _bgmFadeTimer = null;
function _bgmCancelFade(){
  if(_bgmFadeTimer){ try{ clearInterval(_bgmFadeTimer); }catch(_){} _bgmFadeTimer = null; }
}
function bgmFadeTo(newId,duration){
  duration=duration||800;
  if(newId==='bgm-battle'){
    const _stageGuess = (typeof _adventureStage!=='undefined' && _adventureStage)
                     || (typeof window._advSelectedStage!=='undefined' && window._advSelectedStage)
                     || null;
    if(_stageGuess==='japan') newId = 'bgm-japan-battle';
  }
  // ★ v1.0.20260421.3000k — 日本小怪戰 BGM 抽象名：從 JAPAN_BATTLE_BGM_LIST 輪流隨機挑選
  //   若 _curBgm 已是清單中任一首則不重播，避免場景切換時跳歌
  if(newId==='bgm-japan-battle'){
    if(_curBgm && typeof JAPAN_BATTLE_BGM_LIST!=='undefined' && JAPAN_BATTLE_BGM_LIST.includes(_curBgm)){
      const _curEl0 = document.getElementById(_curBgm);
      if(_curEl0 && !_curEl0.paused) return;
    }
    newId = (typeof JAPAN_BATTLE_BGM_LIST!=='undefined' && JAPAN_BATTLE_BGM_LIST.length)
      ? JAPAN_BATTLE_BGM_LIST[Math.floor(Math.random()*JAPAN_BATTLE_BGM_LIST.length)]
      : 'bgm-japan-battle';
  }
  // ★ v3.13.24(2026-06-02) — 戰鬥 BGM 5 首輪播修復(鐵律 1.156)
  //   原本 v1.x 把 newId 從 'bgm-battle' 提前隨機替換成具體某一首(如 bgm-battle-03),
  //   但下方 49301 行的 if(newId==='bgm-battle') 因此走不到 bgmPlayBattle() playlist 路徑,
  //   最終 fall through 到 bgmPlay(具體 id) → el.loop=true → 卡死在那首歌無限循環,
  //   永遠不會觸發 onended 切下一首。修法:不提前替換,只保留「已在播 BGM 不重切」防呆。
  if(newId==='bgm-battle'){
    if(_curBgm && typeof BATTLE_BGM_LIST!=='undefined' && BATTLE_BGM_LIST.includes(_curBgm)){
      const _curEl0 = document.getElementById(_curBgm);
      if(_curEl0 && !_curEl0.paused) return;
    }
    // 不替換 newId,讓下方 49301 行走 bgmPlayBattle() playlist
  }
  // ★ 'bgm-menu' → 'bgm-menu-01'
  if(newId==='bgm-menu') newId='bgm-menu-01';
  // ★ 防呆：已在播放同一首就不重播（避免商店販賣時重新渲染導致 BGM 重頭播）
  if(_curBgm === newId){
    const _curEl = document.getElementById(_curBgm);
    if(_curEl && !_curEl.paused) return;
  }
  // ★ v1.0.20260421.3020 — 取消前一次未完成的 fade，避免兩條 setInterval 搶同一個 audio
  _bgmCancelFade();
  const _myToken = ++_bgmFadeToken;
  // 包裝：產生一個 fadeOut Interval，結束後檢查 token 是否仍有效才 play 新曲
  const _doFadeOut = (oldEl, onDone)=>{
    if(!oldEl || oldEl.paused){ onDone(); return; }
    const sv = oldEl.volume;
    const steps = 20, interval = duration/steps;
    let step = 0;
    _bgmFadeTimer = setInterval(()=>{
      // token 過期：已有新的 fadeTo 覆蓋，直接結束本次工作
      if(_myToken !== _bgmFadeToken){ clearInterval(_bgmFadeTimer); _bgmFadeTimer = null; return; }
      step++;
      oldEl.volume = Math.max(0, sv*(1 - step/steps));
      if(step >= steps){
        clearInterval(_bgmFadeTimer); _bgmFadeTimer = null;
        oldEl.onended = null; oldEl.pause();
        try{ oldEl.currentTime = 0; }catch(_){}
        _curBgm = null;
        if(_myToken !== _bgmFadeToken) return;
        onDone();
      }
    }, interval);
  };
  // ★ 稀有怪專屬BGM直接播放（不需映射）
  if(newId==='bgm-lose'){
    const oldEl = _curBgm ? document.getElementById(_curBgm) : null;
    const doPlayLose = ()=>{
      if(_myToken !== _bgmFadeToken) return;
      _battlePlayMode = false; _menuPlayMode = false;
      const el = document.getElementById('bgm-lose');
      if(!el) return;
      el.volume = _bgmMuted ? 0 : BGM_VOLUME;
      el.currentTime = 0;
      el.loop = true;
      el.play().catch(()=>{});
      _curBgm = 'bgm-lose';
    };
    _doFadeOut(oldEl, doPlayLose);
    return;
  }
  if(newId==='bgm-battle'){
    const oldEl = _curBgm ? document.getElementById(_curBgm) : null;
    _doFadeOut(oldEl, ()=>{ if(_myToken===_bgmFadeToken) bgmPlayBattle(); });
    return;
  }
  if(newId==='bgm-menu'){
    const oldEl = _curBgm ? document.getElementById(_curBgm) : null;
    _doFadeOut(oldEl, ()=>{ if(_myToken===_bgmFadeToken) bgmPlayMenu(); });
    return;
  }
  // ★ v3.13.25(2026-06-02) — 鬥技場主頁/戰鬥抽象名(鐵律 1.159)
  //   呼叫端可用 'bgm-arena-lobby-list' 或 'bgm-arena-battle-list',自動走 playlist
  if(newId==='bgm-arena-lobby-list'){
    // 若已在播 lobby 任一首且未暫停,不重切
    if(_curBgm && typeof ARENA_LOBBY_BGM_LIST!=='undefined' && ARENA_LOBBY_BGM_LIST.includes(_curBgm)){
      const _curEl0 = document.getElementById(_curBgm);
      if(_curEl0 && !_curEl0.paused) return;
    }
    const oldEl = _curBgm ? document.getElementById(_curBgm) : null;
    _doFadeOut(oldEl, ()=>{ if(_myToken===_bgmFadeToken) bgmPlayArenaLobby(); });
    return;
  }
  if(newId==='bgm-arena-battle-list'){
    if(_curBgm && typeof ARENA_BATTLE_BGM_LIST!=='undefined' && ARENA_BATTLE_BGM_LIST.includes(_curBgm)){
      const _curEl0 = document.getElementById(_curBgm);
      if(_curEl0 && !_curEl0.paused) return;
    }
    const oldEl = _curBgm ? document.getElementById(_curBgm) : null;
    _doFadeOut(oldEl, ()=>{ if(_myToken===_bgmFadeToken) bgmPlayArenaBattle(); });
    return;
  }
  _battlePlayMode = false;
  _menuPlayMode = false;
  const oldEl = _curBgm ? document.getElementById(_curBgm) : null;
  _doFadeOut(oldEl, ()=>{ if(_myToken===_bgmFadeToken) bgmPlay(newId); });
}
