// ★ 開發密技按鍵（測試用）
document.addEventListener('keydown', function(e){
  // ★ v3.11.8(2026-05-28) — 密技守門:必須是管理員才能用 F8 / F9 / Shift+F10
  //   學生按下這些鍵應該完全沒反應,連 preventDefault 都不做(連按了什麼鍵都看不出)
  //   重要:
  //     1. 集中用 window._isAdminUser() 判定,不再寫死 email 列表(避免 F12 搜「F9」就看到 email)
  //     2. 守門失敗時直接 return,不印任何 console(避免洩漏「有 F9 密技存在」)
  //     3. _fbUser 未就緒時 _isAdminUser() 回 false,啟動初期同樣安全
  try{
    if(typeof window._isAdminUser !== 'function') return;
    if(!window._isAdminUser()) return;
  }catch(_eAdminGuard){ return; }

  // F9：直接戰鬥勝利
  if(e.key === 'F9'){
    e.preventDefault();
    try{
      if(typeof G==='undefined'||!G.p1||!G.p2||!G.p1.length||!G.p2.length){
        console.log('[F9] 目前不在戰鬥中'); return;
      }
      console.log('[F9] 強制勝利觸發！');
      try{ clearTurnTimer(); }catch(_){}
      try{ clearInterval(_advQuizTimer); _advQuizTimer=null; }catch(_){}
      try{ clearInterval(_advQuizTimerHandle); _advQuizTimerHandle=null; }catch(_){}
      try{ _advQuizActive=false; _advQuizPhase='idle'; }catch(_){}
      try{ if(typeof _closeAllBattleModals === 'function') _closeAllBattleModals(); }catch(_){}
      try{ G.pendingTarget=null; pendingCb=null; }catch(_){}
      try{ _gamePaused=false; }catch(_){}
      try{ if(typeof _clearPendingTimers === 'function') _clearPendingTimers('卡死自救'); }catch(_){}
      G._resultShown = false;
      flashScreen('rgba(255,220,50,1)', 400);
      // ★ 對每個活著的 p2 呼叫 doDmg,用巨量傷害確保一擊必殺,走 doDmg 自然清理流程
      //   ignoreBuffs/piercing/ignoreEvasion 確保不被護盾/迴避卡住
      try{
        const _fakeActor = G.p1.find(h => h && h.curHp > 0) || G.p1[0];
        G.p2.filter(h => h && h.curHp > 0).forEach(h => {
          try{
            doDmg(h, 99999, {actor: _fakeActor, isSkill: true, ignoreBuffs: true, piercing: true, ignoreEvasion: true, noHidden: true, skipSfx: true});
          }catch(dE){
            // 如果 doDmg 本身出錯,回退到直接設 curHp=0
            console.warn('[F9 doDmg fallback]', dE);
            h.curHp = 0;
            try{ _lxpsStatFxRestoreAll(h); h.status=[]; h.buffs=[]; }catch(_){}
            try{ renderCard(h); }catch(_){}
          }
        });
      }catch(bulkE){ console.warn('[F9 bulk kill]', bulkE); }
      updateUI();
      // doDmg 裡面最後一擊會呼叫 checkWin,不用再手動呼叫
      // 但為保險,延遲 100ms 再確認一次(若 doDmg 沒觸發 checkWin 因故)
      setTimeout(function(){
        try{
          if(G && G.p2 && G.p2.every(h => h.curHp <= 0) && !G._resultShown){
            console.log('[F9] 補呼叫 checkWin');
            checkWin();
          }
        }catch(x){ console.error('[F9 late checkWin]',x); }
      }, 120);
    }catch(err){ console.error('[F9 error]',err); }
    return;
  }

  // F8：回到上一回合快照
  if(e.key === 'F8'){
    e.preventDefault();
    if(!window._cheatPrevState){
      log('🔑 [F8密技] 沒有可以回溯的快照。');
      flashScreen('rgba(255,50,50,0.5)', 300);
      return;
    }
    log('🔑 [F8密技] 回到上一回合！');
    flashScreen('rgba(100,180,255,0.7)', 500);
    try{
      const snap = window._cheatPrevState;
      // 清除計時器和暫態
      try{ clearTurnTimer(); }catch(_){}
      try{ clearInterval(_advQuizTimer); _advQuizPhase='idle'; _advQuizActive=false; }catch(_){}
      try{ document.getElementById('adv-quiz-overlay').classList.remove('show'); }catch(_){}
      try{ G.pendingTarget=null; pendingCb=null; }catch(_){}
      try{ _gamePaused=false; }catch(_){}
      try{ G._resultShown=false; }catch(_){}
      // 還原快照
      G.p1 = snap.p1; G.p2 = snap.p2;
      G.energy = snap.energy;
      G.round = snap.round;
      G.inv = snap.inv; G.inv2 = snap.inv2;
      G.fieldCards = snap.fieldCards || [];
      G._resultShown = false;
      updateUI(); renderField(); renderItems();
      log(`[F8] 已回溯至第 ${G.round} 回合開始`);
      try{ _gamePaused=false; }catch(_){}
      setTimeout(function(){ try{startTurn();}catch(x){console.error(x);} }, 400);
    }catch(err){ console.error('[F8 cheat]', err); }
    return;
  }

  // Shift+F10：管理員人數統計工具面板（回填歷史資料、手動調整冒險次數）
  if(e.key === 'F10' && e.shiftKey){
    e.preventDefault();
    _showAdminStatsPanel();
    return;
  }
});

(function _setupMobileAdminTrigger(){
  // 避免熱區被重複插入(熱重載或多次載入時)
  if(document.getElementById('_admin-mobile-trigger')) return;

  // 熱區:50×50px,絕對定位於右上角,完全透明
  // top:0、right:60px → 避開 #ctrl-bar 最右側的「結束遊戲」「全螢幕」按鈕
  const hit = document.createElement('div');
  hit.id = '_admin-mobile-trigger';
  hit.style.cssText = ''
    + 'position:fixed;top:0;right:60px;width:50px;height:50px;'
    + 'z-index:99988;background:transparent;pointer-events:none;'   /* ★ v5.301.0 auto → none(見下方說明) */
    + '-webkit-user-select:none;user-select:none;';
  /* ★ v5.301.0(老師「檢查手機版所有頁面是否有按鈕…按了無效或很難按到」)— 實測抓到:這塊 50×50 透明熱區(z 99988、pointer-events:auto)
     蓋在所有頁面右上角,手機上剛好壓住右上功能鍵列的「重新開始」「帳號與指引」、鬥技場的「✕ 離開」等按鈕的一部分 ⇒ 學生點到那一塊就「按了沒反應」。
     改法:熱區本身不再吃任何點擊(pointer-events:none),改在 document 上聽「兩指」觸控,兩根手指都落在熱區範圍內才開始計時 2 秒
     ⇒ 單指點擊完全穿透到底下的按鈕;老師的兩指長按 2 秒開管理面板照舊可用。 */
  if(document.body){
    document.body.appendChild(hit);
  } else {
    document.addEventListener('DOMContentLoaded', () => document.body.appendChild(hit));
  }

  let holdTimer = null;
  let startTouches = null;
  const HOLD_MS = 2000;
  const MOVE_TOLERANCE = 20;

  function _cancelHold(){
    if(holdTimer){ clearTimeout(holdTimer); holdTimer = null; }
    startTouches = null;
  }

  function _inHit(t){ const r = hit.getBoundingClientRect(); return t.clientX >= r.left && t.clientX <= r.right && t.clientY >= r.top && t.clientY <= r.bottom; }
  document.addEventListener('touchstart', (e) => {
    if(e.touches.length !== 2 || !_inHit(e.touches[0]) || !_inHit(e.touches[1])){ _cancelHold(); return; }
    startTouches = [
      { x: e.touches[0].clientX, y: e.touches[0].clientY },
      { x: e.touches[1].clientX, y: e.touches[1].clientY },
    ];
    holdTimer = setTimeout(() => {
      holdTimer = null;
      startTouches = null;
      try{
        const _ok = (typeof window._isAdminUser === 'function')
                  ? window._isAdminUser()
                  : true;
        if(!_ok) return;
        if(typeof _showAdminStatsPanel === 'function'){
          _showAdminStatsPanel();
        }
      }catch(err){
        console.warn('[_setupMobileAdminTrigger] open admin panel failed:', err);
      }
    }, HOLD_MS);
  }, { passive: true });

  document.addEventListener('touchmove', (e) => {
    if(!startTouches) return;
    if(e.touches.length !== 2){ _cancelHold(); return; }
    for(let i = 0; i < 2; i++){
      const dx = e.touches[i].clientX - startTouches[i].x;
      const dy = e.touches[i].clientY - startTouches[i].y;
      if(Math.hypot(dx, dy) > MOVE_TOLERANCE){ _cancelHold(); return; }
    }
  }, { passive: true });

  document.addEventListener('touchend', function(){ if(startTouches || holdTimer) _cancelHold(); }, { passive: true });
  document.addEventListener('touchcancel', function(){ if(startTouches || holdTimer) _cancelHold(); }, { passive: true });
})();

// ★ 管理員人數統計工具面板
// ════════════════════════════════════════════════════════════════════════════
// ★ v3.5.45 — 管理員後台已抽出為獨立模組 admin_panel.js
// ────────────────────────────────────────────────────────────────────────────
// 為什麼?
//   完整面板 ~4,380 行 / 240 KB,但只有老師會用到。從 index.html 抽出後,
//   玩家初次載入省 240 KB,管理員第一次按 Shift+F10 才下載。
//
// 怎麼用?
//   呼叫 _showAdminStatsPanel() 會先確保 admin_panel.js 已載入,然後執行實作
//   ・若已載入 → 立即執行 _showAdminStatsPanelImpl
//   ・若載入中 → 等載入完再執行
//   ・若未載入 → 開始載入,完成後執行
//
// 部署檢查:
//   1. 上傳 admin_panel.js 到 GitHub 同一資料夾(跟 game_changelog.js 同層)
//   2. 改 admin_panel.js 後,把下面的 ?v=YYYYMMDD 改成新日期破快取
//   3. F12 → Network → 按 Shift+F10 應看到 admin_panel.js 200 OK
// ════════════════════════════════════════════════════════════════════════════
(function(){
  var _loadState = 'idle'; // idle / loading / loaded / failed
  var _waitQueue = [];
  var ADMIN_PANEL_VERSION = '20260529-v3-11-35j-comforting-text'; // ★ v3.11.35j — 安撫版通知文字 + 大公告強調 SSR 緣分

  function _flushQueue(ok){
    var q = _waitQueue;
    _waitQueue = [];
    for(var i=0;i<q.length;i++){
      try{ q[i](ok); }catch(e){ console.warn('[admin_panel] callback error', e); }
    }
  }

  window._ensureAdminPanelLoaded = function(cb){
    cb = (typeof cb === 'function') ? cb : function(){};
    // ★ v3.11.8(2026-05-28) — 守門:非管理員呼叫直接 fail,不下載 admin_panel.js
    //   避免學生在 console 手動 _ensureAdminPanelLoaded(()=>{}) bypass keydown 守門
    try{
      if(typeof window._isAdminUser !== 'function' || !window._isAdminUser()){
        cb(false);
        return;
      }
    }catch(_eGuard){ cb(false); return; }
    if(_loadState === 'loaded' || window._adminPanelLoaded){
      cb(true);
      return;
    }
    if(_loadState === 'loading'){
      _waitQueue.push(cb);
      return;
    }
    _loadState = 'loading';
    _waitQueue.push(cb);

    var s = document.createElement('script');
    // ★ v3.11.13(2026-05-28) — 破快取改走中央版本清單 _LXPS_FILE_VERSIONS:
    //   老師改 admin_panel.js 後只要在清單把 admin_panel.js 版本號 +1,
    //   玩家就一定重抓新檔(不會再「主程式更新了、後台選單還是舊版」)。
    s.src = (typeof window._lxpsFileSrc === 'function')
      ? './' + window._lxpsFileSrc('admin_panel.js')
      : './admin_panel.js?v=' + ADMIN_PANEL_VERSION;
    s.async = true;
    s.onload = function(){
      // 等待 admin_panel.js 內把實作掛到 window
      var tries = 0;
      var iv = setInterval(function(){
        tries++;
        if(window._adminPanelLoaded && typeof window._showAdminStatsPanelImpl === 'function'){
          clearInterval(iv);
          _loadState = 'loaded';
          console.log('[admin_panel] ✅ 載入完成(共試 ' + tries + ' 次)');
          _flushQueue(true);
        } else if(tries > 30){ // 3 秒
          clearInterval(iv);
          _loadState = 'failed';
          console.error('[admin_panel] ❌ 載入後未找到 _showAdminStatsPanelImpl');
          _flushQueue(false);
        }
      }, 100);
    };
    s.onerror = function(e){
      _loadState = 'failed';
      console.error('[admin_panel] ❌ 載入失敗:', e);
      try{ alert('管理員後台載入失敗,請檢查網路或重新整理頁面'); }catch(_){}
      _flushQueue(false);
    };
    document.head.appendChild(s);
    console.log('[admin_panel] 🔄 開始載入 ' + s.src);
  };
})();

// stub: 管理員按 Shift+F10 都會呼叫到這個
// ★ v3.11.8(2026-05-28) — 入口守門:非管理員直接 return,連 admin_panel.js 都不下載
//   避免:
//     1. 學生在 console 手動跑 _showAdminStatsPanel() bypass keydown 守門
//     2. F12 → Network 看到 admin_panel.js 請求(暴露「存在後台檔案」)
//     3. 載入失敗 alert「管理員後台載入失敗」(直接彈視窗給學生看)
async function _showAdminStatsPanel(){
  // 守門:非管理員直接靜默退出,完全無痕
  try{
    if(typeof window._isAdminUser !== 'function' || !window._isAdminUser()){
      return;
    }
  }catch(_eAdminStub){ return; }
  // 若已開啟就不重開
  if(document.getElementById('_admin-stats-panel')) return;
  // 確保模組已載入
  await new Promise(function(resolve){
    window._ensureAdminPanelLoaded(function(ok){
      if(!ok){
        // 守門已通過,這裡 alert 只會給管理員看到
        try{ alert('❌ 管理員後台載入失敗,請檢查網路後重新整理'); }catch(_){}
      }
      resolve(ok);
    });
  });
  // 載入完成 → 執行實作
  if(typeof window._showAdminStatsPanelImpl === 'function'){
    return window._showAdminStatsPanelImpl();
  } else {
    console.error('[admin_panel] _showAdminStatsPanelImpl 不存在!');
  }
}


// 每回合開始時儲存快照（F8密技用）
function _saveCheatSnapshot(){
  if(typeof G === 'undefined' || !G.p1) return;
  try{
    window._cheatPrevState = {
      p1: JSON.parse(JSON.stringify(G.p1)),
      p2: JSON.parse(JSON.stringify(G.p2)),
      energy: {...G.energy},
      round: G.round||1,
      inv: JSON.parse(JSON.stringify(G.inv||[])),
      inv2: JSON.parse(JSON.stringify(G.inv2||[])),
      fieldCards: JSON.parse(JSON.stringify(G.fieldCards||[])),
    };
  }catch(_){}
}

// ★ 每回合戰鬥快照（崩潰恢復用，只寫 localStorage，不阻塞遊戲）
function _saveBattleRoundSnapshot(){
  if(typeof G === 'undefined' || !G || !G.p1 || !G.p2) return;
  // ★★ v4.89.0 — 主線真實戰鬥「絕不寫續戰快照」(老師帳號零汙染明令):
  //   主線戰鬥戰敗只重打該場(Q4 甲),不走中斷續戰;若寫入 stage='mainstory' 快照,
  //   下次登入 _advCheckCrashRecovery 會誤跳續戰彈窗、甚至誤還原成冒險戰 → 壞檔。
  //   不能靠 _advSuppressSnapSave(advStartBattle 開場會 reset 為 false),必須獨立旗標。
  try{ if(window._msRealBattleActive === true || (typeof _adventureStage !== 'undefined' && _adventureStage === 'mainstory')) return; }catch(_){}
  // ★ v3.13.29(2026-06-03) — 鬥技場戰鬥也存快照(老師裁示:單人鬥技可中斷續戰)
  //   鬥技場與冒險快照互斥(同時間只一場),共用 adv_battle_snap key。
  //   鬥技場 _adventureMode===false,用 _arenaBgmContext 判定「鬥技場戰鬥中」。
  const _isArenaSnap = (typeof window._arenaBgmContext !== 'undefined' && window._arenaBgmContext === true)
                     && (typeof _adventureMode !== 'undefined' && _adventureMode === false);
  if(!_isArenaSnap){
    if(!_adventureMode || !_adventureStage) return;   // 冒險維持原守門
  }
  // ★ v1.0.20260424.0910 — 戰鬥結算面板已顯示時不再存快照
  //   (避免 BOSS 死亡後若還有 startTurn 觸發,把已清除的快照寫回去)
  // ★ v3.16.96 — 加掛勝利序列抑制鎖 _advSuppressSnapSave(問題4):清快照後若 _advBattleResultShown 被 reset,本鎖仍擋住重寫
  try{ if(window._advBattleResultShown || window._advSuppressSnapSave) return; }catch(_){}
  try{
    // ★ v1.0.20260424.0800 — 序列化英雄:用「全屬性深複製」避免某些 _xxx 旗標被遺漏
    //   (原版手動列舉欄位,結果 _yamataDoubleTriggered/_kinderRounds/shield 等沒被存到,
    //    導致回溯後對手 HP/狀態看似正常,但部分內部狀態錯亂或殘留)
    const _serHero = h => {
      // 從原物件深複製,但要排除函式引用
      const _out = {};
      for(const k in h){
        if(!Object.prototype.hasOwnProperty.call(h, k)) continue;
        const v = h[k];
        if(typeof v === 'function') continue; // 跳過函式
        try{
          _out[k] = (typeof v === 'object' && v !== null) ? JSON.parse(JSON.stringify(v)) : v;
        }catch(_){
          // JSON 不能序列化的(如 DOM 元素)就略過
        }
      }
      return _out;
    };
    const snap = {
      ts:         Date.now(),
      stage:      _isArenaSnap ? 'arena' : _adventureStage,
      isArena:    !!_isArenaSnap,
      grade:      _advPlayerGrade      || '',
      subject:    _advPlayerSubject    || '',
      difficulty: _advPlayerDifficulty || '',
      treasures:  JSON.parse(JSON.stringify(_advTreasures||[])),
      heroes:     _heroPickSelected ? [..._heroPickSelected] : [],
      round:      G.round || 1,
      // ★ v1.0.20260422.0100 — 保存場景索引與 BOSS 變體索引，
      //   讓 _advRestoreBattleState 能還原正確的背景圖與 BGM（尤其日本關各路線）
      sceneIdx:   (typeof _advSceneIdx === 'number') ? _advSceneIdx : 0,
      variantIdx: (typeof window._advSelectedVariantIdx === 'number') ? window._advSelectedVariantIdx : 0,
      // ── 完整戰鬥狀態 ──
      battleState: {
        p1:          (G.p1||[]).map(_serHero),
        p2:          (G.p2||[]).map(_serHero),
        energy:      {...(G.energy||{p1:0,p2:0})},
        inv:         JSON.parse(JSON.stringify(G.inv||[])),
        inv2:        JSON.parse(JSON.stringify(G.inv2||[])),
        fieldCards:  JSON.parse(JSON.stringify((typeof fieldCards !== 'undefined' && fieldCards) || G.fieldCards || [])),
        round:       G.round || 1,
        fm:          (G._fm ? JSON.parse(JSON.stringify(G._fm)) : null),
        fmBid:       (G._fm && G._fmBid) ? G._fmBid : null,   // v5.284.0 續戰沿用場次編號(防重新整理重置每場 1 次的免死)   // ★ v5.282.0 英魂陣型(審查 H1):續戰時沿用,不重新套用能力加成
        isMini:      !!_advMiniBattleActive,  // ★ 記錄是否為小怪戰
        pendingReward: _advPendingReward ? JSON.parse(JSON.stringify(_advPendingReward)) : null,
        rewardOptions: _advRewardOptions ? JSON.parse(JSON.stringify(_advRewardOptions)) : [],
        // ★ v3.6.0 — 中斷恢復:技能格 3「知識化為力量」+ 新回合答題狀態
        knowledgePowerReward: window._advKnowledgePowerReward
          ? JSON.parse(JSON.stringify(window._advKnowledgePowerReward)) : null,
        lastQuizRound: window._advLastQuizRound || 0,
        advStats:    JSON.parse(JSON.stringify(_advStats||{})),
        // ★ v1.0.20260424.0800 — 補充全域戰鬥旗標,確保回溯後行為正確
        comboFatigue: G.comboFatigue||0,
        comboFatigueByHero: JSON.parse(JSON.stringify(G.comboFatigueByHero||{})),
        lastSkillName: G.lastSkillName||null,
        lastSkillByHero: JSON.parse(JSON.stringify(G.lastSkillByHero||{})),
        // ★ v5.67.0(稽核修復·老師 2026-08-18 裁定「丹藥戰鬥快照要存」)—
        //   神農鼎丹藥的兩個戰場狀態原本完全沒進快照,造成兩個實質破口:
        //   ① G._alchUsed 遺失 → 中斷後續戰,每場 3 顆上限重置 = 可無限吃丹藥(共機環境易被利用)
        //   ② G._alchFx 遺失 → 疾風丹 +10 / 迷魂散 -20 是「直加 h.spd + 記帳於 _alchFx.rec」,
        //      快照存了加成後的 spd 卻沒存記帳 → 續戰後永遠不會還原 = 速度增益/減益整場鎖死。
        //   兩者一併存入,由 _advRestoreBattleState 對稱還原。
        alchUsed:    (G._alchUsed|0),
        alchFx:      G._alchFx ? JSON.parse(JSON.stringify(G._alchFx)) : null,
        // ★ v5.291.0 — 續戰補存:接關次數(舊版重新整理就重置成 2 次可用)、台灣關 BOSS(舊版續戰打贏拿不到至寶、BGM/背景錯)
        contCount:   (typeof _advContinueCount === 'number') ? _advContinueCount : 0,
        twBoss:      window._advSelectedTaiwanBoss || null,
        twBossCur:   window._taiwanCurrentBossId || null,
      }
    };
    localStorage.setItem('adv_battle_snap', JSON.stringify(snap));
    // ★ v4.47.0 任務D — 快照寫入診斷 log(每回合一筆·供 BUG 回報 console 追溯快照最後存在時間點)
    try{ console.log('[續戰診斷 v4.47.0] 已存戰鬥快照 stage=' + snap.stage + ' round=' + snap.round + (snap.isArena ? ' (鬥技場)' : '')); }catch(_){}
  }catch(e){ console.error('[battleSnap]',e); }
}

// ════════════════════════════════════════════════════════════════
// ★ v3.5.16 — 戰鬥中斷快照強化(老師 2026/5/22 回報:打 BOSS 戰到一半突然跳出遊戲,
//             也沒辦法回到上次的戰鬥,白白浪費了時間)
//
// 【問題】舊版快照系統雖然每回合存,但仍有 3 個漏洞:
//   1. _saveBattleRoundSnapshot 只在 startTurn 開頭觸發 — 若玩家還沒到下一回合
//      就跳出(分頁切換、iPad 切後台、瀏覽器當機),最新一回合的進度沒被存
//   2. 沒有 beforeunload / pagehide 強制存快照 → iOS Safari 殺 page 時雲端可能來不及同步
//   3. 世界 BOSS 戰快照雖然存了,但連線層 _wbNet 重建很複雜,單純走 _advRestoreBattleState
//      不夠 → 玩家「續戰」進去看到空白戰場
//
// 【修法】
//   (1) 暴露 window._forceSaveBattleSnapshotAndSync(reason) 對外 API,
//       手動觸發「存本地 + 寫雲端」,跨各種離開路徑統一使用
//   (2) 註冊 beforeunload + pagehide + visibilitychange(hidden) 三個事件,
//       戰鬥中且回合 >= 1 就強制呼叫上面的 API
//   (3) 把 worldboss 排除在自動續戰之外(在 _advCheckCrashRecovery 內擋掉),
//       改顯示「上次的世界 BOSS 戰中斷了,請從關卡選擇重新加入」的溫和提示
// ════════════════════════════════════════════════════════════════
window._forceSaveBattleSnapshotAndSync = function(reason){
  try{
    // 必須在戰鬥中且至少跑過 1 回合(避免空快照覆蓋)
    // ★ v3.13.29(2026-06-03) — 鬥技場戰鬥(_adventureMode===false + _arenaBgmContext)也允許強制存+同步雲端
    const _isArenaForce = (typeof window._arenaBgmContext !== 'undefined' && window._arenaBgmContext === true)
                        && (typeof _adventureMode !== 'undefined' && _adventureMode === false);
    if(!_isArenaForce){
      if(typeof _adventureMode === 'undefined' || !_adventureMode) return false;
      if(typeof _adventureStage === 'undefined' || !_adventureStage) return false;
    }
    if(typeof G === 'undefined' || !G || !Array.isArray(G.p1) || !Array.isArray(G.p2)) return false;
    if(!(G.round >= 1)) return false;
    if(window._advBattleResultShown || window._advSuppressSnapSave) return false;  // ★ v3.16.96 — 加掛勝利序列抑制鎖(問題4)
    // 強制存 localStorage(會記下最新一回合進度,不論 _lastBattleSnapRound)
    try{
      _saveBattleRoundSnapshot();
    }catch(_eS){ console.warn('[forceSaveBattleSnapshot] 存 localStorage 失敗', _eS); }
    // 同步雲端(若守門通過會把 advSnapshot 寫上去)
    try{
      if(typeof gameCloudSave === 'function' && window._gUserId){
        try{ window._lxpsCloudSaveForceNext = true; }catch(_){}  // ★ v4.47.0 任務B — 強制存快照屬關鍵路徑,直通節流立即上雲
        gameCloudSave();  // 不 await,讓事件能盡快結束;後續事件會再存
      }
    }catch(_eC){ console.warn('[forceSaveBattleSnapshot] gameCloudSave 失敗', _eC); }
    try{ console.log('💾 [forceSaveBattleSnapshot] 已強制存快照(原因:' + (reason || 'unknown') + ', round=' + G.round + ', stage=' + _adventureStage + ')'); }catch(_){}
    return true;
  }catch(e){
    console.warn('[forceSaveBattleSnapshot] 例外', e);
    return false;
  }
};

// 註冊頁面離開事件:強制存快照
// 三層事件都要綁,因為各瀏覽器情境不同:
//   - beforeunload:正常關閉/重新整理(桌面瀏覽器主要靠這個)
//   - pagehide:iOS Safari 唯一可靠的 unload 事件
//   - visibilitychange→hidden:分頁切換、app 切後台(iPad 上 page 可能被回收)
(function _setupBattleSnapAutoSaveOnExit(){
  if(window._battleSnapAutoSaveInstalled) return;
  window._battleSnapAutoSaveInstalled = true;
  const _handler = function(ev){
    try{
      const _reason = (ev && ev.type) || 'unknown';
      // ★ v4.47.0 任務B — 離頁時若有「被節流待寫」的雲端存檔排程中,設直通旗標立即補寫一次
      //   (best-effort;非戰鬥情境 _forceSave 會早退不呼叫 gameCloudSave,故此處自行補)
      try{
        if(window._lxpsCloudSaveTrailing && typeof gameCloudSave === 'function'){
          window._lxpsCloudSaveForceNext = true;
          gameCloudSave();
        }
      }catch(_eFl){}
      window._forceSaveBattleSnapshotAndSync('exit_' + _reason);
    }catch(_){}
  };
  window.addEventListener('beforeunload', _handler);
  window.addEventListener('pagehide', _handler);
  document.addEventListener('visibilitychange', function(){
    if(document.visibilityState === 'hidden'){
      _handler({ type: 'visibility_hidden' });
    }
  });
  console.log('💾 [v3.5.16] 戰鬥快照離場自動保存已安裝(beforeunload / pagehide / visibilitychange)');
})();

