// ====== 自訂確認視窗（iOS/iPad 安全，取代原生 confirm()）======
// 避免 iPad WKWebView 在 App 切換時自動 dismiss confirm() 造成誤確認
let _customConfirmCb = null;
function _customConfirm(msg, onOk) {
  const ov = document.getElementById('custom-confirm-overlay');
  const msgEl = document.getElementById('custom-confirm-msg');
  const okBtn = document.getElementById('custom-confirm-ok');
  if(!ov || !msgEl || !okBtn) {
    // fallback: 若 DOM 尚未就緒則用原生 confirm
    if(confirm(msg)) onOk();
    return;
  }
  // ★★ v5.104.0(2026-08-21・老師回報「超出經驗視窗階層太低，被圖鑑蓋住」)— 根因與根治 ★★
  //   【根因】本 overlay 靜態掛在 #_gc_wrapper 之內，而 #_gc_wrapper 是 position:fixed
  //     且**沒有 z-index** —— WebKit/Blink 對 position:fixed 一律建立 stacking context，
  //     所以它在 body 層的排序值等同 auto(≈0)。
  //     而圖鑑整備路徑(v3.12.0 起)會把 #hero-page-overlay(10000) 與 #hero-detail-overlay(10500)
  //     **detach 到 body 末端**；於是 body 層真正在比的是
  //       #_gc_wrapper(auto)  vs  hero-detail-overlay(10500)  ⇒ 圖鑑贏。
  //     本 overlay 就算寫 z-index:2147483647 也只是「#_gc_wrapper 內部第一名」，
  //     整個容器被壓下去時一起被壓 ⇒ 老師看到確認視窗躲在圖鑑後面。
  //     ⚠ 從主選單開圖鑑(未 detach)時圖鑑仍在 #gc 內，所以那條路徑看起來一切正常 ——
  //       這正是本 BUG 只在「編組頁／預設陣容視窗 → 📖 圖鑑整備」路徑重現的原因。
  //   【修法】顯示前把 overlay 搬成 **document.body 的最後一個子節點**：
  //     此後它與 #_gc_wrapper、以及任何 detach 出來的圖鑑層都是 body 直系兄弟，
  //     2147483647 才真正生效 ⇒ 蓋過圖鑑(10500)、也蓋過 #ctrl-bar(同為 max 但在 #_gc_wrapper 內)。
  //   ★ 單點修法涵蓋全檔 100+ 個 _customConfirm 呼叫點，不必逐處補圖層手術。
  //   ★ 只搬一次(冪等)，關閉後刻意不搬回去 —— 搬回去只會讓下次再中一次同樣的招。
  //   ⚠ 這確實部分推翻 main.css v20260517「#ctrl-bar 必須永遠在最高層」的舊裁定：
  //     破壞性確認視窗開著時，玩家本來就不該還能按到音量／收合鈕，擋住是正確行為。
  try{
    if(ov.parentNode !== document.body || ov !== document.body.lastElementChild){
      document.body.appendChild(ov);
    }
  }catch(_eReparent){ console.warn('[v5.104.0 _customConfirm 提升圖層]', _eReparent); }
  msgEl.innerHTML = msg.replace(/\n/g, '<br>');
  _customConfirmCb = onOk;
  okBtn.onclick = function() {
    ov.style.display = 'none';
    _customConfirmCb = null;
    onOk();
  };
  ov.style.display = 'flex';
}
function _customConfirmCancel() {
  const ov = document.getElementById('custom-confirm-overlay');
  if(ov) ov.style.display = 'none';
  _customConfirmCb = null;
}

// ====== CONTROL BAR ======
function _detectCurrentBgm(){
  const isVisible = id => {
    const el = document.getElementById(id);
    if(!el) return false;
    try{
      const cs = window.getComputedStyle(el);
      return cs && cs.display !== 'none' && cs.visibility !== 'hidden';
    }catch(_){
      return el.style.display !== 'none';
    }
  };
  const _inAdvBattle = (typeof _adventureMode !== 'undefined' && _adventureMode &&
                       typeof G !== 'undefined' && G && G.p2 && G.p2.length);
  if(_inAdvBattle || (typeof G !== 'undefined' && G && G.p2 && G.p2.length && isVisible('gc'))){
    if(typeof _adventureMode !== 'undefined' && _adventureMode){
      const _names = G.p2.map(h => h && h.name).filter(Boolean);
      // 稀有怪戰（優先判斷，避免被 BOSS_NAMES 誤判成 BOSS）
      if(_names.includes('寶箱怪')) return 'bgm-chest';
      if(_names.includes('小惡魔')) return 'bgm-devil';
      // ★ v5.50.0 — 中國關稀有瑞獸貔貅專屬 BGM(優先於中國小怪輪播;素材未上傳前播放失敗自動靜默)
      if(_names.includes('貔貅')) return 'bgm-china-pixiu';
      // ★ v1.0.20260421.3000j — 日本關稀有小怪專屬 BGM（優先於一般日本小怪 BGM）
      if(_names.includes('座敷童子')) return 'bgm-japan-zashiki';
      if(_names.includes('行走的二宮尊德像')) return 'bgm-japan-ninomiya';
      // ★ v1.0.20260421.0600 — 日本關專屬 BGM 判斷（優先於其他 BOSS BGM）
      //   v1.0.20260421.2800 — BOSS BGM 依 variant 細分（shutendoji/tamamo 有自己的 BGM）
      if(typeof _adventureStage !== 'undefined' && _adventureStage === 'japan'){
        const _japanBosses = ['大天狗','酒吞童子','玉藻前','八岐大蛇'];
        if(_names.some(n => _japanBosses.includes(n))){
          const _jv = (typeof ADV_BOSS_VARIANTS !== 'undefined' && ADV_BOSS_VARIANTS.japan)
            ? ADV_BOSS_VARIANTS.japan[window._advSelectedVariantIdx] : null;
          if(_jv && _jv.id === 'shutendoji') return 'bgm-japan-boss-shutendoji';
          if(_jv && _jv.id === 'tamamo') return 'bgm-japan-boss-tamamo';
          return 'bgm-japan-boss';
        }
        // ★ v1.0.20260421.3000k — 若已在播日本小怪戰 BGM 清單中任一首，維持不換歌
        if(typeof JAPAN_BATTLE_BGM_LIST !== 'undefined' && _curBgm && JAPAN_BATTLE_BGM_LIST.includes(_curBgm)) return _curBgm;
        return 'bgm-japan-battle';
      }
      // ★ v3.15.0 — 埃及關:雙王戰(法老王/埃及豔后)= bgm-egypt-boss;其餘小怪戰兩首輪播(v3.15.2)
      if(typeof _adventureStage !== 'undefined' && _adventureStage === 'egypt'){
        if(_names.includes('法老王') || _names.includes('埃及豔后')) return 'bgm-egypt-boss';
        // ★ v3.15.2 — 小怪戰兩首輪播:_egyptMobBattleCount 於每場 advStartMiniBattle 遞增,戰中穩定(故不會戰中重切)
        if(typeof EGYPT_BATTLE_BGM_LIST !== 'undefined') return EGYPT_BATTLE_BGM_LIST[(_egyptMobBattleCount||0) % EGYPT_BATTLE_BGM_LIST.length];
        return 'bgm-egypt-battle';
      }
      // ★ v5.39.0 — 中國關:BOSS 戰依變體(曹操/蚩尤專屬曲,其餘妖王共用);小怪戰兩首輪播(埃及同款)
      if(typeof _adventureStage !== 'undefined' && _adventureStage === 'china'){
        const _cnBosses = ['妲己','牛魔王','呂布','曹操','蚩尤'].concat((window._CN2 && window._CN2.bossNames) || []);   // ★ v5.293.0 補《繪卷新章》6 BOSS
        if(_names.some(n => _cnBosses.includes(n))){
          // ★ v5.69.1 — 改讀單一真相 window._chinaBossBgmId(偵測與實際播放不再分裂);舊逐條判定保留備查(勿刪):
          //   const _cv = (...ADV_BOSS_VARIANTS.china[window._advSelectedVariantIdx]...);
          //   if((_cv && _cv.id === 'fengshen') || _names.includes('妲己'))   return 'bgm-china-boss-daji';
          //   if((_cv && _cv.id === 'xiyou')    || _names.includes('牛魔王')) return 'bgm-china-boss-niumowang';
          //   if((_cv && _cv.id === 'sanguo')   || _names.includes('呂布'))   return 'bgm-china-boss-lvbu';
          //   if((_cv && _cv.id === 'caocao')   || _names.includes('曹操'))   return 'bgm-china-boss-caocao';
          //   if((_cv && _cv.id === 'chiyou')   || _names.includes('蚩尤'))   return 'bgm-china-boss-chiyou';
          //   return 'bgm-china-boss';
          return window._chinaBossBgmId(_names);
        }
        // ★ v5.49.0 — 小怪戰輪播池依路線分流(封神/西遊共用兩首;三國獨立兩首)
        if(typeof CHINA_BATTLE_BGM_LIST !== 'undefined'){ const _cnL = _chinaGetMobBgmList(); return _cnL[(_chinaMobBattleCount||0) % _cnL.length]; }
        return 'bgm-china-mob01';
      }
      // ★ v1.0.20260428.3740 — 台灣關 BOSS 戰:玉山專屬 + 其他輪播
      if(typeof _adventureStage !== 'undefined' && _adventureStage === 'taiwan'){
        if(window._advSelectedTaiwanBoss === 'yushan_giant'){
          return 'bgm-taiwan-boss-yushan';
        }
        // 若目前已在播台灣 BOSS 系列任一首,保持不換(避免靜音/取消靜音來回切歌)
        if(_curBgm === 'bgm-taiwan-boss-2' || _curBgm === 'bgm-taiwan-boss') return _curBgm;
        return 'bgm-taiwan-boss';
      }
      // ★ 依 BOSS 變體決定 BOSS BGM（即使 _curBgm 為 null 從靜音切回也能正確判斷）
      if(window._currentBossVariantInfo && window._currentBossVariantInfo.id === 'apricot'){
        return 'bgm-boss-apricot';
      }
      // ★ v3.8.0(2026-05-25) — 木柵第三隻 BOSS:黑暗球‧希望型態
      if(window._currentBossVariantInfo && window._currentBossVariantInfo.id === 'darkorb'){
        return 'bgm-boss-darkorb';
      }
      if(_names.includes('九尾空貓怪')) return 'bgm-boss-01';
      if(_names.includes('杏花妖')) return 'bgm-boss-apricot';
      // ★ v3.8.0 — 黑暗球(fallback,若 variantInfo 漏設)
      if(_names.includes('黑暗球‧希望型態')) return 'bgm-boss-darkorb';
      // 一般小怪戰：用場景 BGM
      return 'bgm-adv-scene';
    }
    // 鬥技場等非冒險模式戰鬥：維持 _curBgm 的戰鬥/BOSS BGM
    if(_curBgm && _curBgm.includes('boss')) return _curBgm;
    if(_curBgm && _curBgm.includes('battle')) return _curBgm;
    return null; // 無法判斷則維持現狀
  }
  // ★ v1.0.20260424.0790 — 召喚頁
  if(isVisible('summon-overlay')) return 'bgm-summon';
  // 冒險選關頁（若英雄圖鑑或魔物圖鑑疊在上方，不重播 BGM，維持現狀）
  if(isVisible('adventure-overlay')){
    if(isVisible('hero-page-overlay') || isVisible('monster-page-overlay') || isVisible('medal-page-overlay') || isVisible('pet-page-overlay')) return _curBgm;
    return 'bgm-menu-01';
  }
  // 超商
  if(isVisible('shop-overlay')) return 'bgm-shop';
  // 選角頁
  if(isVisible('hero-pick-overlay')) return 'bgm-menu-02';
  // 首頁（gc 隱藏中）
  if(!isVisible('gc')) return 'bgm-menu-02';
  return _curBgm; // 其他情況維持現狀
}

// ★ 統一場景 BGM 入口：依目前場景判斷該播什麼，並避免重複播放。
//   所有「切換頁面/開關面板」的程式碼應呼叫此函式，而不要各自直接呼叫 bgmPlay。
function bgmEnsureSceneBgm(){
  try{
    const target = _detectCurrentBgm();
    if(!target) return;                 // 戰鬥中 / 維持現狀
    if(target === _curBgm){
      // 防呆：若旗標顯示在播但實際被暫停了（切回前景後），補 play 一次
      const _el = document.getElementById(_curBgm);
      if(_el && _el.paused && !_bgmMuted) _el.play().catch(()=>{});
      return;
    }
    bgmPlay(target);
  }catch(_){}
}

function ctrlToggleBgm(){
  _bgmMuted = !_bgmMuted;
  // ★ v5.37.0 需求③ — 靜音切換同步套用到播放中的爆發/圖鑑欣賞影片(音樂靜音=影片靜音)
  try{
    if(typeof window._bvApplyBgmVol === 'function'){
      document.querySelectorAll('#_bv-overlay video, #hero-detail-anim-overlay video').forEach(function(_vd){
        window._bvApplyBgmVol(_vd);
      });
    }
  }catch(_eBvT){}
  const btn = document.getElementById('ctrl-bgm');
  btn.childNodes[0].textContent = _bgmMuted ? '🔇' : '🎵';
  btn.querySelector('.ctrl-tip').textContent = _bgmMuted ? '音樂音量（已靜音）' : '音樂音量';   // ★ v5.37.0 — 文案對齊音量面板
  btn.classList.toggle('muted', _bgmMuted);

  try{
    if(typeof AC !== 'undefined' && AC && AC.state === 'suspended'){
      AC.resume().catch(()=>{});
    }
  }catch(_){}

  if(_bgmMuted){
    // 靜音：停止所有 BGM
    document.querySelectorAll('audio[id^="bgm"]').forEach(el => {
      el.volume = 0;
      el._wasMuted = true;
    });
  } else {
    // 恢復：偵測當前場景並播放正確的 BGM
    document.querySelectorAll('audio[id^="bgm"]').forEach(el => {
      el.volume = 0;
      el._wasMuted = false;
    });
    const targetBgm = _detectCurrentBgm();
    if(targetBgm){
      // 強制重播正確 BGM
      try{
        bgmStop();
        setTimeout(() => {
          try{ bgmPlay(targetBgm); }catch(_){}
          // ★ iPad 保險：150ms 後若仍 paused，再嘗試一次（user gesture 已在 onclick 觸發）
          setTimeout(() => {
            try{
              const _el = document.getElementById(targetBgm);
              if(_el && _el.paused){
                _el.volume = BGM_VOLUME;
                _el.play().catch(()=>{});
              }
            }catch(_){}
          }, 300);
        }, 150);
      }catch(_){}
    }
  }
}
function ctrlToggleSfx(){
  _sfxMuted=!_sfxMuted;
  const btn=document.getElementById('ctrl-sfx');
  btn.childNodes[0].textContent=_sfxMuted?'🔈':'🔊';
  btn.querySelector('.ctrl-tip').textContent=_sfxMuted?'音效音量（已靜音）':'音效音量';   // ★ v5.37.0 — 文案對齊音量面板
  btn.classList.toggle('muted',_sfxMuted);
  // ★ v1.0.20260422.0108 — iPad 音訊恢復：
  //   AudioContext 可能處於 suspended，取消靜音時一併 resume 以喚醒 beep/noise 音效
  if(!_sfxMuted){
    try{
      if(typeof AC !== 'undefined' && AC && AC.state === 'suspended'){
        AC.resume().catch(()=>{});
      }
      // 播一個非常輕微的 beep 確認 AC 是否真正 running（user gesture 下才能成功）
      if(typeof AC !== 'undefined' && AC && AC.state === 'running'){
        try{ beep(880,'sine',0.05,0.02); }catch(_){}
      }
    }catch(_){}
  }
}
// Wrap beep/noise to respect sfx mute (done after function definitions)

// ════════════════════════════════════════════════════════════════
// ★ v5.37.0(2026-08-14·老師需求)— 功能鍵列收合/展開 + 🎵🔊 音量調整面板
// ════════════════════════════════════════════════════════════════
function _cvT(c, p){ return (typeof _artStyle !== 'undefined' && _artStyle === 'cute') ? c : p; }

// ── ① 功能鍵列收合/展開(避免長時間覆蓋右上資訊·狀態存本機 localStorage 裝置級偏好·零雲端寫入)──
function ctrlBarToggleCollapse(){
  try{ playSfx('sfx-gentle', 0.4); }catch(_){}
  var bar = document.getElementById('ctrl-bar');
  if(!bar) return;
  var collapsed = !bar.classList.contains('lxps-collapsed');
  _ctrlBarApplyCollapsed(collapsed);
  try{ localStorage.setItem('lxps_ctrlbar_collapsed', collapsed ? '1' : '0'); }catch(_){}
  // 收合當下順手關閉音量面板(面板錨定在功能鍵列下方,列收起面板不該獨留)
  if(collapsed){ try{ _ctrlCloseVolumePanel(); }catch(_){} }
}
function _ctrlBarApplyCollapsed(collapsed){
  var bar = document.getElementById('ctrl-bar');
  var btn = document.getElementById('ctrl-collapse');
  if(!bar || !btn) return;
  bar.classList.toggle('lxps-collapsed', !!collapsed);
  if(btn.childNodes && btn.childNodes[0] && btn.childNodes[0].nodeType === 3){
    btn.childNodes[0].textContent = collapsed ? '⚙' : '⏵';
  }
  var tip = btn.querySelector('.ctrl-tip');
  if(tip) tip.textContent = collapsed ? '展開功能鍵' : '收合功能鍵';
}
// 開機還原上次收合狀態(本 script 位於 body 之後·DOM 已就緒)
(function(){
  try{
    if(localStorage.getItem('lxps_ctrlbar_collapsed') === '1') _ctrlBarApplyCollapsed(true);
  }catch(_){}
})();

// ── ② 🎵/🔊 音量調整面板(拉桿 0~100·0=靜音;靜音狀態切換沿用既有 ctrlToggleBgm/ctrlToggleSfx
//      完整行為[圖示/場景 BGM 重啟/AC resume],僅音量微調時直接套用當前 BGM 元素)──
function ctrlOpenVolumePanel(kind){
  var old = document.getElementById('ctrl-vol-panel');
  if(old){
    var sameKind = (old._cvKind === kind);
    _ctrlCloseVolumePanel();
    if(sameKind) return;   // 同顆鈕再點一次 = 關閉
  }
  var pv = document.createElement('div');
  pv.id = 'ctrl-vol-panel';
  pv._cvKind = kind;
  pv.style.cssText = 'position:fixed;top:82px;right:16px;z-index:2147483647;width:300px;'
    + 'background:rgba(10,12,24,0.96);border:1.5px solid rgba(255,255,255,0.22);border-radius:14px;'
    + 'padding:16px 18px;box-shadow:0 8px 28px rgba(0,0,0,0.6);backdrop-filter:blur(8px);'
    + 'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
  var isBgm = (kind === 'bgm');
  var curPct = isBgm
    ? (_bgmMuted ? 0 : Math.round(((typeof window._bgmUserVol==='number')?window._bgmUserVol:1) * 100))
    : (_sfxMuted ? 0 : Math.round(((typeof window._sfxUserVol==='number')?window._sfxUserVol:1) * 100));
  var title = isBgm ? _cvT('🎵 音樂大小聲', '🎵 音樂音量') : _cvT('🔊 音效大小聲', '🔊 音效音量');
  pv.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">'
    + '<div style="font-size:20px;font-weight:900;color:#f0c060;">' + title + '</div>'
    + '<button onclick="_ctrlCloseVolumePanel()" style="padding:2px 10px;font-size:16px;background:rgba(60,10,10,0.4);border:1.5px solid #e84040;color:#e84040;border-radius:7px;cursor:pointer;font-family:inherit;">✕</button>'
    + '</div>'
    + '<div style="display:flex;align-items:center;gap:10px;">'
    + '<span style="font-size:18px;">🔇</span>'
    + '<input type="range" id="ctrl-vol-slider" min="0" max="100" step="5" value="' + curPct + '"'
    + ' oninput="_ctrlVolInput(\'' + kind + '\', this.value)" onchange="_ctrlVolChangeDone(\'' + kind + '\', this.value)">'
    + '<span style="font-size:18px;">🔊</span>'
    + '</div>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-top:8px;">'
    + '<div style="font-size:14px;color:#8a8a9a;">' + _cvT('拉到最左邊就沒聲音囉', '拉桿最左端 = 靜音') + '</div>'
    + '<div id="ctrl-vol-pct" style="font-size:20px;font-weight:900;color:#eee;min-width:64px;text-align:right;">' + (curPct <= 0 ? _cvT('靜音', '靜音') : (curPct + '%')) + '</div>'
    + '</div>';
  document.body.appendChild(pv);
  // 點面板外側自動關閉(下一拍才掛·避免開啟這一下立即觸發)
  setTimeout(function(){
    document.addEventListener('click', _ctrlVolOutsideClose, true);
  }, 0);
}
function _ctrlVolOutsideClose(e){
  try{
    var pv = document.getElementById('ctrl-vol-panel');
    if(!pv){ document.removeEventListener('click', _ctrlVolOutsideClose, true); return; }
    if(pv.contains(e.target)) return;
    var bgmBtn = document.getElementById('ctrl-bgm');
    var sfxBtn = document.getElementById('ctrl-sfx');
    if((bgmBtn && bgmBtn.contains(e.target)) || (sfxBtn && sfxBtn.contains(e.target))) return;
    _ctrlCloseVolumePanel();
  }catch(_){}
}
function _ctrlCloseVolumePanel(){
  var pv = document.getElementById('ctrl-vol-panel');
  if(pv) pv.remove();
  document.removeEventListener('click', _ctrlVolOutsideClose, true);
}
// 拉桿即時套用:①更新使用者音量與 BGM_VOLUME ②跨越 0 邊界時沿用既有靜音切換(完整還原/停播行為)
//   ③非邊界的音量微調直接套當前 BGM 元素(尊重暫停 50% 減量)
function _ctrlVolInput(kind, val){
  var pct = Math.max(0, Math.min(100, parseInt(val, 10) || 0));
  if(kind === 'bgm'){
    window._bgmUserVol = pct / 100;
    BGM_VOLUME = _BGM_BASE_VOLUME * window._bgmUserVol;
    var wantMuteB = (pct <= 0);
    if(wantMuteB !== _bgmMuted){
      try{ ctrlToggleBgm(); }catch(_eTb){ console.warn('[音量面板 BGM 切換]', _eTb); }
    } else if(!_bgmMuted && _curBgm){
      try{
        var el = document.getElementById(_curBgm);
        if(el) el.volume = _gamePaused ? Math.max(0, BGM_VOLUME * 0.5) : BGM_VOLUME;
      }catch(_){}
    }
    // ★ v5.37.0 需求③ — 播放中的爆發影片(戰場 _bv-overlay)/圖鑑欣賞影片 即時跟隨音樂音量
    try{
      if(typeof window._bvApplyBgmVol === 'function'){
        document.querySelectorAll('#_bv-overlay video, #hero-detail-anim-overlay video').forEach(function(_vd){
          window._bvApplyBgmVol(_vd);
        });
      }
    }catch(_eBv){}
  } else {
    window._sfxUserVol = pct / 100;
    var wantMuteS = (pct <= 0);
    if(wantMuteS !== _sfxMuted){
      try{ ctrlToggleSfx(); }catch(_eTs){ console.warn('[音量面板 SFX 切換]', _eTs); }
    }
  }
  var lbl = document.getElementById('ctrl-vol-pct');
  if(lbl) lbl.textContent = (pct <= 0) ? '靜音' : (pct + '%');
}
// 放開拉桿:音效播一聲試聽(讓孩子聽到目前大小聲);雲端 settings 持久化(3 秒冷卻防連拉狂寫,
//   最終值本就隨任何後續正常存檔週期上雲,漏存零風險)
function _ctrlVolChangeDone(kind, val){
  if(kind === 'sfx' && !_sfxMuted){
    try{ playSfx('sfx-sel', 0.7); }catch(_){}
  }
  try{
    if(window._btnCooldown && window._btnCooldown('ctrl_vol_save', 3000)){
      if(typeof gameCloudSave === 'function') gameCloudSave();
    }
  }catch(_){}
}
// 雲端 settings 載回後同步:重算 BGM_VOLUME、套用當前 BGM 元素、修正 🎵/🔊 圖示與 muted 樣式
//   (順手根治既有小缺口:載入雲端 bgmMuted/sfxMuted 後按鈕圖示原本不會同步)
function _ctrlSyncAudioUi(){
  try{
    BGM_VOLUME = _BGM_BASE_VOLUME * ((typeof window._bgmUserVol === 'number') ? window._bgmUserVol : 1);
    if(_curBgm){
      var el = document.getElementById(_curBgm);
      if(el) el.volume = _bgmMuted ? 0 : (_gamePaused ? Math.max(0, BGM_VOLUME * 0.5) : BGM_VOLUME);
    }
    var b = document.getElementById('ctrl-bgm');
    if(b && b.childNodes && b.childNodes[0] && b.childNodes[0].nodeType === 3){
      b.childNodes[0].textContent = _bgmMuted ? '🔇' : '🎵';
      b.classList.toggle('muted', _bgmMuted);
      var bt = b.querySelector('.ctrl-tip');
      if(bt) bt.textContent = _bgmMuted ? '音樂音量（已靜音）' : '音樂音量';
    }
    var s = document.getElementById('ctrl-sfx');
    if(s && s.childNodes && s.childNodes[0] && s.childNodes[0].nodeType === 3){
      s.childNodes[0].textContent = _sfxMuted ? '🔈' : '🔊';
      s.classList.toggle('muted', _sfxMuted);
      var st = s.querySelector('.ctrl-tip');
      if(st) st.textContent = _sfxMuted ? '音效音量（已靜音）' : '音效音量';
    }
  }catch(_e){ console.warn('[_ctrlSyncAudioUi]', _e); }
}
try{
  window.ctrlBarToggleCollapse = ctrlBarToggleCollapse;
  window.ctrlOpenVolumePanel = ctrlOpenVolumePanel;
  window._ctrlVolInput = _ctrlVolInput;
  window._ctrlVolChangeDone = _ctrlVolChangeDone;
  window._ctrlCloseVolumePanel = _ctrlCloseVolumePanel;
  window._ctrlSyncAudioUi = _ctrlSyncAudioUi;
}catch(_eCvW){}

function ctrlTogglePause(){
  // ════════════════════════════════════════════════════════════
  // ★ v3.5.69 — 暫停鍵升級:戰鬥中改走「暫停存檔離開」確認 modal
  //   守門條件:在冒險戰鬥中 + 至少跑過 1 回合 + 非世界 BOSS + 戰鬥未結算
  //   不符合條件 → 走原本的單純凍結畫面行為
  // ════════════════════════════════════════════════════════════
  try{
    if(_canShowPauseExitDialog()){
      // 在戰鬥中,先單純凍結畫面 + 顯示存檔離開 modal
      _doSimplePauseFreeze(true);  // true = 立刻凍結
      _showPauseExitDialog();
      return;
    }
  }catch(_e3569){ console.warn('[v3.5.69 暫停] 守門檢查例外,改走舊版凍結', _e3569); }

  // ── 舊版邏輯:單純凍結畫面(沒在冒險戰鬥中時) ──
  const overlay=document.getElementById('pause-overlay');
  const btn=document.getElementById('ctrl-pause');
  _gamePaused=!_gamePaused;
  overlay.style.display=_gamePaused?'flex':'none';
  if(btn.childNodes && btn.childNodes[0] && btn.childNodes[0].nodeType === 3){
    btn.childNodes[0].textContent = _gamePaused?'▶':'⏸';
  }else{
    // fallback:textContent + 重建 .ctrl-tip(維持向後相容)
    btn.textContent = _gamePaused?'▶':'⏸';
    const _tip = document.createElement('span');
    _tip.className = 'ctrl-tip';
    _tip.textContent = _gamePaused?'繼續遊戲':'暫停';
    btn.appendChild(_tip);
  }
  const _tipEl = btn.querySelector('.ctrl-tip');
  if(_tipEl){
    _tipEl.textContent = _gamePaused?'繼續遊戲':'暫停';
  }
  btn.classList.toggle('active',_gamePaused);

  // BGM音量：暫停降50%，恢復正常
  const bgmEl=_curBgm?document.getElementById(_curBgm):null;
  if(bgmEl){
    if(_gamePaused){
      try{ bgmEl.volume=Math.max(0,(_bgmMuted?0:BGM_VOLUME)*0.5); }catch(_){}
    } else {
      try{ bgmEl.volume=_bgmMuted?0:BGM_VOLUME; bgmEl.play().catch(()=>{}); }catch(_){}
    }
  }
  // Web Audio Context gain：暫停時降50%，恢復時還原
  // 用全域GainNode統一控制所有beep/noise音量
  if(typeof AC!=='undefined'){
    try{
      if(!window._masterGain){
        window._masterGain=AC.createGain();
        window._masterGain.connect(AC.destination);
        // 重新把beep/noise的輸出接到masterGain（透過攔截）
      }
      // ★ v3.4.22 — 用 _safeAcTime 取代 AC.currentTime,
      //   iPad Safari 偶爾回 NaN/Infinity,setTargetAtTime 拋 TypeError 雖被外層 try 吞,
      //   但持續錯誤會讓 iPad Safari 判定頁面異常並可能殺分頁(BUG 4 候選根因)
      const _safeT = (typeof _safeAcTime === 'function') ? _safeAcTime() : (AC.currentTime || 0);
      window._masterGain.gain.setTargetAtTime(_gamePaused?0.5:1.0, _safeT, 0.05);
    }catch(_){}
  }

  // Pause/resume the turn countdown timer
  if(_gamePaused){
    if(_turnTimerHandle){ clearInterval(_turnTimerHandle); _turnTimerHandle=null; _turnTimerPaused=true; }
  } else {
    // ── Resume all pending _pSetTimeout timers (critical for AI turn continuation) ──
    _resumeTimers();
    if(_turnTimerPaused && _turnTimerCount>0 && G&&G.activeChar&&G.activeChar.side==='p1'){
      _turnTimerPaused=false;
      const tc2=document.getElementById('timer-count');
      const actor2=G.activeChar;
      _turnTimerHandle=setInterval(function(){
        if(_gamePaused){ return; }
        _turnTimerCount--;
        if(tc2) tc2.textContent=_turnTimerCount;
        if(_turnTimerCount<=0){ clearTurnTimer(); if(G.activeChar===actor2&&!actor2.acted&&!G.pendingTarget) doRest(); }
      },1000);
    }
    _turnTimerPaused=false;
    // If it's AI's turn and they haven't acted yet, nudge them (safety net)
    if(G && G.activeChar && G.activeChar.side==='p2' && !G.activeChar.acted && G.activeChar.curHp>0){
      setTimeout(function(){
        if(G && G.activeChar && G.activeChar.side==='p2' && !G.activeChar.acted && G.activeChar.curHp>0 && !_gamePaused){
          aiAct(G.activeChar);
        }
      }, 600);
    }
  }
}

// ════════════════════════════════════════════════════════════════════
// ★ v3.5.69 — 暫停存檔 + 續戰預覽 + 首次教學金框（整批新函式）
//   設計理念:複用既有 _forceSaveBattleSnapshotAndSync / _advRestoreBattleState /
//   exitAdventureMode / openAdventureOverlay 四大現成 API,不重造輪子
// ════════════════════════════════════════════════════════════════════

// ── 關卡 stage code → 中文顯示名映射(用於續戰預覽) ───────────────
window._STAGE_NAME_MAP = {
  maokong:    '木柵防衛戰(貓空)',
  yushan:     '玉山攻略',
  taiwan:     '台灣 BOSS 戰',
  japan:      '日本冒險',
  taiwan_arena:'台灣鬥技場',
  worldboss:  '世界 BOSS 戰',
  vesuvius:   '火山炎龍王',
};
function _advGetStageDisplayName(stage, snap){
  try{
    // 1) 台灣 BOSS:從快照取 _advSelectedTaiwanBoss(可能存在 advStats 或 battleState)
    if(stage === 'taiwan'){
      const _twb = (snap && snap.battleState && snap.battleState.taiwanBoss)
                  || (snap && snap.taiwanBoss);
      if(_twb && typeof TAIWAN_BOSSES !== 'undefined' && TAIWAN_BOSSES[_twb]){
        return TAIWAN_BOSSES[_twb].name + '(台灣關)';
      }
    }
    // 2) 日本關:從 battleState.p2[0] 取 BOSS 名稱
    if(stage === 'japan' && snap && snap.battleState
       && Array.isArray(snap.battleState.p2) && snap.battleState.p2.length){
      const _b = snap.battleState.p2.find(h => h && h.name);
      if(_b) return _b.name + '(日本關)';
    }
    // 3) 一般關卡用映射表
    return window._STAGE_NAME_MAP[stage] || stage;
  }catch(_e){ return stage; }
}

// ── 暫停存檔守門:判斷現在能不能用「存檔離開」流程 ────────────────
// ════════════════════════════════════════════════════════════════
// ★ v3.10.10(2026-05-26) — 凍結戰鬥保護系統(取代 v3.5.69 的兩段式關閉)
//
//   設計原則:「儲存戰鬥 = 凍結時光膠囊」
//     一旦玩家按 ⏸ 存檔,從此到「打完 / 放棄」之前不能做任何事:
//     • 不能進商店買至寶
//     • 不能升級角色
//     • 不能抽式神 / 召喚英雄
//     • 不能逛圖鑑 / 看更新日誌
//     • 不能去其他關卡
//     • 不能玩世界 BOSS / 鬥技場
//   理由:升級之後又回到沒升之前的戰鬥矛盾,商店買新至寶也無法套用,
//         整個遊戲狀態必須跟戰鬥當下凍結,不然續戰會崩潰或結果不一致。
//
//   解法:
//     1. 全域旗標 _advHasPendingBattle() — 偵測快照是否存在且未處理
//     2. 主要入口(14 個函式)全部 monkey-patch 守門,有未完成戰鬥 → 攔截
//     3. 「按 ⏸ 存檔離開」改成顯示「請關閉遊戲」全螢幕鎖定頁
//     4. 「下次登入彈續戰提示」改為強制模態(無關閉按鈕、無背景退出)
//     5. 關卡頁加紅色橫幅 + 紅色「放棄未完成戰鬥」按鈕
// ════════════════════════════════════════════════════════════════

// 偵測:是否有未完成戰鬥快照?(只看本機 localStorage)
window._advHasPendingBattle = function(){
  try{
    // 玩家正在打世界 BOSS → 雖然不能存暫停,但避免守門誤觸發
    if(window._wbInWorldBossMode || window._wbConnectedClientMode
       || window._wbConnectedHostMode || window._wbSoloPracticeMode) return false;
    // 玩家正在冒險戰鬥中(同一場戰鬥的快照不算「未處理」)
    if(typeof _adventureMode !== 'undefined' && _adventureMode
       && typeof _advBattleResultShown !== 'undefined' && !_advBattleResultShown){
      // 進行中的戰鬥本身就是「處理中」狀態,不算 pending
      return false;
    }
    let raw = localStorage.getItem('adv_battle_snap');
    if(!raw) raw = localStorage.getItem('adv_crash_snapshot');
    if(!raw) return false;
    const snap = JSON.parse(raw);
    if(!snap || !snap.stage) return false;
    // 24 小時內才算有效
    if(Date.now() - (snap.ts || 0) > 24*60*60*1000) return false;
    // 世界 BOSS 快照不參與凍結(連線層無法續戰,走別的引導路徑)
    if(snap.stage === 'worldboss') return false;
    // 必須有真實戰鬥資料(過濾掉雲端 fallback 殘留)
    const _bs = snap.battleState;
    const _p1 = (_bs && _bs.p1) || snap.p1;
    const _p2 = (_bs && _bs.p2) || snap.p2;
    if(!_p1 || !_p1.length || !_p2 || !_p2.length) return false;
    if(((snap.round) || (_bs && _bs.round) || 0) < 1) return false;
    return true;
  }catch(_e){
    console.warn('[v3.10.10 _advHasPendingBattle] 例外', _e);
    return false;
  }
};

// 顯示「請先處理未完成戰鬥」攔截彈窗(玩家試圖進入其他入口時觸發)
window._showPendingBattleBlocker = function(intentName){
  // 防重複
  if(document.getElementById('_pending-battle-blocker')) return;
  const ov = document.createElement('div');
  ov.id = '_pending-battle-blocker';
  ov.style.cssText = 'position:fixed;inset:0;z-index:99000;background:rgba(0,0,8,0.88);'
    + 'display:flex;align-items:center;justify-content:center;padding:20px;'
    + 'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
  const _intent = intentName ? '【' + intentName + '】' : '其他功能';
  ov.innerHTML =
    '<div style="background:linear-gradient(160deg,rgba(50,15,15,0.99),rgba(30,8,8,0.99));'
    + 'border:3px solid #ff8844;border-radius:20px;padding:32px 36px;'
    + 'max-width:min(94vw,560px);text-align:center;'
    + 'box-shadow:0 0 60px rgba(255,140,60,0.45);">'
    + '<div style="font-size:60px;margin-bottom:10px;">⚠️</div>'
    + '<div style="font-size:26px;font-weight:900;color:#ffaa66;margin-bottom:16px;letter-spacing:2px;">'
    + '請先處理未完成戰鬥</div>'
    + '<div style="font-size:18px;color:#ffdcc8;line-height:1.85;margin-bottom:22px;text-align:left;">'
    + '你有一場暫停中的戰鬥還沒打完。<br><br>'
    + '在處理之前,<b style="color:#ffcc44;">無法</b>使用 ' + _intent + ',因為:<br>'
    + '&nbsp;&nbsp;• 中途升級會導致戰鬥前後不一致<br>'
    + '&nbsp;&nbsp;• 新買的至寶無法套用到凍結中的戰鬥<br>'
    + '&nbsp;&nbsp;• 抽到的新角色也無法加入隊伍<br><br>'
    + '請先選擇:<b style="color:#88ffaa;">繼續打完</b>,或 <b style="color:#ff8866;">放棄這場</b>。'
    + '</div>'
    + '<button id="_pbb_go_btn" style="padding:14px 36px;font-size:20px;font-weight:900;'
    + 'background:linear-gradient(135deg,rgba(255,200,40,0.45),rgba(220,150,20,0.55));'
    + 'border:2.5px solid #ffcc44;color:#fff5cc;border-radius:14px;cursor:pointer;'
    + 'font-family:inherit;letter-spacing:1.5px;box-shadow:0 4px 18px rgba(255,180,40,0.4);">'
    + '⚔ 立刻處理</button>'
    + '<button id="_pbb_close_btn" style="padding:12px 24px;font-size:16px;margin-left:10px;'
    + 'background:rgba(60,30,30,0.5);border:1.5px solid #aa6655;color:#ccaa99;'
    + 'border-radius:10px;cursor:pointer;font-family:inherit;">關閉</button>'
    + '</div>';
  document.body.appendChild(ov);
  document.getElementById('_pbb_go_btn').onclick = function(){
    try{ if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.55); }catch(_){}
    ov.remove();
    // 強制進關卡頁觸發續戰彈窗
    try{ if(typeof openAdventureOverlay === 'function') openAdventureOverlay.call(window, true); }catch(_){}
  };
  document.getElementById('_pbb_close_btn').onclick = function(){ ov.remove(); };
};

// monkey-patch 守門:對 14 個主要入口包一層,有未完成戰鬥就攔截
// (這裡用 IIFE 確保 patch 只跑一次)
(function _installPendingBattleGate(){
  if(window._advPendingBattleGateInstalled) return;
  const _gatedFns = [
    {name:'openShopOverlay',         label:'商店'},
    {name:'openSummonOverlay',       label:'召喚'},
    {name:'openHeroPage',            label:'英雄圖鑑/升級'},
    {name:'openTaiwanTreasurePage',  label:'台灣至寶'},
    {name:'openMonsterPage',         label:'妖怪圖鑑'},
    {name:'openPetPage',             label:'寵物圖鑑'},
    {name:'openFriendPanel',         label:'好友面板'},
    {name:'openBackpackOverlay',     label:'背包'},
    {name:'openMedalPage',           label:'獎章'},
    {name:'openChangelogPanel',      label:'更新日誌'},
    {name:'openPresetTeamPanel',     label:'預設陣容'},
    {name:'openPresetEditorPanel',   label:'預設陣容編輯'},
    {name:'openSetRepHeroModal',     label:'代表英雄設定'},
    {name:'openNicknameModal',       label:'暱稱設定'},
    {name:'openSavePresetPanel',     label:'儲存陣容'}
  ];
  // 延遲 800ms 等所有 function 都載入到 window
  // (有些 function 是 hoisted declaration,有些是後段才掛到 window)
  setTimeout(function(){
    _gatedFns.forEach(function(item){
      const orig = window[item.name];
      if(typeof orig !== 'function'){
        console.warn('[v3.10.10 gate] 找不到 ' + item.name + ',跳過');
        return;
      }
      window[item.name] = function(){
        // 守門:有未完成戰鬥 → 攔截
        if(window._advHasPendingBattle && window._advHasPendingBattle()){
          console.log('[v3.10.10 gate] 攔截 ' + item.name + ' — 有未完成戰鬥');
          window._showPendingBattleBlocker(item.label);
          return;
        }
        return orig.apply(this, arguments);
      };
      // 標記已 patch
      window[item.name]._gatedByPendingBattle = true;
    });
    window._advPendingBattleGateInstalled = true;
    console.log('[v3.10.10] ✅ 未完成戰鬥守門已安裝(共 ' + _gatedFns.length + ' 個入口)');
  }, 800);
})();

function _canShowPauseExitDialog(){
  try{
    // ★ v3.13.33(2026-06-04) — 鬥技場按暫停也允許 modal
    // ★ v3.13.38(2026-06-04) — 老師回報:台灣關卡的暫停變成鬥技場「投降並退出」modal
    //   根因:原本用 !_adventureMode 當鬥技場判定,但如果 _adventureMode 因 race 變 falsy,
    //         還在台灣關卡的玩家會被誤判為鬥技場,顯示錯誤 modal
    //   修補:改用 _adventureStage 為準
    //     - 有 _adventureStage(木柵/日本/台灣/貓空)→ 一律冒險版 modal(存檔/離開)
    //     - 沒 _adventureStage 但 G.p1/p2 有英雄 → 鬥技場版 modal(投降並退出)
    //   _adventureMode 只當輔助參考,不再當主要判定(避免 race 誤判)
    if(typeof G === 'undefined' || !G) return false;
    if(!Array.isArray(G.p1) || !Array.isArray(G.p2)) return false;
    if(!(G.round >= 1)) return false;
    // 排除世界 BOSS(任何 wb 變體都不允許)
    if(window._wbInWorldBossMode) return false;
    if(window._wbConnectedClientMode) return false;
    if(window._wbConnectedHostMode) return false;
    if(window._wbSoloPracticeMode) return false;
    // 結算面板已顯示
    if(window._advBattleResultShown) return false;
    if(G._arenaResultShown) return false;
    // 以 _adventureStage 為主要判定:
    const _hasStage = (typeof _adventureStage !== 'undefined' && _adventureStage);
    if(_hasStage) return true;   // 冒險模式(木柵/日本/台灣/貓空)
    // 沒 stage → 鬥技場(必須 G.p1/p2 都有英雄才算戰鬥中)
    if(G.p1.length > 0 && G.p2.length > 0) return true;
    return false;
  }catch(_e){ return false; }
}

// ── 立即凍結遊戲(複用既有 _gamePaused 模式) ───────────────────────
function _doSimplePauseFreeze(forcePause){
  try{
    if(forcePause){ _gamePaused = true; }
    else { _gamePaused = false; }
    // 暫停回合計時器
    if(_gamePaused){
      if(_turnTimerHandle){ clearInterval(_turnTimerHandle); _turnTimerHandle=null; _turnTimerPaused=true; }
    }
    // BGM 降音
    const bgmEl=_curBgm?document.getElementById(_curBgm):null;
    if(bgmEl){
      try{
        if(_gamePaused){ bgmEl.volume=Math.max(0,(_bgmMuted?0:BGM_VOLUME)*0.5); }
        else { bgmEl.volume=_bgmMuted?0:BGM_VOLUME; bgmEl.play().catch(()=>{}); }
      }catch(_){}
    }
    // 更新 ⏸ 按鈕視覺
    const btn = document.getElementById('ctrl-pause');
    if(btn){
      if(btn.childNodes && btn.childNodes[0] && btn.childNodes[0].nodeType === 3){
        btn.childNodes[0].textContent = _gamePaused ? '▶' : '⏸';
      }
      const _tip = btn.querySelector('.ctrl-tip');
      if(_tip) _tip.textContent = _gamePaused ? '繼續遊戲' : '暫停';
      btn.classList.toggle('active', _gamePaused);
    }
  }catch(_e){ console.warn('[v3.5.69 _doSimplePauseFreeze] 例外', _e); }
}

// ── 暫停存檔離開確認 modal ─────────────────────────────────────────
function _showPauseExitDialog(){
  // 防重複開啟
  if(document.getElementById('_pause_exit_modal')) return;

  const modal = document.createElement('div');
  modal.id = '_pause_exit_modal';
  const _round = (typeof G !== 'undefined' && G && G.round) || 1;
  // ★ v3.13.33(2026-06-04) — 鬥技場按暫停也出現 modal,但顯示「投降並退出」流程
  // ★ v3.13.38(2026-06-04) — 老師回報:台灣關卡按暫停變成鬥技場 modal
  //   修補:用 _adventureStage 判定,而非 _adventureMode(後者在 race 下可能 falsy)
  //         - 有 _adventureStage → 冒險版 modal(任何冒險關卡都走這條)
  //         - 沒 _adventureStage → 鬥技場版 modal
  const _hasAdvStage = (typeof _adventureStage !== 'undefined' && _adventureStage);
  const _isArenaCtx = !_hasAdvStage;

  let _stageDisplayName;
  try{
    _stageDisplayName = _isArenaCtx ? '鬥技場 單人挑戰' :
      _advGetStageDisplayName(_adventureStage, {
        battleState: { p2: G.p2, taiwanBoss: window._advSelectedTaiwanBoss }
      });
  }catch(_eStageName){ _stageDisplayName = _isArenaCtx ? '鬥技場' : '冒險'; }

  if(_isArenaCtx){
    // ── 鬥技場版 modal ─────────────────────────────────────────────
    modal.innerHTML =
      '<div class="_pem-card">'+
        '<div class="_pem-icon">⏸</div>'+
        '<div class="_pem-title">暫停戰鬥</div>'+
        '<div class="_pem-sub">'+
          '目前在 <b style="color:#ffcc66">'+_stageDisplayName+'</b><br>'+
          '第 <b style="color:#ffcc66">'+_round+'</b> 回合<br><br>'+
          '⚔ 鬥技場是一場制戰鬥,不需要存檔。<br>'+
          '可以選擇繼續戰鬥,或投降退出(記為敗場,至少要打 5 回合才能投降)'+
        '</div>'+
        '<button id="_pem_btn_arena_surrender" class="_pem-btn primary">'+
          '🏳 投降並退出'+
        '</button>'+
        '<button id="_pem_btn_resume" class="_pem-btn cancel">'+
          '▶ 繼續戰鬥'+
        '</button>'+
      '</div>';
    document.body.appendChild(modal);

    document.getElementById('_pem_btn_arena_surrender').onclick = function(){
      try{ if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.5); }catch(_){}
      // 關掉 modal + 解暫停,把控制權交給既有投降流程(走 ctrlSurrender → 投降確認 → doSurrender)
      const m = document.getElementById('_pause_exit_modal');
      if(m) m.remove();
      try{ _doSimplePauseFreeze(false); }catch(_){}
      try{
        if(typeof ctrlSurrender === 'function'){ ctrlSurrender(); }
        else if(typeof window.ctrlSurrender === 'function'){ window.ctrlSurrender(); }
      }catch(_eSur){ console.warn('[v3.13.33 鬥技場暫停投降] 觸發 ctrlSurrender 失敗', _eSur); }
    };
    document.getElementById('_pem_btn_resume').onclick = function(){
      try{ if(typeof playSfx === 'function') playSfx('sfx-cancel', 0.4); }catch(_){}
      _pauseExitDoResume();
    };
    console.log('[v3.13.33 鬥技場暫停] modal 已顯示, round=' + _round);
    return;
  }

  // ── 冒險版 modal(原本邏輯) ──────────────────────────────────────
  modal.innerHTML =
    '<div class="_pem-card">'+
      '<div class="_pem-icon">⏸</div>'+
      '<div class="_pem-title">暫停戰鬥</div>'+
      '<div class="_pem-sub">'+
        '目前在 <b style="color:#ffcc66">'+_stageDisplayName+'</b><br>'+
        '第 <b style="color:#ffcc66">'+_round+'</b> 回合<br><br>'+
        '可以選擇主動存檔上傳到雲端,<br>下次登入就能從這個回合繼續打 ⚔️'+
      '</div>'+
      '<button id="_pem_btn_save_exit" class="_pem-btn primary">'+
        '☁️ 存檔並關閉遊戲'+
      '</button>'+
      '<button id="_pem_btn_save_only" class="_pem-btn secondary">'+
        '💾 只存檔,繼續玩'+
      '</button>'+
      '<button id="_pem_btn_resume" class="_pem-btn cancel">'+
        '▶ 繼續戰鬥(不存檔)'+
      '</button>'+
    '</div>';

  document.body.appendChild(modal);

  document.getElementById('_pem_btn_save_exit').onclick = function(){
    try{ if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.5); }catch(_){}
    _pauseExitDoSaveAndExit();
  };
  document.getElementById('_pem_btn_save_only').onclick = function(){
    try{ if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.4); }catch(_){}
    _pauseExitDoSaveOnly();
  };
  document.getElementById('_pem_btn_resume').onclick = function(){
    try{ if(typeof playSfx === 'function') playSfx('sfx-cancel', 0.4); }catch(_){}
    _pauseExitDoResume();
  };

  console.log('[v3.5.69] 暫停存檔離開 modal 已顯示, stage=' + _adventureStage + ', round=' + _round);
}

// ── 暫停存檔離開 modal:三個動作 ────────────────────────────────────
async function _pauseExitDoSaveAndExit(){
  const modal = document.getElementById('_pause_exit_modal');
  // 換成 loading 狀態
  if(modal){
    const _card = modal.querySelector('._pem-card');
    if(_card){
      _card.innerHTML =
        '<div class="_pem-icon">☁️</div>'+
        '<div class="_pem-title">正在存檔...</div>'+
        '<div class="_pem-sub">把進度上傳到雲端,請稍候 ⏳</div>';
    }
  }
  try{
    // 1. 強制存快照 + 同步雲端
    let _saveOk = false;
    try{
      if(typeof window._forceSaveBattleSnapshotAndSync === 'function'){
        _saveOk = window._forceSaveBattleSnapshotAndSync('manual_pause_exit');
      }
    }catch(_e1){ console.warn('[v3.5.69 暫停存檔] _forceSave 失敗', _e1); }
    console.log('[v3.5.69 暫停存檔] _forceSave 結果=' + _saveOk);

    // 2. 確認雲端寫入完成(等 gameCloudSave)
    try{
      if(typeof gameCloudSave === 'function'){
        try{ window._lxpsCloudSaveForceNext = true; }catch(_){}  // ★ v4.47.0 任務B — 玩家主動存檔離開,直通節流立即寫(不等尾端補寫)
        await gameCloudSave().catch(function(e){
          console.warn('[v3.5.69 暫停存檔] gameCloudSave 失敗', e);
        });
      }
    }catch(_e2){ console.warn('[v3.5.69 暫停存檔] gameCloudSave 例外', _e2); }

    // 3. 移除 modal,進入「乾淨退出戰鬥回關卡頁」流程
    if(modal) modal.remove();
    _gamePaused = false;  // 解除暫停,讓 exitAdventureMode 能正常跑
    _exitToStageAfterSave();
  }catch(eMain){
    console.error('[v3.5.69 暫停存檔] 主流程異常', eMain);
    if(modal) modal.remove();
    _gamePaused = false;
    if(typeof _showInGameToast === 'function'){
      _showInGameToast('⚠ 存檔時發生錯誤,請重新整理', '#ff4444', 3000);
    }
  }
}

async function _pauseExitDoSaveOnly(){
  const modal = document.getElementById('_pause_exit_modal');
  if(modal){
    const _card = modal.querySelector('._pem-card');
    if(_card){
      _card.innerHTML =
        '<div class="_pem-icon">💾</div>'+
        '<div class="_pem-title">正在存檔...</div>'+
        '<div class="_pem-sub">把進度上傳到雲端,請稍候 ⏳</div>';
    }
  }
  try{
    let _saveOk = false;
    try{
      if(typeof window._forceSaveBattleSnapshotAndSync === 'function'){
        _saveOk = window._forceSaveBattleSnapshotAndSync('manual_pause_save_only');
      }
    }catch(_e){ console.warn('[v3.5.69 只存檔] _forceSave 失敗', _e); }
    try{
      if(typeof gameCloudSave === 'function'){
        try{ window._lxpsCloudSaveForceNext = true; }catch(_){}  // ★ v4.47.0 任務B — 玩家主動只存檔,直通節流立即寫
        await gameCloudSave().catch(function(e){});
      }
    }catch(_e){}
    if(modal) modal.remove();
    // 解除暫停,繼續戰鬥
    _pauseExitDoResume(true);  // true = 不再顯示 modal
    // 顯示一個簡短 toast
    if(typeof _showInGameToast === 'function'){
      _showInGameToast('☁️ 已存檔!可以放心繼續戰鬥', '#44ff88', 2500);
    }
    console.log('[v3.5.69 只存檔] 完成, _saveOk=' + _saveOk);
  }catch(e){
    console.error('[v3.5.69 只存檔] 異常', e);
    if(modal) modal.remove();
    _gamePaused = false;
  }
}

function _pauseExitDoResume(skipModalRemove){
  if(!skipModalRemove){
    const modal = document.getElementById('_pause_exit_modal');
    if(modal) modal.remove();
  }
  // 解除凍結(複用 _doSimplePauseFreeze(false) 的邏輯,但要走原本的 ctrlTogglePause 解凍)
  try{
    _gamePaused = false;
    // 恢復 BGM 音量
    const bgmEl=_curBgm?document.getElementById(_curBgm):null;
    if(bgmEl){
      try{ bgmEl.volume=_bgmMuted?0:BGM_VOLUME; bgmEl.play().catch(()=>{}); }catch(_){}
    }
    // 恢復 timers
    try{ if(typeof _resumeTimers === 'function') _resumeTimers(); }catch(_){}
    // 更新 ⏸ 按鈕
    const btn = document.getElementById('ctrl-pause');
    if(btn){
      if(btn.childNodes && btn.childNodes[0] && btn.childNodes[0].nodeType === 3){
        btn.childNodes[0].textContent = '⏸';
      }
      const _tip = btn.querySelector('.ctrl-tip');
      if(_tip) _tip.textContent = '暫停';
      btn.classList.remove('active');
    }
    // 若 AI 回合卡住,nudge 一下
    if(G && G.activeChar && G.activeChar.side==='p2' && !G.activeChar.acted && G.activeChar.curHp>0){
      setTimeout(function(){
        if(G && G.activeChar && G.activeChar.side==='p2' && !G.activeChar.acted
           && G.activeChar.curHp>0 && !_gamePaused){
          aiAct(G.activeChar);
        }
      }, 600);
    }
  }catch(_e){ console.warn('[v3.5.69 _pauseExitDoResume] 例外', _e); }
}

// ── 「存檔離開」第二段:乾淨退出戰鬥回關卡頁 + 金色 toast ──────────
// ★ v3.10.10(2026-05-26) — 改為「請關閉遊戲」全螢幕鎖定頁,玩家硬關 app 或選放棄
//   v3.5.69 舊版會開關卡頁 + 彈金色 toast → 老師反映「很怪」(剛存又問要不要繼續)
//   現在的設計:存檔成功 = 玩家被鎖在「請關閉遊戲」頁,無路可走除非放棄戰鬥
function _exitToStageAfterSave(){
  try{
    // 1. 用既有的 exitAdventureMode 做完整清理(_adventureMode/_advMiniBattleActive/各種 overlay/BGM/背景等)
    try{
      if(typeof exitAdventureMode === 'function') exitAdventureMode();
    }catch(eExit){ console.error('[v3.10.10 _exitToStage] exitAdventureMode 失敗', eExit); }

    // 2. 隱藏戰鬥中相關元素(避免黑畫面殘留)
    try{
      const gc = document.getElementById('gc');
      if(gc){
        gc.classList.remove('adv-battle');
        gc.style.filter = '';
      }
      const _enemyN = document.getElementById('enemy-turn-notice');
      if(_enemyN) _enemyN.style.display = 'none';
      const _itemP = document.getElementById('item-panel');
      if(_itemP) _itemP.style.display = 'none';
      ['adv-rollback-btn','adv-tut-btn','adv-deadlock-rescue-btn','adv-bug-report-battle-btn']
        .forEach(id => {
          const _b = document.getElementById(id);
          if(_b) _b.style.display = 'none';
        });
    }catch(eUI){ console.error('[v3.10.10 _exitToStage] UI 隱藏失敗', eUI); }

    // 3. ★ v3.10.10 — 不開關卡頁,改顯示鎖定頁
    _showCloseGameLockOverlay();

    console.log('[v3.10.10 _exitToStage] 已退出戰鬥,顯示鎖定頁(玩家須手動關閉或放棄)');
  }catch(eMain){
    console.error('[v3.10.10 _exitToStage] 主流程異常', eMain);
  }
}

