// ── 金色「進度已上傳雲端」toast(8 秒) ──────────────────────────────
function _showSaveDoneToast(){
  // 移除舊的(避免重複)
  const _old = document.getElementById('_save_done_toast');
  if(_old) _old.remove();

  const toast = document.createElement('div');
  toast.id = '_save_done_toast';
  toast.innerHTML =
    '<div class="_sdt-emoji">🌙</div>'+
    '<div class="_sdt-title">✅ 進度已上傳雲端!</div>'+
    '<div class="_sdt-sub">'+
      '可以安心關掉遊戲了<br>'+
      '<span style="font-size:15px;color:#ddc090;">下次登入會問你要不要繼續這場戰鬥</span>'+
    '</div>';
  document.body.appendChild(toast);

  // 8 秒後淡出
  setTimeout(function(){
    if(toast && toast.parentNode){
      toast.style.transition = 'opacity 0.8s ease-out, transform 0.8s ease-out';
      toast.style.opacity = '0';
      toast.style.transform = 'translate(-50%,-50%) scale(0.9)';
      setTimeout(function(){
        if(toast && toast.parentNode) toast.remove();
      }, 850);
    }
  }, 8000);

  // 點擊背景也可關閉
  toast.addEventListener('click', function(){
    toast.style.transition = 'opacity 0.3s';
    toast.style.opacity = '0';
    setTimeout(function(){
      if(toast && toast.parentNode) toast.remove();
    }, 350);
  });
}

// ── 渲染續戰預覽卡片(隊伍 + HP) ────────────────────────────────────
function _crvRenderHeroRow(h, side, currentLv){
  // side: 'enemy' 或 'ally'
  if(!h || !h.name) return '';
  const _curHp = (typeof h.curHp === 'number') ? h.curHp : 0;
  const _maxHp = (typeof h.hp === 'number' && h.hp > 0) ? h.hp : 1;
  const _pct = Math.max(0, Math.min(100, Math.round(_curHp / _maxHp * 100)));
  let _hpClass = 'full';
  if(_pct === 0) _hpClass = 'dead';
  else if(_pct >= 100) _hpClass = 'full';
  else if(_pct >= 50)  _hpClass = 'high';
  else if(_pct >= 25)  _hpClass = 'mid';
  else                 _hpClass = 'low';
  const _statusIcon = (_pct === 0) ? '<span class="_crv-status-icon" title="倒下">💀</span>'
                    : (_pct === 100) ? '<span class="_crv-status-icon" title="滿血">✨</span>'
                    : (_pct < 25) ? '<span class="_crv-status-icon" title="危險">⚠️</span>'
                    : '';
  const _img = (typeof HERO_IMGS !== 'undefined' && HERO_IMGS[h.name])
              || (typeof AVATARS !== 'undefined' && AVATARS[h.name])
              || '';
  const _imgTag = _img && _img.startsWith('http')
                ? '<img class="_crv-hero-img" src="'+_img+'" alt="'+h.name+'" onerror="this.style.display=\'none\'">'
                : '<div class="_crv-hero-img" style="display:flex;align-items:center;justify-content:center;font-size:24px;">'+(_img || '👤')+'</div>';
  const _lvLabel = (side === 'ally' && currentLv) ? '<span class="lv">Lv'+currentLv+'</span>' : '';
  const _deadClass = (_pct === 0) ? ' dead' : '';
  return '<div class="_crv-hero-row '+side+_deadClass+'">'+
    _imgTag+
    '<div class="_crv-hero-info">'+
      '<div class="_crv-hero-name">'+_escapeHtml(h.name)+_lvLabel+'</div>'+
      '<div class="_crv-hp-bar">'+
        '<div class="_crv-hp-fill '+_hpClass+'" style="width:'+_pct+'%"></div>'+
        '<div class="_crv-hp-text">'+_curHp.toLocaleString()+' / '+_maxHp.toLocaleString()+' ('+_pct+'%)</div>'+
      '</div>'+
    '</div>'+
    _statusIcon+
  '</div>';
}
function _escapeHtml(s){
  return String(s == null ? '' : s).replace(/[<>&"']/g, function(c){
    return { '<':'&lt;', '>':'&gt;', '&':'&amp;', '"':'&quot;', "'":'&#39;' }[c];
  });
}

// ── 讀取畫面:正在恢復戰鬥進度 ─────────────────────────────────────
function _advShowResumeLoadingOverlay(){
  // 防重複
  const _old = document.getElementById('_adv_resume_loading');
  if(_old) _old.remove();

  const ov = document.createElement('div');
  ov.id = '_adv_resume_loading';
  ov.innerHTML =
    '<div class="_arl-ring"></div>'+
    '<div class="_arl-title">⚔ 正在恢復戰鬥進度</div>'+
    '<div class="_arl-sub">整理隊伍、清點戰場、準備繼續戰鬥...</div>'+
    '<div class="_arl-bar-wrap"><div class="_arl-bar-fill" id="_arl_fill"></div></div>';
  document.body.appendChild(ov);

  // 進度條動畫:0% → 100% in 1.5s
  setTimeout(function(){
    const _fill = document.getElementById('_arl_fill');
    if(_fill) _fill.style.width = '100%';
  }, 50);
}
function _advHideResumeLoadingOverlay(){
  const ov = document.getElementById('_adv_resume_loading');
  if(ov){
    ov.style.transition = 'opacity 0.4s ease-out';
    ov.style.opacity = '0';
    setTimeout(function(){
      if(ov && ov.parentNode) ov.remove();
    }, 420);
  }
}

// ── 「徹底放棄快照」清理流程(複用卡死自救脫離戰鬥的清理路徑) ─────
async function _advDiscardSnapshotAndExit(){
  console.log('[v3.5.69 放棄快照] 開始徹底清理流程');
  try{
    // ════════════════════════════════════════════════════════════════════
    // ★ v3.11.36(2026-05-29) — 修「放棄後又被雲端寫回」BUG
    //   災情:BUG #3「不讓我繼續玩下一關」,玩家放棄快照後 13 秒,_fbLoad 又拉一次雲端,
    //         由於 Firestore 寫入有 latency(eventual consistency),
    //         拉到的可能是舊資料(advSnapshot 還在)→ _applySafeData 把它寫回
    //         localStorage.adv_battle_snap → _advHasPendingBattle() 又回 true
    //         → 玩家點任何關卡入口都被 _showPendingBattleBlocker 擋住。
    //   修法:設一個全域旗標 _advRecentlyDiscarded(時間戳),_applySafeData 套用
    //         advSnapshot 前檢查:30 秒內剛放棄過 → 跳過寫回,並主動清雲端。
    // ════════════════════════════════════════════════════════════════════
    window._advRecentlyDiscarded = Date.now();
    console.log('[v3.11.36] 設定 _advRecentlyDiscarded 旗標,30 秒內 _applySafeData 不會寫回 advSnapshot');

    // 1. 清 localStorage 快照
    try{ localStorage.removeItem('adv_battle_snap'); }catch(_){}
    try{ localStorage.removeItem('adv_crash_snapshot'); }catch(_){}

    // 2. 標記戰鬥已結束(防止後續觸發續戰 / 快照寫入)
    try{ window._advBattleResultShown = true; }catch(_){}

    // 3. 清各種戰鬥旗標
    try{
      if(typeof _adventureMode !== 'undefined') _adventureMode = false;
      if(typeof _adventureStage !== 'undefined') _adventureStage = null;
      if(typeof _advMiniBattleActive !== 'undefined') _advMiniBattleActive = false;
      if(typeof window._advMiniResultShowing !== 'undefined') window._advMiniResultShowing = false;
      if(typeof _advQuizActive !== 'undefined'){ _advQuizActive = false; _advQuizPhase = 'idle'; }
      if(typeof _advQuizResolveCb !== 'undefined') _advQuizResolveCb = null;
      if(typeof _gamePaused !== 'undefined') _gamePaused = false;
      try{ if(typeof _advQuizTimer !== 'undefined' && _advQuizTimer){ clearInterval(_advQuizTimer); _advQuizTimer = null; } }catch(_){}
      try{ if(typeof clearTurnTimer === 'function') clearTurnTimer(); }catch(_){}
      try{ if(typeof _clearPendingTimers === 'function') _clearPendingTimers('放棄快照'); }catch(_){}
    }catch(_e){}

    // 4. 清 G 戰鬥狀態
    try{
      if(typeof G !== 'undefined' && G){
        G.p1 = [];
        G.p2 = [];
        G.activeChar = null;
        G.fieldCards = [];
        G.energy = { p1:0, p2:0 };
        G.inv = [];
        G.inv2 = [];
        G.round = 0;
        G._resultShown = false;
        G.pendingTarget = null;
        G.taunted = null;
        G.guardFor = null;
        G.passiveInterruptUsed = false;
        G.interruptTarget = null;
        G.waitFor = null;
        G.lastSkillName = null;
        G.lastSkillByHero = {};
        G.comboFatigue = 0;
        G.comboFatigueByHero = {};
      }
      if(typeof fieldCards !== 'undefined') fieldCards = [];
    }catch(_e){}

    // 5. 關閉所有戰鬥/續戰相關 overlay(複用卡死自救的清單)
    const _overlayIds = [
      'adv-quiz-overlay','adv-reward-overlay','adv-cutscene-overlay',
      'adv-dialog-box','burst-priority-modal','adv-boss-intro',
      'taiwan-cutscene-overlay','taiwan-dialog-overlay','taiwan-difficulty-overlay',
      'adv-boss-detail-pop','active-passive-modal','burst-confirm-modal',
      'burst-target-pick','pause-overlay','tutorial-overlay','discard-overlay',
      'dice-overlay','tarot-choice-overlay','charm-ov','mimic-ov',
      'immovable-prompt','custom-confirm-overlay','_deadlock-rescue-menu',
      'battle-start-overlay','adv-jp-diff-modal','adv-skip-select-box',
      'adv-quiz-overlay','adv-continue-overlay','adv-result-overlay',
      'adv-mini-result','adv-treasure-confirm','adv-treasure-popup',
      'passive-prompt','passive-prompt-countdown',
      '_rollback-menu','rollback-reinforce-ov',
      'bag-hero-select','bag-skill-select',
      'alchemist-prompt','auto-confirm-ov',
      'burst-mimic-confirm','burst-mimic-ov','burst-equip-ov','burst-panel',
      '_tut-prompt','_ti-dim-overlay','_tut-dim',
      'action-confirm-bar','fc-detail-pop','_heal-warn-pop','_ts_popup',
      'adv-repick-popup','enemy-info-popup','elem-popup',
      'burst-upgrade-confirm-box','invest-confirm-box','upgrade-confirm-box',
      'adv-crash-recovery-box','_crv_discard_confirm',
      // ★ v3.10.10 — 凍結戰鬥保護系統相關 overlay
      '_close-game-lock','_pending-battle-banner','_pending-battle-blocker',
    ];
    _overlayIds.forEach(function(id){
      try{
        const el = document.getElementById(id);
        if(!el) return;
        if(el.classList) el.classList.remove('show');
        el.style.display = 'none';
        // 動態元素直接 remove
        if(id === '_tut-prompt' || id === '_tut-dim' || id === 'adv-crash-recovery-box'
           || id === '_crv_discard_confirm' || id === '_deadlock-rescue-menu'
           || id === '_rollback-menu'
           || id === '_close-game-lock' || id === '_pending-battle-banner'
           || id === '_pending-battle-blocker'){
          if(typeof el.remove === 'function') el.remove();
        }
      }catch(_){}
    });

    // 6. gc 容器恢復(不要 display:none,否則 adventure-overlay 看不到)
    try{
      const gc = document.getElementById('gc');
      if(gc){
        gc.classList.remove('adv-battle');
        gc.style.filter = '';
      }
      const _enemyN = document.getElementById('enemy-turn-notice');
      if(_enemyN) _enemyN.style.display = 'none';
      const _itemP = document.getElementById('item-panel');
      if(_itemP) _itemP.style.display = 'none';
      ['adv-rollback-btn','adv-tut-btn','adv-deadlock-rescue-btn',
       'adv-bug-report-battle-btn','adv-pause-btn'].forEach(function(id){
        const _b = document.getElementById(id);
        if(_b) _b.style.display = 'none';
      });
    }catch(_e){}

    // 7. exitAdventureMode 做完整清理
    try{
      if(typeof exitAdventureMode === 'function') exitAdventureMode();
    }catch(_e){ console.warn('[v3.5.69 放棄快照] exitAdventureMode 例外', _e); }

    // 8. 寫雲端(把空狀態同步上去,清掉雲端 advSnapshot)
    try{
      if(typeof gameCloudSave === 'function'){
        await gameCloudSave().catch(function(e){
          console.warn('[v3.5.69 放棄快照] gameCloudSave 失敗', e);
        });
      }
    }catch(_e){}

    // ★ v3.11.36(2026-05-29) — 雙重保險:Firestore eventual consistency,
    //   3 秒 + 10 秒後再各寫一次,並再清一次 localStorage(防 _fbLoad 寫回殘留)
    //   配合 _advRecentlyDiscarded 30 秒旗標,確保「放棄」後雲端是真正乾淨的狀態。
    try{
      setTimeout(function(){
        try{ localStorage.removeItem('adv_battle_snap'); }catch(_){}
        try{ localStorage.removeItem('adv_crash_snapshot'); }catch(_){}
        try{
          if(typeof gameCloudSave === 'function'){
            gameCloudSave().catch(function(e){
              console.warn('[v3.11.36 放棄快照 retry 3s] gameCloudSave 失敗', e);
            });
          }
        }catch(_){}
      }, 3000);
      setTimeout(function(){
        try{ localStorage.removeItem('adv_battle_snap'); }catch(_){}
        try{ localStorage.removeItem('adv_crash_snapshot'); }catch(_){}
        try{
          if(typeof gameCloudSave === 'function'){
            gameCloudSave().catch(function(e){
              console.warn('[v3.11.36 放棄快照 retry 10s] gameCloudSave 失敗', e);
            });
          }
        }catch(_){}
      }, 10000);
    }catch(_eRetry){ console.warn('[v3.11.36 放棄快照 retry setup] 例外', _eRetry); }

    // 9. 開啟關卡選擇頁
    try{
      if(typeof openAdventureOverlay === 'function') openAdventureOverlay();
    }catch(_e){}

    // 10. 顯示 toast
    if(typeof _showInGameToast === 'function'){
      _showInGameToast('🗑 已放棄上次戰鬥,可以開始新的冒險!', '#bb99ff', 3000);
    }

    console.log('[v3.5.69 放棄快照] ✅ 已徹底清除戰鬥狀態');
  }catch(eMain){
    console.error('[v3.5.69 放棄快照] 主流程異常', eMain);
    if(typeof _showInGameToast === 'function'){
      _showInGameToast('⚠ 清理時發生錯誤,請重新整理', '#ff4444', 3000);
    }
  }
}

