// Inject UI sounds into all interactive elements via event delegation
document.addEventListener('click', function(e){
  if(_sfxMuted) return;
  const t = e.target;
  // Identify element type and play appropriate sound
  if(t.matches('#hero-pick-confirm:not(:disabled)')){ sndConfirm(); return; }
  if(t.matches('.hf-invite:not(:disabled)')){
    // 離開隊伍→uninvite音效，邀請加入→invite音效
    const _txt = t.textContent||'';
    if(_txt.includes('離開')) sndHeroUninvite(); else sndHeroInvite();
    return;
  }
  if(t.matches('.hf-dismiss')){ sndCancel(); return; }
  if(t.matches('.hpick-node,.hpick-node *')){ sndHeroFocus(); return; }
  if(t.matches('.picked-badge,.picked-badge *')){ sndHeroFocus(); return; }
  if(t.matches('#skill-replace-confirm')){ sndConfirm(); return; }
  if(t.matches('.sk-pick-btn:not(.assigned)')){ sndSkillSelect(); return; }
  if(t.matches('.srh-skill-box,.srh-skill-box *')){ sndSkillAssign(); return; }
  if(t.matches('.srh-cancel-btn')){ sndCancel(); return; }
  if(t.matches('#iop-use-btn')){ sndClick(); return; }
  if(t.matches('#iop-equip-btn')){ sndClick(); return; }
  if(t.matches('.iop-btn[onclick*="doSell()"],.iop-btn[style*="8e44ad"]')){ sndSell(); return; }
  if(t.matches('.ibox,.ibox *')){ sndItemClick(); return; }
  if(t.matches('.abtn:not(:disabled),.abtn:not(:disabled) *')){ sndTab(); return; }
  if(t.matches('.equip-hero-btn,.equip-hero-btn *')){ sndClick(); return; }
  if(t.matches('.equip-skip-btn')){ sndCancel(); return; }
  if(t.matches('.ctrl-btn')){ sndClickSoft(); return; }
  if(t.matches('#ctrl-quit')){ sndCancel(); return; }
  if(t.matches('#start-btn')){ /* sfx-enter handled in onclick */ return; }
  if(t.matches('.pause-resume-btn')){ sndClick(); return; }
  if(t.matches('#ctrl-restart')){ /* has confirm dialog, skip */ return; }
  if(t.closest('.discard-card')){ sndClick(); return; }
  if(t.closest('.equip-hero-btn')){ sndClick(); return; }
}, true);


