// ====== TURN ORDER BAR ======
function renderTurnOrderBar(){
  const bar = document.getElementById('turn-order-bar');
  if(!bar) return;
  // 確保 bar 永遠是 #field 最後一個子節點（DOM後面的元素蓋過前面）
  const field = bar.parentNode;
  if(field && field.lastChild !== bar) field.appendChild(bar);
  const flag = document.getElementById('tob-flag');
  // Remove all slots but keep flag
  Array.from(bar.children).forEach(el=>{ if(el!==flag) el.remove(); });

  if(!G || !G.p1 || !G.p2) return;

  // ★ v5.284.0(老師 2026-10-20 需求 4)— 順序條與實際出手順序同一套速度(startTurn 的 _effSpd:含英魂陣型速度與第一回合先手);
  //   還沒跑過 startTurn 時退回「原速度 + 陣型速度」。任何例外一律退回原本的 h.spd 排序。
  const _tobSpd = function(h){
    try{
      if(typeof window._lxpsTurnEffSpd === 'function') return window._lxpsTurnEffSpd(h);
      return (h.spd || 0) + ((G && G._fm && typeof window._fmSpd === 'function') ? (fieldHas('reverse') ? -1 : 1) * window._fmSpd(h) : 0);
    }catch(_eTob){ return h.spd || 0; }
  };
  const sortFn2 = fieldHas('reverse') ? (a,b)=>_tobSpd(a)-_tobSpd(b) : (a,b)=>_tobSpd(b)-_tobSpd(a);
  const allHeroes = [...G.p1,...G.p2].filter(h=>h.hp>0||h.curHp>0);
  // Sort: alive unacted first (by spd), then alive acted, then dead
  const unacted = allHeroes.filter(h=>h.curHp>0&&!h.acted).sort(sortFn2);
  const acted   = allHeroes.filter(h=>h.curHp>0&&h.acted).sort(sortFn2);
  const dead    = allHeroes.filter(h=>h.curHp<=0);
  const ordered = [...unacted, ...acted, ...dead];

  // Display up to 8 slots (leftmost after flag = fastest / next to act)
  const display = ordered.slice(0,8);
  // flex-direction:row — display[0]=fastest appears leftmost right after flag

  // 先把旗子移到最左
  bar.insertBefore(flag, bar.firstChild);

  // 當前行動角色強制排第一（緊靠旗子）
  let sortedDisplay = [...display];
  if(G.activeChar && G.activeChar.curHp>0){
    const activeIdx = sortedDisplay.indexOf(G.activeChar);
    if(activeIdx > 0){
      sortedDisplay.splice(activeIdx,1);
      sortedDisplay.unshift(G.activeChar);
    }
  }

  // 旗子上方加「開始行動!」浮動標籤 + 回合數
  const existingStartLabel = document.getElementById('tob-start-label');
  if(existingStartLabel) existingStartLabel.remove();
  const existingRoundLabel = document.getElementById('tob-round-label');
  if(existingRoundLabel) existingRoundLabel.remove();
  // 回合數標示（旗子下方）
  const roundLabel = document.createElement('div');
  roundLabel.id = 'tob-round-label';
  roundLabel.textContent = G.round||1;
  roundLabel.style.cssText = 'position:absolute;bottom:-26px;left:50%;transform:translateX(-50%);font-size:22px;font-weight:900;color:#fff;white-space:nowrap;pointer-events:none;text-shadow:0 0 10px rgba(255,210,0,1),0 1px 3px #000;letter-spacing:1px;background:rgba(0,0,0,0.5);border-radius:6px;padding:1px 7px;';
  flag.style.position='relative';
  flag.appendChild(roundLabel);
  if(G.activeChar && G.activeChar.curHp>0){
    const startLabel = document.createElement('div');
    startLabel.id = 'tob-start-label';
    startLabel.textContent = '開始行動!';
    startLabel.style.cssText = 'position:absolute;top:-28px;left:0;transform:translateX(-50%);font-size:18px;font-weight:700;color:#ffdd44;white-space:nowrap;pointer-events:none;text-shadow:0 0 8px rgba(255,210,0,0.9),0 1px 2px #000;animation:tobLabelFloat 1.5s ease-in-out infinite;letter-spacing:1px;';
    flag.appendChild(startLabel);
  }

  sortedDisplay.forEach((h, i) => {
    const isActive = G.activeChar === h;
    const isActed  = h.curHp>0 && h.acted && !isActive;
    const isDead   = h.curHp<=0;
    const isP1     = h.side==='p1';
    const isNext   = !isActive && !isActed && !isDead && i===1;
    // 用 wrapper 包住，讓標籤可以超出 clip-path 範圍顯示
    const wrapper = document.createElement('div');
    wrapper.style.cssText = 'position:relative;display:inline-block;overflow:visible;margin-right:-8px;';
    const slot = document.createElement('div');
    slot.className = 'tob-slot' +
      (isP1?' tob-p1':' tob-p2') +
      (isActive?' tob-active':'') +
      (isActed?' tob-acted':'') +
      (isDead?' tob-dead':'');
    slot.style.marginRight = '0'; // margin移到wrapper
    slot.dataset.heroKey = h.side+'-'+h.pos;
    slot.innerHTML = '<div class="tob-av">'+h.av+'</div>'
      + '<div class="tob-name">'+h.name+'</div>'
      + '<div class="tob-spd">SPD:'+(function(){   // ★ v5.284.0 顯示含英魂陣型速度加成的數值;第一回合先手另標「先手」
          try{
            if(!(G && G._fm && typeof window._fmSpd === 'function')) return h.spd;
            var _fs = window._fmSpd(h), _first = _fs >= 100000;
            if(_first) _fs -= 100000;
            return (h.spd + _fs) + (_fs > 0 ? '↑' : '') + (_first ? ' 先手' : '');
          }catch(_eTobS){ return h.spd; }
        })()+'</div>';
    wrapper.appendChild(slot);
    if(isNext){
      const nextLabel = document.createElement('div');
      nextLabel.style.cssText = 'position:absolute;top:-26px;left:50%;transform:translateX(-50%);font-size:16px;font-weight:700;color:#ff88cc;white-space:nowrap;pointer-events:none;text-shadow:0 0 8px rgba(255,100,180,0.9),0 1px 2px #000;animation:tobLabelFloat 1.8s ease-in-out infinite 0.3s;letter-spacing:1px;z-index:50;';
      nextLabel.textContent = '下一位';
      wrapper.appendChild(nextLabel);
    }
    bar.appendChild(wrapper);
  });
}

