window.addEventListener('resize',scaleToViewport);
window.addEventListener('orientationchange',function(){
  if(typeof _scaleToViewportRetry === 'function') _scaleToViewportRetry();
  else setTimeout(scaleToViewport, 200);
  // ★ 裝置旋轉時嘗試鎖回橫式
  setTimeout(function(){
    if(screen.orientation && screen.orientation.lock){
      screen.orientation.lock('landscape').catch(()=>{});
    }
    // 若全螢幕遺失則重取
    if(!(document.fullscreenElement||document.webkitFullscreenElement)){
      const el = document.documentElement;
      const fn = el.requestFullscreen||el.webkitRequestFullscreen||el.mozRequestFullScreen;
      // ★ v1.0.20260428.3930 — 處理 promise rejection
      if(fn){ try{ const _p = fn.call(el,{navigationUI:'hide'}); if(_p && _p.catch) _p.catch(()=>{}); }catch(_){} }
    }
  }, 300);
});
if(window.visualViewport) window.visualViewport.addEventListener('resize',scaleToViewport);
// ★ v1.0.20260422.0108 — 監聽更多會讓 iPad viewport 變動的事件
window.addEventListener('resize', scaleToViewport);
window.addEventListener('orientationchange', () => {
  if(typeof _scaleToViewportRetry === 'function') _scaleToViewportRetry();
  else setTimeout(scaleToViewport, 300);
});
try{
  if(typeof ResizeObserver !== 'undefined'){
    const _docElResizeOb = new ResizeObserver(() => {
      // 用 RAF 讓 ResizeObserver callback 不在 layout 階段內執行,避免 forced reflow
      requestAnimationFrame(scaleToViewport);
    });
    _docElResizeOb.observe(document.documentElement);
  }
}catch(_){}
// ★ v1.0.20260422.0112 — 清除舊版（v0111 以下）scaleGame IIFE 可能遺留在 inline style 上的
//   left / top / width / height 值。新架構完全靠 CSS flex 置中，這些 inline 值會干擾版面。
try{
  const _gcInit = document.getElementById('gc');
  if(_gcInit){
    _gcInit.style.left = '';
    _gcInit.style.top = '';
    _gcInit.style.width = '';
    _gcInit.style.height = '';
  }
  const _wrInit = document.getElementById('_gc_wrapper');
  if(_wrInit){
    _wrInit.style.width = '';
    _wrInit.style.height = '';
  }
}catch(_){}
scaleToViewport();

(function _installViewportGuard(){
  // 用旗標讓「玩家主動捲動」(例如關卡選擇頁的整頁捲動)豁免。
  // 預設遊戲頁不應該有 document 級捲動,所以一律歸位。
  // 若未來有真的需要 document 捲動的頁面,把 window._allowDocScroll = true 即可暫停。
  let _scheduled = false;
  function _snapBack(){
    if(window._allowDocScroll === true) return;
    // ★ v5.305.0(老師「會員資料無法正常輸入」)— iPad 叫出鍵盤時,瀏覽器會捲動頁面把輸入格露出來;
    //   舊版立刻把頁面捲回 0,0 ⇒ 輸入格被鍵盤蓋住、游標亂跳,學生看起來就是「打不了字」。打字中先不歸位,收鍵盤後再歸位。
    try{ if(typeof window._lxpsTypingActive === 'function' && window._lxpsTypingActive()) return; }catch(_){}
    // 已經在 0,0,不必做事
    const sx = window.pageXOffset || document.documentElement.scrollLeft || 0;
    const sy = window.pageYOffset || document.documentElement.scrollTop  || 0;
    if(sx === 0 && sy === 0) return;
    try{ window.scrollTo(0, 0); }catch(_){}
    try{ document.documentElement.scrollTop = 0; document.documentElement.scrollLeft = 0; }catch(_){}
    try{ document.body.scrollTop = 0; document.body.scrollLeft = 0; }catch(_){}
  }
  // 監聽全域 scroll(passive 以免影響效能)
  window.addEventListener('scroll', function(){
    if(_scheduled) return;
    _scheduled = true;
    // 用 rAF 而非立即,避免和瀏覽器自動捲動 race;同時合併多次捲動成一次處理
    requestAnimationFrame(function(){
      _scheduled = false;
      _snapBack();
    });
  }, {passive: true, capture: true});
  // ★ v5.305.0 收鍵盤(離開輸入格)後補一次歸位(打字中被略過的那次)
  try{ document.addEventListener('focusout', function(){ setTimeout(function(){ try{ _snapBack(); }catch(_){} }, 1700); }, true); }catch(_){}
  // 初始化也跑一次(防止頁面載入時就被某個 anchor / hash 捲走)
  _snapBack();
  // 暴露手動歸位 API(玩家或除錯時可用)
  window._snapViewportBack = _snapBack;
})();

