// ════════════════════════════════════════════════════════════════════
// ★ v4.32.0 — 全 8 龍王「排名獎勵/顯示至寶」單一真相映射(index.html 內·不依賴 world-boss.js)
//   修:雷龍王(風暴雷龍王)/海/暗/光/幻 原缺對應 → 領獎與獎勵頁彈窗都 fallback 火龍王之牙(發錯/顯示錯)。
//   ★ 未來新增龍王:於此 base 加一筆(或於 world-boss.js window._WB_DRAGON_TREASURE_MAP 加一筆)即自動對應。
//   本地 8 筆為 base,再以 world-boss.js 的 window._WB_DRAGON_TREASURE_MAP 覆蓋/追加(雲端補齊時以雲端為準·雙保險防載入順序)。
window._lxpsDragonTreasureMapFull = function(){
  return Object.assign({
    vesuvius_fire_dragon:   'dragon_fang_fire',      // 炎龍王之牙(火)
    shenhai_water_dragon:   'dragon_claw_sea',       // 海龍王之爪(水)
    taifeng_wind_dragon:    'dragon_wing_thunder',   // 雷龍王之翼(風暴雷龍王·風/雷)
    shanyue_earth_dragon:   'dragon_scale_earth',    // 地龍王之麟(土)
    bushi_dark_dragon:      'dragon_bone_dark',      // 暗龍王之骸(暗)
    shensheng_light_dragon: 'dragon_feather_light',  // 光龍王之羽(光)
    cuiyu_grass_dragon:     'dragon_whisker_grass',  // 森龍王之鬚(草)
    xingchen_omni_dragon:   'dragon_horn_omni',      // 幻龍王之角(幻/omni)
  }, (window._WB_DRAGON_TREASURE_MAP && typeof window._WB_DRAGON_TREASURE_MAP === 'object') ? window._WB_DRAGON_TREASURE_MAP : {});
};
window._lxpsDragonTreasureId = function(bossId){
  try{
    var _m = window._lxpsDragonTreasureMapFull();
    if(bossId && _m[bossId]) return _m[bossId];
    var _cur = (typeof window._wbGetCurrentBossId === 'function') ? window._wbGetCurrentBossId() : null;
    if(_cur && _m[_cur]) return _m[_cur];
  }catch(_){}
  return 'dragon_fang_fire';
};

