window._wbShowDragonTreasureInfo = function(){
  try{
    // ★ v3.14.24 — 改依當前龍王動態取至寶(維蘇威=火龍王之牙 / 翠玉草=草龍王之鬚);原本寫死 dragon_fang_fire
    // ★ v4.32.0 — 改走 index.html 內完整 8 龍王映射(_lxpsDragonTreasureId),不再依賴 world-boss.js 殘缺 3 筆 map
    //   → 雷龍王/海/暗/光/幻 獎勵頁彈窗也顯示正確專屬至寶(原全 fallback 火龍王之牙)。
    const _tid = (typeof window._lxpsDragonTreasureId === 'function')
      ? window._lxpsDragonTreasureId((typeof window._wbGetCurrentBoss === 'function' && window._wbGetCurrentBoss() || {}).id)
      : ((typeof window._wbGetCurrentDragonTreasureId === 'function') ? window._wbGetCurrentDragonTreasureId() : 'dragon_fang_fire');
    const _t = (typeof TAIWAN_TREASURES === 'object' && TAIWAN_TREASURES[_tid])
      ? TAIWAN_TREASURES[_tid]
      : ((typeof TAIWAN_TREASURES === 'object' && TAIWAN_TREASURES.dragon_fang_fire) ? TAIWAN_TREASURES.dragon_fang_fire : null);
    if(!_t){ console.warn('[_wbShowDragonTreasureInfo] 找不到龍王至寶資料 ' + _tid); return; }
    const _dtBossNm = (function(){ try{ const _b = (typeof window._wbGetCurrentBoss === 'function') && window._wbGetCurrentBoss(); return (_b && _b.name) || '世界 BOSS'; }catch(_){ return '世界 BOSS'; } })();
    // 移除舊彈窗(防重複)
    const _old = document.getElementById('_wb-dragon-treasure-info-modal');
    if(_old) _old.remove();
    const _bs = _t.baseStats || {};
    const _statsList = [];
    if(_bs.hp)  _statsList.push('❤️ HP +' + _bs.hp);
    if(_bs.atk) _statsList.push('⚔ 攻擊 +' + _bs.atk);
    if(_bs.sp)  _statsList.push('✨ 特技 +' + _bs.sp);
    if(_bs.spd) _statsList.push('🌀 速度 +' + _bs.spd);
    const _statsHtml = _statsList.length ? _statsList.join(' / ') : '(無基礎能力)';
    const _modal = document.createElement('div');
    _modal.id = '_wb-dragon-treasure-info-modal';
    _modal.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.75);' +
      'display:flex;align-items:center;justify-content:center;padding:20px;' +
      'animation:fadeIn 0.2s ease;';
    _modal.innerHTML =
      '<div style="background:linear-gradient(135deg,#2a1810,#3d2418);' +
      '  border:3px solid #ff8866;border-radius:16px;max-width:500px;width:100%;' +
      '  padding:24px 28px;box-shadow:0 10px 40px rgba(255,120,60,0.4);' +
      '  position:relative;color:#ffe8d0;">' +
      '  <button onclick="document.getElementById(\'_wb-dragon-treasure-info-modal\').remove();"' +
      '    style="position:absolute;top:10px;right:14px;background:transparent;border:none;' +
      '    color:#ffaa88;font-size:30px;cursor:pointer;font-weight:bold;line-height:1;">×</button>' +
      '  <div style="text-align:center;margin-bottom:16px;">' +
      (_t.iconUrl
        ? '    <img src="' + _t.iconUrl + '" alt="' + _t.name + '" ' +
          '    style="width:120px;height:120px;border-radius:14px;border:2px solid #ff8866;' +
          '    box-shadow:0 4px 16px rgba(255,150,80,0.5);"' +
          '    onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'block\';">' +
          '    <div style="display:none;font-size:90px;">' + (_t.icon || '🦷') + '</div>'
        : '    <div style="font-size:90px;">' + (_t.icon || '🦷') + '</div>') +
      '  </div>' +
      '  <div style="text-align:center;font-size:26px;font-weight:900;color:#ffaa66;' +
      '    margin-bottom:6px;text-shadow:0 2px 8px rgba(255,150,80,0.6);">' +
      '    🐉 ' + _t.name +
      '  </div>' +
      '  <div style="text-align:center;font-size:14px;color:#ffd0b0;margin-bottom:14px;">' +
      '    神話級・' + _dtBossNm + '排名獎勵專屬' +
      '  </div>' +
      '  <div style="font-size:15px;color:#fff1d8;line-height:1.7;margin-bottom:14px;' +
      '    padding:12px 14px;background:rgba(255,150,80,0.1);border-radius:8px;' +
      '    border-left:3px solid #ff8866;font-style:italic;">' +
      '    ' + (_t.desc || '') +
      '  </div>' +
      '  <div style="background:rgba(0,0,0,0.3);border-radius:10px;padding:14px 16px;' +
      '    margin-bottom:10px;">' +
      '    <div style="font-size:13px;color:#ff8866;font-weight:700;margin-bottom:6px;' +
      '      letter-spacing:1px;">⚡ 基礎能力</div>' +
      '    <div style="font-size:17px;color:#ffe8a0;font-weight:600;">' + _statsHtml + '</div>' +
      '  </div>' +
      '  <div style="background:rgba(0,0,0,0.3);border-radius:10px;padding:14px 16px;">' +
      '    <div style="font-size:13px;color:#ff8866;font-weight:700;margin-bottom:6px;' +
      '      letter-spacing:1px;">🔥 特殊效果</div>' +
      '    <div style="font-size:15px;color:#fff1d8;line-height:1.65;">' +
      '      ' + (_t.abilityText || '無描述') +
      '    </div>' +
      '  </div>' +
      '  <div style="margin-top:14px;text-align:center;font-size:12px;color:#aa8866;">' +
      '    ⚠ 此至寶僅能透過世界 BOSS 排名獎勵獲得,無法在召喚池中抽到' +
      '  </div>' +
      '</div>';
    // 點背景關閉
    _modal.addEventListener('click', function(e){
      if(e.target === _modal) _modal.remove();
    });
    document.body.appendChild(_modal);
  }catch(e){
    console.error('[_wbShowDragonTreasureInfo] 例外', e);
  }
};

