try{ if(window._TW2) window._TW2.bosses.forEach(function(b){ if(!TAIWAN_IMG_MAP[b.id]) TAIWAN_IMG_MAP[b.id] = { boss:b.img.boss, scene:b.img.scene }; }); }catch(_eTw2Img){}
// 工具函式:取得指定 BOSS 的圖片 URL(自動 URL encode)
function _getTaiwanBossImage(bossId){
  const m = TAIWAN_IMG_MAP[bossId];
  if(!m || !m.boss) return '';
  return TAIWAN_IMG_BASE + encodeURIComponent(m.boss);
}
function _getTaiwanSceneImage(bossId){
  const m = TAIWAN_IMG_MAP[bossId];
  if(!m || !m.scene) return '';
  return TAIWAN_IMG_BASE + encodeURIComponent(m.scene);
}
function _getTaiwanMapBgImage(){
  if(!TAIWAN_IMG_MAP.mapBg) return '';
  return TAIWAN_IMG_BASE + encodeURIComponent(TAIWAN_IMG_MAP.mapBg);
}

function _renderTaiwanTreasureIconHtml(treas, sizePx, glowColor){
  if(!treas) return '💎';
  const _emoji = (treas.icon || '💎').replace(/"/g, '&quot;');
  if(treas.iconUrl){
    const _glow = glowColor ? ('filter:drop-shadow(0 0 10px ' + glowColor + ');') : '';
    // 圖片大小用 sizePx,失敗時 fallback 成同尺寸的 emoji
    return '<img src="' + treas.iconUrl + '" '
         + 'style="width:' + sizePx + 'px;height:' + sizePx + 'px;object-fit:contain;display:inline-block;' + _glow + '" '
         + 'onerror="this.outerHTML=&quot;<span style=\'font-size:' + sizePx + 'px;line-height:1;\'>' + _emoji + '</span>&quot;" />';
  }
  return '<span style="font-size:' + sizePx + 'px;line-height:1;">' + _emoji + '</span>';
}

