// 「申請」一天一次守門(per-uid per-item per-day)
function _codexActionDayKey(type, key){
  var _uid = window._gUserId || 'guest';
  var _d = (typeof _getTodayKeyTW === 'function') ? _getTodayKeyTW() : (new Date()).toISOString().slice(0, 10);
  return 'lxps_codex_act_' + _uid + '_' + type + '_' + key + '_' + _d;
}
function _codexActionUsedToday(type, key){ try{ return !!localStorage.getItem(_codexActionDayKey(type, key)); }catch(_){ return false; } }
function _codexMarkActionToday(type, key){ try{ localStorage.setItem(_codexActionDayKey(type, key), '1'); }catch(_){} }

// ★ v3.16.70 — 未收錄英雄「要救回」持久審查狀態(與每日限額分離;送出即 pending、直到 GM 核可變已擁有才算通過)
function _codexLostPendingKey(type, key){ return 'lxps_codex_lostpending_' + (window._gUserId || 'guest') + '_' + type + '_' + key; }
function _codexLostPassedKey(type, key){ return 'lxps_codex_lostpassed_' + (window._gUserId || 'guest') + '_' + type + '_' + key; }
function _codexLostPendingAt(type, key){ try{ var _v = localStorage.getItem(_codexLostPendingKey(type, key)); return _v ? (parseInt(_v, 10) || 0) : 0; }catch(_){ return 0; } }
function _codexMarkLostPending(type, key){ try{ localStorage.setItem(_codexLostPendingKey(type, key), String(Date.now())); }catch(_){} }
function _codexClearLostPending(type, key){ try{ localStorage.removeItem(_codexLostPendingKey(type, key)); }catch(_){} }
function _codexLostPassedAt(type, key){ try{ var _v = localStorage.getItem(_codexLostPassedKey(type, key)); return _v ? (parseInt(_v, 10) || 0) : 0; }catch(_){ return 0; } }
function _codexMarkLostPassed(type, key){ try{ if(!localStorage.getItem(_codexLostPassedKey(type, key))) localStorage.setItem(_codexLostPassedKey(type, key), String(Date.now())); }catch(_){} }

// 重新整理當前圖鑑詳情頁的來源帶(英雄改底部帶;至寶整個重渲)
function _codexRerenderCurrent(type, key){
  try{
    if(type === 'hero'){ if(typeof _renderHeroCodexUnlockBar === 'function') _renderHeroCodexUnlockBar(key); }
    else { if(typeof _renderTaiwanTreasureDetail === 'function') _renderTaiwanTreasureDetail(key); }
  }catch(_){}
}

// 送出 disown / lost 申請(claims:hero→disownHeroes/lostHeroes;treasure→disownTreasures/lostTreasures)
function _codexSubmitClaim(type, key, kind){
  var _uid = window._gUserId; if(!_uid) return;
  var _u = window._fbUser || {};
  var _label = '';
  try{ if(typeof window._getAdminPlayerLabel === 'function') _label = window._getAdminPlayerLabel(_u.email || '', window._playerNickname || ''); }catch(_){}
  if(!_label) _label = (window._playerNickname || _u.email || _uid);
  var _claims = {};
  if(type === 'hero' && kind === 'disown') _claims.disownHeroes = [key];
  else if(type === 'hero' && kind === 'lost') _claims.lostHeroes = [key];
  else if(type === 'treasure' && kind === 'disown') _claims.disownTreasures = [key];
  else if(type === 'treasure' && kind === 'lost') _claims.lostTreasures = [key];
  if(typeof window._fbSubmitAccountRescueRequest !== 'function'){ try{ if(typeof _showInGameToast === 'function') _showInGameToast('目前無法送出,請稍後再試。', '#ff8866', 2400); }catch(_){} return; }
  window._fbSubmitAccountRescueRequest(_uid, _u.email || '', _label, _claims, { codex:true, at:Date.now() }).then(function(ok){
    if(ok){
      _codexMarkActionToday(type, key);
      if(kind === 'lost' && type === 'hero') _codexMarkLostPending(type, key);   // ★ v3.16.70 — 未收錄英雄救回:持久「審查中」直到 GM 核可(至寶維持每日限額不變)
      try{ if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.6); }catch(_){}
      try{ if(typeof _showInGameToast === 'function') _showInGameToast(kind === 'disown' ? '🗑 已送出移除申請,老師審核後處理。' : '🔓 已送出救回申請,老師確認後處理。', '#88dd99', 2800); }catch(_){}
      _codexRerenderCurrent(type, key);
    } else {
      try{ if(typeof _showInGameToast === 'function') _showInGameToast('送出失敗,請稍後再試。', '#ff8866', 2400); }catch(_){}
    }
  }).catch(function(){ try{ if(typeof _showInGameToast === 'function') _showInGameToast('送出失敗,請稍後再試。', '#ff8866', 2400); }catch(_){} });
}

// ★ v3.16.86 — 過度補回「學生自我審核」視窗(GM 派發 type='overRestoreReview' → 登入彈出)
//   ②乙:每筆不預設,全部選完才能送出;勾「不是我的」且該英雄已練(lv>1)→ 彈再確認子視窗
//        (z-index 2147483640 > 主視窗 2147483600 → 階層正確絕不被蓋·老師明確要求)
//   ③甲:是我的→_lxpsConfirmOwnHero/Treasure 綁 UID 永久;不是我的→可逆移除(GM 後台可救回)+補償(依 GM 記錄等級)
//   放此 block(可直接呼叫同 block 的 _lxpsConfirmOwnHero/_lxpsConfirmOwnTreasure;disown/補償為 window 函式跨 block 可呼叫)
window._showOverRestoreReviewModal = function(uid, data){
  return new Promise(function(resolve){
    try{
      var _items = (data && Array.isArray(data.items)) ? data.items.filter(function(x){ return x && x.key; }) : [];
      if(!_items.length){ resolve(); return; }
      var _choices = _items.map(function(){ return null; });   // null | 'mine' | 'notmine'

      function _esc2(s){ return String(s==null?'':s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }

      var _old = document.getElementById('_orr-review-overlay');
      if(_old) _old.remove();
      var _ov = document.createElement('div');
      _ov.id = '_orr-review-overlay';
      _ov.style.cssText = 'position:fixed;inset:0;z-index:2147483600;background:rgba(8,6,10,0.93);display:flex;flex-direction:column;align-items:center;justify-content:flex-start;backdrop-filter:blur(6px);font-family:"M PLUS Rounded 1c","Nunito",sans-serif;overflow:hidden;';

      var _box = document.createElement('div');
      _box.style.cssText = 'width:100%;max-width:680px;height:100%;height:100dvh;display:flex;flex-direction:column;';
      var _head = '<div style="flex:0 0 auto;padding:18px 18px 10px;text-align:center;">'
        + '<div style="font-size:24px;font-weight:900;color:#ffd86b;margin-bottom:6px;">🛡️ 請確認這些是不是你的</div>'
        + '<div style="font-size:14px;color:#d8d2c0;line-height:1.55;">老師發現下面這些英雄／至寶<b style="color:#ffb0b0;">可能不是你的</b>(是別人帳號解鎖、被補進你帳號的)。<br>請你自己判斷,<b style="color:#9effb0;">每一個都要選</b>:<br><span style="color:#9effb0;">✅ 是我的</span> → 永久綁定給你,以後不會再被問;　<span style="color:#ffae8a;">🗑 不是我的</span> → 移除並補償你練功的心力。</div>'
        + '</div>';
      var _scroll = '<div id="_orr-review-scroll" style="flex:1 1 auto;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:6px 14px 14px;"></div>';
      var _bar = '<div style="flex:0 0 auto;padding:12px 16px calc(14px + env(safe-area-inset-bottom));background:rgba(20,16,24,0.97);border-top:1px solid rgba(255,255,255,0.12);display:flex;gap:10px;align-items:center;">'
        + '<div id="_orr-review-status" style="flex:1;font-size:13px;color:#ffcf8a;"></div>'
        + '<button id="_orr-review-submit" disabled style="padding:12px 26px;font-size:16px;font-weight:900;background:#3a3030;border:2px solid #555;color:#888;border-radius:8px;cursor:not-allowed;font-family:inherit;touch-action:manipulation;">送出</button>'
        + '</div>';
      // ★ v3.16.91 — 帳號身分橫幅:共用 iPad 上學生可能登到別人帳號,審查前先確認「現在是誰」,不是本人可一鍵切換重登。
      var _curEmail = '';
      try{ _curEmail = (window._fbAuth && window._fbAuth.currentUser && window._fbAuth.currentUser.email) || ''; }catch(_eEm){}
      var _rosterLbl = '';
      try{ if(typeof window._getRosterEntry==='function' && typeof window._formatRosterLabel==='function'){ _rosterLbl = window._formatRosterLabel(window._getRosterEntry((_curEmail||'').toLowerCase())) || ''; } }catch(_eRl){}
      var _acctBanner = '<div style="flex:0 0 auto;margin:0 14px 10px;padding:11px 14px;background:rgba(46,34,18,0.9);border:2px solid #ffce5a;border-radius:11px;text-align:center;">'
        + '<div style="font-size:12px;color:#ffd86b;font-weight:800;letter-spacing:2px;margin-bottom:3px;">目前登入的帳號</div>'
        + (_rosterLbl ? '<div style="font-size:21px;font-weight:900;color:#fff3d0;line-height:1.3;">' + _esc2(_rosterLbl) + '</div>' : '')
        + (_curEmail ? '<div style="font-size:12px;color:#cfc6b0;word-break:break-all;margin-top:2px;">' + _esc2(_curEmail) + '</div>' : '')
        + ((!_rosterLbl && !_curEmail) ? '<div style="font-size:15px;color:#ffae8a;font-weight:700;">(讀不到帳號資訊,請重新整理)</div>' : '')
        + '<div style="font-size:13px;color:#ffb89a;font-weight:700;margin-top:8px;line-height:1.5;">⚠ 先確認上面是「<u>你本人</u>」的帳號再往下審查。<br>如果這不是你的帳號,請按下面切換。</div>'
        + '<button id="_orr-review-switch" style="margin-top:9px;padding:10px 16px;font-size:13.5px;font-weight:800;background:rgba(150,60,60,0.32);border:2px solid #ff8a8a;color:#ffd6d6;border-radius:8px;cursor:pointer;font-family:inherit;touch-action:manipulation;">🔄 這不是我的帳號,切換帳號重新登入</button>'
        + '</div>';
      _box.innerHTML = _head + _acctBanner + _scroll + _bar;
      _ov.appendChild(_box);
      document.body.appendChild(_ov);

      var _scrollEl = document.getElementById('_orr-review-scroll');
      var _submitBtn = document.getElementById('_orr-review-submit');
      var _statusEl = document.getElementById('_orr-review-status');
      // ★ v3.16.91 — 「這不是我的帳號」→ 不消化本帳號審查(resolve switched 讓外層 break·不刪 pending),登出回登入頁讓學生改登自己帳號(該帳號若有待審會再跳)。
      var _switchBtn = document.getElementById('_orr-review-switch');
      if(_switchBtn){
        _switchBtn.onclick = function(){
          try{ if(_ov && _ov.parentNode) _ov.remove(); }catch(_eRm){}
          resolve({ switched:true });
          try{ if(typeof window._fbSignOut==='function') window._fbSignOut(); }catch(_eSo){ console.warn('[自審 切換帳號] 登出失敗', _eSo); }
        };
      }

      function _renderRows(){
        var html = _items.map(function(it, i){
          var _trained = (it.kind==='hero' && it.lv>1);
          var _kindLabel = (it.kind==='hero') ? '英雄' : '至寶';
          var _kindColor = (it.kind==='hero') ? '#ffc0c0' : '#f0d090';
          var _lvText = (it.kind==='hero') ? (' · Lv' + (it.lv||1) + (_trained ? ' 🔥已練' : '')) : '';
          var _ch = _choices[i];
          var _mineSel = (_ch==='mine'); var _notSel = (_ch==='notmine');
          return '<div style="margin-bottom:9px;padding:11px 12px;background:rgba(30,26,34,0.72);border:1px solid rgba(255,255,255,0.1);border-radius:9px;">'
            + '<div style="font-size:15px;font-weight:800;color:' + _kindColor + ';margin-bottom:8px;">'
            +   (it.kind==='hero'?'🦸 ':'💎 ') + _esc2(it.name)
            +   '<span style="font-size:12.5px;color:#bbb;font-weight:600;"> (' + _kindLabel + _lvText + ')</span>'
            + '</div>'
            + '<div style="display:flex;gap:8px;">'
            +   '<button class="_orr-pick" data-i="' + i + '" data-v="mine" style="flex:1;padding:11px 6px;font-size:14px;font-weight:800;border-radius:7px;cursor:pointer;font-family:inherit;touch-action:manipulation;'
            +     (_mineSel ? 'background:#1d6b33;border:2px solid #4fe07a;color:#eaffe0;' : 'background:rgba(80,140,90,0.16);border:2px solid rgba(80,200,120,0.4);color:#bfe8c8;') + '">✅ 是我的</button>'
            +   '<button class="_orr-pick" data-i="' + i + '" data-v="notmine" style="flex:1;padding:11px 6px;font-size:14px;font-weight:800;border-radius:7px;cursor:pointer;font-family:inherit;touch-action:manipulation;'
            +     (_notSel ? 'background:#7a2330;border:2px solid #ff6b7f;color:#ffe0e4;' : 'background:rgba(200,100,100,0.16);border:2px solid rgba(220,120,120,0.4);color:#f0c8c8;') + '">🗑 不是我的</button>'
            + '</div>'
            + '</div>';
        }).join('');
        _scrollEl.innerHTML = html;
        _scrollEl.querySelectorAll('._orr-pick').forEach(function(b){
          b.onclick = function(){
            var i = parseInt(b.getAttribute('data-i'),10);
            var v = b.getAttribute('data-v');
            if(v==='notmine' && _items[i].kind==='hero' && _items[i].lv>1){
              _showReconfirm(_items[i], function(ok){ _choices[i] = ok ? 'notmine' : null; _renderRows(); _updateStatus(); });
              return;
            }
            _choices[i] = v; _renderRows(); _updateStatus();
          };
        });
      }

      function _updateStatus(){
        var _undecided = _choices.filter(function(c){ return c===null; }).length;
        if(_undecided > 0){
          _statusEl.textContent = '還有 ' + _undecided + ' 個需要選擇';
          _submitBtn.disabled = true;
          _submitBtn.style.cssText = 'padding:12px 26px;font-size:16px;font-weight:900;background:#3a3030;border:2px solid #555;color:#888;border-radius:8px;cursor:not-allowed;font-family:inherit;touch-action:manipulation;';
        }else{
          var _notN = _choices.filter(function(c){ return c==='notmine'; }).length;
          var _mineN = _choices.filter(function(c){ return c==='mine'; }).length;
          _statusEl.textContent = '已選好:✅是我的 ' + _mineN + ' 個 / 🗑不是我的 ' + _notN + ' 個';
          _submitBtn.disabled = false;
          _submitBtn.style.cssText = 'padding:12px 26px;font-size:16px;font-weight:900;background:#ffce5a;border:2px solid #ffe08a;color:#3a2c00;border-radius:8px;cursor:pointer;font-family:inherit;touch-action:manipulation;box-shadow:0 2px 10px rgba(255,206,90,0.4);';
        }
      }

      // 再確認子視窗(z-index 2147483640 > 主視窗 → 永遠在最上層,不被遮蓋)
      function _showReconfirm(it, cb){
        var _old2 = document.getElementById('_orr-reconfirm-overlay');
        if(_old2) _old2.remove();
        var _rc = document.createElement('div');
        _rc.id = '_orr-reconfirm-overlay';
        _rc.style.cssText = 'position:fixed;inset:0;z-index:2147483640;background:rgba(0,0,0,0.82);display:flex;align-items:center;justify-content:center;padding:22px;backdrop-filter:blur(3px);font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
        _rc.innerHTML = '<div style="max-width:420px;width:100%;background:linear-gradient(160deg,#2a1816,#1a0e0c);border:2.5px solid #ff8a5a;border-radius:16px;padding:22px;box-shadow:0 10px 40px rgba(0,0,0,0.6);">'
          + '<div style="font-size:20px;font-weight:900;color:#ffb070;text-align:center;margin-bottom:12px;">⚠️ 再確認一次</div>'
          + '<div style="font-size:15px;color:#f0e0d0;line-height:1.6;text-align:center;margin-bottom:18px;">「<b style="color:#ffd86b;">' + _esc2(it.name) + '</b>」已經練到 <b style="color:#ff9a6a;">Lv' + (it.lv||1) + '</b> 了。<br>你確定這隻<b style="color:#ff8a8a;">不是你的</b>嗎?<br><span style="font-size:13px;color:#c0b0a0;">(移除後雖然老師可以幫你救回,但請再想一下是不是按錯了)</span></div>'
          + '<div style="display:flex;gap:10px;">'
          +   '<button id="_orr-rc-cancel" style="flex:1;padding:13px 6px;font-size:15px;font-weight:800;background:rgba(120,140,90,0.2);border:2px solid #6ec06e;color:#cfe8b0;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">✗ 取消(還是我的)</button>'
          +   '<button id="_orr-rc-ok" style="flex:1;padding:13px 6px;font-size:15px;font-weight:800;background:#7a2330;border:2px solid #ff6b7f;color:#ffe0e4;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">✓ 確定不是我的</button>'
          + '</div>'
          + '</div>';
        document.body.appendChild(_rc);
        document.getElementById('_orr-rc-cancel').onclick = function(){ _rc.remove(); cb(false); };
        document.getElementById('_orr-rc-ok').onclick = function(){ _rc.remove(); cb(true); };
      }

      function _showDoneAndReload(mineN, notN, coins, crys){
        _ov.innerHTML = '<div style="margin:auto;max-width:440px;width:100%;text-align:center;padding:30px;">'
          + '<div style="font-size:28px;font-weight:900;color:#9effb0;margin-bottom:14px;">✅ 完成!</div>'
          + '<div style="font-size:15px;color:#e0e0e0;line-height:1.65;margin-bottom:8px;">'
          +   '保留為你的:<b style="color:#9effb0;">' + mineN + '</b> 個(已永久綁定,以後不會再被問)<br>'
          +   '移除的:<b style="color:#ffae8a;">' + notN + '</b> 個'
          +   ((coins||crys) ? ('<br>補償你:💰知識幣 ×' + coins + ' ＋ 🔮召喚水晶 ×' + crys) : '')
          + '</div>'
          + '<div style="font-size:13px;color:#c0b8a8;margin-bottom:20px;">即將重新整理讓變更生效...</div>'
          + '<button onclick="_lxpsReloadKeepLogin()" style="padding:13px 30px;font-size:16px;font-weight:900;background:#ffce5a;border:2px solid #ffe08a;color:#3a2c00;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">立即重新整理</button>'
          + '</div>';
        setTimeout(function(){ try{ window._lxpsReloadKeepLogin(); }catch(_){ try{ location.reload(); }catch(__){} } }, 3500);   // ★ v5.141.0 — 自家重載設放行旗標
      }

      _submitBtn.onclick = async function(){
        if(_submitBtn.disabled) return;
        _submitBtn.disabled = true; _submitBtn.textContent = '處理中...';
        _statusEl.textContent = '正在套用你的選擇...';
        var _mineHeroes = [], _mineTre = [], _notHeroes = [], _notTre = [];
        var _notTrainedLvSum = 0, _notTrainedCount = 0;
        _items.forEach(function(it, i){
          var c = _choices[i];
          if(c==='mine'){ if(it.kind==='hero') _mineHeroes.push(it.key); else _mineTre.push(it.key); }
          else if(c==='notmine'){
            if(it.kind==='hero'){ _notHeroes.push(it.key); if(it.lv>1){ _notTrainedLvSum += it.lv; _notTrainedCount++; } }
            else _notTre.push(it.key);
          }
        });
        try{
          // ① 是我的 → 綁 UID 永久(player_confirmed 三槽 + 鎖等級)
          _mineHeroes.forEach(function(n){ try{ if(typeof _lxpsConfirmOwnHero==='function') _lxpsConfirmOwnHero(n); }catch(_){} });
          _mineTre.forEach(function(id){ try{ if(typeof _lxpsConfirmOwnTreasure==='function') _lxpsConfirmOwnTreasure(id); }catch(_){} });
          // ② 不是我的 → 可逆移除(GM 後台可救回)
          // ★ v5.126.0 — 三個寫入全部加逾時保護（原本裸 await，佇列塞滿時整個視窗卡死）
          var _tmOut = false;
          if(_notHeroes.length && typeof window._fbStudentDisownHeroes==='function'){ try{ await window._lxpsFbAwait(window._fbStudentDisownHeroes(uid, _notHeroes), '過度補回自審·移除英雄'); }catch(_e1){ if(_e1 && _e1.lxpsTimeout) _tmOut = true; console.warn('[自審] 移除英雄失敗', _e1); } }
          if(_notTre.length && typeof window._fbStudentDisownTreasures==='function'){ try{ await window._lxpsFbAwait(window._fbStudentDisownTreasures(uid, _notTre), '過度補回自審·移除至寶'); }catch(_e2){ if(_e2 && _e2.lxpsTimeout) _tmOut = true; console.warn('[自審] 移除至寶失敗', _e2); } }
          // ③ 補償(只算不是我的·已練英雄·依 GM 記錄的等級·與 GM 回收公式一致)
          if(_notTrainedCount && typeof window._fbCompensatePlayer==='function'){
            var _coins = _notTrainedLvSum * 500;
            var _crys = Math.min(_notTrainedCount * 2, 20);
            try{ await window._lxpsFbAwait(window._fbCompensatePlayer(uid, { reason:'過度補回自審·移除別人英雄補償(練功心力)', coinsMode:'add', coins:_coins, backpack:{ summon_crystal:_crys } }), '過度補回自審·補償'); }catch(_e3){ if(_e3 && _e3.lxpsTimeout) _tmOut = true; console.warn('[自審] 補償失敗', _e3); }
          }
        }catch(_eApply){ console.warn('[過度補回自審] 套用失敗', _eApply); }
        // ★★ v5.126.0 — 逾時時**不可以**宣稱完成並重載：那會讓學生以為處理好了，
        //   但雲端其實沒寫進去（或稍後才寫），下次登入又被問一次、還可能誤領第二次補償。
        //   ⇒ 恢復按鈕、保留學生已勾好的選擇、請他重按；刻意不 resolve()，
        //     讓這筆 pending 留著，下次登入仍會再問（可重入，重按不會產生雙倍效果）。
        if(_tmOut){
          _submitBtn.disabled = false;
          _submitBtn.textContent = '✅ 送出我的選擇';
          _statusEl.textContent = '⚠ 網路忙碌，剛剛沒有送出成功。你的選擇還在，請再按一次送出。';
          try{ _statusEl.style.color = '#ffcc66'; }catch(_){}
          return;
        }
        var _payCoins = _notTrainedCount ? (_notTrainedLvSum*500) : 0;
        var _payCrys = _notTrainedCount ? Math.min(_notTrainedCount*2,20) : 0;
        _showDoneAndReload(_mineHeroes.length + _mineTre.length, _notHeroes.length + _notTre.length, _payCoins, _payCrys);
        resolve();   // 讓外層讀取迴圈 deleteDoc 消化這筆 pending
      };

      _renderRows();
      _updateStatus();
    }catch(_e){ console.warn('[_showOverRestoreReviewModal] 例外', _e); resolve(); }
  });
};

// ════════════════════════════════════════════════════════════════════
// ★ v5.92.0（老師需求 2026-08-20）— UR 超額「學生自己確認並退回」視窗
//   （GM 派發 type='urSurplusReview' → 登入彈出；後端 _fbAdminQueueURSurplusReview）
// ────────────────────────────────────────────────────────────────────
//   老師指示原文：「說明先前 UR 卷使用後沒有消失導致可以重複召喚的問題已修復，
//   該同學因為什麼表現獲得 UR 召喚卷、應該只有幾隻 UR 角色，請確認目前持有的
//   UR 角色數量並將多餘的 UR 角色勾選刪除，老師會退還培育的資源。用親切理性的
//   語氣，讓學生知道自己是退回本來就不該多得的珍貴獎勵。」
//   ★ 必須剛好勾選 N 隻才能送出（N = GM 記錄的超額數），避免退太多或退太少；
//     但「留哪幾隻」完全由學生自己決定。
//   ★ 退還資源一律走 GM 派發當下的培育快照 → _lxpsHeroRefundPlanMerge（單一真相，
//     與 GM 端「🧮 依勾選英雄自動算退回資源」完全同一支，不會兩套口徑）。
//   ★ 順序＝先退資源（只增不減·失敗不傷學生）再移除英雄；任一步失敗都**不 resolve**、
//     不消化這筆通知，改顯示錯誤與「再試一次／稍後再處理」→ 絕不會發生「東西沒了、資源沒補」。
//   ★ 雙版文案（鐵律 1.232）：window._artStyle === 'cute' 走簡單風。
//   ★ 共用 iPad 防呆：沿用 v3.16.91 帳號橫幅＋「這不是我的帳號」切換鈕。
//   放此 block＝與 _showOverRestoreReviewModal 同區，可直接沿用同款 disown／補償通道。
// ════════════════════════════════════════════════════════════════════
window._showURSurplusReviewModal = function(uid, data){
  return new Promise(function(resolve){
    try{
      var _d = data || {};
      var _all = (Array.isArray(_d.heroes) ? _d.heroes : []).filter(function(x){ return x && x.name; });
      if(!_all.length){ resolve(); return; }

      function _esc2(s){ return String(s==null?'':s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
      var _cute = false;
      try{ _cute = (window._artStyle === 'cute'); }catch(_eSty){}

      // ① 只列「現在真的還持有」的 UR（老師若已先手動刪、或學生已在別台處理過 → 自動對齊）
      var _own = null;
      try{ if(typeof advGetUnlockedHeroes === 'function'){ _own = advGetUnlockedHeroes() || []; } }catch(_eOwn){ _own = null; }
      var _items = _all;
      if(Array.isArray(_own) && _own.length){
        var _ownSet = {};
        _own.forEach(function(n){ _ownSet[n] = 1; });
        var _f = _all.filter(function(x){ return _ownSet[x.name]; });
        if(_f.length) _items = _f;   // 全部都查不到就維持原清單（讀取異常時不要讓視窗變空白）
      }
      var _expected = Math.max(0, parseInt(_d.expected, 10) || 0);
      var _need = parseInt(_d.surplus, 10);
      if(isNaN(_need) || _need <= 0) _need = _items.length - _expected;
      if(_need > _items.length) _need = _items.length;
      // 已經不超額了（老師先手動處理過）→ 直接消化這筆通知，不打擾學生
      if(_need <= 0){ resolve(); return; }

      var _picked = _items.map(function(){ return false; });
      var _merit = String(_d.merit || '');
      var _autoRefund = (_d.autoRefund === false) ? false : true;

      var _old = document.getElementById('_urs-review-overlay');
      if(_old) _old.remove();
      var _ov = document.createElement('div');
      _ov.id = '_urs-review-overlay';
      _ov.style.cssText = 'position:fixed;inset:0;z-index:2147483600;background:rgba(8,6,10,0.94);display:flex;flex-direction:column;align-items:center;justify-content:flex-start;backdrop-filter:blur(6px);font-family:"M PLUS Rounded 1c","Nunito",sans-serif;overflow:hidden;';

      var _box = document.createElement('div');
      _box.style.cssText = 'width:100%;max-width:700px;height:100%;height:100dvh;display:flex;flex-direction:column;';

      // ── 標題與說明（親切理性・雙版鐵律1.232）
      var _title = _cute ? '👑 你的 UR 角色數量要確認一下' : '👑 UR 角色數量確認';
      var _meritLine = _merit
        ? (_cute
            ? ('老師當時是因為你<b style="color:#ffe08a;">' + _esc2(_merit) + '</b>，才給你 UR 召喚卷的。')
            : ('老師當初是因為你<b style="color:#ffe08a;">' + _esc2(_merit) + '</b>，才頒給你 UR 召喚卷。'))
        : (_cute
            ? '老師是因為你很棒的表現，才給你 UR 召喚卷的。'
            : '老師當初是因為你的優異表現，才頒給你 UR 召喚卷。');

      var _intro = _cute
        ? ('<div style="font-size:15px;color:#e6e0d2;line-height:1.75;text-align:left;">'
          + '<p style="margin:0 0 9px;">先跟你說一件事，<b style="color:#9effb0;">這不是你做錯什麼</b>，是老師的程式出了問題。</p>'
          + '<p style="margin:0 0 9px;">🔧 之前 <b style="color:#ffd86b;">UR 召喚卷用完之後有時候沒有消失</b>，所以同一張卷被用了好幾次，就多召喚出了 UR 角色。這個問題老師<b style="color:#9effb0;">已經修好了</b>。</p>'
          + '<p style="margin:0 0 9px;">' + _meritLine + '所以你應該有 <b style="color:#ffd86b;font-size:19px;">' + _expected + '</b> 隻 UR 角色。</p>'
          + '<p style="margin:0 0 9px;">你現在有 <b style="color:#ffd86b;font-size:19px;">' + _items.length + '</b> 隻，多了 <b style="color:#ff9a8a;font-size:19px;">' + _need + '</b> 隻。請你自己選出要<b style="color:#ff9a8a;">退回哪 ' + _need + ' 隻</b>，留下你最喜歡的。</p>'
          + '<p style="margin:0 0 9px;">✨ UR 是全遊戲最珍貴的獎勵，全校只有很少人拿得到。把多的放回去，留下來的那幾隻才是你真正憑本事得到的。</p>'
          + '<p style="margin:0;">💚 你花在退回角色身上的<b style="color:#9effb0;">經驗、膠囊、技能書、爆發果實，老師會全部還給你</b>，可以拿去養你自己的英雄，不會白費。</p>'
          + '</div>')
        : ('<div style="font-size:14.5px;color:#e6e0d2;line-height:1.75;text-align:left;">'
          + '<p style="margin:0 0 9px;">老師想先跟你說明一件事——<b style="color:#9effb0;">這不是你的錯</b>，是遊戲程式先前有一個問題。</p>'
          + '<p style="margin:0 0 9px;">🔧 <b style="color:#ffd86b;">UR 召喚卷使用之後，有時候沒有正確消失</b>，導致同一張卷被重複使用，因此多召喚出了 UR 角色。這個問題老師<b style="color:#9effb0;">已經修復完成</b>，之後不會再發生。</p>'
          + '<p style="margin:0 0 9px;">' + _meritLine + '依照發放紀錄，你應該擁有 <b style="color:#ffd86b;font-size:19px;">' + _expected + '</b> 隻 UR 角色。</p>'
          + '<p style="margin:0 0 9px;">目前你持有 <b style="color:#ffd86b;font-size:19px;">' + _items.length + '</b> 隻，比應有的多出 <b style="color:#ff9a8a;font-size:19px;">' + _need + '</b> 隻。請你確認一下自己的 UR 角色，並選出要<b style="color:#ff9a8a;">退回的 ' + _need + ' 隻</b>——留下哪幾隻，由你自己決定。</p>'
          + '<p style="margin:0 0 9px;">✨ UR 是全遊戲最珍貴的獎勵，全校只有極少數同學獲得，<b>正因為稀有才有意義</b>。把多出來的放回去，你手上留下的每一隻，都是你真正憑表現贏來的。</p>'
          + '<p style="margin:0;">💚 你投入在退回角色身上的培育資源——<b style="color:#9effb0;">累積經驗（換成經驗之書）、極限膠囊、技能升級書、超越極限果實，老師會全部退還給你</b>，可以直接拿去培育你自己喜歡的英雄，一點都不會白費。</p>'
          + '</div>');

      var _head = '<div style="flex:0 0 auto;padding:16px 16px 8px;text-align:center;">'
        + '<div style="font-size:23px;font-weight:900;color:#ffd86b;margin-bottom:8px;">' + _title + '</div>'
        + _intro
        + '</div>';

      // ── 帳號身分橫幅（共用 iPad 防呆・v3.16.91 範式）
      var _curEmail = '';
      try{ _curEmail = (window._fbAuth && window._fbAuth.currentUser && window._fbAuth.currentUser.email) || ''; }catch(_eEm){}
      var _rosterLbl = '';
      try{ if(typeof window._getRosterEntry==='function' && typeof window._formatRosterLabel==='function'){ _rosterLbl = window._formatRosterLabel(window._getRosterEntry((_curEmail||'').toLowerCase())) || ''; } }catch(_eRl){}
      // ★ v5.92.0 追加（老師需求）— 顯示名稱（遊戲暱稱）也一起秀出來，學生最認得的是這個
      var _myNick = '';
      try{ _myNick = String(window._playerNickname || '').slice(0, 40); }catch(_eNk){}
      var _acctBanner = '<div style="flex:0 0 auto;margin:8px 14px 10px;padding:10px 14px;background:rgba(46,34,18,0.9);border:2px solid #ffce5a;border-radius:11px;text-align:center;">'
        + '<div style="font-size:12px;color:#ffd86b;font-weight:800;letter-spacing:2px;margin-bottom:3px;">目前登入的帳號</div>'
        + (_myNick ? '<div style="font-size:23px;font-weight:900;color:#fff3d0;line-height:1.25;">' + _esc2(_myNick) + '</div>' : '')
        + (_rosterLbl ? '<div style="font-size:' + (_myNick ? '15px' : '20px') + ';font-weight:900;color:' + (_myNick ? '#ffe8b8' : '#fff3d0') + ';line-height:1.3;">' + _esc2(_rosterLbl) + '</div>' : '')
        + (_curEmail ? '<div style="font-size:12px;color:#cfc6b0;word-break:break-all;margin-top:2px;">' + _esc2(_curEmail) + '</div>' : '')
        + ((!_myNick && !_rosterLbl && !_curEmail) ? '<div style="font-size:15px;color:#ffae8a;font-weight:700;">(讀不到帳號資訊，請重新整理)</div>' : '')
        + '<div style="font-size:12.5px;color:#ffb89a;font-weight:700;margin-top:7px;line-height:1.5;">'
        +   (_cute ? '⚠ 上面是<u>你自己</u>的帳號嗎？是的話請打勾，再往下看。' : '⚠ 請先確認上面顯示的是「<u>你本人</u>」的帳號，再繼續往下。')
        + '</div>'
        + '<label id="_urs-acct-label" style="display:flex;align-items:center;justify-content:center;gap:8px;margin-top:8px;padding:9px 12px;background:rgba(0,0,0,0.3);border:2px solid rgba(255,206,90,0.55);border-radius:9px;cursor:pointer;font-size:14.5px;font-weight:800;color:#fff3d0;touch-action:manipulation;">'
        +   '<input type="checkbox" id="_urs-acct-ok" style="width:20px;height:20px;cursor:pointer;flex:0 0 auto;">'
        +   '<span>' + (_cute ? '✅ 對，這是我的帳號' : '✅ 我確認這是我本人的帳號') + '</span>'
        + '</label>'
        + '<button id="_urs-review-switch" style="margin-top:8px;padding:10px 16px;font-size:13px;font-weight:800;background:rgba(150,60,60,0.32);border:2px solid #ff8a8a;color:#ffd6d6;border-radius:8px;cursor:pointer;font-family:inherit;touch-action:manipulation;">🔄 這不是我的帳號，切換帳號重新登入</button>'
        + '</div>';

      var _scroll = '<div id="_urs-review-scroll" style="flex:1 1 auto;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:4px 14px 14px;"></div>';
      // ★ v5.92.0 追加（老師需求）— 底部兩條互斥路徑：
      //   ①「我同意被收回」必須打勾才能送出（＋帳號本人確認＋剛好勾滿超額數，三個閘門缺一不可）
      //   ②「與事實不符，我要申訴」→ 展開最多 100 字理由，送出後**不移除任何角色**，
      //      走既有 bugReports → 老師在後台回覆，學生用既有「📩 老師的回覆」小視窗收到。
      var _bar = '<div style="flex:0 0 auto;padding:10px 14px calc(12px + env(safe-area-inset-bottom));background:rgba(20,16,24,0.97);border-top:1px solid rgba(255,255,255,0.12);">'
        + '<label id="_urs-agree-label" style="display:flex;align-items:center;gap:9px;padding:10px 12px;margin-bottom:8px;background:rgba(40,70,50,0.35);border:2px solid rgba(120,220,150,0.5);border-radius:9px;cursor:pointer;font-size:14.5px;font-weight:800;color:#dfffe8;touch-action:manipulation;">'
        +   '<input type="checkbox" id="_urs-agree" style="width:20px;height:20px;cursor:pointer;flex:0 0 auto;">'
        +   '<span>' + (_cute ? '我同意把多召喚出來的 UR 英雄還回去' : '我同意被收回多召喚出來的 UR 英雄') + '</span>'
        + '</label>'
        + '<div style="display:flex;gap:10px;align-items:center;">'
        +   '<div id="_urs-review-status" style="flex:1;font-size:13px;color:#ffcf8a;line-height:1.45;"></div>'
        +   '<button id="_urs-review-submit" disabled style="padding:12px 24px;font-size:16px;font-weight:900;background:#3a3030;border:2px solid #555;color:#888;border-radius:8px;cursor:not-allowed;font-family:inherit;touch-action:manipulation;flex:0 0 auto;">' + (_cute ? '送出' : '確認送出') + '</button>'
        + '</div>'
        + '<div style="margin-top:9px;padding-top:8px;border-top:1px dashed rgba(255,255,255,0.14);">'
        +   '<label id="_urs-appeal-label" style="display:flex;align-items:center;gap:9px;padding:9px 12px;background:rgba(70,50,90,0.32);border:2px solid rgba(180,150,230,0.5);border-radius:9px;cursor:pointer;font-size:14px;font-weight:800;color:#e6dcff;touch-action:manipulation;">'
        +     '<input type="checkbox" id="_urs-appeal-on" style="width:19px;height:19px;cursor:pointer;flex:0 0 auto;">'
        +     '<span>' + (_cute ? '🙋 跟老師說的不一樣，我要申訴' : '🙋 與事實不符，我要申訴') + '</span>'
        +   '</label>'
        +   '<div id="_urs-appeal-box" style="display:none;margin-top:8px;">'
        +     '<div style="font-size:12.5px;color:#c8bcdd;line-height:1.6;margin-bottom:6px;">'
        +       (_cute
                  ? '把你覺得哪裡不對寫下來（最多 100 字），老師看到會在遊戲裡回覆你（右下角會跳小卡片）。送出申訴<b style="color:#9effb0;">不會移除你的任何角色</b>。'
                  : '請簡短說明哪裡與事實不符（最多 100 字）。老師會在遊戲內回覆你，回覆會保留在「🐛 卡死或 BUG 回報 → 📬 管理員回信」裡隨時可查。送出申訴<b style="color:#9effb0;">不會移除你的任何角色</b>，資料維持原狀。')
        +     '</div>'
        +     '<textarea id="_urs-appeal-text" maxlength="100" rows="3" placeholder="' + (_cute ? '例：這幾隻是老師上次比賽發給我的' : '例：其中一隻是上學期科展得獎老師另外發的') + '" style="width:100%;box-sizing:border-box;padding:9px 10px;font-size:14.5px;line-height:1.55;background:rgba(0,0,0,0.45);border:2px solid rgba(180,150,230,0.5);color:#fff;border-radius:8px;font-family:inherit;resize:none;"></textarea>'
        +     '<div style="display:flex;gap:10px;align-items:center;margin-top:6px;">'
        +       '<div id="_urs-appeal-count" style="flex:1;font-size:12px;color:#a8a0bb;">0 / 100</div>'
        +       '<button id="_urs-appeal-send" disabled style="padding:10px 18px;font-size:14.5px;font-weight:900;background:#3a3040;border:2px solid #555;color:#888;border-radius:8px;cursor:not-allowed;font-family:inherit;touch-action:manipulation;flex:0 0 auto;">' + (_cute ? '送出申訴' : '送出申訴給老師') + '</button>'
        +     '</div>'
        +   '</div>'
        + '</div>'
        + '</div>';

      _box.innerHTML = _head + _acctBanner + _scroll + _bar;
      _ov.appendChild(_box);
      document.body.appendChild(_ov);

      var _scrollEl = document.getElementById('_urs-review-scroll');
      var _submitBtn = document.getElementById('_urs-review-submit');
      var _statusEl  = document.getElementById('_urs-review-status');
      // ★ v5.92.0 追加（老師需求）— 三個閘門的控制項 + 申訴區
      var _acctOkEl   = document.getElementById('_urs-acct-ok');
      var _agreeEl    = document.getElementById('_urs-agree');
      var _appealOnEl = document.getElementById('_urs-appeal-on');
      var _appealBox  = document.getElementById('_urs-appeal-box');
      var _appealTxt  = document.getElementById('_urs-appeal-text');
      var _appealCnt  = document.getElementById('_urs-appeal-count');
      var _appealSend = document.getElementById('_urs-appeal-send');

      function _acctOk(){ return !!(_acctOkEl && _acctOkEl.checked); }
      function _agreeOk(){ return !!(_agreeEl && _agreeEl.checked); }

      // 申訴模式：勾起來就把「同意收回」整條路徑關掉（兩條路互斥，避免同時按到）
      function _syncAppealMode(){
        var _on = !!(_appealOnEl && _appealOnEl.checked);
        if(_appealBox) _appealBox.style.display = _on ? 'block' : 'none';
        if(_on && _agreeEl && _agreeEl.checked) _agreeEl.checked = false;
        _updateAppealBtn();
        _updateStatus();
      }
      function _updateAppealBtn(){
        if(!_appealSend) return;
        var _len = _appealTxt ? String(_appealTxt.value || '').trim().length : 0;
        if(_appealCnt) _appealCnt.textContent = (_appealTxt ? String(_appealTxt.value || '').length : 0) + ' / 100';
        var _ready = _acctOk() && _len > 0;
        _appealSend.disabled = !_ready;
        _appealSend.style.cssText = _ready
          ? 'padding:10px 18px;font-size:14.5px;font-weight:900;background:#b48ce0;border:2px solid #d8bcff;color:#2a1840;border-radius:8px;cursor:pointer;font-family:inherit;touch-action:manipulation;flex:0 0 auto;'
          : 'padding:10px 18px;font-size:14.5px;font-weight:900;background:#3a3040;border:2px solid #555;color:#888;border-radius:8px;cursor:not-allowed;font-family:inherit;touch-action:manipulation;flex:0 0 auto;';
      }
      if(_acctOkEl)   _acctOkEl.onchange   = function(){ _updateAppealBtn(); _updateStatus(); };
      if(_agreeEl)    _agreeEl.onchange    = function(){
        // 勾「同意」時自動收起申訴（互斥）
        if(_agreeEl.checked && _appealOnEl && _appealOnEl.checked){ _appealOnEl.checked = false; _syncAppealMode(); return; }
        _updateStatus();
      };
      if(_appealOnEl) _appealOnEl.onchange = _syncAppealMode;
      if(_appealTxt){
        _appealTxt.oninput = _updateAppealBtn;
        _appealTxt.onkeyup = _updateAppealBtn;
      }
      if(_appealSend){
        _appealSend.onclick = async function(){
          if(_appealSend.disabled) return;
          var _reason = String(_appealTxt ? _appealTxt.value : '').trim().slice(0, 100);
          if(!_reason) return;
          if(!confirm((_cute ? '要把這段話送給老師嗎？\n\n' : '確定要送出申訴給老師嗎？\n\n')
            + '「' + _reason + '」\n\n'
            + (_cute ? '送出後你的角色都不會被移除，等老師回覆你。' : '送出後不會移除你的任何角色，老師會在遊戲內回覆你。'))) return;
          _appealSend.disabled = true; _appealSend.textContent = _cute ? '送出中…' : '送出中…';
          try{
            if(typeof window._fbSubmitURSurplusAppeal !== 'function') throw new Error('申訴通道未載入');
            await window._fbSubmitURSurplusAppeal(uid, {
              reason:   _reason,
              merit:    _merit,
              expected: _expected,
              actual:   _items.length,
              surplus:  _need,
              nickname: _myNick,
              heroes:   _items
            });
          }catch(_eAp){
            console.warn('[UR 自審 申訴] 送出失敗', _eAp);
            _appealSend.disabled = false; _appealSend.textContent = _cute ? '送出申訴' : '送出申訴給老師';
            _statusEl.innerHTML = '<span style="color:#ff9a8a;font-weight:800;">'
              + (_cute ? '申訴沒送出去，網路好像不太順，請再按一次。' : '申訴送出失敗（沒有任何角色被移除），請再試一次：')
              + _esc2(String(_eAp && _eAp.message || _eAp)) + '</span>';
            return;
          }
          _showAppealDone(_reason);
          resolve();   // 消化這封通知（老師若判定申訴不成立，會重新寄一次）
        };
      }

      // 申訴送出後的畫面（★ 不 reload：什麼都沒改，沒必要打斷學生）
      function _showAppealDone(reason){
        _ov.innerHTML = '<div style="margin:auto;max-width:470px;width:100%;text-align:center;padding:28px;">'
          + '<div style="font-size:27px;font-weight:900;color:#d8bcff;margin-bottom:14px;">🙋 ' + (_cute ? '申訴送出去了！' : '申訴已送出') + '</div>'
          + '<div style="font-size:15px;color:#e6e0d2;line-height:1.75;margin-bottom:14px;text-align:left;">'
          +   '<div style="margin-bottom:9px;padding:10px 12px;background:rgba(70,50,90,0.35);border:1.5px solid rgba(180,150,230,0.5);border-radius:9px;color:#e6dcff;">「' + _esc2(reason) + '」</div>'
          +   '<div style="margin-bottom:8px;color:#9effb0;font-weight:800;">' + (_cute ? '✅ 你的角色一隻都沒有被移除。' : '✅ 你的角色完全沒有被移除，資料維持原狀。') + '</div>'
          +   '<div>' + (_cute
                ? '老師看到之後會在遊戲裡回覆你，畫面右下角會跳出「📨 老師回覆了你的回報」的小卡片，點它就能看。<br><br>之後想再看一次，就到關卡畫面下面的「🐛 卡死或 BUG 回報」→「📬 管理員回信」，你送過的每一則和老師的回覆都在裡面。'
                : '老師收到後會在遊戲內回覆你，屆時畫面右下角會出現「📨 老師回覆了你的回報」小卡（同時回報按鈕會亮紅點），點開即可閱讀全文。<br><br>之後要重看，可從關卡畫面下方「🐛 卡死或 BUG 回報」進入「📬 管理員回信」分頁，你歷次送出的內容與老師的每一則回覆都會保留在那裡。') + '</div>'
          + '</div>'
          + '<div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center;">'
          +   '<button id="_urs-appeal-open-replies" style="padding:13px 22px;font-size:15px;font-weight:900;background:linear-gradient(135deg,#5a9fe0,#3a7fc0);border:2px solid #9fd6ff;color:#fff;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">📬 ' + (_cute ? '看老師的回信' : '開啟管理員回信') + '</button>'
          +   '<button id="_urs-appeal-close" style="padding:13px 26px;font-size:15px;font-weight:900;background:#ffce5a;border:2px solid #ffe08a;color:#3a2c00;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">' + (_cute ? '知道了' : '我知道了') + '</button>'
          + '</div>';
        try{
          var _cb = document.getElementById('_urs-appeal-close');
          if(_cb) _cb.onclick = function(){ try{ if(_ov && _ov.parentNode) _ov.remove(); }catch(_){} };
          // ★ v5.92.0（老師需求）— 一鍵直達「📬 管理員回信」分頁
          //   ⚠ 必須先移除本 overlay 再開：本視窗 z-index 2147483600 遠高於 BUG 回報視窗，
          //     不先關掉會把回信視窗整個蓋住，學生會以為按了沒反應。
          var _orb = document.getElementById('_urs-appeal-open-replies');
          if(_orb) _orb.onclick = function(){
            try{ if(_ov && _ov.parentNode) _ov.remove(); }catch(_){}
            try{
              if(typeof window._showBugReportDialog === 'function'){
                window._showBugReportDialog('ur_surplus_appeal_followup', { openReplies:true });
              }
            }catch(_eOpen){ console.warn('[UR 申訴] 開啟管理員回信失敗', _eOpen); }
          };
        }catch(_){}
      }

      var _switchBtn = document.getElementById('_urs-review-switch');
      if(_switchBtn){
        _switchBtn.onclick = function(){
          try{ if(_ov && _ov.parentNode) _ov.remove(); }catch(_eRm){}
          resolve({ switched:true });   // 不消化本帳號的通知（正在登出）→ 正確的學生登入時會再跳
          try{ if(typeof window._fbSignOut==='function') window._fbSignOut(); }catch(_eSo){ console.warn('[UR 自審 切換帳號] 登出失敗', _eSo); }
        };
      }

      function _trainTxt(it){
        var _t = [];
        if(it.lv > 1) _t.push('Lv' + it.lv);
        var _capN = (it.capsule ? ((it.capsule.hp||0)+(it.capsule.atk||0)+(it.capsule.sp||0)+(it.capsule.spd||0)) : 0);
        if(_capN) _t.push('🧪膠囊×' + _capN);
        if((it.s1||0) + (it.s2||0)) _t.push('📖技能書×' + ((it.s1||0) + (it.s2||0)));
        if(it.burst) _t.push('🍑果實×' + it.burst);
        return _t.length ? _t.join('　') : (_cute ? '還沒開始培育' : '尚未投入培育資源');
      }

      function _renderRows(){
        var html = _items.map(function(it, i){
          var _sel = _picked[i];
          var _gm = it.byGmDirect
            ? ('<span style="display:inline-block;margin-left:6px;padding:1px 7px;border-radius:8px;background:rgba(40,110,60,0.4);border:1px solid #7fdca0;color:#dfffe8;font-size:11.5px;font-weight:800;">'
               + (_cute ? '老師直接送你的' : '老師直接頒發') + '</span>')
            : '';
          return '<div style="margin-bottom:9px;padding:11px 12px;background:' + (_sel ? 'rgba(90,30,38,0.6)' : 'rgba(30,26,34,0.72)')
            + ';border:2px solid ' + (_sel ? '#ff6b7f' : 'rgba(255,255,255,0.1)') + ';border-radius:10px;">'
            + '<div style="font-size:16px;font-weight:800;color:#ffe0f0;margin-bottom:4px;">🦸 ' + _esc2(it.name) + _gm + '</div>'
            + '<div style="font-size:12.5px;color:#bcd;margin-bottom:9px;">' + (_cute ? '你的培育：' : '培育投入：') + _esc2(_trainTxt(it)) + '</div>'
            + '<button class="_urs-pick" data-i="' + i + '" style="width:100%;min-height:46px;padding:11px 8px;font-size:15px;font-weight:800;border-radius:8px;cursor:pointer;font-family:inherit;touch-action:manipulation;'
            +   (_sel ? 'background:#7a2330;border:2px solid #ff6b7f;color:#ffe0e4;' : 'background:rgba(80,140,90,0.14);border:2px solid rgba(150,180,160,0.45);color:#cfe0d4;') + '">'
            +   (_sel ? (_cute ? '✅ 這隻要退回（再按一次取消）' : '✅ 已選擇退回這一隻（再按一次取消）')
                      : (_cute ? '選這隻退回' : '選擇退回這一隻'))
            + '</button>'
            + '</div>';
        }).join('');
        _scrollEl.innerHTML = '<div style="font-size:13.5px;color:#ffd98c;font-weight:800;margin:4px 0 8px;">'
          + (_cute ? ('👇 你的 UR 角色（要選 ' + _need + ' 隻退回）') : ('👇 你目前擁有的 UR 角色（請選出 ' + _need + ' 隻退回）'))
          + '</div>' + html;
        Array.prototype.forEach.call(_scrollEl.querySelectorAll('._urs-pick'), function(b){
          b.onclick = function(){
            var i = parseInt(b.getAttribute('data-i'), 10);
            _picked[i] = !_picked[i];
            _renderRows(); _updateStatus();
          };
        });
      }

      function _cnt(){ var n = 0; _picked.forEach(function(v){ if(v) n++; }); return n; }

      function _updateStatus(){
        var n = _cnt();
        // ★ v5.92.0（老師需求）— 送出需同時滿足三個閘門，缺一不可；
        //   訊息一次只講「下一件要做的事」，不要一口氣列三條讓小朋友慌。
        var _appealOn = !!(_appealOnEl && _appealOnEl.checked);
        var _ok = false, _msg = '', _color = '#ffcf8a';
        if(_appealOn){
          _msg = _cute ? '你選了申訴 → 請在下面寫理由再送出' : '目前為申訴模式 → 請在下方填寫理由後送出申訴';
          _color = '#d8bcff';
        } else if(!_acctOk()){
          _msg = _cute ? '請先在上面打勾「這是我的帳號」' : '請先在上方勾選「我確認這是我本人的帳號」';
          _color = '#ffb89a';
        } else if(n < _need){
          _msg = _cute ? ('還要再選 ' + (_need - n) + ' 隻') : ('還需要選擇 ' + (_need - n) + ' 隻');
        } else if(n > _need){
          _msg = _cute ? ('選太多了！只要 ' + _need + ' 隻') : ('選太多了，只需要退回 ' + _need + ' 隻');
          _color = '#ff9a8a';
        } else if(!_agreeOk()){
          _msg = _cute ? '最後一步：請勾「我同意把多的還回去」' : '最後一步：請勾選「我同意被收回多召喚出來的 UR 英雄」';
          _color = '#9fd6ff';
        } else {
          _ok = true;
          _msg = _cute ? ('好了！已經選好 ' + n + ' 隻，可以送出') : ('已選好 ' + n + ' 隻，可以送出了');
          _color = '#9effb0';
        }
        _statusEl.innerHTML = '<span style="color:' + _color + ';">' + _msg + '</span>';
        _submitBtn.disabled = !_ok;
        _submitBtn.style.cssText = _ok
          ? 'padding:12px 24px;font-size:16px;font-weight:900;background:#ffce5a;border:2px solid #ffe08a;color:#3a2c00;border-radius:8px;cursor:pointer;font-family:inherit;touch-action:manipulation;box-shadow:0 2px 10px rgba(255,206,90,0.4);flex:0 0 auto;'
          : 'padding:12px 24px;font-size:16px;font-weight:900;background:#3a3030;border:2px solid #555;color:#888;border-radius:8px;cursor:not-allowed;font-family:inherit;touch-action:manipulation;flex:0 0 auto;';
      }

      // 最終確認子視窗（z 高於主視窗 → 絕不被蓋住）
      function _showFinalConfirm(names, labels, cb){
        var _o2 = document.getElementById('_urs-confirm-overlay');
        if(_o2) _o2.remove();
        var _rc = document.createElement('div');
        _rc.id = '_urs-confirm-overlay';
        _rc.style.cssText = 'position:fixed;inset:0;z-index:2147483640;background:rgba(0,0,0,0.84);display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(3px);font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
        _rc.innerHTML = '<div style="max-width:460px;width:100%;max-height:86vh;overflow-y:auto;background:linear-gradient(160deg,#2a1e16,#160f0c);border:2.5px solid #ffb070;border-radius:16px;padding:20px;box-shadow:0 10px 40px rgba(0,0,0,0.6);">'
          + '<div style="font-size:20px;font-weight:900;color:#ffd86b;text-align:center;margin-bottom:12px;">' + (_cute ? '再確認一次唷' : '請再確認一次') + '</div>'
          + '<div style="font-size:14.5px;color:#f0e6d8;line-height:1.7;margin-bottom:12px;">'
          +   (_cute ? '你要退回這幾隻：' : '你選擇退回以下角色：')
          +   '<div style="margin:7px 0 0;padding:9px 11px;background:rgba(120,40,50,0.35);border:1px solid #ff8a9a;border-radius:9px;color:#ffd6dc;font-weight:800;">' + _esc2(names.join('、')) + '</div>'
          + '</div>'
          + (labels.length
              ? ('<div style="font-size:14px;color:#dfffe8;line-height:1.7;margin-bottom:14px;">'
                 + (_cute ? '💚 老師會還你：' : '💚 老師會退還給你的培育資源：')
                 + '<div style="margin:7px 0 0;padding:9px 11px;background:rgba(40,110,60,0.3);border:1px solid #7fdca0;border-radius:9px;font-weight:800;">' + _esc2(labels.join('、')) + '</div>'
                 + '</div>')
              : ('<div style="font-size:13px;color:#c0b8a8;margin-bottom:14px;">' + (_cute ? '這幾隻還沒培育，所以沒有東西要還你。' : '這幾隻尚未投入培育資源，因此沒有可退還的項目。') + '</div>'))
          + '<div style="display:flex;gap:10px;">'
          +   '<button id="_urs-cf-cancel" style="flex:1;padding:13px 6px;font-size:15px;font-weight:800;background:rgba(120,140,90,0.2);border:2px solid #6ec06e;color:#cfe8b0;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">✗ 再想一下</button>'
          +   '<button id="_urs-cf-ok" style="flex:1;padding:13px 6px;font-size:15px;font-weight:800;background:#ffce5a;border:2px solid #ffe08a;color:#3a2c00;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">✓ 確定退回</button>'
          + '</div>'
          + '</div>';
        document.body.appendChild(_rc);
        document.getElementById('_urs-cf-cancel').onclick = function(){ _rc.remove(); cb(false); };
        document.getElementById('_urs-cf-ok').onclick     = function(){ _rc.remove(); cb(true); };
      }

      function _showDone(names, labels){
        _ov.innerHTML = '<div style="margin:auto;max-width:470px;width:100%;text-align:center;padding:28px;">'
          + '<div style="font-size:27px;font-weight:900;color:#9effb0;margin-bottom:14px;">✅ ' + (_cute ? '完成了，謝謝你！' : '完成，謝謝你的配合！') + '</div>'
          + '<div style="font-size:15px;color:#e6e0d2;line-height:1.75;margin-bottom:12px;text-align:left;">'
          +   '<div style="margin-bottom:8px;">' + (_cute ? '已經退回：' : '已退回：') + '<b style="color:#ffae8a;">' + _esc2(names.join('、')) + '</b></div>'
          +   (labels.length ? ('<div style="margin-bottom:8px;">' + (_cute ? '老師還你：' : '已退還培育資源：') + '<b style="color:#9effb0;">' + _esc2(labels.join('、')) + '</b>（' + (_cute ? '在背包裡' : '請到背包查看') + '）</div>') : '')
          +   '<div style="color:#ffd86b;">' + (_cute ? '你留下來的 UR 角色，是你自己努力得來的，好好珍惜它們！' : '你留下的 UR 角色，每一隻都是你憑自己的表現贏來的，好好珍惜。') + '</div>'
          + '</div>'
          + '<div style="font-size:13px;color:#c0b8a8;margin-bottom:18px;">' + (_cute ? '馬上幫你重新整理…' : '即將重新整理讓變更生效…') + '</div>'
          + '<button onclick="_lxpsReloadKeepLogin()" style="padding:13px 30px;font-size:16px;font-weight:900;background:#ffce5a;border:2px solid #ffe08a;color:#3a2c00;border-radius:9px;cursor:pointer;font-family:inherit;touch-action:manipulation;">立即重新整理</button>'
          + '</div>';
        setTimeout(function(){ try{ window._lxpsReloadKeepLogin(); }catch(_){ try{ location.reload(); }catch(__){} } }, 4000);   // ★ v5.141.0 — 自家重載設放行旗標
      }

      // 失敗處理：不 resolve（不消化通知）→ 讓學生重試，或稍後再處理（下次登入會再跳）
      function _fail(msg){
        _submitBtn.disabled = false;
        _submitBtn.textContent = '再試一次';
        _submitBtn.style.cssText = 'padding:12px 24px;font-size:16px;font-weight:900;background:#ffce5a;border:2px solid #ffe08a;color:#3a2c00;border-radius:8px;cursor:pointer;font-family:inherit;touch-action:manipulation;';
        _statusEl.innerHTML = '<span style="color:#ff9a8a;font-weight:800;">' + _esc2(msg) + '</span>'
          + ' <button id="_urs-later" style="margin-left:8px;padding:6px 11px;font-size:12px;font-weight:800;background:rgba(90,90,110,0.4);border:1.5px solid #99a;color:#dde;border-radius:7px;cursor:pointer;font-family:inherit;touch-action:manipulation;">'
          + (_cute ? '晚點再處理' : '稍後再處理') + '</button>';
        try{
          var _lb = document.getElementById('_urs-later');
          if(_lb) _lb.onclick = function(){
            try{ if(_ov && _ov.parentNode) _ov.remove(); }catch(_){}
            resolve({ postponed:true });   // 不刪這筆通知 → 下次登入再跳
          };
        }catch(_){}
      }

      _submitBtn.onclick = function(){
        if(_submitBtn.disabled) return;
        if(_cnt() !== _need) return;
        // ★ v5.92.0 — 按下當下再複查一次三個閘門（防 DOM 被外力改動或狀態不同步）
        if(!_acctOk() || !_agreeOk()){ _updateStatus(); return; }
        if(_appealOnEl && _appealOnEl.checked){ _updateStatus(); return; }
        var _names = [], _snaps = [];
        _items.forEach(function(it, i){ if(_picked[i]){ _names.push(it.name); _snaps.push(it); } });
        // 依 GM 記錄的培育快照算退款（單一真相，與 GM 端同一支）
        var _plan = { backpack:{}, labels:[] };
        try{
          if(typeof window._lxpsHeroRefundPlanMerge === 'function') _plan = window._lxpsHeroRefundPlanMerge(_snaps) || _plan;
        }catch(_ePlan){ console.warn('[UR 自審] 退款計算失敗', _ePlan); }
        var _labels = (_autoRefund && _plan.labels) ? _plan.labels : [];
        _showFinalConfirm(_names, _labels, function(ok){
          if(!ok) return;
          _submitBtn.disabled = true;
          _submitBtn.textContent = '處理中…';
          _statusEl.innerHTML = '<span style="color:#9fd6ff;">' + (_cute ? '正在幫你處理…' : '正在處理，請稍候…') + '</span>';
          (async function(){
            // ★ 順序：先退資源（只增不減，即使後面失敗也不會害學生虧）→ 再移除英雄
            try{
              if(_autoRefund && _plan.backpack && Object.keys(_plan.backpack).length){
                if(typeof window._fbCompensatePlayer !== 'function') throw new Error('補償通道未載入');
                // ★ v5.126.0 — 加逾時保護（寫入佇列塞滿時 Firestore 不 reject，會永遠排隊 ⇒ 卡在「處理中…」）
                await window._lxpsFbAwait(window._fbCompensatePlayer(uid, {
                  reason: 'UR 超額自審退回·培育資源退還(v5.92.0)',
                  backpack: _plan.backpack
                }), 'UR超額自審·退還資源');
              }
            }catch(_e1){
              console.warn('[UR 自審] 退還資源失敗', _e1);
              _fail(_cute ? '網路好像不太順，資源還沒還給你，所以先不會移除角色。' : '退還資源失敗（角色尚未移除，你不會有任何損失）：' + String(_e1 && _e1.message || _e1));
              return;
            }
            try{
              // ★ v5.92.0（老師需求）— 改走三槽同寫版：學生已明示同意 → 主檔 + live + safe
              //   三槽都寫 admin_delete 帳本，任一殘槽合併都不會把這幾隻復活。
              //   （原 _fbStudentDisownHeroes 只寫主檔，reload 前的存檔或殘槽 union 有機會復活。）
              if(typeof window._fbStudentSurplusURRemove !== 'function') throw new Error('移除通道未載入');
              // ★ v5.126.0 — 同上加逾時保護
              var _r = await window._lxpsFbAwait(window._fbStudentSurplusURRemove(uid, _names, {
                reason: '學生於「UR 角色數量確認」視窗勾選同意·退回多召喚出來的 UR(v5.92.0)'
              }), 'UR超額自審·移除英雄');
              if(!_r || _r.ok !== true) throw new Error((_r && _r.reason) || 'unknown');
            }catch(_e2){
              console.warn('[UR 自審] 移除英雄失敗', _e2);
              _fail(_cute ? '網路好像不太順，請再按一次試試看。' : '移除角色失敗（培育資源已先退還給你）：' + String(_e2 && _e2.message || _e2));
              return;
            }
            _showDone(_names, _labels);
            resolve();   // 讓外層讀取迴圈消化這筆通知
          })();
        });
      };

      _renderRows();
      _updateAppealBtn();   // ★ v5.92.0 — 初始化字數計數與申訴鈕狀態
      _updateStatus();
    }catch(_e){ console.warn('[_showURSurplusReviewModal] 例外', _e); resolve(); }
  });
};

// ════════════════════════════════════════════════════════════════════
// ★ v5.99.0（老師 2026-08-21 需求）— 「召喚卷確認」學生自我回報視窗
// ────────────────────────────────────────────────────────────────────
// 老師指示原文：「告訴學生：你曾經因為課堂表現優良獲得老師發送的 UR／至寶自選卷
//   幾張，但是目前查到的持有數量不符，請到 GM 獎勵信箱或召喚星空做一次確認」
//   ① 有拿到召喚卷，還沒使用
//   ② 有拿到召喚卷，使用了但沒有獲得角色／至寶（BUG，老師之後補發）
//   ③ 有拿到召喚卷，曾經用過但券沒消失，可以繼續召喚（BUG）
//   ④ 沒拿到召喚卷
//   ⑤ 其他說明
//
// ★★ 本視窗**完全不動任何資料**：不移除角色、不扣券、不補發。純問卷。★★
