// ★★ v5.101.0(老師 2026-08-21 裁定五·丙)— 中國關答題也給中華三至寶經驗 ★★
//   背景(本輪稽核發現):至寶經驗三個來源全部寫死 `_adventureStage === 'taiwan'`
//   或 `subject === '台灣環島'` ⇒ 中華三至寶(與 8 件龍王至寶一樣)**完全無法從戰鬥取得經驗**,
//   唯一途徑是 📜至寶經驗卷軸(+10 EXP/張)。Lv1→10 需 540 EXP ＋ 315,000 知識幣
//   = 54 張卷軸/件、三件 162 張 ⇒ 中國關開放後學生實質練不動。
//   ────────────────────────────────────────────────────────────────────────
//   老師裁定丙:中國關答題**三件各 +1**(不分路線)——官渡/涿鹿兩條不掉至寶的路線同樣給,
//   等於那兩線是「練至寶的甜點」,鼓勵學生回頭刷隱藏線。
//   數量口徑完全對齊台灣關:BOSS 戰答對 = 每件 +5;小怪戰/菁英戰答對 = 每件 +1。
//   ★ 只發給「已擁有」的至寶(_getTaiwanTreasureRecord 非 null)——沒打到那條路線就沒有那件,
//     不會憑空生出至寶(與台灣關 `_twRec` 守門同款)。
//   ★ 走既有 _addTaiwanTreasureExp 單一真相 ⇒ 審查凍結、知識幣不足暫緩、滿級、升級視窗、
//     等級獎章全部自動沿用,本函式一行都不重寫。
//   ★ 知識王刻意不接:v5.64.0 已把「中國關」排除於知識王科目池,該路徑不存在。
//   ★ 知識預習頁刻意不接:台灣關無對照(預習本就不給至寶經驗)。
//   ★ 龍王 8 件至寶維持「只能靠至寶經驗卷軸」(老師 2026-08-21 裁定六),本函式不涉及。
// ════════════════════════════════════════════════════════════════════════════
window._CHINA_TREASURE_IDS = ['dashen_whip', 'jingu_bang', 'qinglong_blade'];
window._chinaAddTreasureExpAll = function(amount, tag){
  try{
    if(typeof _adventureStage === 'undefined' || _adventureStage !== 'china') return 0;   // 中國關守門
    if(typeof _addTaiwanTreasureExp !== 'function') return 0;
    var _amt = (typeof amount === 'number' && amount > 0) ? amount : 1;
    var _n = 0;
    window._CHINA_TREASURE_IDS.forEach(function(_tid){
      try{
        var _rec = (typeof _getTaiwanTreasureRecord === 'function') ? _getTaiwanTreasureRecord(_tid) : null;
        if(!_rec) return;                      // 尚未取得該件 → 不發(不會憑空生出至寶)
        _addTaiwanTreasureExp(_tid, _amt);
        _n++;
      }catch(_eOne){}
    });
    if(_n > 0){ try{ console.log('[中華至寶 EXP] ' + (tag || '') + ' 已擁有 ' + _n + ' 件,各 +' + _amt + ' EXP'); }catch(_){} }
    return _n;
  }catch(_eCnTx){ console.warn('[中華至寶 EXP] 失敗:', _eCnTx); return 0; }
};
// 答對題目時為當前關卡的至寶累積經驗(由戰鬥流程呼叫)
// ★ v1.1.0 — 升級需要花費知識幣;若知識幣不足則 EXP 累積但不升級(等玩家湊夠錢)
function _addTaiwanTreasureExp(id, amount){
  // ★ v3.16.31 — 至寶審查凍結:待審查中的至寶不累積經驗/不升級(靜默·鏡像英雄 addHeroExp·不打斷戰鬥)。
  if(window._isAuditPendingTreasure && window._isAuditPendingTreasure(id)) return;
  const rec = _taiwanTreasureData[id];
  if(!rec || rec.lv >= TAIWAN_TREASURE_MAX_LV) return;
  rec.exp = (rec.exp || 0) + (amount || 1);
  // 檢查升級
  let need = _getTaiwanTreasureExpForNextLv(rec.lv);
  while(need > 0 && rec.exp >= need && rec.lv < TAIWAN_TREASURE_MAX_LV){
    // ★ v1.1.0 — 升級前先檢查知識幣是否足夠
    const _coinNeed = _getTaiwanTreasureCoinForNextLv(rec.lv);
    const _curCoins = (typeof _knowledgeCoins !== 'undefined') ? _knowledgeCoins : 0;
    if(_curCoins < _coinNeed){
      try{
        const _treasName = TAIWAN_TREASURES[id] ? TAIWAN_TREASURES[id].name : id;
        console.log('[至寶升級暫緩] '+_treasName+' EXP 已滿(Lv'+rec.lv+'→'+(rec.lv+1)+')但知識幣不足:需 '+_coinNeed.toLocaleString()+' / 持有 '+_curCoins.toLocaleString());
        if(typeof _showInGameToast === 'function'){
          _showInGameToast('💎 ['+_treasName+'] 經驗已滿!需 '+_coinNeed.toLocaleString()+' 💰升級(目前 '+_curCoins.toLocaleString()+')', '#ffaa44', 4000);
        }
      }catch(_){}
      break; // 跳出 while,不升級也不扣 EXP(等玩家湊夠錢再來)
    }
    // 扣知識幣 + 扣 EXP + 升級
    try{
      _knowledgeCoins = (_knowledgeCoins || 0) - _coinNeed;
      try{ _logCoinTx(-_coinNeed, '消費:升級至寶'); }catch(_){}
      if(typeof _syncCoinsDisplay === 'function') _syncCoinsDisplay();
    }catch(_){}
    rec.exp -= need;
    rec.lv++;
    try{
      const _treasName2 = TAIWAN_TREASURES[id] ? TAIWAN_TREASURES[id].name : id;
      console.log('[至寶升級] '+_treasName2+' 升至 Lv'+rec.lv+' (花費 '+_coinNeed.toLocaleString()+' 💰)');
      // ★ v1.0.20260501.4870 — 移除升級 toast 訊息
      //   原本會顯示「🎊 [至寶名] 升至 LvN!花費 XX,XXX 💰」橫幅在畫面上方,
      //   訊息太長換行造成蓋住中央升級視窗(_showTreasureLevelUpModal)。
      //   中央視窗已包含至寶名稱和等級,訊息冗餘 → 直接移除 toast。
      //   (花費資訊保留在 console.log 與遊戲記錄 log 中,需要時可查)
      if(typeof log === 'function') log('🎊 至寶 ['+_treasName2+'] 升級至 Lv'+rec.lv+'(花費 '+_coinNeed.toLocaleString()+' 知識幣)!');
      // ★ v1.0.20260501.4840 — 至寶升級時排入中央視窗(仿英雄升級風格)
      //   queue 機制延遲 1.5 秒,讓戰鬥動畫先跑完,多枚同時升級會依序顯示
      try{
        const _tDef = TAIWAN_TREASURES[id];
        if(typeof _enqueueTreasureLevelUp === 'function'){
          _enqueueTreasureLevelUp({
            id: id,
            name: _tDef ? _tDef.name : id,
            iconUrl: _tDef ? _tDef.iconUrl : null,
            icon: _tDef ? _tDef.icon : '💎',
            lv: rec.lv
          });
        }
      }catch(_){}
    }catch(_){}
    need = _getTaiwanTreasureExpForNextLv(rec.lv);
  }
  _saveTaiwanTreasureData();
  // ★ v1.1.0 — 升級後觸發等級獎章檢查
  try{ if(typeof window._checkTaiwanTreasureLvMedals === 'function') window._checkTaiwanTreasureLvMedals(); }catch(_){}
}
function _equipTaiwanTreasure(treasureId, heroName){
  const def = TAIWAN_TREASURES[treasureId];
  const rec = _taiwanTreasureData[treasureId];
  if(!def || !rec) return false;
  const _slot2Unlocked = (typeof _isHeroSlot2Unlocked === 'function') && _isHeroSlot2Unlocked(heroName);
  const _maxSlots = _slot2Unlocked ? 2 : 1;
  // 取得該英雄目前已裝的至寶(排除本身,因為本身可能已裝在這英雄上)
  const _curOnHero = Object.keys(_taiwanTreasureData).filter(otherId => {
    if(otherId === treasureId) return false;
    const otherRec = _taiwanTreasureData[otherId];
    return otherRec && otherRec.equippedTo === heroName;
  });
  // 處理同 slot 衝突:同 slot 第二件會自動換掉同 slot 那件
  Object.keys(_taiwanTreasureData).forEach(otherId => {
    if(otherId === treasureId) return;
    const otherDef = TAIWAN_TREASURES[otherId];
    const otherRec = _taiwanTreasureData[otherId];
    if(otherDef && otherRec && otherDef.slot === def.slot && otherRec.equippedTo === heroName){
      otherRec.equippedTo = null;
    }
  });
  // 重新計算該英雄剩下幾件(排除本身 + 排除剛剛因 same slot 卸掉的)
  const _afterSameSlot = Object.keys(_taiwanTreasureData).filter(otherId => {
    if(otherId === treasureId) return false;
    const otherRec = _taiwanTreasureData[otherId];
    return otherRec && otherRec.equippedTo === heroName;
  });
  // 若仍超過 maxSlots-1(因為要再裝這件,所以舊的不能等於 maxSlots),自動卸最早一件
  if(_afterSameSlot.length >= _maxSlots){
    // 找最舊的(_TAIWAN_TREASURE_ORDER 最前面)優先卸下
    const order = (typeof _TAIWAN_TREASURE_ORDER !== 'undefined' && Array.isArray(_TAIWAN_TREASURE_ORDER))
      ? _TAIWAN_TREASURE_ORDER : _afterSameSlot;
    let _removed = false;
    order.forEach(orderedId => {
      if(_removed) return;
      if(_afterSameSlot.includes(orderedId)){
        _taiwanTreasureData[orderedId].equippedTo = null;
        _removed = true;
      }
    });
  }
  // 卸下這個至寶在其他英雄身上的裝備(一個至寶不能同時裝兩個英雄)
  if(rec.equippedTo && rec.equippedTo !== heroName){
    rec.equippedTo = null;
  }
  rec.equippedTo = heroName;
  _saveTaiwanTreasureData();
  try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}
  // ★ v1.1.0 — 裝備後觸發獎章檢查
  try{ if(typeof window._checkTaiwanTreasureEquipMedals === 'function') window._checkTaiwanTreasureEquipMedals(); }catch(_){}
  return true;
}

function _equipTaiwanTreasureToSlot(treasureId, heroName, slotIdx){
  const def = TAIWAN_TREASURES[treasureId];
  const rec = _taiwanTreasureData[treasureId];
  if(!def || !rec) return false;
  const _slot2Unlocked = (typeof _isHeroSlot2Unlocked === 'function') && _isHeroSlot2Unlocked(heroName);
  const _maxSlots = _slot2Unlocked ? 2 : 1;
  const _targetSlot = Math.max(0, Math.min(slotIdx|0, _maxSlots - 1));

  // ★ v3.3.4 — 診斷 log:印出進入時的所有相關狀態,日後若再回報「裝錯位置」可一眼追到根因
  try{
    const _beforeList = (typeof _getHeroEquippedTreasures === 'function')
                       ? _getHeroEquippedTreasures(heroName) : [];
    console.log('[至寶裝備] 進入,treasureId=' + treasureId
      + ', heroName=' + heroName
      + ', slotIdx 傳入=' + slotIdx
      + ', _slot2Unlocked=' + _slot2Unlocked
      + ', _maxSlots=' + _maxSlots
      + ', _targetSlot 實際=' + _targetSlot
      + ', 該英雄目前裝備=' + JSON.stringify(_beforeList.map(e => ({
          id: e.id, slot: e.record.equippedSlot
        }))));
  }catch(_){}

  // 1. 卸下「目標槽位上已裝的其他至寶」
  Object.keys(_taiwanTreasureData).forEach(otherId => {
    if(otherId === treasureId) return;
    const otherRec = _taiwanTreasureData[otherId];
    if(otherRec && otherRec.equippedTo === heroName
       && (typeof otherRec.equippedSlot === 'number')
       && otherRec.equippedSlot === _targetSlot){
      // ★ v3.3.4 — 加 log:這條會把「正好在目標槽位」的舊至寶卸下,玩家若回報「主裝備消失」就是這條觸發
      try{ console.log('[至寶裝備] step 1 卸下舊至寶: id=' + otherId + ', 原 slot=' + otherRec.equippedSlot + ' === _targetSlot=' + _targetSlot); }catch(_){}
      otherRec.equippedTo = null;
      otherRec.equippedSlot = null;
    }
  });

  // 2. 修正:如果該英雄目前還有「沒寫 equippedSlot」的舊資料,且未佔用 _targetSlot,
  //    把它先補上 equippedSlot(以 _getHeroEquippedTreasures 排序後的順序填),避免之後衝突
  try{
    const _curList = (typeof _getHeroEquippedTreasures === 'function')
                    ? _getHeroEquippedTreasures(heroName) : [];
    let _nextSlot = 0;
    _curList.forEach(e => {
      if(e.id === treasureId) return;
      if(typeof e.record.equippedSlot !== 'number'){
        // 找下一個沒被佔用的槽
        while(_nextSlot < _maxSlots && _nextSlot === _targetSlot) _nextSlot++;
        if(_nextSlot < _maxSlots){
          e.record.equippedSlot = _nextSlot;
          _nextSlot++;
        }
      }
    });
  }catch(_){}

  // 3. 若新至寶原本在另一槽 → 換槽(不改 equippedTo,只改 equippedSlot)
  // 4. 若新至寶裝在「其他英雄」身上 → 從那邊卸下
  if(rec.equippedTo && rec.equippedTo !== heroName){
    rec.equippedTo = null;
    rec.equippedSlot = null;
  }

  // 5. 真正裝上
  rec.equippedTo = heroName;
  rec.equippedSlot = _targetSlot;

  _saveTaiwanTreasureData();
  try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}
  try{ if(typeof window._checkTaiwanTreasureEquipMedals === 'function') window._checkTaiwanTreasureEquipMedals(); }catch(_){}
  return true;
}

// 卸下英雄指定槽位的至寶
function _unequipTaiwanTreasureFromSlot(heroName, slotIdx){
  let _removed = false;
  Object.keys(_taiwanTreasureData).forEach(id => {
    const rec = _taiwanTreasureData[id];
    if(!rec || rec.equippedTo !== heroName) return;
    // 完全匹配槽位才卸(沒寫 equippedSlot 的舊資料當槽位 0 處理)
    const _slot = (typeof rec.equippedSlot === 'number') ? rec.equippedSlot : 0;
    if(_slot === (slotIdx|0)){
      rec.equippedTo = null;
      rec.equippedSlot = null;
      _removed = true;
    }
  });
  if(_removed){
    _saveTaiwanTreasureData();
    try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}
  }
  return _removed;
}
function _getHeroEquippedTreasures(heroName){
  const result = [];
  Object.keys(_taiwanTreasureData).forEach(id => {
    const rec = _taiwanTreasureData[id];
    if(rec && rec.equippedTo === heroName){
      result.push({ id, def: TAIWAN_TREASURES[id], record: rec });
    }
  });
  // 排序:有 equippedSlot 的依數字小→大,沒有的排後面(以 _TAIWAN_TREASURE_ORDER 為穩定次序)
  const _order = (typeof _TAIWAN_TREASURE_ORDER !== 'undefined' && Array.isArray(_TAIWAN_TREASURE_ORDER))
    ? _TAIWAN_TREASURE_ORDER : [];
  result.sort((a, b) => {
    const sa = (typeof a.record.equippedSlot === 'number') ? a.record.equippedSlot : 99;
    const sb = (typeof b.record.equippedSlot === 'number') ? b.record.equippedSlot : 99;
    if(sa !== sb) return sa - sb;
    // 同槽(或都沒設)時用 _TAIWAN_TREASURE_ORDER 穩定排序
    const oa = _order.indexOf(a.id); const ob = _order.indexOf(b.id);
    return (oa < 0 ? 999 : oa) - (ob < 0 ? 999 : ob);
  });
  return result;
}
