// ── 半價賣出(售價=該稀有度定價÷2;帳本 source:'sold' → 多槽合併稽核感知不復活)──
window._gearSell = function(eqUid, heroName, slot){
  try{
    if(typeof window._btnCooldown === 'function' && !window._btnCooldown('gear_sell', 800)) return;
    const inst = _gearGetInstance(eqUid); if(!inst) return;
    const def = GEAR_DB[inst.itemId]; if(!def) return;
    const rn = (GEAR_RARITY[def.r] && GEAR_RARITY[def.r].name) || '稀有';
    const price = Math.floor(((GEAR_RARITY[def.r] && GEAR_RARITY[def.r].price) || 1000) / 2);
    const _wear = inst.equippedTo ? ('\n(目前由「' + inst.equippedTo + '」裝備中,賣出將自動卸下)') : '';
    const _msg = (window._artStyle === 'cute')
      ? ('要把「' + def.n + '」(' + rn + ')賣掉換 ' + price.toLocaleString() + ' 知識幣嗎?賣掉就拿不回來囉!' + _wear)
      : ('確定以 ' + price.toLocaleString() + ' 知識幣(半價)賣出「' + def.n + '」(' + rn + ')?賣出後無法復原。' + _wear);
    const _doSell = function(){
      try{
        const inst2 = _gearGetInstance(eqUid); if(!inst2) return;
        _gearWriteLedger(eqUid, inst2.itemId, 'sold', null, 'sold');   // ★ 稽核感知:合併端視為已移除(殘槽不復活)
        delete window._gearData.instances[eqUid];
        _knowledgeCoins = (_knowledgeCoins || 0) + price;
        try{ _logCoinTx(price, '收入:賣出裝備-' + def.n); }catch(_){}
        try{ _syncCoinsDisplay(); }catch(_){}
        _gearRequestSave();
        try{ playSfx('sfx-coin', 0.7); }catch(_){}
        try{ _showInGameToast('💰 已賣出「' + def.n + '」,獲得 ' + price.toLocaleString() + ' 知識幣!', '#ffe066', 2800); }catch(_){}
        if(heroName && slot){ _gearPickerRefresh(heroName, slot); }
      }catch(_e2){ console.warn('[裝備賣出] 執行失敗', _e2); }
    };
    if(typeof _customConfirm === 'function'){ _customConfirm(_msg, _doSell); }
    else if(confirm(_msg)){ _doSell(); }
  }catch(_e){ console.warn('[裝備賣出] 失敗', _e); }
};
