    '<div style="font-size:clamp(26px,3.4vw,42px);font-weight:900;color:#9ec8ff;letter-spacing:6px;text-shadow:0 0 24px rgba(120,180,255,0.6);">🛡️ 裝備圖鑑</div>' +
    '<div style="font-size:17px;color:#bcd6ff;letter-spacing:1px;padding:8px 16px;background:rgba(0,0,0,0.4);border:1.5px solid rgba(120,180,255,0.3);border-radius:10px;">' +
      '📖 ' + (_cute ? '收集到' : '收錄') + ':<b style="color:#fff;">' + _collected + '</b> / ' + ((window._gearDbTotal && window._gearDbTotal()) || 72) + '&nbsp;&nbsp;🎒 ' + (_cute ? '身上有' : '持有') + ':<b style="color:#fff;">' + _gearOwnedCount() + '</b> / ' + window._GEAR_MAX_OWNED +
    '</div>';
  ov.appendChild(header);

  // 主區域:左卡片網格 / 右詳細面板(鏡像至寶頁)
  const main = document.createElement('div');
  main.style.cssText = 'flex:1;display:flex;overflow:hidden;min-height:0;';
