window._buildTaiwanBossTeam = function(bossId){
  const boss = TAIWAN_BOSSES[bossId];
  if(!boss) return [];
  const bossElem = TAIWAN_BOSS_ELEMENT[bossId] || 'fire';
  // 單獨 BOSS 陣容(pos=0)
  return [
    { name: boss.name, element: bossElem, isMainBoss: true },
  ];
};

