function _requestFullscreenAll(){
  // ★ v3.16.40 — 請求全螢幕前先設「全螢幕切換瞬間」旗標,讓 visibilitychange 略過進全螢幕那一下的假隱藏。
  try{ if(typeof window._lxpsMarkFsTransition === 'function') window._lxpsMarkFsTransition(); }catch(_){}
  // 支援各平台全螢幕：標準、webkit（iOS/Safari）、moz（Firefox）、ms（舊Edge）
  const el = document.documentElement;
  const fn = el.requestFullscreen
           || el.webkitRequestFullscreen
           || el.webkitEnterFullscreen
           || el.mozRequestFullScreen
           || el.msRequestFullscreen;
  if(fn){
    try{
      const p = fn.call(el, {navigationUI:'hide'});
      if(p && p.then){
        p.then(function(){
          // 進入全螢幕後立即鎖橫式
          if(screen.orientation && screen.orientation.lock){
            screen.orientation.lock('landscape').catch(()=>{});
          }
        }).catch(()=>{});
      }
    }catch(e){
      try{ fn.call(el); }catch(_){}
    }
  }
  // 無論全螢幕是否成功，嘗試鎖橫式方向
  if(screen.orientation && screen.orientation.lock){
    screen.orientation.lock('landscape').catch(()=>{});
  } else if(screen.lockOrientation){
    try{ screen.lockOrientation('landscape'); }catch(_){}
  } else if(screen.mozLockOrientation){
    try{ screen.mozLockOrientation('landscape'); }catch(_){}
  }
}

function _clearBattleBg(reason){
  try{
    const _bb = document.getElementById('adv-battle-bg');
    if(_bb){
      _bb.classList.remove('visible');
      _bb.className = ''; // 立即清空所有 bg-* class
    }
    // 一併清除戰鬥容器的 .adv-battle class,避免黑色戰鬥模式遮罩殘留
    const _gc = document.getElementById('gc');
    if(_gc){ _gc.classList.remove('adv-battle'); _gc.style.filter = ''; }
    if(reason) console.log('[背景清除]', reason);
  }catch(_e){ console.warn('[背景清除] 失敗:', _e); }
}

function _closeAllBattleModals(){
  const _ids = [
    'adv-reward-overlay',    // 答題獎勵(內部也用此 DOM 做「選擇爆發隊友」picker)
    'adv-quiz-overlay',      // 問題視窗
    'adv-repick-popup',      // ★ v1.0.20260424.1360 — 重選題庫視窗(避免戰鬥結束後殘留到下個場景對白)
    'passive-prompt',        // 被動技能提示
    'burst-priority-modal',  // 多人可爆發的優先選擇
    'burst-panel',           // 單人爆發確認面板
    // 🔧 v5.261.0 舊 bug(審查 M1):冒險模式結算不走 showResult ⇒ 盜取/逆轉神計/塔羅/命星選擇視窗在這裡一併移除(所有模式結算都會經過)
    'cst-steal2-ov','cst-field-pair-ov','tarot-choice-overlay','cst-pick7-ov',
    'invent-picker',   // ★ v5.262.0 審查:即刻發明選擇視窗:結算時直接移除、不回呼(與 game_adv.js 卡死自救一致)
    'steal-picker-ov','steal-preview-ov','steal-discard-ov','surprise-field-ov','surprise-confirm-ov',
  ];
  try{ window._cstPick7Q = []; }catch(_eCstP7q){}   // ✨ 命星 ✦ 結算時清掉排隊中的命星選擇視窗
  const _rmIdsV5261 = ['invent-picker','cst-pick7-ov','cst-steal2-ov','cst-field-pair-ov','tarot-choice-overlay','steal-picker-ov','steal-preview-ov','steal-discard-ov','surprise-field-ov','surprise-confirm-ov'];   // 🔧 v5.261.0 舊 bug(審查 M1):動態產生的選擇視窗直接 remove   // ★ v5.262.0 審查:invent-picker 一併直接移除(不回呼 onConfirm)
  _ids.forEach(id => {
    try{
      const el = document.getElementById(id);
      if(!el) return;
      // (a) 移除 .show class(class-based overlay)
      el.classList.remove('show');
      // (b) 強制 display:none(inline-style overlay)
      el.style.display = 'none';
      // (c) 對於動態產生後 appendChild 的 modal(burst-priority-modal / burst-panel / adv-repick-popup),直接移除
      if(id === 'burst-priority-modal' || id === 'burst-panel' || id === 'passive-prompt' || id === 'adv-repick-popup' || _rmIdsV5261.indexOf(id) >= 0){   // 🔧 v5.261.0 舊 bug(審查 M1):選擇視窗也直接移除
        el.remove();
      }
    }catch(_){}
  });
  try{ window._stealState = null; }catch(_){}   // 🔧 v5.261.0 舊 bug(審查 M1):盜取視窗被移除時一併清掉盜取暫存狀態
  // 同步清理可能被面板留下來的全域旗標
  try{
    if(typeof window !== 'undefined'){
      window._advSelectedRewardId = null;
      window._advRewardContext = null;
      window._advMiniRewardOnDone = null;
    }
    // 計時器
    if(typeof _advQuizTimer !== 'undefined' && _advQuizTimer){ clearInterval(_advQuizTimer); _advQuizTimer = null; }
    if(typeof _advQuizTimerHandle !== 'undefined' && _advQuizTimerHandle){ clearInterval(_advQuizTimerHandle); _advQuizTimerHandle = null; }
    if(typeof _advQuizPhase !== 'undefined') _advQuizPhase = 'idle';
  }catch(_){}
  console.log('[戰鬥結束清理] 互動視窗已全部關閉');
}

const _ADV_BG_URLS = [
  // 新倉庫(優先,符合 v5_5700 規範)
  './' + encodeURIComponent('力行校門口.png'),
  // 舊倉庫(歷史路徑,作為備援)
  './' + encodeURIComponent('力行校門口.png'),
];
let _ADV_BG_LOADED_URL = null; // 已成功載入的 URL,下次直接用不用再試
function _setAdventureOverlayBg(ov){
  if(!ov) return;
  // 已成功載入過 → 直接套用既有 URL,iPad 上 HTTP cache 會立刻命中
  if(_ADV_BG_LOADED_URL){
    try{
      ov.style.backgroundImage = 'url("' + _ADV_BG_LOADED_URL + '")';
      ov.style.backgroundSize = 'cover';
      ov.style.backgroundPosition = 'center';
      ov.style.backgroundRepeat = 'no-repeat';
    }catch(_){}
    return;
  }
  // 還沒成功過 → 依序嘗試 URL 清單,第一個成功就停
  let _idx = 0;
  const _tryNext = () => {
    if(_idx >= _ADV_BG_URLS.length){
      // 全失敗 — 保留 CSS 預設深藍漸層,不要清掉(否則會變全黑)
      console.warn('[adv-bg] 所有 URL 都載入失敗,保留漸層底色');
      return;
    }
    const _url = _ADV_BG_URLS[_idx++];
    const _img = new Image();
    let _resolved = false;
    const _onSuccess = () => {
      if(_resolved) return;
      _resolved = true;
      _ADV_BG_LOADED_URL = _url;
      try{
        ov.style.backgroundImage = 'url("' + _url + '")';
        ov.style.backgroundSize = 'cover';
        ov.style.backgroundPosition = 'center';
        ov.style.backgroundRepeat = 'no-repeat';
      }catch(_){}
    };
    const _onFail = () => {
      if(_resolved) return;
      _resolved = true;
      console.warn('[adv-bg] 載入失敗,嘗試下一個 URL:', _url);
      _tryNext();
    };
    _img.onload = _onSuccess;
    _img.onerror = _onFail;
    _img.src = _url;
    // 安全網:8 秒沒回來就視為失敗,試下一個
    setTimeout(() => { if(!_resolved) _onFail(); }, 8000);
  };
  _tryNext();
}

function _updateStageEnhanceBadges(){
  try{
    // ─── 1. 有可強化英雄 ───
    const _heroBadge = document.getElementById('badge-enhance-hero');
    if(_heroBadge){
      let _hasEnhanceHero = false;
      try{
        const _unlocked = (typeof advGetUnlockedHeroes === 'function') ? advGetUnlockedHeroes() : [];
        for(let i = 0; i < _unlocked.length; i++){
          const _n = _unlocked[i];
          if((_heroStatPoints && _heroStatPoints[_n]) > 0){
            _hasEnhanceHero = true;
            break;
          }
        }
      }catch(_){}
      if(_hasEnhanceHero) _heroBadge.classList.add('show');
      else _heroBadge.classList.remove('show');
    }

    // ─── 2. 有可升級至寶 ───
    const _treasureBadge = document.getElementById('badge-enhance-treasure');
    if(_treasureBadge){
      let _hasUpgradableTreasure = false;
      try{
        const _scrollCnt = (typeof backpackGet === 'function') ? (backpackGet('treasure_exp_scroll') || 0) : 0;
        if(_scrollCnt > 0 && typeof _taiwanTreasureData === 'object' && _taiwanTreasureData){
          const _SCROLL_EXP = 10; // 每張至寶經驗卷軸 +10 EXP
          const _ids = Object.keys(_taiwanTreasureData);
          for(let i = 0; i < _ids.length; i++){
            const _rec = _taiwanTreasureData[_ids[i]];
            if(!_rec) continue;
            if(_rec.lv >= TAIWAN_TREASURE_MAX_LV) continue;
            const _need = _getTaiwanTreasureExpForNextLv(_rec.lv);
            const _curExp = _rec.exp || 0;
            const _afterUse = _curExp + _scrollCnt * _SCROLL_EXP;
            if(_afterUse >= _need){
              _hasUpgradableTreasure = true;
              break;
            }
          }
        }
      }catch(_){}
      if(_hasUpgradableTreasure) _treasureBadge.classList.add('show');
      else _treasureBadge.classList.remove('show');
    }

    // ─── 3. 免費1抽(每日免費召喚還沒用)───  ★ v3.13.4(2026-05-31)
    const _summonBadge = document.getElementById('badge-free-summon');
    if(_summonBadge){
      let _hasFreeSummon = false;
      try{
        if(typeof _isDailyFreeSummonAvailable === 'function'){
          _hasFreeSummon = !!_isDailyFreeSummonAvailable();
        }
      }catch(_){}
      if(_hasFreeSummon) _summonBadge.classList.add('show');
      else _summonBadge.classList.remove('show');
    }

    // ─── 4. 送禮給好友(今日還可送至少一位且有負擔得起的禮物)───  ★ v3.13.4(2026-05-31)
    //   判定條件:有好友 + 今日送禮 < 5 + 有任一未送過的好友
    //   (禮物是否負擔得起不影響徽章 — 玩家點進好友頁可看到完整提示)
    const _giftBadge = document.getElementById('badge-gift-friend');
    if(_giftBadge){
      let _canGift = false;
      try{
        const _flist = (typeof _friendList !== 'undefined' && Array.isArray(_friendList)) ? _friendList : [];
        if(_flist.length > 0 && typeof window._giftMaybeResetHistory === 'function'){
          try{ window._giftMaybeResetHistory(); }catch(_){}
          const _sent = (window._giftHistory && Array.isArray(window._giftHistory.sentUids))
            ? window._giftHistory.sentUids : [];
          // 還有送禮配額(<5)且至少一位好友今日未送
          if(_sent.length < 5){
            for(let i = 0; i < _flist.length; i++){
              const _fu = _flist[i] && _flist[i].uid;
              if(_fu && _sent.indexOf(_fu) < 0){
                _canGift = true;
                break;
              }
            }
          }
        }
      }catch(_){}
      if(_canGift) _giftBadge.classList.add('show');
      else _giftBadge.classList.remove('show');
    }
  }catch(_e){ console.warn('[_updateStageEnhanceBadges]', _e); }
}

// ════════════════════════════════════════════════════════════════════════
// ★ v3.15.49 — 關卡首頁主選單提醒徽章「定時 + 跨日重置」自動刷新器
// ────────────────────────────────────────────────────────────────────────
//   老師回報:關卡頁下方 4 個提醒(✨免費1抽 / ✨有可強化英雄 / 💎有至寶可強化 /
//             🎁送禮給好友)「常常沒出現」。
//   根因:_updateStageEnhanceBadges() 只在「進關卡頁 / 特定動作後」呼叫,沒有定時重檢:
//         ① 雲端資料(好友清單/至寶/每日免費召喚狀態)晚於首次計算才載入 → 徽章算過一次就不再更新。
//         ② 玩家停在關卡頁跨過台灣 08:00(每日重置)→ 免費1抽/送禮配額已重置,但徽章不會自己刷新。
//   修法(零 Firebase 讀寫,純本地計算 + DOM class 切換):
//     每 25 秒,只要關卡選擇頁(#adventure-overlay)可見就重跑 _updateStageEnhanceBadges();
//     另記錄上次 game-day-key(_lxpsGetGameDayKey,台灣 08:00 為界),一旦跨日「立即」強制刷新一次
//     (免費1抽/送禮的每日判定函式本就比對 day-key,重跑即正確反映重置)。
(function _setupStageBadgeAutoRefresh(){
  try{
    if(window._lxpsStageBadgeTimer) return;   // 防重複安裝
    var _lastDayKey = null;
    function _advOverlayVisible(){
      try{
        var ov = document.getElementById('adventure-overlay');
        // offsetParent === null 代表 display:none 或被隱藏祖先(對全螢幕 overlay 是可靠的可見性判定)
        return !!(ov && ov.offsetParent !== null);
      }catch(_){ return false; }
    }
    function _tick(){
      try{
        // 跨日偵測:day-key 變了就強制刷新一次(即使玩家正停在關卡頁)
        var _dk = null;
        try{ if(typeof window._lxpsGetGameDayKey === 'function') _dk = window._lxpsGetGameDayKey(); }catch(_){}
        var _dayRolled = (_dk && _lastDayKey && _dk !== _lastDayKey);
        if(_dk) _lastDayKey = _dk;
        // 只在「已登入 + 關卡頁可見」時才重跑(省去無謂運算;隱藏時切 class 無意義)
        if(window._gUserId && _advOverlayVisible()){
          if(typeof _updateStageEnhanceBadges === 'function') _updateStageEnhanceBadges();
        } else if(_dayRolled){
          // 即使當下不在關卡頁,也讓 day-key 對齊(下次進頁就是新的一天的判定)
        }
      }catch(_e){ /* 靜默,絕不可因徽章刷新影響主流程 */ }
    }
    window._lxpsStageBadgeTimer = setInterval(_tick, 25000);
    // 啟動時先對齊一次 day-key(避免第一個 tick 就誤判跨日)
    try{ if(typeof window._lxpsGetGameDayKey === 'function') _lastDayKey = window._lxpsGetGameDayKey(); }catch(_){}
  }catch(_e){ console.warn('[StageBadgeAutoRefresh] 安裝失敗', _e); }
})();

// ════════════════════════════════════════════════════════════════════════
// ★ v3.13.17(2026-06-02) — 帳號權威驗證 + 無訪客模式 + 斷線踢回首頁(徹底杜絕汙染)
//   老師方針:
//     (1) 沒登入帳號就進不去關卡頁。
//     (2) 斷線直接踢回首頁。
//     (3) 確定自動偵測帳號雲端資料沒問題,才能讓玩家重新進到關卡頁。
//     (4) 登入讀取雲端可以久一點,寧可等待也不要出現錯誤存檔。
//     (5) 前提:保證能順利登入,絕不可造成「登入又立即被登出」的循環。
//
//   _lxpsResolveUid():回傳目前「真正有效」的帳號 uid。
//     - window._gUserId 有值 → 直接用。
//     - 缺(onAuth race / 變數時序)→ 用 Firebase 權威 currentUser.uid 自我修復。
//     - Firebase 也沒 currentUser → 真的沒登入,回 null。
//   ★ 純讀取狀態 + 自我修復,絕不主動 signOut → 不會引發登入/登出循環(對齊方針 5)。
window._lxpsResolveUid = function(){
  if(window._gUserId){
    try{ window._lxpsLoggedInThisSession = true; }catch(_){}   // 確認登入中,保 showLoginGate 快速路徑順暢
    return window._gUserId;
  }
  try{
    var _cu = (window._fbAuth && window._fbAuth.currentUser) ? window._fbAuth.currentUser : null;
    if(_cu && _cu.uid){
      window._gUserId = _cu.uid;   // 修復 window 上的 uid(跨 script block 通用)
      try{ window._lxpsLoggedInThisSession = true; }catch(_){}
      console.warn('[帳號修復 v3.13.17] _gUserId 由 Firebase currentUser 補回:'
        + String(_cu.uid).slice(0,8) + '..(避免誤判未登入)');
      return _cu.uid;
    }
  }catch(_){}
  return null;
};

// ★ v3.13.17 — 一律踢回首頁:關閉所有關卡/戰鬥 overlay + 顯示登入閘門,要求重新登入確認。
//   重設 _progressLoaded=false → 強制下次進關卡前重讀雲端、確認資料 OK(對齊方針 3)。
//   ★ 不主動 signOut:若只是短暫斷線,Firebase 仍記得登入,玩家按登入鍵即可快速回來,
//     不會落入「登入又被登出」循環(對齊方針 5)。
window._lxpsKickToHome = function(reason){
  console.error('⛔ [踢回首頁 v3.13.17] ' + (reason || '帳號登入有問題') + ' → 關閉關卡頁,回首頁重新確認登入');
  try{
    ['adventure-overlay','wb-ui-overlay','adv-result-overlay','adv-reward-overlay',
     'wb-lobby-overlay','wb-result-overlay','action-panel','item-panel','battle-overlay']
      .forEach(function(id){ var _e = document.getElementById(id); if(_e) _e.style.display = 'none'; });
  }catch(_){}
  try{ window._progressLoaded = false; }catch(_){}            // 強制重新確認雲端資料才放行
  try{ window._cloudVerified  = false; }catch(_){}            // ★ v3.13.18 — 重進關卡前必須重新通過雲端驗證
  try{ window._lxpsLoggedInThisSession = false; }catch(_){}   // 清黏著旗標,讓首頁閘門正常顯示
  try{
    if(typeof window.showLoginGate === 'function') window.showLoginGate();
    else setTimeout(function(){ try{ location.reload(); }catch(_){} }, 200);
  }catch(_eGate){
    console.warn('[踢回首頁] showLoginGate 例外,fallback reload', _eGate);
    try{ location.reload(); }catch(_){}
  }
};
