// ════════════════════════════════════════════════════════════════════════
// ★ v3.13.64(2026-06-06) — uid 權威化 + 自證身分多層防護(老師方針:永遠根治
//   「讀到別 uid / 訪客殘留 / 載入失敗剩 8 隻」,寧可登入慢一點也要保證讀到自己的資料)
//   本區塊提供 4 個共用工具,給存讀檔/守門/裝置對齊使用:
//     _lxpsAuthUid()         — 以 Firebase currentUser.uid 為「最終準據」(快取 _gUserId 只是優化)
//     _lxpsUidDrift()        — 偵測「快取 uid 與權威 uid 都有值卻不同」= 換帳號進行中/bug → 呼叫端中止
//     _lxpsEnforceDeviceOwner(uid) — 裝置擁有者戳記;本機共用全域資料若屬別 uid → 清掉,改由雲端重灌
//     _lxpsShowLoadFailedModal()   — 載入失敗全螢幕視窗(需求 1:不退回預設 8 隻,只請玩家重新整理)
// ════════════════════════════════════════════════════════════════════════
// ★ v3.13.64 — 權威 uid:Firebase currentUser 為最終準據,currentUser 不可用時才退回快取
window._lxpsAuthUid = function(){
  try{
    var _cu = (window._fbAuth && window._fbAuth.currentUser) ? window._fbAuth.currentUser : null;
    if(_cu && _cu.uid) return _cu.uid;
  }catch(_){}
  return window._gUserId || null;
};
// ★ v3.13.64 — 漂移偵測:快取 uid 與權威 uid「都有值且不同」→ true(呼叫端應中止讀/寫,等 onAuth 穩定)
window._lxpsUidDrift = function(){
  try{
    var _cu = (window._fbAuth && window._fbAuth.currentUser) ? window._fbAuth.currentUser : null;
    if(_cu && _cu.uid && window._gUserId && window._gUserId !== _cu.uid) return true;
  }catch(_){}
  return false;
};
// ★ v3.13.64 — 裝置擁有者戳記(全域 key 防外來殘留的「強制對齊」單一守門點)
//   背景:adv_unlocked_heroes 以外的全域 key(adv_medals / 至寶 / 肖像 / 戰鬥快照…)目前
//         「唯一」防線是換帳號時 _clearAccountLocalData 被觸發 → 單點故障。
//   作法:每次載入前先比對 localStorage 'lxps_device_owner_uid' 與「現在登入的 uid」。
//         不同 → 代表本機共用全域資料屬於別人 → 直接清掉(改由雲端重灌,全域 key 都是雲端快取,不會掉資料)。
//   保證:不論有多少讀取點直接讀全域 key,當下拿到的都「不可能是別 uid 的殘留」(對齊或被清空)。
//   不動 per-account 的 lxps_{uid}_progress(綁 uid、無害,且是離線備份)。
window._lxpsEnforceDeviceOwner = function(uid){
  if(!uid) return false;
  var _prev = null;
  try{ _prev = localStorage.getItem('lxps_device_owner_uid') || null; }catch(_){}
  var _wiped = false;
  if(_prev && _prev !== uid){
    console.warn('[裝置擁有者 v3.13.64] 本機共用資料屬別帳號 (' + String(_prev).slice(0,8)
      + '... ≠ ' + String(uid).slice(0,8) + '...) → 清掉全域殘留,改由雲端重灌');
    try{ if(typeof window._clearAccountLocalData === 'function') window._clearAccountLocalData('device_owner_mismatch'); }catch(_){}
    _wiped = true;
  }
  try{ localStorage.setItem('lxps_device_owner_uid', uid); }catch(_){}
  return _wiped;
};
// ★ v3.13.64 — 載入失敗全螢幕視窗(需求 1):任何「無法取得已驗證的自己 uid 資料」一律走這裡,
//   絕不退回預設 8 隻、絕不進場、絕不存檔。單一「重新整理」鈕,訊息對小朋友友善。
window._lxpsShowLoadFailedModal = function(reason){
  try{
    if(document.getElementById('_lxps-load-failed-modal')) return;   // 防重複疊加
    // 先關掉所有關卡/戰鬥 overlay,避免底下露出預設狀態
    try{
      ['adventure-overlay','wb-ui-overlay','adv-result-overlay','adv-reward-overlay',
       'wb-lobby-overlay','wb-result-overlay','action-panel','item-panel','battle-overlay']
        .forEach(function(id){ var _e = document.getElementById(id); if(_e) _e.style.display = 'none'; });
    }catch(_){}
    try{ window._progressLoaded = false; }catch(_){}
    try{ window._cloudVerified  = false; }catch(_){}
    try{ window._dataReadyForUid = null; }catch(_){}
    var box = document.createElement('div');
    box.id = '_lxps-load-failed-modal';
    box.style.cssText = 'position:fixed;inset:0;z-index:100002;background:rgba(0,0,8,0.92);'
      + 'display:flex;align-items:center;justify-content:center;padding:24px;'
      + 'backdrop-filter:blur(8px);font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
    box.innerHTML = '<div style="background:linear-gradient(160deg,#1a1226,#0a0814);'
      + 'border:3px solid #ffaa44;border-radius:22px;padding:34px 32px;max-width:min(520px,92vw);'
      + 'text-align:center;box-shadow:0 0 60px rgba(255,150,60,0.35);color:#ffe0c0;">'
      + '<div style="font-size:52px;margin-bottom:12px;">&#9888;&#65039;</div>'
      + '<div style="font-size:28px;font-weight:900;color:#ffcc88;margin-bottom:14px;letter-spacing:1px;">資料載入失敗</div>'
      + '<div style="font-size:17px;color:#ffd9b0;line-height:1.75;margin-bottom:22px;">'
      + '沒有成功載入你的雲端進度,<br>為了保護你的資料,先不進入遊戲。<br><br>'
      + '<b style="color:#ffcc66;">請確認網路後,點下方按鈕重新整理。</b><br>'
      + '<span style="font-size:13px;color:#ffb380;">(你的進度都安全存在雲端,重新整理就會回來)</span>'
      + '</div>'
      + '<button onclick="_lxpsReloadKeepLogin()" style="width:100%;padding:15px;font-size:20px;font-weight:800;'
      + 'background:linear-gradient(135deg,#ffaa44,#ee8822);border:none;color:#3a1a00;border-radius:14px;'
      + 'cursor:pointer;letter-spacing:2px;box-shadow:0 4px 18px rgba(255,150,60,0.4);">&#128260; 重新整理遊戲</button>'
      + '</div>';
    document.body.appendChild(box);
    console.error('⛔ [載入失敗視窗 v3.13.64] ' + (reason || '無法取得已驗證的雲端資料'));
  }catch(_e){ try{ window._lxpsReloadKeepLogin(); }catch(__){ try{ location.reload(); }catch(___){} } }   // ★ v5.141.0 — 自家重載設放行旗標
};

// ════════════════════════════════════════════════════════════════════════
// ★ v3.15.45(2026-06-19) — 帳號資料污染「自救看門狗」(老師需求)
// ────────────────────────────────────────────────────────────────────────
// 背景:帳號資料偶爾被本地資料污染 → 冒險選關頁左上「代表英雄頭像 + 暱稱」會消失
//       (暱稱條 #adv-username-bar 因 #google-name 讀不到而 display:none)。
//       根因改過多次仍偶發,故改設「症狀偵測 + 一鍵自救」:
//   ① 看門狗在選關頁開著時定期偵測「本機記得你的暱稱、畫面卻沒顯示」→ 判定疑似污染
//   ② 跳出友善提示 → 玩家按「重新載入」→ 清本地污染標記 + 重整
//   ③ 重整自動重新登入 + gameCloudLoad 用「雲端三槽最豐富資料」覆蓋本地污染
//   ④ 重整後彈出「資料確認畫面」顯示 英雄/至寶/總等級/知識幣/水晶,讓玩家確認資料回來了
//   ⑤ 自救成功後冷卻 10 分鐘(避免一直彈)
// 防誤判:只在「localStorage/_playerNickname/google-name 有暱稱、但 UI 沒顯示」時判定
//         → 新玩家/載入中(_cloudLoadDone!==true)不誤判;二次確認(1.2s)防渲染時序瞬間誤判。
// ════════════════════════════════════════════════════════════════════════
window._ADV_REPAIR_COOLDOWN_MS = 10 * 60 * 1000;   // 自救冷卻 10 分鐘

// 冷卻檢查:10 分鐘內剛自救過 → true
function _advRepairOnCooldown(uid){
  try{
    var ts = parseInt(localStorage.getItem('lxps_advRepairCooldown_' + uid) || '0', 10);
    return !!(ts && (Date.now() - ts < (window._ADV_REPAIR_COOLDOWN_MS || 600000)));
  }catch(_){ return false; }
}
window._advRepairOnCooldown = _advRepairOnCooldown;

// 小工具:元素是否實際隱藏(display:none)
function _advElHidden(el){
  if(!el) return true;
  if(el.style && el.style.display === 'none') return true;
  try{ return getComputedStyle(el).display === 'none'; }catch(_){ return false; }
}

// 看門狗:偵測冒險選關頁的暱稱消失(疑似本地污染)
function _advCorruptionWatchdog(){
  try{
    var uid = window._gUserId;
    if(!uid) return;                              // 未登入不判定
    if(window._cloudLoadDone !== true) return;    // 雲端載入未完成(載入中)→ 不判定
    // ★ v3.15.64(老師回報:彈窗在登入/載入畫面誤跳)— 強化 gate:
    //   _cloudLoadDone=true 只代表「雲端流程跑完了(含失敗)」,不代表資料載入成功。
    //   網路不穩讀取失敗時 _cloudLoadDone=true 但 _progressLoaded=false(空殼狀態),
    //   看門狗會把這個「載入失敗的空畫面」誤判成『污染』而在登入/載入畫面誤跳。
    //   → 必須 _progressLoaded=true(資料確實載入成功)才判定,確保只在「真正進入
    //     有資料的選關頁」時才可能彈窗(對齊全站 gameCloudSave 等既有 _progressLoaded 守門)。
    if(window._progressLoaded !== true) return;   // 資料未成功載入(網路失敗空殼)→ 不判定
    var ov = document.getElementById('adventure-overlay');
    if(!ov || _advElHidden(ov)) return;           // 選關頁沒開著 → 沒有要偵測的 UI
    if(_advRepairOnCooldown(uid)) return;         // 冷卻中不重複提示
    if(document.getElementById('_adv-corruption-modal')) return;  // 已在提示中

    // ── 偵測「該有暱稱卻消失」── (暱稱是登入玩家必有,最可靠的污染徵兆)
    var uBar  = document.getElementById('adv-username-bar');
    var uName = document.getElementById('adv-user-name');
    var nameText = (uName && uName.textContent || '').trim();
    var nicknameMissing = _advElHidden(uBar) || !nameText;
    // ★★ v5.141.0（老師回報「PC 每次登入都跳『因為網路問題沒有讀取到正確紀錄』要重登三次」）★★
    //   實查這個視窗不是網路問題,是「顯示層賽跑」:PC 上雲端載入快、選關頁先開,而名字條要等 onAuth
    //   跑完 6～7 次 Firestore 讀寫才畫 ⇒ 本看門狗每 4 秒一巡,在名字還沒畫上的窗口內把它當「污染」
    //   ⇒ 跳視窗 → 重整(舊碼沒放行旗標)→ 被攔截器踢出 → 重登 → 同樣的賽跑再來一次 ⇒ 老師的「登三次」。
    //   修法:判定前先用手上的帳號資料自癒(_lxpsPaintAccountBar),補得上就不是污染、直接返回;
    //   只有「本機記得暱稱、卻連 Firebase 都給不出使用者資料」才進入原本的二次確認 → 視窗。
    if(nicknameMissing){
      try{
        if(typeof window._lxpsPaintAccountBar === 'function' && window._lxpsLoggedInThisSession === true){
          window._lxpsPaintAccountBar(null, { selfHeal: true });
          uBar  = document.getElementById('adv-username-bar');
          uName = document.getElementById('adv-user-name');
          nameText = (uName && uName.textContent || '').trim();
          if(!(_advElHidden(uBar) || !nameText)){
            console.log('[污染看門狗 v5.141.0] 名字條只是還沒畫上,已自癒補畫,不視為污染');
            return;
          }
        }
      }catch(_eSh){}
    }
    // 「本機應該記得你的暱稱」嗎?
    var shouldHaveName = false;
    try{
      shouldHaveName = !!(
        localStorage.getItem('lxps_nickname_' + uid)
        || window._playerNickname
        || (((document.getElementById('google-name') || {}).textContent) || '').trim()
      );
    }catch(_){}

    if(shouldHaveName && nicknameMissing){
      // 二次確認(1.2s 後再看一次),避免渲染時序造成的瞬間誤判
      setTimeout(function(){
        try{
          if(document.getElementById('_adv-corruption-modal')) return;
          if(_advRepairOnCooldown(uid)) return;
          if(window._progressLoaded !== true) return;   // ★ v3.15.64 — 二次確認同步守門(空殼不誤判)
          var ov2 = document.getElementById('adventure-overlay');
          if(!ov2 || _advElHidden(ov2)) return;
          var uBar2  = document.getElementById('adv-username-bar');
          var uName2 = document.getElementById('adv-user-name');
          var nameText2 = (uName2 && uName2.textContent || '').trim();
          if(_advElHidden(uBar2) || !nameText2){
            // ★ v5.141.0 — 二次確認前再自癒一次(onAuth 可能剛好在這 1.2 秒內把帳號畫好)
            try{ if(typeof window._lxpsPaintAccountBar === 'function') window._lxpsPaintAccountBar(null, { selfHeal: true }); }catch(_){}
            uBar2  = document.getElementById('adv-username-bar');
            uName2 = document.getElementById('adv-user-name');
            nameText2 = (uName2 && uName2.textContent || '').trim();
            if(!(_advElHidden(uBar2) || !nameText2)) return;
            _showAdvCorruptionModal(uid);
          }
        }catch(_e2){ console.warn('[污染看門狗 二次確認] 例外', _e2); }
      }, 1200);
    }
  }catch(_e){ console.warn('[污染看門狗] 例外', _e); }
}
window._advCorruptionWatchdog = _advCorruptionWatchdog;

// 提示視窗:疑似污染 → 請玩家重新載入(只有重載鈕,引導修復)
function _showAdvCorruptionModal(uid){
  try{
    if(document.getElementById('_adv-corruption-modal')) return;
    var box = document.createElement('div');
    box.id = '_adv-corruption-modal';
    box.style.cssText = 'position:fixed;inset:0;z-index:100003;background:rgba(0,0,8,0.92);'
      + 'display:flex;align-items:center;justify-content:center;padding:24px;'
      + 'backdrop-filter:blur(8px);font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
    box.innerHTML = '<div style="background:linear-gradient(160deg,#1a1226,#0a0814);'
      + 'border:3px solid #ffaa44;border-radius:22px;padding:34px 32px;max-width:min(540px,92vw);'
      + 'text-align:center;box-shadow:0 0 60px rgba(255,150,60,0.35);color:#ffe0c0;">'
      + '<div style="font-size:52px;margin-bottom:12px;">&#9888;&#65039;</div>'
      + '<div style="font-size:26px;font-weight:900;color:#ffcc88;margin-bottom:16px;letter-spacing:1px;">沒有正確讀取到遊戲記錄</div>'
      + '<div style="font-size:18px;color:#ffd9b0;line-height:1.8;margin-bottom:24px;">'
      + '因為網路連線不穩定,目前沒有正確讀取到您的<br>完整遊戲記錄,請按此重新載入。'
      + '<br><br><span style="font-size:14px;color:#ffb380;">(您的進度都安全存在雲端,重新載入就會回來)</span>'
      + '</div>'
      + '<button id="_adv-corruption-reload-btn" style="width:100%;padding:16px;font-size:21px;font-weight:800;'
      + 'background:linear-gradient(135deg,#ffaa44,#ee8822);border:none;color:#3a1a00;border-radius:14px;'
      + 'cursor:pointer;letter-spacing:2px;box-shadow:0 4px 18px rgba(255,150,60,0.4);">&#128260; 重新載入</button>'
      + '</div>';
    document.body.appendChild(box);
    var btn = document.getElementById('_adv-corruption-reload-btn');
    if(btn) btn.onclick = function(){ try{ if(typeof playSfx === 'function') playSfx('sfx-sel', 0.6); }catch(_){} _advRepairReload(uid); };
    console.warn('⚠ [污染看門狗] 偵測到選關頁暱稱消失,彈出自救視窗 uid=' + String(uid).slice(0, 8));
  }catch(_e){ console.warn('[污染看門狗 modal] 例外', _e); }
}
window._showAdvCorruptionModal = _showAdvCorruptionModal;

// 一鍵自救:寫冷卻 + 修復標記 + 清本地污染 → 重整(自動重新登入 + 雲端最豐富覆蓋本地)
function _advRepairReload(uid){
  uid = uid || window._gUserId;
  try{
    if(uid){
      localStorage.setItem('lxps_advRepairCooldown_' + uid, String(Date.now()));        // 冷卻 10 分
      localStorage.setItem('lxps_advRepairPending', JSON.stringify({ uid: uid, ts: Date.now() })); // 重整後顯示資料確認
    }
  }catch(_){}
  // 清本地污染:本機若有別 uid 的共用全域資料 → 清掉,改由雲端重灌;並清記憶體擁有者強制重驗
  try{ if(uid && window._lxpsEnforceDeviceOwner) window._lxpsEnforceDeviceOwner(uid); }catch(_){}
  try{ window._memoryOwnerUid = null; }catch(_){}
  // 重整(Firebase auth 持久化 → 自動重新登入;gameCloudLoad 三槽最豐富覆蓋本地污染)
  // ★ v5.141.0 — 舊碼裸 reload 沒設放行旗標 ⇒ 重整後被 v3.10.1 攔截器當「自動還原」強制登出，
  //   「自救」變成「被踢出」（老師實測「自動登出」的其中一條鏈）。改走 _lxpsReloadKeepLogin。
  try{ if(typeof window._lxpsReloadKeepLogin === 'function'){ window._lxpsReloadKeepLogin(); return; } }catch(_){}
  try{ location.reload(); }catch(_){ try{ window.location.href = window.location.href; }catch(__){} }
}
window._advRepairReload = _advRepairReload;

// 重整後檢查:若剛做過自救 → 彈出「資料確認畫面」顯示主要數據,讓玩家確認資料回來了
function _advCheckRepairResult(uid){
  try{
    var raw = localStorage.getItem('lxps_advRepairPending');
    if(!raw) return;
    var pending = null; try{ pending = JSON.parse(raw); }catch(_){}
    if(!pending || pending.uid !== uid) return;
    localStorage.removeItem('lxps_advRepairPending');   // 消化標記(只彈一次)
    // 取主要數據(各自 try,取不到顯示 0)
    var heroes = 0, treasures = 0, totalLv = 0, coins = 0, crystal = 0;
    try{ if(typeof advGetUnlockedHeroes === 'function'){ var _a = advGetUnlockedHeroes(); if(Array.isArray(_a)) heroes = _a.length; } }catch(_){}
    try{ var _tw = window.taiwanTreasureData; if(_tw && typeof _tw === 'object') treasures = Object.keys(_tw).length; }catch(_){}
    try{ var _hl = window._heroLevels; if(!_hl){ try{ _hl = _heroLevels; }catch(__){ _hl = {}; } } totalLv = Object.values(_hl || {}).reduce(function(a, b){ return a + (Number(b) || 0); }, 0); }catch(_){}
    try{ coins = Number(window._knowledgeCoins || 0); }catch(_){}
    try{ if(typeof window._getCrystalBal === 'function') crystal = Number(window._getCrystalBal() || 0); }catch(_){}
    // 稍延遲彈出,讓選關頁先渲染完
    setTimeout(function(){ _showRepairResultModal({ heroes: heroes, treasures: treasures, totalLv: totalLv, coins: coins, crystal: crystal }); }, 800);
  }catch(_e){ console.warn('[自救資料確認] 例外', _e); }
}
window._advCheckRepairResult = _advCheckRepairResult;

// 資料確認畫面:顯示重整後的主要數據(英雄/至寶/總等級/知識幣/水晶)
function _showRepairResultModal(d){
  try{
    if(document.getElementById('_adv-repair-result-modal')) return;
    d = d || {};
    var _row = function(icon, label, val){
      return '<div style="display:flex;align-items:center;justify-content:space-between;gap:14px;'
        + 'padding:11px 16px;background:rgba(255,255,255,0.06);border:1.5px solid rgba(120,200,120,0.3);'
        + 'border-radius:11px;margin-bottom:9px;">'
        + '<span style="font-size:17px;color:#cfe8d0;">' + icon + ' ' + label + '</span>'
        + '<span style="font-size:22px;font-weight:900;color:#aaffaa;">' + (Number(val) || 0).toLocaleString() + '</span></div>';
    };
    var box = document.createElement('div');
    box.id = '_adv-repair-result-modal';
    box.style.cssText = 'position:fixed;inset:0;z-index:100003;background:rgba(0,5,2,0.9);'
      + 'display:flex;align-items:center;justify-content:center;padding:24px;'
      + 'backdrop-filter:blur(8px);font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
    box.innerHTML = '<div style="background:linear-gradient(160deg,#12200f,#081406);'
      + 'border:3px solid #66dd99;border-radius:22px;padding:30px 28px;max-width:min(460px,92vw);'
      + 'box-shadow:0 0 60px rgba(100,220,140,0.3);color:#e0ffe0;">'
      + '<div style="font-size:46px;text-align:center;margin-bottom:8px;">&#9989;</div>'
      + '<div style="font-size:24px;font-weight:900;color:#aaffaa;text-align:center;margin-bottom:6px;letter-spacing:1px;">已重新載入完整記錄</div>'
      + '<div style="font-size:14px;color:#bfe8c0;text-align:center;line-height:1.7;margin-bottom:20px;">'
      + '已用雲端最完整的資料重新整理,<br>請確認以下主要數據是否正確:</div>'
      + _row('&#129464;', '持有英雄', d.heroes)
      + _row('&#128142;', '台灣至寶', d.treasures)
      + _row('&#11088;', '英雄總等級', d.totalLv)
      + _row('&#128176;', '知識幣', d.coins)
      + _row('&#128302;', '召喚水晶', d.crystal)
      + '<button id="_adv-repair-result-ok" style="width:100%;margin-top:16px;padding:14px;font-size:19px;font-weight:800;'
      + 'background:linear-gradient(135deg,#66dd99,#44bb77);border:none;color:#06270f;border-radius:13px;'
      + 'cursor:pointer;letter-spacing:2px;box-shadow:0 4px 16px rgba(100,220,140,0.35);">&#10004; 確認</button>'
      + '</div>';
    document.body.appendChild(box);
    var ok = document.getElementById('_adv-repair-result-ok');
    if(ok) ok.onclick = function(){ try{ if(typeof playSfx === 'function') playSfx('sfx-sel', 0.5); }catch(_){} try{ box.remove(); }catch(_){} };
  }catch(_e){ console.warn('[資料確認 modal] 例外', _e); }
}
window._showRepairResultModal = _showRepairResultModal;

// 啟動看門狗:每 4 秒檢查一次(函式內自我守門:只在選關頁開著+已登入+載入完成+未冷卻時才判定)
try{
  if(!window._advCorruptionWatchdogTimer){
    window._advCorruptionWatchdogTimer = setInterval(function(){
      try{ if(window._advCorruptionWatchdog) window._advCorruptionWatchdog(); }catch(_){}
    }, 4000);
  }
}catch(_){}
