// ★ v3.10.10 — 渲染/隱藏關卡頁頂部的未完成戰鬥紅色橫幅
function _renderPendingBattleBanner(){
  // 移除舊的(避免重複)
  const _old = document.getElementById('_pending-battle-banner');
  if(_old) _old.remove();

  // 沒有未完成戰鬥 → 不顯示
  if(!window._advHasPendingBattle || !window._advHasPendingBattle()) return;

  const ov = document.getElementById('adventure-overlay');
  if(!ov) return;

  const banner = document.createElement('div');
  banner.id = '_pending-battle-banner';
  banner.style.cssText = 'position:absolute;top:0;left:0;right:0;z-index:850;'
    + 'background:linear-gradient(135deg,rgba(160,30,30,0.95),rgba(110,20,20,0.95));'
    + 'border-bottom:2.5px solid #ff5544;'
    + 'padding:12px 18px;display:flex;align-items:center;justify-content:center;gap:14px;'
    + 'flex-wrap:wrap;color:#fff;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;'
    + 'box-shadow:0 4px 18px rgba(255,80,60,0.4);'
    + 'animation:_pbbSlideDown 0.4s ease-out;';
  banner.innerHTML =
    '<style>@keyframes _pbbSlideDown{0%{transform:translateY(-100%);opacity:0}100%{transform:translateY(0);opacity:1}}'
    + '@keyframes _pbbPulse{0%,100%{box-shadow:0 0 0 0 rgba(255,80,60,0.6)}50%{box-shadow:0 0 0 8px rgba(255,80,60,0)}}</style>'
    + '<div style="font-size:24px;">⚠️</div>'
    + '<div style="font-size:17px;font-weight:800;letter-spacing:1px;line-height:1.4;">'
    + '你有未完成戰鬥 — <span style="color:#ffdd44;">無法</span>使用其他功能,'
    + '<br style="display:none">請繼續戰鬥或放棄</div>'
    + '<button id="_pbb_continue" style="padding:8px 18px;font-size:15px;font-weight:900;'
    + 'background:linear-gradient(135deg,rgba(255,200,40,0.5),rgba(220,160,20,0.6));'
    + 'border:2px solid #ffcc44;color:#fff5cc;border-radius:10px;cursor:pointer;'
    + 'font-family:inherit;letter-spacing:1px;animation:_pbbPulse 1.8s infinite;">'
    + '⚔ 繼續戰鬥</button>'
    + '<button id="_pbb_discard" style="padding:8px 18px;font-size:15px;'
    + 'background:rgba(40,15,15,0.7);border:1.5px solid #aa5544;color:#ee9988;'
    + 'border-radius:10px;cursor:pointer;font-family:inherit;letter-spacing:1px;">'
    + '🗑 放棄未完成戰鬥</button>';
  ov.appendChild(banner);

  document.getElementById('_pbb_continue').onclick = function(){
    try{ if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.55); }catch(_){}
    // 直接彈續戰提示(_advCheckCrashRecovery 會讀快照重彈)
    try{ if(typeof _advCheckCrashRecovery === 'function') _advCheckCrashRecovery(); }catch(_){}
  };
  document.getElementById('_pbb_discard').onclick = function(){
    try{ if(typeof playSfx === 'function') playSfx('sfx-cancel', 0.4); }catch(_){}
    // ★ v3.13.29 — 判斷未完成戰鬥是否為鬥技場:鬥技場放棄 = 記戰敗(二次確認)
    let _isArenaPending = false;
    try{
      const _raw = localStorage.getItem('adv_battle_snap');
      if(_raw){ const _s = JSON.parse(_raw); _isArenaPending = !!(_s && (_s.isArena===true || _s.stage==='arena')); }
    }catch(_){}
    if(_isArenaPending){
      try{ const _old=document.getElementById('_arena_discard_confirm'); if(_old) _old.remove(); }catch(_){}
      const _cm = document.createElement('div');
      _cm.id = '_arena_discard_confirm';
      _cm.style.cssText = 'position:fixed;inset:0;z-index:2147483647;background:rgba(0,0,8,0.9);'
        + 'display:flex;align-items:center;justify-content:center;padding:24px;'
        + 'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
      _cm.innerHTML =
        '<div style="background:linear-gradient(160deg,rgba(40,15,15,0.99),rgba(22,8,8,0.99));'
        + 'border:2.5px solid #cc4444;border-radius:18px;padding:30px 34px;width:min(94vw,480px);text-align:center;">'
        + '<div style="font-size:50px;margin-bottom:8px;">🏳</div>'
        + '<div style="font-size:26px;font-weight:900;color:#fff;margin-bottom:10px;">放棄鬥技場戰鬥?</div>'
        + '<div style="font-size:17px;color:#ffbbaa;line-height:1.7;margin-bottom:20px;">'
        + '放棄將<b style="color:#ff6655;">記錄為一場戰敗</b><br>已用掉的 1 次今日場次不會退還<br>(僅獲得 1 枚鬥技之證)</div>'
        + '<div style="display:flex;gap:14px;justify-content:center;">'
        + '<button id="_adc_cancel" style="flex:1;padding:12px 0;font-size:20px;font-weight:800;border-radius:10px;'
        + 'cursor:pointer;background:rgba(50,50,60,0.9);border:2px solid #555;color:#ccc;">✕ 取消</button>'
        + '<button id="_adc_ok" style="flex:1;padding:12px 0;font-size:20px;font-weight:800;border-radius:10px;'
        + 'cursor:pointer;background:linear-gradient(135deg,#cc4444,#882222);border:2px solid #ff6655;color:#fff;">🗑 確定放棄</button>'
        + '</div></div>';
      document.body.appendChild(_cm);
      _cm.querySelector('#_adc_cancel').onclick = function(){ try{ _cm.remove(); }catch(_){} };
      _cm.querySelector('#_adc_ok').onclick = function(){
        try{ _cm.remove(); }catch(_){}
        let _snapObj = {};
        try{ _snapObj = JSON.parse(localStorage.getItem('adv_battle_snap')||'{}'); }catch(_){}
        try{ _arenaDiscardAsLoss(_snapObj); }catch(e){ console.error('[鬥技場橫幅放棄記敗]', e); }
        try{ const _b=document.getElementById('_pending-battle-banner'); if(_b) _b.remove(); }catch(_){}
      };
      return;
    }
    // 冒險:用既有的二次確認對話框(crashBox 給 null 表示「沒有要關的續戰彈窗」)
    if(typeof _showDiscardConfirmDialog === 'function'){
      _showDiscardConfirmDialog(null);
    }
  };
}
window._renderPendingBattleBanner = _renderPendingBattleBanner;

