// ── 主入口:開啟預習頁面 ──
window._showPreviewPage = function(stage, focusSectionId){
  try{
    // 先移除舊的(避免堆疊)
    const oldOv = document.getElementById('preview-page-overlay');
    if(oldOv) oldOv.remove();

    // 預設為 taiwan
    // ★ v5.65.0(2026-08-18)— 丙①:中國關納入合法 stage(否則會被打回 taiwan)
    if(stage !== 'japan' && stage !== 'taiwan' && stage !== 'egypt' && stage !== 'china') stage = 'taiwan';
    _previewCheckDailyReset();

    // 取得題庫
    let allQuestions = [];
    let stageLabel = '';
    let stageColor = '';
    let stageIcon = '';
    if(stage === 'japan'){
      stageLabel = '日本關';
      stageColor = '#ffaa66';
      stageIcon = '🗾';
      try{
        if(typeof ADV_QUIZ_DB !== 'undefined')
          allQuestions = ADV_QUIZ_DB.filter(q => q.subject === '日本關');
      }catch(_){}
    } else if(stage === 'egypt'){
      stageLabel = '古埃及';
      stageColor = '#ffd86b';
      stageIcon = '🏜️';
      try{
        if(typeof ADV_QUIZ_DB !== 'undefined')
          allQuestions = ADV_QUIZ_DB.filter(q => q.subject === '埃及');
      }catch(_){}
    } else if(stage === 'china'){
      // ★ v5.65.0(2026-08-18)— 丙①:中國關 200 題(id 3201-3400·水墨朱紅配色)
      stageLabel = '中國古代關';
      stageColor = '#ff9966';
      stageIcon = '🏯';
      try{
        if(typeof ADV_QUIZ_DB !== 'undefined')
          allQuestions = ADV_QUIZ_DB.filter(q => q.subject === '中國關');
      }catch(_){}
    } else {
      stageLabel = '台灣環島';
      stageColor = '#66ddff';
      stageIcon = '🏝';
      try{
        if(typeof TAIWAN_QUIZ_DB !== 'undefined')
          allQuestions = TAIWAN_QUIZ_DB.slice();
      }catch(_){}
    }

    if(allQuestions.length === 0){
      try{ _showInGameToast('⚠ 題庫尚未載入,請稍後再試', '#ff8844', 2500); }catch(_){}
      return;
    }

    // 建立 overlay
    const ov = document.createElement('div');
    ov.id = 'preview-page-overlay';
    ov.style.cssText =
      'position:fixed;inset:0;z-index:9750;' +
      'background:linear-gradient(180deg,#0d1530 0%,#1a2848 50%,#0d1530 100%);' +
      'display:flex;flex-direction:column;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;' +
      'overflow:hidden;animation:fadeIn 0.4s;';
    document.body.appendChild(ov);

    // 標題列
    const header = document.createElement('div');
    header.style.cssText = 'flex-shrink:0;padding:14px 20px 10px;display:flex;align-items:center;gap:18px;background:rgba(0,0,0,0.4);border-bottom:2px solid rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.3);';
    header.innerHTML =
      '<button id="preview-back-btn" style="padding:10px 22px;font-size:20px;font-weight:800;background:rgba(0,30,60,0.85);border:2.5px solid ' + stageColor + ';color:' + stageColor + ';border-radius:12px;cursor:pointer;letter-spacing:2px;font-family:inherit;flex-shrink:0;">← 返回</button>' +
      '<div style="flex:1;font-size:clamp(22px,2.6vw,32px);font-weight:900;color:' + stageColor + ';letter-spacing:3px;text-shadow:0 0 18px rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.5);">' +
        '📚 ' + stageIcon + ' ' + stageLabel + ' · 知識預習' +
      '</div>' +
      '<div id="preview-coin-info" style="font-size:16px;color:#ffe066;background:rgba(255,200,50,0.12);padding:6px 14px;border:1.5px solid rgba(255,200,50,0.4);border-radius:10px;letter-spacing:1px;">' +
        '今日已領 <span id="preview-today-coins" style="color:#ffd633;font-weight:900;">0</span> / 500 💰' +
      '</div>';
    ov.appendChild(header);

    // 分頁列
    const tabs = document.createElement('div');
    tabs.style.cssText = 'flex-shrink:0;display:flex;gap:0;padding:0 20px;background:rgba(0,0,0,0.25);border-bottom:1.5px solid rgba(255,255,255,0.1);';
    tabs.innerHTML =
      '<button id="preview-tab-browse" data-tab="browse" class="preview-tab-active" style="flex:1;padding:14px 20px;font-size:20px;font-weight:800;background:rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.18);color:' + stageColor + ';border:none;border-bottom:3px solid ' + stageColor + ';cursor:pointer;font-family:inherit;letter-spacing:2px;">📖 知識瀏覽</button>' +
      '<button id="preview-tab-quiz" data-tab="quiz" style="flex:1;padding:14px 20px;font-size:20px;font-weight:800;background:transparent;color:#aaa;border:none;border-bottom:3px solid transparent;cursor:pointer;font-family:inherit;letter-spacing:2px;">✏️ 練習答題</button>';
    ov.appendChild(tabs);

    // 主內容區
    const body = document.createElement('div');
    body.id = 'preview-body';
    body.style.cssText = 'flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:20px;';
    ov.appendChild(body);

    // 更新今日已領幣顯示
    function _updateTodayCoinDisplay(){
      try{
        const el = document.getElementById('preview-today-coins');
        if(!el) return;
        const coins = (stage === 'japan') ? (_medalStats.previewTodayJpCoins||0) : (stage === 'egypt') ? (_medalStats.previewTodayEgCoins||0) : (stage === 'china') ? (_medalStats.previewTodayCnCoins||0) : (_medalStats.previewTodayTwCoins||0);
        el.textContent = String(coins);
        if(coins >= 500){
          el.style.color = '#ff6644';
        }
      }catch(_){}
    }
    _updateTodayCoinDisplay();

    function _renderBrowseTab(){
      // 取得對應的內容資料
      const contentData = (stage === 'japan') ? JAPAN_PREVIEW_CONTENT : (stage === 'egypt') ? EGYPT_PREVIEW_CONTENT : (stage === 'china') ? CHINA_PREVIEW_CONTENT : TAIWAN_PREVIEW_CONTENT;
      const sections = (contentData && contentData.sections) ? contentData.sections : [];
      const introText = (contentData && contentData.intro) ? contentData.intro : '';

      // 取得已讀章節集合
      const seenSet = (stage === 'japan')
        ? (_medalStats.previewJpSeen || {})
        : (stage === 'egypt')
        ? (_medalStats.previewEgSeen || {})
        : (stage === 'china')
        ? (_medalStats.previewCnSeen || {})
        : (_medalStats.previewTwSeen || {});
      const seenCount = sections.filter(s => seenSet[s.id]).length;
      const totalCount = sections.length;
      const pct = totalCount > 0 ? Math.round(seenCount * 100 / totalCount) : 0;
      const allDone = (seenCount >= totalCount && totalCount > 0);

      // ★ v1.0.20260501.5040 — 段落中 <b> 標籤套用答案綠色 (#aaffbb) 凸顯關鍵字
      const _highlightKeywords = function(text){
        return String(text || '').replace(/<b>/g, '<b style="color:#aaffbb;">');
      };

      let html = '';

      // 進度條(再放大)
      html += '<div style="max-width:1100px;margin:0 auto 36px;padding:30px 36px;background:linear-gradient(135deg,rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.14),rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.06));border:3px solid ' + stageColor + ';border-radius:18px;box-shadow:0 4px 18px rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.15);">' +
        '<div style="font-size:34px;color:' + stageColor + ';font-weight:900;margin-bottom:18px;letter-spacing:3px;">📊 我的閱讀進度</div>' +
        '<div style="height:28px;background:rgba(0,0,0,0.4);border-radius:14px;overflow:hidden;border:2px solid rgba(255,255,255,0.15);">' +
          '<div style="width:' + pct + '%;height:100%;background:linear-gradient(90deg,' + stageColor + ',' + (stage==='japan'?'#ffcc88':'#88ddff') + ');transition:width 0.4s;box-shadow:inset 0 1px 0 rgba(255,255,255,0.3);"></div>' +
        '</div>' +
        '<div style="margin-top:16px;font-size:30px;color:#ddeeff;line-height:1.5;letter-spacing:1px;">' +
          '已讀完 <span style="color:' + stageColor + ';font-weight:900;font-size:38px;">' + seenCount + '</span> / ' + totalCount + ' 個主題章節 ' +
          '<span style="color:' + (allDone ? '#88ff88' : '#ffd633') + ';font-weight:800;">(' + pct + '%)</span>' +
          (allDone ? ' <span style="color:#88ff88;font-weight:800;margin-left:10px;">✅ 全部讀完!</span>' : '') +
        '</div>' +
      '</div>';

      // 開場介紹(再放大)
      if(introText){
        html += '<div style="max-width:1100px;margin:0 auto 36px;padding:32px 38px;background:rgba(0,15,30,0.65);border:2.5px solid rgba(255,255,255,0.18);border-radius:18px;font-size:36px;line-height:1.85;color:#e8f0ff;letter-spacing:1.5px;">' +
          introText +
        '</div>';
      }

      // 各章節(再放大)
      sections.forEach((section, sIdx) => {
        const isSeen = !!seenSet[section.id];
        const cardBorder = isSeen
          ? '3px solid rgba(120,255,150,0.7)'
          : ('3px solid ' + stageColor);
        html += '<div data-section-id="' + section.id + '" style="max-width:1100px;margin:0 auto 42px;background:linear-gradient(180deg,rgba(0,20,40,0.85),rgba(0,10,25,0.95));border:' + cardBorder + ';border-radius:22px;overflow:hidden;box-shadow:0 6px 28px rgba(0,0,0,0.5);">';

        // 章節大標題列(再放大)
        html += '<div style="padding:32px 38px;background:linear-gradient(135deg,rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.22),rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.08));border-bottom:2.5px solid rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.35);display:flex;align-items:center;gap:26px;">' +
          '<div style="font-size:96px;line-height:1;flex-shrink:0;">' + section.icon + '</div>' +
          '<div style="flex:1;">' +
            '<div style="font-size:50px;font-weight:900;color:' + stageColor + ';letter-spacing:5px;line-height:1.2;text-shadow:0 0 18px rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.45);">' +
              '第 ' + (sIdx+1) + ' 章 · ' + section.title +
            '</div>' +
            (section.desc ? '<div style="margin-top:12px;font-size:28px;color:#bbd0ee;letter-spacing:2.5px;font-style:italic;">' + section.desc + '</div>' : '') +
          '</div>' +
          (isSeen ? '<div style="flex-shrink:0;padding:14px 26px;background:rgba(120,255,150,0.18);border:2.5px solid rgba(120,255,150,0.6);border-radius:14px;font-size:26px;color:#aaffbb;font-weight:800;letter-spacing:1.5px;">✅ 已讀</div>' : '') +
        '</div>';

        // 段落內容(★大字、寬行距、舒適閱讀,粗體關鍵字綠色 ★)
        html += '<div style="padding:38px 44px;">';
        if(Array.isArray(section.paragraphs)){
          section.paragraphs.forEach(p => {
            html += '<div style="font-size:36px;line-height:2;color:#f0f5ff;margin-bottom:30px;letter-spacing:1px;text-indent:2em;">' + _highlightKeywords(p) + '</div>';
          });
        }

        // 知識小卡(再放大)
        if(Array.isArray(section.facts) && section.facts.length > 0){
          html += '<div style="margin-top:32px;padding:30px 34px;background:rgba(255,200,50,0.08);border:2.5px dashed rgba(255,200,50,0.45);border-radius:18px;">' +
            '<div style="font-size:34px;font-weight:900;color:#ffd633;margin-bottom:22px;letter-spacing:3px;">💡 知識小卡(快速複習)</div>' +
            '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(420px,1fr));gap:16px;">';
          section.facts.forEach(f => {
            html += '<div style="padding:20px 24px;background:rgba(0,0,0,0.35);border-left:5px solid #ffd633;border-radius:12px;font-size:30px;line-height:1.65;color:#e8e8e8;">' +
              '<span style="color:#ffe066;font-weight:700;">Q:</span> ' + f.q + '<br>' +
              '<span style="color:#88ff88;font-weight:700;">A:</span> <b style="color:#aaffbb;">' + f.a + '</b>' +
            '</div>';
          });
          html += '</div></div>';
        }

        // 章節底部按鈕區(再放大)
        html += '<div style="margin-top:36px;padding-top:28px;border-top:1.5px solid rgba(255,255,255,0.12);text-align:center;">';
        if(!isSeen){
          html += '<button class="preview-mark-section-btn" data-sid="' + section.id + '" style="padding:22px 58px;font-size:34px;font-weight:900;letter-spacing:5px;background:linear-gradient(135deg,#22b3a3,#1d7a72);color:#fff;border:3px solid #6ed8cc;border-radius:16px;cursor:pointer;font-family:inherit;box-shadow:0 4px 18px rgba(34,179,163,0.5);">✅ 我看完這章了!</button>';
        } else {
          html += '<div style="font-size:32px;color:#aaffbb;font-weight:800;letter-spacing:3px;">🎉 你已讀完這個章節</div>';
        }
        html += '</div>';

        html += '</div>'; // 段落內容區
        html += '</div>'; // 整個章節卡片
      });

      // 底部「全部看完了!開始 5 題小測驗」總結卡片(再放大)
      html += '<div style="max-width:1100px;margin:0 auto 42px;padding:46px;background:linear-gradient(135deg,rgba(80,40,140,0.45),rgba(40,20,80,0.6));border:3px solid #aa88ee;border-radius:22px;text-align:center;box-shadow:0 6px 30px rgba(140,80,200,0.4);">';
      if(allDone){
        html += '<div style="font-size:84px;margin-bottom:22px;">🎓</div>' +
          '<div style="font-size:44px;color:#ffe066;font-weight:900;letter-spacing:5px;margin-bottom:18px;">恭喜!你已經讀完全部 ' + totalCount + ' 個章節!</div>' +
          '<div style="font-size:32px;color:#ddccff;line-height:1.7;margin-bottom:34px;">想試試看自己學會了多少嗎?來挑戰 5 題小測驗,全對可以拿到 100 知識幣 💰</div>' +
          '<button id="preview-go-quiz-btn" style="padding:26px 66px;font-size:42px;font-weight:900;letter-spacing:6px;background:linear-gradient(135deg,#ffd633,#ff9900);color:#3a1f00;border:3px solid #ffe066;border-radius:18px;cursor:pointer;font-family:inherit;box-shadow:0 6px 24px rgba(255,200,50,0.5);">✏️ 我準備好了!開始 5 題測驗</button>';
      } else {
        html += '<div style="font-size:72px;margin-bottom:20px;">📚</div>' +
          '<div style="font-size:36px;color:#ddccff;font-weight:800;letter-spacing:4px;margin-bottom:14px;">繼續加油!還有 ' + (totalCount - seenCount) + ' 個章節待閱讀</div>' +
          '<div style="font-size:30px;color:#bbaadd;line-height:1.7;margin-bottom:34px;">不過你也可以隨時挑戰測驗看看自己的程度喔~</div>' +
          '<button id="preview-go-quiz-btn" style="padding:22px 52px;font-size:32px;font-weight:800;letter-spacing:4px;background:rgba(140,100,200,0.6);color:#fff;border:3px solid #aa88ee;border-radius:16px;cursor:pointer;font-family:inherit;">✏️ 直接去測驗</button>';
      }
      html += '</div>';

      body.innerHTML = html;

      // 綁定「我看完這章」按鈕
      try{
        body.querySelectorAll('.preview-mark-section-btn').forEach(btn => {
          btn.onclick = function(){
            const sid = this.getAttribute('data-sid');
            if(!sid) return;
            try{ playSfx('sfx-medal-unlock', 0.6); }catch(_){}
            _previewMarkSeen(stage, sid);
            // 重新渲染整個瀏覽分頁(更新進度條和章節狀態)
            _renderBrowseTab();
            // 滾到剛才的位置
            try{
              const target = body.querySelector('div[data-section-id="' + sid + '"]');
              if(target) target.scrollIntoView({ behavior:'smooth', block:'start' });
            }catch(_){}
          };
        });
      }catch(_){}

      // 綁定「去測驗」按鈕
      try{
        const _gqBtn = document.getElementById('preview-go-quiz-btn');
        if(_gqBtn){
          _gqBtn.onclick = function(){
            try{ playSfx('sfx-battle-start', 0.5); }catch(_){}
            _switchTab('quiz');
            // 自動滾到頂部
            try{ body.scrollTop = 0; }catch(_){}
          };
        }
      }catch(_){}
    }

    // ── 渲染「練習答題」分頁 ──
    let _quizState = null;  // { questions: [], curIdx: 0, correctCount: 0, answered: [] }
    function _renderQuizTab(){
      _previewCheckDailyReset();
      const todayKey = (stage === 'japan') ? 'previewTodayJpCoins' : (stage === 'egypt') ? 'previewTodayEgCoins' : (stage === 'china') ? 'previewTodayCnCoins' : 'previewTodayTwCoins';
      const todayCoins = _medalStats[todayKey] || 0;
      const remainCoins = Math.max(0, 500 - todayCoins);
      let html = '';
      html += '<div style="max-width:780px;margin:0 auto;">';
      html += '<div style="margin-bottom:20px;padding:16px 20px;background:rgba(255,200,50,0.1);border:2px solid rgba(255,200,50,0.4);border-radius:12px;text-align:center;">' +
        '<div style="font-size:18px;color:#ffe066;font-weight:800;margin-bottom:6px;">🎯 練習答題</div>' +
        '<div style="font-size:15px;color:#ddd;line-height:1.6;">每輪 <b style="color:#ffd633;">5 題</b>,5 題全對可獲得 <b style="color:#ffd633;">100 知識幣 💰</b><br>每天每個關卡上限 500 幣(共 5 次全對機會),今日剩餘 <b style="color:' + (remainCoins>0?'#88ff88':'#ff6644') + ';">' + remainCoins + ' 💰</b></div>' +
      '</div>';

      if(!_quizState){
        // 顯示開始按鈕
        html += '<div style="text-align:center;padding:40px 0;">' +
          '<button id="preview-start-quiz" style="padding:18px 40px;font-size:26px;font-weight:900;letter-spacing:3px;background:linear-gradient(135deg,#22b3a3,#1d7a72);color:#fff;border:3px solid #6ed8cc;border-radius:14px;cursor:pointer;font-family:inherit;box-shadow:0 4px 18px rgba(34,179,163,0.5);">🎲 開始 5 題挑戰</button>' +
        '</div>';
      } else {
        // 顯示題目
        const total = _quizState.questions.length;
        const cur = _quizState.curIdx;
        if(cur < total){
          const q = _quizState.questions[cur];
          html += '<div style="margin-bottom:18px;padding:8px 16px;background:rgba(0,0,0,0.4);border-radius:10px;display:flex;justify-content:space-between;align-items:center;">' +
            '<span style="font-size:18px;color:' + stageColor + ';font-weight:800;">第 ' + (cur+1) + ' / ' + total + ' 題</span>' +
            '<span style="font-size:16px;color:#aaffbb;">已答對 ' + _quizState.correctCount + ' 題</span>' +
          '</div>';
          html += '<div style="background:rgba(0,15,30,0.7);border:2px solid ' + stageColor + ';border-radius:14px;padding:24px;">' +
            '<div style="font-size:22px;color:#fff;line-height:1.6;margin-bottom:20px;font-weight:700;">' + q.question + '</div>' +
            '<div id="preview-quiz-options">';
          if(Array.isArray(q.options)){
            q.options.forEach((opt, i) => {
              html += '<button class="preview-quiz-opt" data-idx="' + i + '" style="display:block;width:100%;margin:10px 0;padding:14px 20px;background:rgba(20,40,80,0.6);border:2px solid rgba(120,200,255,0.35);color:#e0e8f0;border-radius:10px;cursor:pointer;font-size:18px;text-align:left;font-family:inherit;line-height:1.5;transition:all 0.15s;">' +
                '<span style="font-weight:900;margin-right:10px;color:' + stageColor + ';">' + ['A','B','C','D'][i] + '.</span>' + opt +
              '</button>';
            });
          }
          html += '</div></div>';
        } else {
          // 答完 5 題,顯示結算
          const allCorrect = _quizState.correctCount === total;
          const _todayKey = (stage === 'japan') ? 'previewTodayJpCoins' : (stage === 'egypt') ? 'previewTodayEgCoins' : (stage === 'china') ? 'previewTodayCnCoins' : 'previewTodayTwCoins';
          const _todayCoins = _medalStats[_todayKey] || 0;
          // ★ v3.15.31 — 管理員自動繞過預習每日 500 幣上限(登入後自動生效)
          const _canEarn = (typeof window._isAdminUser === 'function' && window._isAdminUser()) || (_todayCoins < 500);
          let coinsAwarded = 0;
          let resultMsg = '';
          let resultColor = '';
          if(allCorrect){
            if(_canEarn){
              coinsAwarded = 100;
              resultMsg = '🎉 全部答對!獲得 ' + coinsAwarded + ' 知識幣 💰';
              resultColor = '#88ff88';
            } else {
              resultMsg = '🎉 全部答對!但今日已達上限,只給經驗 ✨';
              resultColor = '#88ff88';
            }
          } else {
            resultMsg = '答對 ' + _quizState.correctCount + ' / ' + total + ' 題,要 5 題全對才有獎勵喔!';
            resultColor = '#ffaa66';
          }
          // 結算 + 統計更新(只在這次結算時做一次)
          if(!_quizState._settled){
            _quizState._settled = true;
            try{
              _medalStats.previewTotalCompleted = (_medalStats.previewTotalCompleted||0) + 1;
              if(allCorrect){
                _medalStats.previewTotalPerfect = (_medalStats.previewTotalPerfect||0) + 1;
                _medalStats.previewPerfectStreak = (_medalStats.previewPerfectStreak||0) + 1;
                if(_medalStats.previewPerfectStreak > (_medalStats.previewMaxStreak||0)){
                  _medalStats.previewMaxStreak = _medalStats.previewPerfectStreak;
                }
                if(coinsAwarded > 0){
                  _medalStats[_todayKey] = _todayCoins + coinsAwarded;
                  _medalStats.previewCoinsEarned = (_medalStats.previewCoinsEarned||0) + coinsAwarded;
                  try{ if(typeof addKnowledgeCoins === 'function') addKnowledgeCoins(coinsAwarded, '收入:預習全對'); }catch(_){}
                }
              } else {
                _medalStats.previewPerfectStreak = 0;
              }
              _saveMedals();
              // 檢查獎章解鎖
              _previewCheckQuizAchievements();
            }catch(_e){ console.warn('[預習結算]', _e); }
          }
          html += '<div style="background:rgba(0,15,30,0.7);border:3px solid ' + resultColor + ';border-radius:16px;padding:30px;text-align:center;margin-top:20px;">' +
            '<div style="font-size:64px;margin-bottom:14px;">' + (allCorrect ? '🏆' : '📝') + '</div>' +
            '<div style="font-size:24px;color:' + resultColor + ';font-weight:900;margin-bottom:14px;letter-spacing:2px;">' + resultMsg + '</div>' +
            '<div style="font-size:16px;color:#aaa;line-height:1.7;margin-bottom:22px;">' +
              '答對:' + _quizState.correctCount + ' / ' + total + ' 題' +
              (coinsAwarded > 0 ? '<br>💰 +' + coinsAwarded + ' 知識幣' : '') +
              '<br>連續全對:' + (_medalStats.previewPerfectStreak||0) + ' 次(歷史最高 ' + (_medalStats.previewMaxStreak||0) + ' 次)' +
            '</div>' +
            '<div style="display:flex;gap:14px;justify-content:center;flex-wrap:wrap;">' +
              '<button id="preview-quiz-again" style="padding:14px 30px;font-size:18px;font-weight:800;background:linear-gradient(135deg,#22b3a3,#1d7a72);color:#fff;border:2.5px solid #6ed8cc;border-radius:12px;cursor:pointer;font-family:inherit;letter-spacing:1px;">🔄 再來一輪</button>' +
              '<button id="preview-quiz-review" style="padding:14px 30px;font-size:18px;font-weight:800;background:rgba(60,80,140,0.7);color:#cce0ff;border:2.5px solid rgba(120,160,220,0.6);border-radius:12px;cursor:pointer;font-family:inherit;letter-spacing:1px;">📋 查看答題詳情</button>' +
            '</div>' +
          '</div>';
          // 詳情區
          html += '<div id="preview-quiz-review-area" style="display:none;margin-top:20px;background:rgba(0,15,30,0.5);border:1.5px solid rgba(255,255,255,0.15);border-radius:12px;padding:18px;">';
          _quizState.questions.forEach((q, qi) => {
            const userIdx = _quizState.answered[qi];
            const ansIdx = ['A','B','C','D'].indexOf(q.answer);
            const isCorrect = (userIdx === ansIdx);
            html += '<div style="margin-bottom:14px;padding:12px 16px;background:rgba(0,0,0,0.35);border-left:4px solid ' + (isCorrect ? '#88ff88' : '#ff8866') + ';border-radius:8px;">' +
              '<div style="font-size:16px;color:#fff;line-height:1.5;margin-bottom:8px;">' +
                '<b style="color:' + (isCorrect ? '#88ff88' : '#ff8866') + ';">第 ' + (qi+1) + ' 題 ' + (isCorrect ? '✓' : '✗') + '</b> ' + q.question +
              '</div>';
            if(Array.isArray(q.options)){
              q.options.forEach((opt, i) => {
                const isAns = (i === ansIdx);
                const isUser = (i === userIdx);
                html += '<div style="margin:3px 0;padding:6px 12px;font-size:14px;border-radius:6px;' +
                  (isAns ? 'background:rgba(80,220,120,0.18);color:#aaffbb;font-weight:700;' :
                   isUser ? 'background:rgba(220,80,80,0.18);color:#ffaaaa;' : 'color:#888;') +
                  '">' +
                  ['A','B','C','D'][i] + '. ' + opt +
                  (isAns ? ' ✓ 正解' : '') +
                  (isUser && !isAns ? ' ← 你的答案' : '') +
                '</div>';
              });
            }
            html += '</div>';
          });
          html += '</div>';
        }
      }
      html += '</div>';
      body.innerHTML = html;
      _updateTodayCoinDisplay();

      // 綁定按鈕
      const _startBtn = document.getElementById('preview-start-quiz');
      if(_startBtn){
        _startBtn.onclick = function(){
          try{ playSfx('sfx-battle-start', 0.5); }catch(_){}
          // Fisher-Yates 抽 5 題
          const pool = allQuestions.slice();
          for(let i = pool.length - 1; i > 0; i--){
            const j = Math.floor(Math.random() * (i + 1));
            [pool[i], pool[j]] = [pool[j], pool[i]];
          }
          _quizState = { questions: pool.slice(0, 5), curIdx: 0, correctCount: 0, answered: [] };
          _renderQuizTab();
        };
      }
      const _againBtn = document.getElementById('preview-quiz-again');
      if(_againBtn){
        _againBtn.onclick = function(){
          try{ playSfx('sfx-sel', 0.5); }catch(_){}
          _quizState = null;
          _renderQuizTab();
        };
      }
      const _reviewBtn = document.getElementById('preview-quiz-review');
      if(_reviewBtn){
        _reviewBtn.onclick = function(){
          try{ playSfx('sfx-sel', 0.4); }catch(_){}
          const area = document.getElementById('preview-quiz-review-area');
          if(area) area.style.display = (area.style.display === 'none' ? 'block' : 'none');
        };
      }
      // 綁定選項點擊
      body.querySelectorAll('.preview-quiz-opt').forEach(btn => {
        btn.onclick = function(){
          const idx = parseInt(this.getAttribute('data-idx'));
          if(!_quizState || _quizState.curIdx >= _quizState.questions.length) return;
          const q = _quizState.questions[_quizState.curIdx];
          const ansIdx = ['A','B','C','D'].indexOf(q.answer);
          _quizState.answered.push(idx);
          const isCorrect = (idx === ansIdx);
          if(isCorrect) _quizState.correctCount++;
          try{
            const _sfxId = isCorrect ? 'sfx-quiz-correct' : 'sfx-quiz-wrong';
            const _sfx = document.getElementById(_sfxId);
            if(_sfx){ _sfx.currentTime = 0; _sfx.volume = 0.63; _sfx.play().catch(()=>{}); }
          }catch(_){}
          // 視覺回饋:正解綠色、錯誤紅色,顯示 0.7 秒
          try{
            const allOpts = body.querySelectorAll('.preview-quiz-opt');
            allOpts.forEach((b, i) => {
              b.disabled = true;
              if(i === ansIdx){
                b.style.background = 'rgba(80,220,120,0.35)';
                b.style.borderColor = '#88ff88';
              } else if(i === idx && !isCorrect){
                b.style.background = 'rgba(220,80,80,0.35)';
                b.style.borderColor = '#ff8866';
              } else {
                b.style.opacity = '0.5';
              }
            });
            // ★ v1.0.20260501.5050 — 音效已在上方播放(sfx-quiz-correct / sfx-quiz-wrong),這裡不再呼叫舊的失敗版本
          }catch(_){}
          setTimeout(() => {
            _quizState.curIdx++;
            _renderQuizTab();
          }, 700);
        };
      });
    }

    // ── 切換分頁 ──
    function _switchTab(tab){
      document.querySelectorAll('#preview-page-overlay [data-tab]').forEach(b => {
        if(b.getAttribute('data-tab') === tab){
          b.style.background = 'rgba(' + (stage==='japan'?'255,170,100':'100,200,255') + ',0.18)';
          b.style.color = stageColor;
          b.style.borderBottom = '3px solid ' + stageColor;
        } else {
          b.style.background = 'transparent';
          b.style.color = '#aaa';
          b.style.borderBottom = '3px solid transparent';
        }
      });
      if(tab === 'browse'){ _renderBrowseTab(); }
      else { _quizState = null; _renderQuizTab(); }
    }

    // 綁定分頁按鈕
    document.getElementById('preview-tab-browse').onclick = function(){
      try{ playSfx('sfx-sel', 0.4); }catch(_){}
      _switchTab('browse');
    };
    document.getElementById('preview-tab-quiz').onclick = function(){
      try{ playSfx('sfx-sel', 0.4); }catch(_){}
      _switchTab('quiz');
    };
    // 返回按鈕
    document.getElementById('preview-back-btn').onclick = function(){
      try{ playSfx('sfx-cancel', 0.5); }catch(_){}
      ov.remove();
    };

    // 初始顯示瀏覽分頁
    _renderBrowseTab();

    // ★ v1.0.20260501.5050 — 若指定了 focusSectionId,延遲一下讓 DOM 渲染完再滾動到該章節
    if(focusSectionId){
      try{
        setTimeout(() => {
          try{
            const target = body.querySelector('div[data-section-id="' + focusSectionId + '"]');
            if(target){
              target.scrollIntoView({ behavior:'smooth', block:'start' });
              // 短暫高亮一下,讓玩家看到「我跳到了哪一章」
              const _origBoxShadow = target.style.boxShadow;
              target.style.boxShadow = '0 0 0 5px rgba(255,200,50,0.7), 0 6px 28px rgba(0,0,0,0.5)';
              setTimeout(() => { target.style.boxShadow = _origBoxShadow; }, 1800);
            }
          }catch(_){}
        }, 200);
      }catch(_){}
    }
  }catch(_e){
    console.error('[預習頁面]', _e);
    try{ _showInGameToast('⚠ 預習頁面開啟失敗', '#ff8844', 2500); }catch(_){}
  }
};

// ── 檢查預習答題相關獎章 ──
function _previewCheckQuizAchievements(){
  try{
    if(!_medalStats) return;
    const total = _medalStats.previewTotalCompleted || 0;
    const perfect = _medalStats.previewTotalPerfect || 0;
    const streak = _medalStats.previewPerfectStreak || 0;
    const coins = _medalStats.previewCoinsEarned || 0;

    // 第一次完成 → 初試身手
    if(total >= 1) _unlockMedal('preview_first');
    // 第一次全對 → 全對小將
    if(perfect >= 1) _unlockMedal('preview_first_perfect');
    // 全對次數階梯
    if(perfect >= 5) _unlockMedal('preview_perfect_5');
    if(perfect >= 20) _unlockMedal('preview_perfect_20');
    if(perfect >= 50) _unlockMedal('preview_perfect_50');
    // 連勝
    if(streak >= 5) _unlockMedal('preview_streak_5');
    // 累計獲得知識幣
    if(coins >= 500) _unlockMedal('preview_coins_500');
    if(coins >= 2000) _unlockMedal('preview_coins_2000');

    _saveMedals();
  }catch(_){}
}

